INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u3-C1','math',6,1,'u3',2,'0.1이 몇 개 · 자연수의 나눗셈 이용하기 — 소수를 0.1(0.01)이 몇 개인 수로 보고 나누며, 나누는 수가 같을 때 나누어지는 수가 ⟨1/10⟩배·⟨1/100⟩배가 되면 몫도 ⟨1/10⟩배·⟨1/100⟩배가 됨을 이용하고, 분수의 나눗셈(÷자연수 → ×자연수분의 1)으로도 계산하기',ARRAY['6수01-10']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u3-C2','math',6,1,'u3',3,'각 자리에서 나누어떨어지지 않는 (소수)÷(자연수) — 자연수의 나눗셈과 똑같이 세로셈으로 계산하고 몫의 소수점은 나누어지는 수의 소수점 자리에 맞추어 올려 찍기',ARRAY['6수01-10']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u3-C3','math',6,1,'u3',4,'몫이 1보다 작은 (소수)÷(자연수) — 나누어지는 수가 나누는 수보다 작으면 몫이 1보다 작음을 알고 몫의 일의 자리에 0을 써서 자리를 지키기',ARRAY['6수01-10']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u3-C4','math',6,1,'u3',5,'소수점 아래 0을 내려 계산하기 — 나누어지는 수의 자리가 끝나도 나머지가 남으면 4.6 = 4.60처럼 소수점 아래에 0을 내려 계산을 이어 가기',ARRAY['6수01-10']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u3-C5','math',6,1,'u3',6,'몫의 가운데에 0이 들어가는 나눗셈 — 수를 내려도 나누어야 할 수가 나누는 수보다 작으면 몫에 0을 쓰고 수를 하나 더 내려 계산하기(9.05와 9.5는 다른 수)',ARRAY['6수01-10']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u3-C6','math',6,1,'u3',7,'(자연수)÷(자연수)의 몫을 소수로 — 자연수를 6 = 6.0처럼 보고 0을 내려 계산하거나, 몫을 분수로 쓴 뒤 분모를 10·100으로 고쳐 소수로 나타내기',ARRAY['6수01-10']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u3-C7','math',6,1,'u3',8,'어림셈으로 고르고 계산으로 확인하기 — 나누어지는 수를 계산하기 쉬운 자연수로 어림해 몫의 크기를 먼저 짐작하고, 계산 결과가 어림과 크게 다르면 다시 확인하기',ARRAY['6수01-10']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u3-X01','math',6,'u3',ARRAY['M6-1-u3-C1','M6-1-u3-C2','M6-1-u3-C4','M6-1-u3-C5','M6-1-u3-C6','M6-1-u3-C7']::text[],'몫의 소수점을 빠뜨리거나 한 자리 뒤에 찍어 몫을 10배·100배 크게 쓴다','몫의 소수점은 나누어지는 수의 소수점 위') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u3-X02','math',6,'u3',ARRAY['M6-1-u3-C1','M6-1-u3-C2','M6-1-u3-C3','M6-1-u3-C4','M6-1-u3-C5','M6-1-u3-C6','M6-1-u3-C7']::text[],'몫의 소수점을 한 자리 앞에 찍어 몫을 10배·100배 작게 쓴다','어림한 값과 견주어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u3-X03','math',6,'u3',ARRAY['M6-1-u3-C1']::text[],'소수가 0.1(0.01)이 몇 개인지 잘못 센다(6.8을 0.1이 680개로)','0.1이 10개면 1이에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u3-X04','math',6,'u3',ARRAY['M6-1-u3-C1']::text[],'분수의 나눗셈으로 바꿀 때 ÷(자연수)를 ×(자연수)로 바꾸거나 분모·분자를 뒤집는다','÷ 자연수는 × 자연수분의 1') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u3-X05','math',6,'u3',ARRAY['M6-1-u3-C3']::text[],'몫이 1보다 작을 때 일의 자리에 0을 쓰지 않아 몫을 10배 크게 쓴다(0.8을 8로)','일의 자리 0은 자리를 지켜요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u3-X06','math',6,'u3',ARRAY['M6-1-u3-C4']::text[],'나머지가 남았는데 0을 내리지 않고 계산을 멈추거나 나머지를 몫 뒤에 붙인다(4.6 ÷ 4를 1.1·1.12로)','4.6 = 4.60 — 0을 내려 이어 가요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u3-X07','math',6,'u3',ARRAY['M6-1-u3-C5']::text[],'몫의 가운데 자리에 0을 쓰지 않는다(9.05를 9.5로)','내린 수가 작으면 몫에 0') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u3-X08','math',6,'u3',ARRAY['M6-1-u3-C6']::text[],'(자연수)÷(자연수)에서 나머지를 그대로 소수 부분으로 쓴다(6 ÷ 5 = 1 … 1을 1.1로)','6을 6.0으로 보고 0을 내려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u3-X09','math',6,'u3',ARRAY['M6-1-u3-C3','M6-1-u3-C6']::text[],'나누어지는 수와 나누는 수를 바꾸어 쓴다(강아지는 고양이의 몇 배 → 4 ÷ 3.2)','「무엇이 무엇의」 — 앞이 나누어지는 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u3-X10','math',6,'u3',ARRAY['M6-1-u3-C1','M6-1-u3-C2','M6-1-u3-C5','M6-1-u3-C6']::text[],'한 사람 몫·한 변·몇 배를 구하는데 나눗셈 대신 곱셈을 한다','똑같이 나누면 나눗셈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u3-X11','math',6,'u3',ARRAY['M6-1-u3-C1','M6-1-u3-C2','M6-1-u3-C3','M6-1-u3-C4','M6-1-u3-C5','M6-1-u3-C6','M6-1-u3-C7']::text[],'단위를 바꿀 때 배수를 잘못 쓴다(1 L = 1000 mL, 1 kg = 1000 g, 1 m = 100 cm, 1 cm = 10 mm)','큰 단위 1이 작은 단위 몇인지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u3-X12','math',6,'u3',ARRAY['M6-1-u3-C1','M6-1-u3-C3','M6-1-u3-C7']::text[],'어림을 하지 못하거나, 어림한 값과 크게 다른 계산 결과를 그대로 둔다','계산하기 쉬운 자연수로 바꾸어 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u3-X13','math',6,'u3',ARRAY['M6-1-u3-C1','M6-1-u3-C2','M6-1-u3-C3','M6-1-u3-C4','M6-1-u3-C5','M6-1-u3-C6','M6-1-u3-C7']::text[],'자연수의 나눗셈·세로셈의 곱셈과 뺄셈을 잘못 계산한다','곱셈으로 거꾸로 확인해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u3-X14','math',6,'u3',ARRAY['M6-1-u3-C1','M6-1-u3-C2','M6-1-u3-C3','M6-1-u3-C4','M6-1-u3-C5','M6-1-u3-C6','M6-1-u3-C7']::text[],'묻는 말을 거꾸로 읽거나 놓친다 — 가장 큰↔작은, 잘못된↔알맞은, kg↔g','물음의 「가장·잘못·단위」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L02_basic#1','math',6,1,'u3','L02','g6_1_math_u3_L02_basic','lesson_basic','M6-1-u3-C1',1,'sa','auto','6.8은 0.1이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u3-C1","difficulty":1,"kind":"sa","stem":"6.8은 0.1이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["68"],"explanation":["0.1이 10개이면 1이에요.","6.8은 6과 소수 부분을 합해 0.1이 68개예요.","그래서 6.8은 0.1이 68개인 수예요."],"mis":"M6-1-u3-X03","variant_rule":{"alt":[{"stem":"3.6은 0.1이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["0.1이 10개이면 1이에요.","3.6은 3과 소수 부분을 합해 0.1이 36개예요.","그래서 3.6은 0.1이 36개인 수예요."]},{"stem":"9.6은 0.1이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["96"],"explanation":["0.1이 10개이면 1이에요.","9.6은 9와 소수 부분을 합해 0.1이 96개예요.","그래서 9.6은 0.1이 96개인 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L02_basic#2','math',6,1,'u3','L02','g6_1_math_u3_L02_basic','lesson_basic','M6-1-u3-C1',1,'mc','auto','648 ÷ 2 = 324예요. 그러면 64.8 ÷ 2의 몫은 얼마인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":2,"concept":"M6-1-u3-C1","difficulty":1,"kind":"mc","stem":"648 ÷ 2 = 324예요. 그러면 64.8 ÷ 2의 몫은 얼마인가요?","options":[{"t":"32.4","correct":true},{"t":"324","mis":"M6-1-u3-X01"},{"t":"3.24","mis":"M6-1-u3-X02"},{"t":"3240","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 2는 그대로예요.","나누어지는 수 64.8은 648의 ⟨1/10⟩배예요.","그래서 몫도 324의 ⟨1/10⟩배 — 32.4예요."],"variant_rule":{"alt":[{"stem":"846 ÷ 2 = 423이에요. 그러면 84.6 ÷ 2의 몫은 얼마인가요?","options":[{"t":"42.3","correct":true},{"t":"423","mis":"M6-1-u3-X01"},{"t":"4.23","mis":"M6-1-u3-X02"},{"t":"4230","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 2는 그대로예요.","나누어지는 수 84.6은 846의 ⟨1/10⟩배예요.","그래서 몫도 423의 ⟨1/10⟩배 — 42.3이에요."]},{"stem":"936 ÷ 3 = 312예요. 그러면 93.6 ÷ 3의 몫은 얼마인가요?","options":[{"t":"31.2","correct":true},{"t":"312","mis":"M6-1-u3-X01"},{"t":"3.12","mis":"M6-1-u3-X02"},{"t":"3120","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 3은 그대로예요.","나누어지는 수 93.6은 936의 ⟨1/10⟩배예요.","그래서 몫도 312의 ⟨1/10⟩배 — 31.2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L02_basic#3','math',6,1,'u3','L02','g6_1_math_u3_L02_basic','lesson_basic','M6-1-u3-C1',1,'sa','auto','884 ÷ 26의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u3-C1","difficulty":1,"kind":"sa","stem":"884 ÷ 26의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["34"],"explanation":["자연수의 나눗셈은 높은 자리부터 나누고 남은 수를 다음 자리로 내려요.","34 × 26 = 884로 확인할 수 있어요.","884 ÷ 26 = 34예요."],"mis":"M6-1-u3-X13","variant_rule":{"alt":[{"stem":"765 ÷ 17의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["자연수의 나눗셈은 높은 자리부터 나누고 남은 수를 다음 자리로 내려요.","45 × 17 = 765로 확인할 수 있어요.","765 ÷ 17 = 45예요."]},{"stem":"882 ÷ 18의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["49"],"explanation":["자연수의 나눗셈은 높은 자리부터 나누고 남은 수를 다음 자리로 내려요.","49 × 18 = 882로 확인할 수 있어요.","882 ÷ 18 = 49예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L02_basic#4','math',6,1,'u3','L02','g6_1_math_u3_L02_basic','lesson_basic','M6-1-u3-C1',1,'mc','auto','6.8 ÷ 2의 몫은 어느 두 수 사이에 있나요?',ARRAY['M6-1-u3-X12']::text[],true,'{"seq":4,"concept":"M6-1-u3-C1","difficulty":1,"kind":"mc","stem":"6.8 ÷ 2의 몫은 어느 두 수 사이에 있나요?","options":[{"t":"3과 4 사이","correct":true},{"t":"2와 3 사이","mis":"M6-1-u3-X12"},{"t":"4와 5 사이","mis":"M6-1-u3-X12"},{"t":"5와 6 사이","mis":"M6-1-u3-X12"}],"explanation":["6.8을 계산하기 쉬운 자연수로 바꾸어 어림해요.","6 ÷ 2 = 3이고 8 ÷ 2 = 4예요.","6.8은 6과 8 사이라 몫도 3과 4 사이예요."],"variant_rule":{"alt":[{"stem":"3.6 ÷ 3의 몫은 어느 두 수 사이에 있나요?","options":[{"t":"1과 2 사이","correct":true},{"t":"0과 1 사이","mis":"M6-1-u3-X12"},{"t":"2와 3 사이","mis":"M6-1-u3-X12"},{"t":"3과 4 사이","mis":"M6-1-u3-X12"}],"explanation":["3.6을 계산하기 쉬운 자연수로 바꾸어 어림해요.","3 ÷ 3 = 1이고 6 ÷ 3 = 2예요.","3.6은 3과 6 사이라 몫도 1과 2 사이예요."]},{"stem":"8.4 ÷ 4의 몫은 어느 두 수 사이에 있나요?","options":[{"t":"2와 3 사이","correct":true},{"t":"1과 2 사이","mis":"M6-1-u3-X12"},{"t":"3과 4 사이","mis":"M6-1-u3-X12"},{"t":"4와 5 사이","mis":"M6-1-u3-X12"}],"explanation":["8.4를 계산하기 쉬운 자연수로 바꾸어 어림해요.","8 ÷ 4 = 2이고 12 ÷ 4 = 3이에요.","8.4는 8과 12 사이라 몫도 2와 3 사이예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L02_basic#5','math',6,1,'u3','L02','g6_1_math_u3_L02_basic','lesson_basic','M6-1-u3-C1',2,'sa','auto','6.8을 두 묶음으로 똑같이 나누어요. 한 묶음은 0.1이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u3-C1","difficulty":2,"kind":"sa","stem":"6.8을 두 묶음으로 똑같이 나누어요. 한 묶음은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["34"],"explanation":["6.8은 0.1이 68개인 수예요.","68 ÷ 2 = 34 — 한 묶음은 0.1이 34개예요.","0.1이 34개이면 3.4예요."],"mis":"M6-1-u3-X03","variant_rule":{"alt":[{"stem":"9.6을 세 묶음으로 똑같이 나누어요. 한 묶음은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["9.6은 0.1이 96개인 수예요.","96 ÷ 3 = 32 — 한 묶음은 0.1이 32개예요.","0.1이 32개이면 3.2예요."]},{"stem":"8.4를 네 묶음으로 똑같이 나누어요. 한 묶음은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["8.4는 0.1이 84개인 수예요.","84 ÷ 4 = 21 — 한 묶음은 0.1이 21개예요.","0.1이 21개이면 2.1이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L02_basic#6','math',6,1,'u3','L02','g6_1_math_u3_L02_basic','lesson_basic','M6-1-u3-C1',2,'mc','auto','488 ÷ 4 = 122예요. 그러면 4.88 ÷ 4의 몫은 얼마인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":6,"concept":"M6-1-u3-C1","difficulty":2,"kind":"mc","stem":"488 ÷ 4 = 122예요. 그러면 4.88 ÷ 4의 몫은 얼마인가요?","options":[{"t":"1.22","correct":true},{"t":"12.2","mis":"M6-1-u3-X01"},{"t":"0.122","mis":"M6-1-u3-X02"},{"t":"122","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 4는 그대로예요.","나누어지는 수 4.88은 488의 ⟨1/100⟩배예요.","그래서 몫도 122의 ⟨1/100⟩배 — 1.22예요."],"variant_rule":{"alt":[{"stem":"393 ÷ 3 = 131이에요. 그러면 3.93 ÷ 3의 몫은 얼마인가요?","options":[{"t":"1.31","correct":true},{"t":"13.1","mis":"M6-1-u3-X01"},{"t":"0.131","mis":"M6-1-u3-X02"},{"t":"131","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 3은 그대로예요.","나누어지는 수 3.93은 393의 ⟨1/100⟩배예요.","그래서 몫도 131의 ⟨1/100⟩배 — 1.31이에요."]},{"stem":"846 ÷ 2 = 423이에요. 그러면 8.46 ÷ 2의 몫은 얼마인가요?","options":[{"t":"4.23","correct":true},{"t":"42.3","mis":"M6-1-u3-X01"},{"t":"0.423","mis":"M6-1-u3-X02"},{"t":"423","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 2는 그대로예요.","나누어지는 수 8.46은 846의 ⟨1/100⟩배예요.","그래서 몫도 423의 ⟨1/100⟩배 — 4.23이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L02_basic#7','math',6,1,'u3','L02','g6_1_math_u3_L02_basic','lesson_basic','M6-1-u3-C1',2,'mc','auto','3.6 ÷ 3을 분수의 나눗셈으로 바꾸어 계산하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u3-X04','M6-1-u3-X03']::text[],true,'{"seq":7,"concept":"M6-1-u3-C1","difficulty":2,"kind":"mc","stem":"3.6 ÷ 3을 분수의 나눗셈으로 바꾸어 계산하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"⟨36/10⟩ × ⟨1/3⟩","correct":true},{"t":"⟨36/10⟩ × 3","mis":"M6-1-u3-X04"},{"t":"⟨10/36⟩ × ⟨1/3⟩","mis":"M6-1-u3-X04"},{"t":"⟨36/100⟩ × ⟨1/3⟩","mis":"M6-1-u3-X03"}],"explanation":["3.6은 ⟨36/10⟩이에요.","÷ 3은 × ⟨1/3⟩로 바꾸어 계산해요.","그래서 ⟨36/10⟩ × ⟨1/3⟩이에요."],"variant_rule":{"alt":[{"stem":"6.8 ÷ 2를 분수의 나눗셈으로 바꾸어 계산하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"⟨68/10⟩ × ⟨1/2⟩","correct":true},{"t":"⟨68/10⟩ × 2","mis":"M6-1-u3-X04"},{"t":"⟨10/68⟩ × ⟨1/2⟩","mis":"M6-1-u3-X04"},{"t":"⟨68/100⟩ × ⟨1/2⟩","mis":"M6-1-u3-X03"}],"explanation":["6.8은 ⟨68/10⟩이에요.","÷ 2는 × ⟨1/2⟩로 바꾸어 계산해요.","그래서 ⟨68/10⟩ × ⟨1/2⟩이에요."]},{"stem":"8.4 ÷ 4를 분수의 나눗셈으로 바꾸어 계산하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"⟨84/10⟩ × ⟨1/4⟩","correct":true},{"t":"⟨84/10⟩ × 4","mis":"M6-1-u3-X04"},{"t":"⟨10/84⟩ × ⟨1/4⟩","mis":"M6-1-u3-X04"},{"t":"⟨84/100⟩ × ⟨1/4⟩","mis":"M6-1-u3-X03"}],"explanation":["8.4는 ⟨84/10⟩예요.","÷ 4는 × ⟨1/4⟩로 바꾸어 계산해요.","그래서 ⟨84/10⟩ × ⟨1/4⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L02_basic#8','math',6,1,'u3','L02','g6_1_math_u3_L02_basic','lesson_basic','M6-1-u3-C1',2,'ox','auto','6.8 ÷ 2는 0.1이 68개인 것을 둘로 나누는 것과 같아요.',ARRAY['M6-1-u3-X03']::text[],true,'{"seq":8,"concept":"M6-1-u3-C1","difficulty":2,"kind":"ox","stem":"6.8 ÷ 2는 0.1이 68개인 것을 둘로 나누는 것과 같아요.","answer":"O","reason_options":[{"t":"6.8은 0.1이 68개인 수이기 때문에","correct":true},{"t":"6.8은 0.1이 6개와 8개를 합한 수이기 때문에","mis":"M6-1-u3-X03"}],"mis":"M6-1-u3-X03","explanation":["소수는 0.1이나 0.01이 몇 개인 수로 볼 수 있어요.","나누는 수가 같을 때 나누어지는 수가 ⟨1/10⟩배가 되면 몫도 ⟨1/10⟩배가 돼요.","분수의 나눗셈으로 바꾸면 ÷ 자연수는 × 자연수분의 1이에요."],"variant_rule":{"alt":[{"stem":"나누는 수가 같을 때 나누어지는 수가 ⟨1/10⟩배가 되면 몫도 ⟨1/10⟩배가 돼요.","answer":"O","reason_options":[{"t":"나눌 양이 ⟨1/10⟩로 줄면 한 묶음의 양도 ⟨1/10⟩로 줄기 때문에","correct":true},{"t":"나누는 수가 같으면 몫도 언제나 같기 때문에","mis":"M6-1-u3-X01"}],"explanation":["소수는 0.1이나 0.01이 몇 개인 수로 볼 수 있어요.","나누는 수가 같을 때 나누어지는 수가 ⟨1/10⟩배가 되면 몫도 ⟨1/10⟩배가 돼요.","분수의 나눗셈으로 바꾸면 ÷ 자연수는 × 자연수분의 1이에요."]},{"stem":"846 ÷ 2 = 423이면 84.6 ÷ 2 = 42.3이에요.","answer":"O","reason_options":[{"t":"84.6은 846의 ⟨1/10⟩배라서 몫도 ⟨1/10⟩배이기 때문에","correct":true},{"t":"나누어지는 수가 작아지면 몫은 커지기 때문에","mis":"M6-1-u3-X02"}],"explanation":["소수는 0.1이나 0.01이 몇 개인 수로 볼 수 있어요.","나누는 수가 같을 때 나누어지는 수가 ⟨1/10⟩배가 되면 몫도 ⟨1/10⟩배가 돼요.","분수의 나눗셈으로 바꾸면 ÷ 자연수는 × 자연수분의 1이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L02_basic#9','math',6,1,'u3','L02','g6_1_math_u3_L02_basic','lesson_basic','M6-1-u3-C1',2,'mc','auto','걷기 대회 코스는 모두 6.8 km예요. 반환점은 코스의 정확히 절반 지점에 있어요. 반환점까지는 몇 km인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02','M6-1-u3-X10']::text[],true,'{"seq":9,"concept":"M6-1-u3-C1","difficulty":2,"kind":"mc","stem":"걷기 대회 코스는 모두 6.8 km예요. 반환점은 코스의 정확히 절반 지점에 있어요. 반환점까지는 몇 km인가요?","options":[{"t":"3.4 km","correct":true},{"t":"34 km","mis":"M6-1-u3-X01"},{"t":"0.34 km","mis":"M6-1-u3-X02"},{"t":"13.6 km","mis":"M6-1-u3-X10"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 68 ÷ 2 = 34예요.","6.8은 68의 ⟨1/10⟩배라서 몫도 34의 ⟨1/10⟩배예요.","6.8 ÷ 2 = 3.4예요."],"variant_rule":{"alt":[{"stem":"길이가 3.6 m인 끈을 똑같이 잘라 기념품 상자 3개를 묶어요. 상자 한 개에 쓰는 끈은 몇 m인가요?","options":[{"t":"1.2 m","correct":true},{"t":"12 m","mis":"M6-1-u3-X01"},{"t":"0.12 m","mis":"M6-1-u3-X02"},{"t":"10.8 m","mis":"M6-1-u3-X10"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 36 ÷ 3 = 12예요.","3.6은 36의 ⟨1/10⟩배라서 몫도 12의 ⟨1/10⟩배예요.","3.6 ÷ 3 = 1.2예요."]},{"stem":"리본 9.6 m를 세 명이 똑같이 나누어 가져요. 한 명이 가지는 리본은 몇 m인가요?","options":[{"t":"3.2 m","correct":true},{"t":"32 m","mis":"M6-1-u3-X01"},{"t":"0.32 m","mis":"M6-1-u3-X02"},{"t":"28.8 m","mis":"M6-1-u3-X10"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 96 ÷ 3 = 32예요.","9.6은 96의 ⟨1/10⟩배라서 몫도 32의 ⟨1/10⟩배예요.","9.6 ÷ 3 = 3.2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L02_basic#10','math',6,1,'u3','L02','g6_1_math_u3_L02_basic','lesson_basic','M6-1-u3-C1',3,'sa','auto','리본 0.96 m를 세 명이 똑같이 나누어 가져요. 한 명이 가지는 리본은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u3-C1","difficulty":3,"kind":"sa","stem":"리본 0.96 m를 세 명이 똑같이 나누어 가져요. 한 명이 가지는 리본은 몇 cm인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["0.96 ÷ 3 = 0.32예요.","1 m는 100 cm예요.","0.32 m는 32 cm예요."],"mis":"M6-1-u3-X11","variant_rule":{"alt":[{"stem":"리본 0.84 m를 네 명이 똑같이 나누어 가져요. 한 명이 가지는 리본은 몇 cm인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["0.84 ÷ 4 = 0.21이에요.","1 m는 100 cm예요.","0.21 m는 21 cm예요."]},{"stem":"리본 0.69 m를 세 명이 똑같이 나누어 가져요. 한 명이 가지는 리본은 몇 cm인가요? 숫자로 쓰세요.","answer":["23"],"explanation":["0.69 ÷ 3 = 0.23이에요.","1 m는 100 cm예요.","0.23 m는 23 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L02_challenge#1','math',6,1,'u3','L02','g6_1_math_u3_L02_challenge','lesson_challenge','M6-1-u3-C1',2,'mc','auto','684 ÷ 2 = 342예요. 그러면 68.4 ÷ 2의 몫은 얼마인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":1,"concept":"M6-1-u3-C1","difficulty":2,"kind":"mc","stem":"684 ÷ 2 = 342예요. 그러면 68.4 ÷ 2의 몫은 얼마인가요?","options":[{"t":"34.2","correct":true},{"t":"342","mis":"M6-1-u3-X01"},{"t":"3.42","mis":"M6-1-u3-X02"},{"t":"3420","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 2는 그대로예요.","나누어지는 수 68.4는 684의 ⟨1/10⟩배예요.","그래서 몫도 342의 ⟨1/10⟩배 — 34.2예요."],"variant_rule":{"alt":[{"stem":"963 ÷ 3 = 321이에요. 그러면 96.3 ÷ 3의 몫은 얼마인가요?","options":[{"t":"32.1","correct":true},{"t":"321","mis":"M6-1-u3-X01"},{"t":"3.21","mis":"M6-1-u3-X02"},{"t":"3210","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 3은 그대로예요.","나누어지는 수 96.3은 963의 ⟨1/10⟩배예요.","그래서 몫도 321의 ⟨1/10⟩배 — 32.1이에요."]},{"stem":"488 ÷ 4 = 122예요. 그러면 48.8 ÷ 4의 몫은 얼마인가요?","options":[{"t":"12.2","correct":true},{"t":"122","mis":"M6-1-u3-X01"},{"t":"1.22","mis":"M6-1-u3-X02"},{"t":"1220","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 4는 그대로예요.","나누어지는 수 48.8은 488의 ⟨1/10⟩배예요.","그래서 몫도 122의 ⟨1/10⟩배 — 12.2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L02_challenge#2','math',6,1,'u3','L02','g6_1_math_u3_L02_challenge','lesson_challenge','M6-1-u3-C1',2,'mc','auto','1단원에서 배운 대로 계산하면 ⟨3/4⟩ ÷ 5는 얼마인가요?',ARRAY['M6-1-u3-X04','M6-1-u3-X13']::text[],true,'{"seq":2,"concept":"M6-1-u3-C1","difficulty":2,"kind":"mc","stem":"1단원에서 배운 대로 계산하면 ⟨3/4⟩ ÷ 5는 얼마인가요?","options":[{"t":"⟨3/20⟩","correct":true},{"t":"⟨15/4⟩","mis":"M6-1-u3-X04"},{"t":"⟨4/15⟩","mis":"M6-1-u3-X04"},{"t":"⟨3/9⟩","mis":"M6-1-u3-X13"}],"explanation":["÷ 5를 × ⟨1/5⟩로 바꾸어요.","⟨3/4⟩ × ⟨1/5⟩ = ⟨3/20⟩이에요.","분자는 그대로, 분모에 5를 곱했어요."],"variant_rule":{"alt":[{"stem":"1단원에서 배운 대로 계산하면 ⟨2/5⟩ ÷ 3은 얼마인가요?","options":[{"t":"⟨2/15⟩","correct":true},{"t":"⟨6/5⟩","mis":"M6-1-u3-X04"},{"t":"⟨5/6⟩","mis":"M6-1-u3-X04"},{"t":"⟨2/8⟩","mis":"M6-1-u3-X13"}],"explanation":["÷ 3을 × ⟨1/3⟩로 바꾸어요.","⟨2/5⟩ × ⟨1/3⟩ = ⟨2/15⟩예요.","분자는 그대로, 분모에 3을 곱했어요."]},{"stem":"1단원에서 배운 대로 계산하면 ⟨5/6⟩ ÷ 2는 얼마인가요?","options":[{"t":"⟨5/12⟩","correct":true},{"t":"⟨10/6⟩","mis":"M6-1-u3-X04"},{"t":"⟨6/10⟩","mis":"M6-1-u3-X04"},{"t":"⟨5/8⟩","mis":"M6-1-u3-X13"}],"explanation":["÷ 2를 × ⟨1/2⟩로 바꾸어요.","⟨5/6⟩ × ⟨1/2⟩ = ⟨5/12⟩예요.","분자는 그대로, 분모에 2를 곱했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L02_challenge#3','math',6,1,'u3','L02','g6_1_math_u3_L02_challenge','lesson_challenge','M6-1-u3-C1',3,'error','auto','648 ÷ 2 = 324를 이용해 64.8 ÷ 2를 계산하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X14']::text[],true,'{"seq":3,"concept":"M6-1-u3-C1","difficulty":3,"kind":"error","stem":"648 ÷ 2 = 324를 이용해 64.8 ÷ 2를 계산하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「나누어지는 수가 작아졌으니 몫은 324의 10배야.」","correct":true,"mis_target":"M6-1-u3-X01"},{"t":"이현 — 「64.8은 648의 ⟨1/10⟩배야.」","mis":"M6-1-u3-X14"},{"t":"서아 — 「몫은 32.4야.」","mis":"M6-1-u3-X14"}],"explanation":["나누는 수 2는 그대로예요.","나누어지는 수가 ⟨1/10⟩배가 되면 몫도 ⟨1/10⟩배예요.","준희는 몫이 커진다고 거꾸로 말했어요."],"variant_rule":{"alt":[{"stem":"393 ÷ 3 = 131을 이용해 3.93 ÷ 3을 계산하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「나누어지는 수가 작아졌으니 몫은 131의 10배야.」","correct":true,"mis_target":"M6-1-u3-X01"},{"t":"수아 — 「3.93은 393의 ⟨1/100⟩배야.」","mis":"M6-1-u3-X14"},{"t":"도윤 — 「몫은 1.31이야.」","mis":"M6-1-u3-X14"}],"explanation":["나누는 수 3은 그대로예요.","나누어지는 수가 ⟨1/100⟩배가 되면 몫도 ⟨1/100⟩배예요.","서호는 몫이 커진다고 거꾸로 말했어요."]},{"stem":"846 ÷ 2 = 423을 이용해 84.6 ÷ 2를 계산하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「나누어지는 수가 작아졌으니 몫은 423의 10배야.」","correct":true,"mis_target":"M6-1-u3-X01"},{"t":"나린 — 「84.6은 846의 ⟨1/10⟩배야.」","mis":"M6-1-u3-X14"},{"t":"유진 — 「몫은 42.3이야.」","mis":"M6-1-u3-X14"}],"explanation":["나누는 수 2는 그대로예요.","나누어지는 수가 ⟨1/10⟩배가 되면 몫도 ⟨1/10⟩배예요.","가온은 몫이 커진다고 거꾸로 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L02_challenge#4','math',6,1,'u3','L02','g6_1_math_u3_L02_challenge','lesson_challenge','M6-1-u3-C1',3,'mc','auto','둘레가 8.48 m인 정사각형 모양이 있어요. 한 변의 길이는 몇 m인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02','M6-1-u3-X10']::text[],true,'{"seq":4,"concept":"M6-1-u3-C1","difficulty":3,"kind":"mc","stem":"둘레가 8.48 m인 정사각형 모양이 있어요. 한 변의 길이는 몇 m인가요?","options":[{"t":"2.12 m","correct":true},{"t":"21.2 m","mis":"M6-1-u3-X01"},{"t":"0.212 m","mis":"M6-1-u3-X02"},{"t":"33.92 m","mis":"M6-1-u3-X10"}],"explanation":["정사각형은 4개의 변의 길이가 모두 같아요.","한 변의 길이는 둘레를 변의 수로 나누어 구해요.","8.48 ÷ 4 = 2.12예요."],"variant_rule":{"alt":[{"stem":"둘레가 99.63 cm인 정삼각형 모양이 있어요. 한 변의 길이는 몇 cm인가요?","options":[{"t":"33.21 cm","correct":true},{"t":"332.1 cm","mis":"M6-1-u3-X01"},{"t":"3.321 cm","mis":"M6-1-u3-X02"},{"t":"298.89 cm","mis":"M6-1-u3-X10"}],"explanation":["정삼각형은 3개의 변의 길이가 모두 같아요.","한 변의 길이는 둘레를 변의 수로 나누어 구해요.","99.63 ÷ 3 = 33.21이에요."]},{"stem":"둘레가 12.5 m인 정오각형 모양이 있어요. 한 변의 길이는 몇 m인가요?","options":[{"t":"2.5 m","correct":true},{"t":"25 m","mis":"M6-1-u3-X01"},{"t":"0.25 m","mis":"M6-1-u3-X02"},{"t":"62.5 m","mis":"M6-1-u3-X10"}],"explanation":["정오각형은 5개의 변의 길이가 모두 같아요.","한 변의 길이는 둘레를 변의 수로 나누어 구해요.","12.5 ÷ 5 = 2.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L02_challenge#5','math',6,1,'u3','L02','g6_1_math_u3_L02_challenge','lesson_challenge','M6-1-u3-C1',3,'ox','auto','648 ÷ 2 = 324이면 6.48 ÷ 2 = 32.4예요.',ARRAY['M6-1-u3-X02']::text[],true,'{"seq":5,"concept":"M6-1-u3-C1","difficulty":3,"kind":"ox","stem":"648 ÷ 2 = 324이면 6.48 ÷ 2 = 32.4예요.","answer":"X","reason_options":[{"t":"6.48은 648의 ⟨1/100⟩배라서 몫도 ⟨1/100⟩배인 3.24이기 때문에","correct":true},{"t":"나누어지는 수의 소수점을 한 칸만 옮기면 되기 때문에","mis":"M6-1-u3-X02"}],"mis":"M6-1-u3-X02","explanation":["소수는 0.1이나 0.01이 몇 개인 수로 볼 수 있어요.","나누는 수가 같을 때 나누어지는 수가 ⟨1/10⟩배가 되면 몫도 ⟨1/10⟩배가 돼요.","분수의 나눗셈으로 바꾸면 ÷ 자연수는 × 자연수분의 1이에요."],"variant_rule":{"alt":[{"stem":"3.6 ÷ 3은 ⟨36/10⟩ × 3으로 계산해요.","answer":"X","reason_options":[{"t":"÷ 3은 × ⟨1/3⟩로 바꾸어야 하기 때문에","correct":true},{"t":"÷ 자연수는 × 자연수로 바꾸기 때문에","mis":"M6-1-u3-X04"}],"explanation":["소수는 0.1이나 0.01이 몇 개인 수로 볼 수 있어요.","나누는 수가 같을 때 나누어지는 수가 ⟨1/10⟩배가 되면 몫도 ⟨1/10⟩배가 돼요.","분수의 나눗셈으로 바꾸면 ÷ 자연수는 × 자연수분의 1이에요."]},{"stem":"9.6 ÷ 3의 몫은 3보다 커요.","answer":"O","reason_options":[{"t":"9.6은 9보다 크니 몫도 9 ÷ 3 = 3보다 크기 때문에","correct":true},{"t":"9.6은 소수라서 몫이 1보다 작기 때문에","mis":"M6-1-u3-X12"}],"explanation":["소수는 0.1이나 0.01이 몇 개인 수로 볼 수 있어요.","나누는 수가 같을 때 나누어지는 수가 ⟨1/10⟩배가 되면 몫도 ⟨1/10⟩배가 돼요.","분수의 나눗셈으로 바꾸면 ÷ 자연수는 × 자연수분의 1이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L02_challenge#6','math',6,1,'u3','L02','g6_1_math_u3_L02_challenge','lesson_challenge','M6-1-u3-C1',3,'mc','auto','쌀 84.88 kg을 자루 4개에 똑같이 나누어 담았어요. 자루 한 개에 담긴 쌀은 몇 kg인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02','M6-1-u3-X10']::text[],true,'{"seq":6,"concept":"M6-1-u3-C1","difficulty":3,"kind":"mc","stem":"쌀 84.88 kg을 자루 4개에 똑같이 나누어 담았어요. 자루 한 개에 담긴 쌀은 몇 kg인가요?","options":[{"t":"21.22 kg","correct":true},{"t":"212.2 kg","mis":"M6-1-u3-X01"},{"t":"2.122 kg","mis":"M6-1-u3-X02"},{"t":"339.52 kg","mis":"M6-1-u3-X10"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 8488 ÷ 4 = 2122예요.","84.88은 8488의 ⟨1/100⟩배라서 몫도 2122의 ⟨1/100⟩배예요.","84.88 ÷ 4 = 21.22예요."],"variant_rule":{"alt":[{"stem":"쌀 48.84 kg을 자루 4개에 똑같이 나누어 담았어요. 자루 한 개에 담긴 쌀은 몇 kg인가요?","options":[{"t":"12.21 kg","correct":true},{"t":"122.1 kg","mis":"M6-1-u3-X01"},{"t":"1.221 kg","mis":"M6-1-u3-X02"},{"t":"195.36 kg","mis":"M6-1-u3-X10"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 4884 ÷ 4 = 1221이에요.","48.84는 4884의 ⟨1/100⟩배라서 몫도 1221의 ⟨1/100⟩배예요.","48.84 ÷ 4 = 12.21이에요."]},{"stem":"쌀 88.48 kg을 자루 4개에 똑같이 나누어 담았어요. 자루 한 개에 담긴 쌀은 몇 kg인가요?","options":[{"t":"22.12 kg","correct":true},{"t":"221.2 kg","mis":"M6-1-u3-X01"},{"t":"2.212 kg","mis":"M6-1-u3-X02"},{"t":"353.92 kg","mis":"M6-1-u3-X10"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 8848 ÷ 4 = 2212예요.","88.48은 8848의 ⟨1/100⟩배라서 몫도 2212의 ⟨1/100⟩배예요.","88.48 ÷ 4 = 22.12예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L02_challenge#7','math',6,1,'u3','L02','g6_1_math_u3_L02_challenge','lesson_challenge','M6-1-u3-C1',3,'match','auto','나눗셈식과 몫을 알맞게 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u3-C1","difficulty":3,"kind":"match","stem":"나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"64.8 ÷ 2","r":"32.4"},{"l":"3.93 ÷ 3","r":"1.31"},{"l":"4.88 ÷ 4","r":"1.22"}],"mis":"M6-1-u3-X02","explanation":["자연수의 나눗셈으로 몫을 구한 뒤 같은 배율만큼 작게 해요.","64.8 ÷ 2 = 32.4, 3.93 ÷ 3 = 1.31, 4.88 ÷ 4 = 1.22예요.","어림한 값과 견주어 소수점 자리를 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"84.6 ÷ 2","r":"42.3"},{"l":"9.36 ÷ 3","r":"3.12"},{"l":"48.8 ÷ 4","r":"12.2"}],"explanation":["자연수의 나눗셈으로 몫을 구한 뒤 같은 배율만큼 작게 해요.","84.6 ÷ 2 = 42.3, 9.36 ÷ 3 = 3.12, 48.8 ÷ 4 = 12.2예요.","어림한 값과 견주어 소수점 자리를 확인해요."]},{"stem":"이번에는 다른 보기예요. 나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"6.48 ÷ 2","r":"3.24"},{"l":"39.3 ÷ 3","r":"13.1"},{"l":"8.84 ÷ 4","r":"2.21"}],"explanation":["자연수의 나눗셈으로 몫을 구한 뒤 같은 배율만큼 작게 해요.","6.48 ÷ 2 = 3.24, 39.3 ÷ 3 = 13.1, 8.84 ÷ 4 = 2.21이에요.","어림한 값과 견주어 소수점 자리를 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L02_challenge#8','math',6,1,'u3','L02','g6_1_math_u3_L02_challenge','lesson_challenge','M6-1-u3-C1',4,'mc','auto','846 ÷ 2의 몫은 8.46 ÷ 2의 몫의 몇 배인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":8,"concept":"M6-1-u3-C1","difficulty":4,"kind":"mc","stem":"846 ÷ 2의 몫은 8.46 ÷ 2의 몫의 몇 배인가요?","options":[{"t":"100배","correct":true},{"t":"10배","mis":"M6-1-u3-X01"},{"t":"1000배","mis":"M6-1-u3-X01"},{"t":"⟨1/10⟩배","mis":"M6-1-u3-X02"}],"explanation":["두 나눗셈은 나누는 수 2가 같아요.","나누어지는 수 846은 8.46의 100배예요.","그래서 몫도 100배예요 — 423과 4.23이에요."],"variant_rule":{"alt":[{"stem":"4.88 ÷ 4의 몫은 48.8 ÷ 4의 몫의 몇 배인가요?","options":[{"t":"⟨1/10⟩배","correct":true},{"t":"10배","mis":"M6-1-u3-X01"},{"t":"100배","mis":"M6-1-u3-X01"},{"t":"1000배","mis":"M6-1-u3-X01"}],"explanation":["두 나눗셈은 나누는 수 4가 같아요.","나누어지는 수 4.88은 48.8의 ⟨1/10⟩배예요.","그래서 몫도 ⟨1/10⟩배예요 — 1.22와 12.2예요."]},{"stem":"3.93 ÷ 3의 몫은 393 ÷ 3의 몫의 몇 배인가요?","options":[{"t":"⟨1/100⟩배","correct":true},{"t":"10배","mis":"M6-1-u3-X01"},{"t":"100배","mis":"M6-1-u3-X01"},{"t":"1000배","mis":"M6-1-u3-X01"}],"explanation":["두 나눗셈은 나누는 수 3이 같아요.","나누어지는 수 3.93은 393의 ⟨1/100⟩배예요.","그래서 몫도 ⟨1/100⟩배예요 — 1.31과 131이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L02_challenge#9','math',6,1,'u3','L02','g6_1_math_u3_L02_challenge','lesson_challenge','M6-1-u3-C1',4,'sa','auto','2.48을 네 묶음으로 똑같이 나누어요. 한 묶음은 0.01이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u3-C1","difficulty":4,"kind":"sa","stem":"2.48을 네 묶음으로 똑같이 나누어요. 한 묶음은 0.01이 몇 개인가요? 숫자로 쓰세요.","answer":["62"],"explanation":["2.48은 0.01이 248개인 수예요.","248 ÷ 4 = 62 — 한 묶음은 0.01이 62개예요.","0.01이 62개이면 0.62예요."],"mis":"M6-1-u3-X03","variant_rule":{"alt":[{"stem":"1.86을 세 묶음으로 똑같이 나누어요. 한 묶음은 0.01이 몇 개인가요? 숫자로 쓰세요.","answer":["62"],"explanation":["1.86은 0.01이 186개인 수예요.","186 ÷ 3 = 62 — 한 묶음은 0.01이 62개예요.","0.01이 62개이면 0.62예요."]},{"stem":"2.94를 세 묶음으로 똑같이 나누어요. 한 묶음은 0.01이 몇 개인가요? 숫자로 쓰세요.","answer":["98"],"explanation":["2.94는 0.01이 294개인 수예요.","294 ÷ 3 = 98 — 한 묶음은 0.01이 98개예요.","0.01이 98개이면 0.98이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L02_challenge#10','math',6,1,'u3','L02','g6_1_math_u3_L02_challenge','lesson_challenge','M6-1-u3-C1',4,'essay','teacher','걷기 대회 코스는 6.8 km이고 반환점은 코스의 정확히 절반 지점에 있어요. 반환점까지의 거리를 「0.1이 몇 개」로 생각하여 구하고, 그 거리가 몇 m인지도 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u3-C1","difficulty":4,"kind":"essay","stem":"걷기 대회 코스는 6.8 km이고 반환점은 코스의 정확히 절반 지점에 있어요. 반환점까지의 거리를 「0.1이 몇 개」로 생각하여 구하고, 그 거리가 몇 m인지도 써 보세요.","answer_guide":{"answer":"예: 6.8은 0.1이 68개인 수이다. 68개를 둘로 똑같이 나누면 34개이고, 0.1이 34개이면 3.4이므로 반환점까지는 3.4 km이다. 1 km는 1000 m이므로 3.4 km는 3400 m이다.","scoring_points":["6.8을 0.1이 68개로 보았는가","68 ÷ 2 = 34로 3.4 km를 구했는가","3400 m로 바꾸었는가"]},"explanation":["6.8은 0.1이 68개예요.","68 ÷ 2 = 34 — 3.4 km예요.","3.4 km는 3400 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L03_basic#1','math',6,1,'u3','L03','g6_1_math_u3_L03_basic','lesson_basic','M6-1-u3-C2',1,'mc','auto','492 ÷ 4 = 123이에요. 그러면 49.2 ÷ 4의 몫은 얼마인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":1,"concept":"M6-1-u3-C2","difficulty":1,"kind":"mc","stem":"492 ÷ 4 = 123이에요. 그러면 49.2 ÷ 4의 몫은 얼마인가요?","options":[{"t":"12.3","correct":true},{"t":"123","mis":"M6-1-u3-X01"},{"t":"1.23","mis":"M6-1-u3-X02"},{"t":"1230","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 4는 그대로예요.","나누어지는 수 49.2는 492의 ⟨1/10⟩배예요.","그래서 몫도 123의 ⟨1/10⟩배 — 12.3이에요."],"variant_rule":{"alt":[{"stem":"1379 ÷ 7 = 197이에요. 그러면 13.79 ÷ 7의 몫은 얼마인가요?","options":[{"t":"1.97","correct":true},{"t":"19.7","mis":"M6-1-u3-X01"},{"t":"0.197","mis":"M6-1-u3-X02"},{"t":"197","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 7은 그대로예요.","나누어지는 수 13.79는 1379의 ⟨1/100⟩배예요.","그래서 몫도 197의 ⟨1/100⟩배 — 1.97이에요."]},{"stem":"585 ÷ 5 = 117이에요. 그러면 58.5 ÷ 5의 몫은 얼마인가요?","options":[{"t":"11.7","correct":true},{"t":"117","mis":"M6-1-u3-X01"},{"t":"1.17","mis":"M6-1-u3-X02"},{"t":"1170","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 5는 그대로예요.","나누어지는 수 58.5는 585의 ⟨1/10⟩배예요.","그래서 몫도 117의 ⟨1/10⟩배 — 11.7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L03_basic#2','math',6,1,'u3','L03','g6_1_math_u3_L03_basic','lesson_basic','M6-1-u3-C2',1,'mc','auto','11.7 ÷ 3의 몫은 얼마인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":2,"concept":"M6-1-u3-C2","difficulty":1,"kind":"mc","stem":"11.7 ÷ 3의 몫은 얼마인가요?","options":[{"t":"3.9","correct":true},{"t":"39","mis":"M6-1-u3-X01"},{"t":"0.39","mis":"M6-1-u3-X02"},{"t":"390","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 117 ÷ 3 = 39예요.","11.7은 117의 ⟨1/10⟩배라서 몫도 39의 ⟨1/10⟩배예요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 11.7 ÷ 3 = 3.9예요."],"variant_rule":{"alt":[{"stem":"34.5 ÷ 5의 몫은 얼마인가요?","options":[{"t":"6.9","correct":true},{"t":"69","mis":"M6-1-u3-X01"},{"t":"0.69","mis":"M6-1-u3-X02"},{"t":"690","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 345 ÷ 5 = 69예요.","34.5는 345의 ⟨1/10⟩배라서 몫도 69의 ⟨1/10⟩배예요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 34.5 ÷ 5 = 6.9예요."]},{"stem":"49.2 ÷ 4의 몫은 얼마인가요?","options":[{"t":"12.3","correct":true},{"t":"123","mis":"M6-1-u3-X01"},{"t":"1.23","mis":"M6-1-u3-X02"},{"t":"1230","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 492 ÷ 4 = 123이에요.","49.2는 492의 ⟨1/10⟩배라서 몫도 123의 ⟨1/10⟩배예요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 49.2 ÷ 4 = 12.3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L03_basic#3','math',6,1,'u3','L03','g6_1_math_u3_L03_basic','lesson_basic','M6-1-u3-C1',1,'sa','auto','117 ÷ 3의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u3-C1","difficulty":1,"kind":"sa","stem":"117 ÷ 3의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["39"],"explanation":["자연수의 나눗셈은 높은 자리부터 나누고 남은 수를 다음 자리로 내려요.","39 × 3 = 117로 확인할 수 있어요.","117 ÷ 3 = 39예요."],"mis":"M6-1-u3-X13","variant_rule":{"alt":[{"stem":"138 ÷ 6의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["23"],"explanation":["자연수의 나눗셈은 높은 자리부터 나누고 남은 수를 다음 자리로 내려요.","23 × 6 = 138로 확인할 수 있어요.","138 ÷ 6 = 23이에요."]},{"stem":"172 ÷ 4의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["43"],"explanation":["자연수의 나눗셈은 높은 자리부터 나누고 남은 수를 다음 자리로 내려요.","43 × 4 = 172로 확인할 수 있어요.","172 ÷ 4 = 43이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L03_basic#4','math',6,1,'u3','L03','g6_1_math_u3_L03_basic','lesson_basic','M6-1-u3-C2',1,'sa','auto','34.5 ÷ 5의 몫에서 소수 첫째 자리 숫자는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u3-C2","difficulty":1,"kind":"sa","stem":"34.5 ÷ 5의 몫에서 소수 첫째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 345 ÷ 5 = 69예요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 34.5 ÷ 5 = 6.9예요.","6.9의 소수 첫째 자리 숫자는 9예요."],"mis":"M6-1-u3-X13","variant_rule":{"alt":[{"stem":"11.7 ÷ 3의 몫에서 소수 첫째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 117 ÷ 3 = 39예요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 11.7 ÷ 3 = 3.9예요.","3.9의 소수 첫째 자리 숫자는 9예요."]},{"stem":"49.2 ÷ 4의 몫에서 소수 첫째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 492 ÷ 4 = 123이에요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 49.2 ÷ 4 = 12.3이에요.","12.3의 소수 첫째 자리 숫자는 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L03_basic#5','math',6,1,'u3','L03','g6_1_math_u3_L03_basic','lesson_basic','M6-1-u3-C2',2,'mc','auto','13.79 ÷ 7의 몫은 얼마인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":5,"concept":"M6-1-u3-C2","difficulty":2,"kind":"mc","stem":"13.79 ÷ 7의 몫은 얼마인가요?","options":[{"t":"1.97","correct":true},{"t":"19.7","mis":"M6-1-u3-X01"},{"t":"0.197","mis":"M6-1-u3-X02"},{"t":"197","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1379 ÷ 7 = 197이에요.","13.79는 1379의 ⟨1/100⟩배라서 몫도 197의 ⟨1/100⟩배예요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 13.79 ÷ 7 = 1.97이에요."],"variant_rule":{"alt":[{"stem":"19.56 ÷ 2의 몫은 얼마인가요?","options":[{"t":"9.78","correct":true},{"t":"97.8","mis":"M6-1-u3-X01"},{"t":"0.978","mis":"M6-1-u3-X02"},{"t":"978","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1956 ÷ 2 = 978이에요.","19.56은 1956의 ⟨1/100⟩배라서 몫도 978의 ⟨1/100⟩배예요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 19.56 ÷ 2 = 9.78이에요."]},{"stem":"5.88 ÷ 4의 몫은 얼마인가요?","options":[{"t":"1.47","correct":true},{"t":"14.7","mis":"M6-1-u3-X01"},{"t":"0.147","mis":"M6-1-u3-X02"},{"t":"147","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 588 ÷ 4 = 147이에요.","5.88은 588의 ⟨1/100⟩배라서 몫도 147의 ⟨1/100⟩배예요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 5.88 ÷ 4 = 1.47이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L03_basic#6','math',6,1,'u3','L03','g6_1_math_u3_L03_basic','lesson_basic','M6-1-u3-C2',2,'mc','auto','식혜 11.7 L를 병 3개에 똑같이 나누어 담았어요. 병 하나에 담긴 식혜는 몇 mL인가요?',ARRAY['M6-1-u3-X11']::text[],true,'{"seq":6,"concept":"M6-1-u3-C2","difficulty":2,"kind":"mc","stem":"식혜 11.7 L를 병 3개에 똑같이 나누어 담았어요. 병 하나에 담긴 식혜는 몇 mL인가요?","options":[{"t":"3900 mL","correct":true},{"t":"390 mL","mis":"M6-1-u3-X11"},{"t":"39000 mL","mis":"M6-1-u3-X11"},{"t":"39 mL","mis":"M6-1-u3-X11"}],"explanation":["11.7 ÷ 3 = 3.9 (L)예요.","1 L는 1000 mL예요.","3.9 L는 3900 mL예요."],"variant_rule":{"alt":[{"stem":"식혜 13.5 L를 병 5개에 똑같이 나누어 담았어요. 병 하나에 담긴 식혜는 몇 mL인가요?","options":[{"t":"2700 mL","correct":true},{"t":"270 mL","mis":"M6-1-u3-X11"},{"t":"27000 mL","mis":"M6-1-u3-X11"},{"t":"27 mL","mis":"M6-1-u3-X11"}],"explanation":["13.5 ÷ 5 = 2.7 (L)예요.","1 L는 1000 mL예요.","2.7 L는 2700 mL예요."]},{"stem":"수정과 7.2 L를 병 3개에 똑같이 나누어 담았어요. 병 하나에 담긴 수정과는 몇 mL인가요?","options":[{"t":"2400 mL","correct":true},{"t":"240 mL","mis":"M6-1-u3-X11"},{"t":"24000 mL","mis":"M6-1-u3-X11"},{"t":"24 mL","mis":"M6-1-u3-X11"}],"explanation":["7.2 ÷ 3 = 2.4 (L)예요.","1 L는 1000 mL예요.","2.4 L는 2400 mL예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L03_basic#7','math',6,1,'u3','L03','g6_1_math_u3_L03_basic','lesson_basic','M6-1-u3-C2',2,'mc','auto','(소수)÷(자연수)를 세로로 계산할 때 몫의 소수점은 어디에 찍나요?',ARRAY['M6-1-u3-X01','M6-1-u3-X13','M6-1-u3-X02']::text[],true,'{"seq":7,"concept":"M6-1-u3-C2","difficulty":2,"kind":"mc","stem":"(소수)÷(자연수)를 세로로 계산할 때 몫의 소수점은 어디에 찍나요?","options":[{"t":"나누어지는 수의 소수점 바로 위","correct":true},{"t":"몫의 맨 끝","mis":"M6-1-u3-X01"},{"t":"나누는 수의 바로 위","mis":"M6-1-u3-X13"},{"t":"몫의 맨 앞","mis":"M6-1-u3-X02"}],"explanation":["(소수)÷(자연수)는 자연수의 나눗셈과 계산 과정이 똑같아요.","달라진 것은 나누어지는 수가 ⟨1/10⟩배·⟨1/100⟩배라는 것뿐이에요.","그래서 몫의 소수점은 나누어지는 수의 소수점 위에 그대로 올려 찍어요."],"variant_rule":{"alt":[{"stem":"11.7 ÷ 3을 세로로 계산할 때 몫의 소수점은 어디에 찍나요?","options":[{"t":"11.7의 소수점 바로 위","correct":true},{"t":"몫의 맨 끝","mis":"M6-1-u3-X01"},{"t":"3의 바로 위","mis":"M6-1-u3-X13"},{"t":"몫의 일의 자리 앞","mis":"M6-1-u3-X02"}],"explanation":["(소수)÷(자연수)는 자연수의 나눗셈과 계산 과정이 똑같아요.","달라진 것은 나누어지는 수가 ⟨1/10⟩배·⟨1/100⟩배라는 것뿐이에요.","그래서 몫의 소수점은 나누어지는 수의 소수점 위에 그대로 올려 찍어요."]},{"stem":"34.5 ÷ 5와 345 ÷ 5의 세로셈은 무엇이 다른가요?","options":[{"t":"몫에 소수점을 찍는 것만 달라요","correct":true},{"t":"나누는 방법이 완전히 달라요","mis":"M6-1-u3-X13"},{"t":"몫의 숫자가 달라요","mis":"M6-1-u3-X01"},{"t":"나머지를 버리는 것이 달라요","mis":"M6-1-u3-X13"}],"explanation":["(소수)÷(자연수)는 자연수의 나눗셈과 계산 과정이 똑같아요.","달라진 것은 나누어지는 수가 ⟨1/10⟩배·⟨1/100⟩배라는 것뿐이에요.","그래서 몫의 소수점은 나누어지는 수의 소수점 위에 그대로 올려 찍어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L03_basic#8','math',6,1,'u3','L03','g6_1_math_u3_L03_basic','lesson_basic','M6-1-u3-C2',2,'ox','auto','34.5 ÷ 5와 345 ÷ 5는 계산 과정이 같고 몫의 소수점만 달라요.',ARRAY['M6-1-u3-X01']::text[],true,'{"seq":8,"concept":"M6-1-u3-C2","difficulty":2,"kind":"ox","stem":"34.5 ÷ 5와 345 ÷ 5는 계산 과정이 같고 몫의 소수점만 달라요.","answer":"O","reason_options":[{"t":"34.5는 345의 ⟨1/10⟩배라 몫도 ⟨1/10⟩배이기 때문에","correct":true},{"t":"소수의 나눗셈은 방법이 완전히 다르기 때문에","mis":"M6-1-u3-X01"}],"mis":"M6-1-u3-X01","explanation":["각 자리에서 나누어떨어지지 않아도 자연수의 나눗셈과 똑같이 계산해요.","몫의 소수점은 나누어지는 수의 소수점 위에 올려 찍어요.","어림한 값과 견주면 소수점 자리를 확인할 수 있어요."],"variant_rule":{"alt":[{"stem":"11.7 ÷ 3의 몫은 약 4예요.","answer":"O","reason_options":[{"t":"11.7을 12로 어림하면 12 ÷ 3 = 4이기 때문에","correct":true},{"t":"11.7을 1로 어림해야 하기 때문에","mis":"M6-1-u3-X12"}],"explanation":["각 자리에서 나누어떨어지지 않아도 자연수의 나눗셈과 똑같이 계산해요.","몫의 소수점은 나누어지는 수의 소수점 위에 올려 찍어요.","어림한 값과 견주면 소수점 자리를 확인할 수 있어요."]},{"stem":"세로셈에서 몫의 소수점은 나누어지는 수의 소수점 바로 위에 찍어요.","answer":"O","reason_options":[{"t":"자연수의 나눗셈과 과정이 같고 나누어지는 수만 ⟨1/10⟩배이기 때문에","correct":true},{"t":"나누는 수의 소수점에 맞추어 찍기 때문에","mis":"M6-1-u3-X01"}],"explanation":["각 자리에서 나누어떨어지지 않아도 자연수의 나눗셈과 똑같이 계산해요.","몫의 소수점은 나누어지는 수의 소수점 위에 올려 찍어요.","어림한 값과 견주면 소수점 자리를 확인할 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L03_basic#9','math',6,1,'u3','L03','g6_1_math_u3_L03_basic','lesson_basic','M6-1-u3-C2',2,'mc','auto','11.7을 12로 어림하면 12 ÷ 3 = 4예요. 11.7 ÷ 3의 몫으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02','M6-1-u3-X13']::text[],true,'{"seq":9,"concept":"M6-1-u3-C2","difficulty":2,"kind":"mc","stem":"11.7을 12로 어림하면 12 ÷ 3 = 4예요. 11.7 ÷ 3의 몫으로 알맞은 것은 어느 것인가요?","options":[{"t":"3.9","correct":true},{"t":"39","mis":"M6-1-u3-X01"},{"t":"0.39","mis":"M6-1-u3-X02"},{"t":"4.9","mis":"M6-1-u3-X13"}],"explanation":["어림한 몫은 4쯤이에요.","자연수의 나눗셈으로 바꾸어 봐요 — 117 ÷ 3 = 39예요.","3.9는 4에 가까워요 — 몫은 3.9예요."],"variant_rule":{"alt":[{"stem":"34.5를 35로 어림하면 35 ÷ 5 = 7이에요. 34.5 ÷ 5의 몫으로 알맞은 것은 어느 것인가요?","options":[{"t":"6.9","correct":true},{"t":"69","mis":"M6-1-u3-X01"},{"t":"0.69","mis":"M6-1-u3-X02"},{"t":"7.9","mis":"M6-1-u3-X13"}],"explanation":["어림한 몫은 7쯤이에요.","자연수의 나눗셈으로 바꾸어 봐요 — 345 ÷ 5 = 69예요.","6.9는 7에 가까워요 — 몫은 6.9예요."]},{"stem":"25.2를 24로 어림하면 24 ÷ 4 = 6이에요. 25.2 ÷ 4의 몫으로 알맞은 것은 어느 것인가요?","options":[{"t":"6.3","correct":true},{"t":"63","mis":"M6-1-u3-X01"},{"t":"0.63","mis":"M6-1-u3-X02"},{"t":"7.3","mis":"M6-1-u3-X13"}],"explanation":["어림한 몫은 6쯤이에요.","자연수의 나눗셈으로 바꾸어 봐요 — 252 ÷ 4 = 63이에요.","6.3은 6에 가까워요 — 몫은 6.3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L03_basic#10','math',6,1,'u3','L03','g6_1_math_u3_L03_basic','lesson_basic','M6-1-u3-C2',3,'sa','auto','넓이가 25.2 cm²이고 밑변이 4 cm인 평행사변형이 있어요. 이 평행사변형의 높이는 몇 mm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u3-C2","difficulty":3,"kind":"sa","stem":"넓이가 25.2 cm²이고 밑변이 4 cm인 평행사변형이 있어요. 이 평행사변형의 높이는 몇 mm인가요? 숫자로 쓰세요.","answer":["63"],"explanation":["평행사변형의 넓이 = 밑변 × 높이이니 높이 = 넓이 ÷ 밑변이에.","25.2 ÷ 4 = 6.3 (cm)예요.","1 cm는 10 mm라서 6.3 cm는 63 mm예요."],"mis":"M6-1-u3-X11","variant_rule":{"alt":[{"stem":"넓이가 34.5 cm²이고 밑변이 5 cm인 평행사변형이 있어요. 이 평행사변형의 높이는 몇 mm인가요? 숫자로 쓰세요.","answer":["69"],"explanation":["평행사변형의 넓이 = 밑변 × 높이이니 높이 = 넓이 ÷ 밑변이에.","34.5 ÷ 5 = 6.9 (cm)예요.","1 cm는 10 mm라서 6.9 cm는 69 mm예요."]},{"stem":"넓이가 29.4 cm²이고 밑변이 7 cm인 평행사변형이 있어요. 이 평행사변형의 높이는 몇 mm인가요? 숫자로 쓰세요.","answer":["42"],"explanation":["평행사변형의 넓이 = 밑변 × 높이이니 높이 = 넓이 ÷ 밑변이에.","29.4 ÷ 7 = 4.2 (cm)예요.","1 cm는 10 mm라서 4.2 cm는 42 mm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L03_challenge#1','math',6,1,'u3','L03','g6_1_math_u3_L03_challenge','lesson_challenge','M6-1-u3-C2',2,'mc','auto','22.68 ÷ 4의 몫은 얼마인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":1,"concept":"M6-1-u3-C2","difficulty":2,"kind":"mc","stem":"22.68 ÷ 4의 몫은 얼마인가요?","options":[{"t":"5.67","correct":true},{"t":"56.7","mis":"M6-1-u3-X01"},{"t":"0.567","mis":"M6-1-u3-X02"},{"t":"567","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 2268 ÷ 4 = 567이에요.","22.68은 2268의 ⟨1/100⟩배라서 몫도 567의 ⟨1/100⟩배예요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 22.68 ÷ 4 = 5.67이에요."],"variant_rule":{"alt":[{"stem":"15.84 ÷ 6의 몫은 얼마인가요?","options":[{"t":"2.64","correct":true},{"t":"26.4","mis":"M6-1-u3-X01"},{"t":"0.264","mis":"M6-1-u3-X02"},{"t":"264","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1584 ÷ 6 = 264예요.","15.84는 1584의 ⟨1/100⟩배라서 몫도 264의 ⟨1/100⟩배예요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 15.84 ÷ 6 = 2.64예요."]},{"stem":"17.34 ÷ 2의 몫은 얼마인가요?","options":[{"t":"8.67","correct":true},{"t":"86.7","mis":"M6-1-u3-X01"},{"t":"0.867","mis":"M6-1-u3-X02"},{"t":"867","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1734 ÷ 2 = 867이에요.","17.34는 1734의 ⟨1/100⟩배라서 몫도 867의 ⟨1/100⟩배예요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 17.34 ÷ 2 = 8.67이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L03_challenge#2','math',6,1,'u3','L03','g6_1_math_u3_L03_challenge','lesson_challenge','M6-1-u3-C2',2,'sa','auto','13.79 ÷ 7의 몫에서 소수 둘째 자리 숫자는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u3-C2","difficulty":2,"kind":"sa","stem":"13.79 ÷ 7의 몫에서 소수 둘째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1379 ÷ 7 = 197이에요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 13.79 ÷ 7 = 1.97이에요.","1.97의 소수 둘째 자리 숫자는 7이에요."],"mis":"M6-1-u3-X13","variant_rule":{"alt":[{"stem":"22.68 ÷ 4의 몫에서 소수 둘째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 2268 ÷ 4 = 567이에요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 22.68 ÷ 4 = 5.67이에요.","5.67의 소수 둘째 자리 숫자는 7이에요."]},{"stem":"15.84 ÷ 6의 몫에서 소수 둘째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1584 ÷ 6 = 264예요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 15.84 ÷ 6 = 2.64예요.","2.64의 소수 둘째 자리 숫자는 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L03_challenge#3','math',6,1,'u3','L03','g6_1_math_u3_L03_challenge','lesson_challenge','M6-1-u3-C2',3,'mc','auto','친구가 34.5 ÷ 5를 세로로 계산해 몫을 69라고 썼어요. 잘못된 곳은 어디인가요?',ARRAY['M6-1-u3-X13']::text[],true,'{"seq":3,"concept":"M6-1-u3-C2","difficulty":3,"kind":"mc","stem":"친구가 34.5 ÷ 5를 세로로 계산해 몫을 69라고 썼어요. 잘못된 곳은 어디인가요?","options":[{"t":"몫에 소수점을 찍지 않았어요","correct":true},{"t":"나누어지는 수를 잘못 썼어요","mis":"M6-1-u3-X13"},{"t":"곱셈을 잘못했어요","mis":"M6-1-u3-X13"},{"t":"뺄셈을 잘못했어요","mis":"M6-1-u3-X13"}],"explanation":["345 ÷ 5 = 69는 맞게 계산했어요.","나누어지는 수 34.5의 소수점을 몫에 올려 찍지 않았어요.","바른 몫은 6.9예요."],"variant_rule":{"alt":[{"stem":"친구가 11.7 ÷ 3을 세로로 계산해 몫을 39라고 썼어요. 잘못된 곳은 어디인가요?","options":[{"t":"몫에 소수점을 찍지 않았어요","correct":true},{"t":"나누어지는 수를 잘못 썼어요","mis":"M6-1-u3-X13"},{"t":"곱셈을 잘못했어요","mis":"M6-1-u3-X13"},{"t":"뺄셈을 잘못했어요","mis":"M6-1-u3-X13"}],"explanation":["117 ÷ 3 = 39는 맞게 계산했어요.","나누어지는 수 11.7의 소수점을 몫에 올려 찍지 않았어요.","바른 몫은 3.9예요."]},{"stem":"친구가 22.68 ÷ 4를 세로로 계산해 몫을 567이라고 썼어요. 잘못된 곳은 어디인가요?","options":[{"t":"몫에 소수점을 찍지 않았어요","correct":true},{"t":"나누어지는 수를 잘못 썼어요","mis":"M6-1-u3-X13"},{"t":"곱셈을 잘못했어요","mis":"M6-1-u3-X13"},{"t":"뺄셈을 잘못했어요","mis":"M6-1-u3-X13"}],"explanation":["2268 ÷ 4 = 567은 맞게 계산했어요.","나누어지는 수 22.68의 소수점을 몫에 올려 찍지 않았어요.","바른 몫은 5.67이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L03_challenge#4','math',6,1,'u3','L03','g6_1_math_u3_L03_challenge','lesson_challenge','M6-1-u3-C2',3,'mc','auto','현의 길이가 반으로 줄면 한 옥타브 높은 소리가 나요. 현의 길이가 19.56 cm일 때 한 옥타브 높은 소리를 내는 현의 길이는 몇 cm인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02','M6-1-u3-X10']::text[],true,'{"seq":4,"concept":"M6-1-u3-C2","difficulty":3,"kind":"mc","stem":"현의 길이가 반으로 줄면 한 옥타브 높은 소리가 나요. 현의 길이가 19.56 cm일 때 한 옥타브 높은 소리를 내는 현의 길이는 몇 cm인가요?","options":[{"t":"9.78 cm","correct":true},{"t":"97.8 cm","mis":"M6-1-u3-X01"},{"t":"0.978 cm","mis":"M6-1-u3-X02"},{"t":"39.12 cm","mis":"M6-1-u3-X10"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1956 ÷ 2 = 978이에요.","19.56은 1956의 ⟨1/100⟩배라서 몫도 978의 ⟨1/100⟩배예요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 19.56 ÷ 2 = 9.78이에요."],"variant_rule":{"alt":[{"stem":"현의 길이가 반으로 줄면 한 옥타브 높은 소리가 나요. 현의 길이가 17.34 cm일 때 한 옥타브 높은 소리를 내는 현의 길이는 몇 cm인가요?","options":[{"t":"8.67 cm","correct":true},{"t":"86.7 cm","mis":"M6-1-u3-X01"},{"t":"0.867 cm","mis":"M6-1-u3-X02"},{"t":"34.68 cm","mis":"M6-1-u3-X10"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1734 ÷ 2 = 867이에요.","17.34는 1734의 ⟨1/100⟩배라서 몫도 867의 ⟨1/100⟩배예요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 17.34 ÷ 2 = 8.67이에요."]},{"stem":"현의 길이가 반으로 줄면 한 옥타브 높은 소리가 나요. 현의 길이가 25.38 cm일 때 한 옥타브 높은 소리를 내는 현의 길이는 몇 cm인가요?","options":[{"t":"12.69 cm","correct":true},{"t":"126.9 cm","mis":"M6-1-u3-X01"},{"t":"1.269 cm","mis":"M6-1-u3-X02"},{"t":"50.76 cm","mis":"M6-1-u3-X10"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 2538 ÷ 2 = 1269예요.","25.38은 2538의 ⟨1/100⟩배라서 몫도 1269의 ⟨1/100⟩배예요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 25.38 ÷ 2 = 12.69예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L03_challenge#5','math',6,1,'u3','L03','g6_1_math_u3_L03_challenge','lesson_challenge','M6-1-u3-C2',3,'ox','auto','11.7 ÷ 3에서 십의 자리 1은 3으로 나누어지지 않으니 몫을 구할 수 없어요.',ARRAY['M6-1-u3-X13']::text[],true,'{"seq":5,"concept":"M6-1-u3-C2","difficulty":3,"kind":"ox","stem":"11.7 ÷ 3에서 십의 자리 1은 3으로 나누어지지 않으니 몫을 구할 수 없어요.","answer":"X","reason_options":[{"t":"11을 3으로 나누고 남은 수를 다음 자리로 내려 계산하면 되기 때문에","correct":true},{"t":"각 자리가 나누어떨어져야만 나눌 수 있기 때문에","mis":"M6-1-u3-X13"}],"mis":"M6-1-u3-X13","explanation":["각 자리에서 나누어떨어지지 않아도 자연수의 나눗셈과 똑같이 계산해요.","몫의 소수점은 나누어지는 수의 소수점 위에 올려 찍어요.","어림한 값과 견주면 소수점 자리를 확인할 수 있어요."],"variant_rule":{"alt":[{"stem":"49.2 ÷ 4의 몫은 123이에요.","answer":"X","reason_options":[{"t":"몫의 소수점을 49.2의 소수점 위에 찍어 12.3이기 때문에","correct":true},{"t":"소수점은 나머지가 있을 때만 찍기 때문에","mis":"M6-1-u3-X01"}],"explanation":["각 자리에서 나누어떨어지지 않아도 자연수의 나눗셈과 똑같이 계산해요.","몫의 소수점은 나누어지는 수의 소수점 위에 올려 찍어요.","어림한 값과 견주면 소수점 자리를 확인할 수 있어요."]},{"stem":"19.56 ÷ 2의 몫은 97.8이에요.","answer":"X","reason_options":[{"t":"19.56은 1956의 ⟨1/100⟩배라 몫은 9.78이기 때문에","correct":true},{"t":"19.56을 20으로 어림하면 100에 가깝기 때문에","mis":"M6-1-u3-X01"}],"explanation":["각 자리에서 나누어떨어지지 않아도 자연수의 나눗셈과 똑같이 계산해요.","몫의 소수점은 나누어지는 수의 소수점 위에 올려 찍어요.","어림한 값과 견주면 소수점 자리를 확인할 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L03_challenge#6','math',6,1,'u3','L03','g6_1_math_u3_L03_challenge','lesson_challenge','M6-1-u3-C2',3,'error','auto','49.2 ÷ 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X14']::text[],true,'{"seq":6,"concept":"M6-1-u3-C2","difficulty":3,"kind":"error","stem":"49.2 ÷ 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「몫은 123이야.」","correct":true,"mis_target":"M6-1-u3-X01"},{"t":"이현 — 「492 ÷ 4를 계산한 몫의 ⟨1/10⟩배야.」","mis":"M6-1-u3-X14"},{"t":"서아 — 「몫의 소수점은 49.2의 소수점 위에 찍어.」","mis":"M6-1-u3-X14"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 492 ÷ 4 = 123이에요.","49.2는 492의 ⟨1/10⟩배라서 몫도 123의 ⟨1/10⟩배예요.","준희는 몫의 소수점을 한 자리 뒤에 찍었어요 — 바른 몫은 12.3이에요."],"variant_rule":{"alt":[{"stem":"13.79 ÷ 7을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「몫은 19.7이야.」","correct":true,"mis_target":"M6-1-u3-X01"},{"t":"수아 — 「137.9 ÷ 7을 계산한 몫의 ⟨1/10⟩배야.」","mis":"M6-1-u3-X14"},{"t":"도윤 — 「몫의 소수점은 13.79의 소수점 위에 찍어.」","mis":"M6-1-u3-X14"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1379 ÷ 7 = 197이에요.","13.79는 1379의 ⟨1/100⟩배라서 몫도 197의 ⟨1/100⟩배예요.","서호는 몫의 소수점을 한 자리 뒤에 찍었어요 — 바른 몫은 1.97이에요."]},{"stem":"34.5 ÷ 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「몫은 69야.」","correct":true,"mis_target":"M6-1-u3-X01"},{"t":"나린 — 「345 ÷ 5를 계산한 몫의 ⟨1/10⟩배야.」","mis":"M6-1-u3-X14"},{"t":"유진 — 「몫의 소수점은 34.5의 소수점 위에 찍어.」","mis":"M6-1-u3-X14"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 345 ÷ 5 = 69예요.","34.5는 345의 ⟨1/10⟩배라서 몫도 69의 ⟨1/10⟩배예요.","가온은 몫의 소수점을 한 자리 뒤에 찍었어요 — 바른 몫은 6.9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L03_challenge#7','math',6,1,'u3','L03','g6_1_math_u3_L03_challenge','lesson_challenge','M6-1-u3-C1',3,'match','auto','나눗셈식과 몫을 알맞게 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u3-C1","difficulty":3,"kind":"match","stem":"나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"11.7 ÷ 3","r":"3.9"},{"l":"34.5 ÷ 5","r":"6.9"},{"l":"49.2 ÷ 4","r":"12.3"}],"mis":"M6-1-u3-X02","explanation":["자연수의 나눗셈으로 몫을 구한 뒤 같은 배율만큼 작게 해요.","11.7 ÷ 3 = 3.9, 34.5 ÷ 5 = 6.9, 49.2 ÷ 4 = 12.3이에요.","어림한 값과 견주어 소수점 자리를 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"13.79 ÷ 7","r":"1.97"},{"l":"19.56 ÷ 2","r":"9.78"},{"l":"5.88 ÷ 4","r":"1.47"}],"explanation":["자연수의 나눗셈으로 몫을 구한 뒤 같은 배율만큼 작게 해요.","13.79 ÷ 7 = 1.97, 19.56 ÷ 2 = 9.78, 5.88 ÷ 4 = 1.47이에요.","어림한 값과 견주어 소수점 자리를 확인해요."]},{"stem":"이번에는 다른 보기예요. 나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"22.68 ÷ 4","r":"5.67"},{"l":"15.84 ÷ 6","r":"2.64"},{"l":"25.38 ÷ 2","r":"12.69"}],"explanation":["자연수의 나눗셈으로 몫을 구한 뒤 같은 배율만큼 작게 해요.","22.68 ÷ 4 = 5.67, 15.84 ÷ 6 = 2.64, 25.38 ÷ 2 = 12.69예요.","어림한 값과 견주어 소수점 자리를 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L03_challenge#8','math',6,1,'u3','L03','g6_1_math_u3_L03_challenge','lesson_challenge','M6-1-u3-C2',4,'mc','auto','어떤 수를 4로 나누었더니 몫이 12.3이 되었어요. 어떤 수를 3으로 나눈 몫은 얼마인가요?',ARRAY['M6-1-u3-X14','M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":8,"concept":"M6-1-u3-C2","difficulty":4,"kind":"mc","stem":"어떤 수를 4로 나누었더니 몫이 12.3이 되었어요. 어떤 수를 3으로 나눈 몫은 얼마인가요?","options":[{"t":"16.4","correct":true},{"t":"49.2","mis":"M6-1-u3-X14"},{"t":"164","mis":"M6-1-u3-X01"},{"t":"1.64","mis":"M6-1-u3-X02"}],"explanation":["어떤 수는 12.3 × 4 = 49.2예요.","이제 49.2 ÷ 3을 계산해요.","49.2 ÷ 3 = 16.4예요."],"variant_rule":{"alt":[{"stem":"어떤 수를 6으로 나누었더니 몫이 2.3이 되었어요. 어떤 수를 3으로 나눈 몫은 얼마인가요?","options":[{"t":"4.6","correct":true},{"t":"13.8","mis":"M6-1-u3-X14"},{"t":"46","mis":"M6-1-u3-X01"},{"t":"0.46","mis":"M6-1-u3-X02"}],"explanation":["어떤 수는 2.3 × 6 = 13.8이에요.","이제 13.8 ÷ 3을 계산해요.","13.8 ÷ 3 = 4.6이에요."]},{"stem":"어떤 수를 5로 나누었더니 몫이 6.9가 되었어요. 어떤 수를 3으로 나눈 몫은 얼마인가요?","options":[{"t":"11.5","correct":true},{"t":"34.5","mis":"M6-1-u3-X14"},{"t":"115","mis":"M6-1-u3-X01"},{"t":"1.15","mis":"M6-1-u3-X02"}],"explanation":["어떤 수는 6.9 × 5 = 34.5예요.","이제 34.5 ÷ 3을 계산해요.","34.5 ÷ 3 = 11.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L03_challenge#9','math',6,1,'u3','L03','g6_1_math_u3_L03_challenge','lesson_challenge','M6-1-u3-C2',4,'sa','auto','넓이가 45.6 cm²이고 가로가 8 cm인 직사각형이 있어요. 이 직사각형의 세로는 몇 mm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u3-C2","difficulty":4,"kind":"sa","stem":"넓이가 45.6 cm²이고 가로가 8 cm인 직사각형이 있어요. 이 직사각형의 세로는 몇 mm인가요? 숫자로 쓰세요.","answer":["57"],"explanation":["직사각형의 넓이 = 가로 × 세로이니 세로 = 넓이 ÷ 가로요예요.","45.6 ÷ 8 = 5.7 (cm)예요.","1 cm는 10 mm라서 5.7 cm는 57 mm예요."],"mis":"M6-1-u3-X11","variant_rule":{"alt":[{"stem":"넓이가 38.4 cm²이고 가로가 6 cm인 직사각형이 있어요. 이 직사각형의 세로는 몇 mm인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["직사각형의 넓이 = 가로 × 세로이니 세로 = 넓이 ÷ 가로요예요.","38.4 ÷ 6 = 6.4 (cm)예요.","1 cm는 10 mm라서 6.4 cm는 64 mm예요."]},{"stem":"넓이가 52.2 cm²이고 가로가 9 cm인 직사각형이 있어요. 이 직사각형의 세로는 몇 mm인가요? 숫자로 쓰세요.","answer":["58"],"explanation":["직사각형의 넓이 = 가로 × 세로이니 세로 = 넓이 ÷ 가로요예요.","52.2 ÷ 9 = 5.8 (cm)예요.","1 cm는 10 mm라서 5.8 cm는 58 mm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L03_challenge#10','math',6,1,'u3','L03','g6_1_math_u3_L03_challenge','lesson_challenge','M6-1-u3-C2',4,'essay','teacher','전통 음식 체험장에서 만든 식혜 11.7 L를 병 3개에 똑같이 나누어 담아요. 몫을 먼저 어림한 뒤 세로셈으로 계산하는 방법을 쓰고, 한 병에 담긴 식혜가 몇 L인지 구해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u3-C2","difficulty":4,"kind":"essay","stem":"전통 음식 체험장에서 만든 식혜 11.7 L를 병 3개에 똑같이 나누어 담아요. 몫을 먼저 어림한 뒤 세로셈으로 계산하는 방법을 쓰고, 한 병에 담긴 식혜가 몇 L인지 구해 보세요.","answer_guide":{"answer":"예: 11.7을 12로 어림하면 12 ÷ 3 = 4이므로 몫은 4쯤이다. 117 ÷ 3과 똑같이 세로로 계산하면 39이고, 몫의 소수점은 11.7의 소수점 위에 찍어 3.9이다. 한 병에 3.9 L씩 담는다.","scoring_points":["12 ÷ 3 = 4로 어림했는가","자연수의 나눗셈과 같이 계산하고 소수점을 나누어지는 수의 소수점 위에 찍었는가","3.9 L를 구했는가"]},"explanation":["12 ÷ 3 = 4로 어림해요.","117 ÷ 3 = 39이고 소수점을 올려 찍어요.","한 병에 3.9 L예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L04_basic#1','math',6,1,'u3','L04','g6_1_math_u3_L04_basic','lesson_basic','M6-1-u3-C3',1,'mc','auto','3.2 ÷ 4의 몫은 얼마인가요?',ARRAY['M6-1-u3-X05','M6-1-u3-X02','M6-1-u3-X01']::text[],true,'{"seq":1,"concept":"M6-1-u3-C3","difficulty":1,"kind":"mc","stem":"3.2 ÷ 4의 몫은 얼마인가요?","options":[{"t":"0.8","correct":true},{"t":"8","mis":"M6-1-u3-X05"},{"t":"0.08","mis":"M6-1-u3-X02"},{"t":"80","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 32 ÷ 4 = 8이에요.","3.2는 32의 ⟨1/10⟩배라서 몫도 8의 ⟨1/10⟩배예요.","몫이 1보다 작으니 일의 자리에 0을 써서 자리를 지켜요 — 3.2 ÷ 4 = 0.8이에요."],"variant_rule":{"alt":[{"stem":"5.6 ÷ 7의 몫은 얼마인가요?","options":[{"t":"0.8","correct":true},{"t":"8","mis":"M6-1-u3-X05"},{"t":"0.08","mis":"M6-1-u3-X02"},{"t":"80","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 56 ÷ 7 = 8이에요.","5.6은 56의 ⟨1/10⟩배라서 몫도 8의 ⟨1/10⟩배예요.","몫이 1보다 작으니 일의 자리에 0을 써서 자리를 지켜요 — 5.6 ÷ 7 = 0.8이에요."]},{"stem":"4.5 ÷ 9의 몫은 얼마인가요?","options":[{"t":"0.5","correct":true},{"t":"5","mis":"M6-1-u3-X05"},{"t":"0.05","mis":"M6-1-u3-X02"},{"t":"50","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 45 ÷ 9 = 5예요.","4.5는 45의 ⟨1/10⟩배라서 몫도 5의 ⟨1/10⟩배예요.","몫이 1보다 작으니 일의 자리에 0을 써서 자리를 지켜요 — 4.5 ÷ 9 = 0.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L04_basic#2','math',6,1,'u3','L04','g6_1_math_u3_L04_basic','lesson_basic','M6-1-u3-C1',1,'sa','auto','32 ÷ 4의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u3-C1","difficulty":1,"kind":"sa","stem":"32 ÷ 4의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["자연수의 나눗셈은 높은 자리부터 나누고 남은 수를 다음 자리로 내려요.","8 × 4 = 32로 확인할 수 있어요.","32 ÷ 4 = 8이에요."],"mis":"M6-1-u3-X13","variant_rule":{"alt":[{"stem":"56 ÷ 7의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["자연수의 나눗셈은 높은 자리부터 나누고 남은 수를 다음 자리로 내려요.","8 × 7 = 56으로 확인할 수 있어요.","56 ÷ 7 = 8이에요."]},{"stem":"45 ÷ 9의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["자연수의 나눗셈은 높은 자리부터 나누고 남은 수를 다음 자리로 내려요.","5 × 9 = 45로 확인할 수 있어요.","45 ÷ 9 = 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L04_basic#3','math',6,1,'u3','L04','g6_1_math_u3_L04_basic','lesson_basic','M6-1-u3-C3',1,'mc','auto','572 ÷ 11 = 52예요. 그러면 5.72 ÷ 11의 몫은 얼마인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":3,"concept":"M6-1-u3-C3","difficulty":1,"kind":"mc","stem":"572 ÷ 11 = 52예요. 그러면 5.72 ÷ 11의 몫은 얼마인가요?","options":[{"t":"0.52","correct":true},{"t":"5.2","mis":"M6-1-u3-X01"},{"t":"0.052","mis":"M6-1-u3-X02"},{"t":"52","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 11은 그대로예요.","나누어지는 수 5.72는 572의 ⟨1/100⟩배예요.","그래서 몫도 52의 ⟨1/100⟩배 — 0.52예요."],"variant_rule":{"alt":[{"stem":"384 ÷ 8 = 48이에요. 그러면 3.84 ÷ 8의 몫은 얼마인가요?","options":[{"t":"0.48","correct":true},{"t":"4.8","mis":"M6-1-u3-X01"},{"t":"0.048","mis":"M6-1-u3-X02"},{"t":"48","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 8은 그대로예요.","나누어지는 수 3.84는 384의 ⟨1/100⟩배예요.","그래서 몫도 48의 ⟨1/100⟩배 — 0.48이에요."]},{"stem":"195 ÷ 3 = 65예요. 그러면 1.95 ÷ 3의 몫은 얼마인가요?","options":[{"t":"0.65","correct":true},{"t":"6.5","mis":"M6-1-u3-X01"},{"t":"0.065","mis":"M6-1-u3-X02"},{"t":"65","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 3은 그대로예요.","나누어지는 수 1.95는 195의 ⟨1/100⟩배예요.","그래서 몫도 65의 ⟨1/100⟩배 — 0.65예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L04_basic#4','math',6,1,'u3','L04','g6_1_math_u3_L04_basic','lesson_basic','M6-1-u3-C3',1,'mc','auto','3.2 ÷ 4의 몫은 1보다 클까요, 작을까요?',ARRAY['M6-1-u3-X12']::text[],true,'{"seq":4,"concept":"M6-1-u3-C3","difficulty":1,"kind":"mc","stem":"3.2 ÷ 4의 몫은 1보다 클까요, 작을까요?","options":[{"t":"1보다 작아요","correct":true},{"t":"1보다 커요","mis":"M6-1-u3-X12"},{"t":"1과 같아요","mis":"M6-1-u3-X12"},{"t":"계산해 보기 전에는 알 수 없어요","mis":"M6-1-u3-X12"}],"explanation":["나누어지는 수 3.2가 나누는 수 4보다 작아요.","4 ÷ 4 = 1이니 3.2 ÷ 4는 1보다 작아요.","실제로 몫은 0.8이에요."],"variant_rule":{"alt":[{"stem":"5.6 ÷ 7의 몫은 1보다 클까요, 작을까요?","options":[{"t":"1보다 작아요","correct":true},{"t":"1보다 커요","mis":"M6-1-u3-X12"},{"t":"1과 같아요","mis":"M6-1-u3-X12"},{"t":"계산해 보기 전에는 알 수 없어요","mis":"M6-1-u3-X12"}],"explanation":["나누어지는 수 5.6이 나누는 수 7보다 작아요.","7 ÷ 7 = 1이니 5.6 ÷ 7은 1보다 작아요.","실제로 몫은 0.8이에요."]},{"stem":"6.3 ÷ 9의 몫은 1보다 클까요, 작을까요?","options":[{"t":"1보다 작아요","correct":true},{"t":"1보다 커요","mis":"M6-1-u3-X12"},{"t":"1과 같아요","mis":"M6-1-u3-X12"},{"t":"계산해 보기 전에는 알 수 없어요","mis":"M6-1-u3-X12"}],"explanation":["나누어지는 수 6.3이 나누는 수 9보다 작아요.","9 ÷ 9 = 1이니 6.3 ÷ 9는 1보다 작아요.","실제로 몫은 0.7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L04_basic#5','math',6,1,'u3','L04','g6_1_math_u3_L04_basic','lesson_basic','M6-1-u3-C3',2,'sa','auto','2.38 ÷ 7의 몫에서 소수 둘째 자리 숫자는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u3-C3","difficulty":2,"kind":"sa","stem":"2.38 ÷ 7의 몫에서 소수 둘째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 238 ÷ 7 = 34예요.","몫이 1보다 작으니 일의 자리에 0을 써서 자리를 지켜요 — 2.38 ÷ 7 = 0.34예요.","0.34의 소수 둘째 자리 숫자는 4예요."],"mis":"M6-1-u3-X13","variant_rule":{"alt":[{"stem":"3.15 ÷ 5의 몫에서 소수 둘째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 315 ÷ 5 = 63이에요.","몫이 1보다 작으니 일의 자리에 0을 써서 자리를 지켜요 — 3.15 ÷ 5 = 0.63이에요.","0.63의 소수 둘째 자리 숫자는 3이에요."]},{"stem":"4.32 ÷ 8의 몫에서 소수 둘째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 432 ÷ 8 = 54예요.","몫이 1보다 작으니 일의 자리에 0을 써서 자리를 지켜요 — 4.32 ÷ 8 = 0.54예요.","0.54의 소수 둘째 자리 숫자는 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L04_basic#6','math',6,1,'u3','L04','g6_1_math_u3_L04_basic','lesson_basic','M6-1-u3-C3',2,'mc','auto','다음 가운데 몫이 1보다 작은 나눗셈은 어느 것인가요?',ARRAY['M6-1-u3-X12']::text[],true,'{"seq":6,"concept":"M6-1-u3-C3","difficulty":2,"kind":"mc","stem":"다음 가운데 몫이 1보다 작은 나눗셈은 어느 것인가요?","options":[{"t":"7.29 ÷ 9","correct":true},{"t":"14.9 ÷ 5","mis":"M6-1-u3-X12"},{"t":"8.4 ÷ 8","mis":"M6-1-u3-X12"},{"t":"4.16 ÷ 4","mis":"M6-1-u3-X12"}],"explanation":["몫이 1보다 작으려면 나누어지는 수가 나누는 수보다 작아야 해요.","나누어지는 수와 나누는 수를 하나씩 견주어 봐요.","7.29 ÷ 9만 나누어지는 수가 더 작아요 — 몫은 0.81이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 가운데 몫이 1보다 작은 나눗셈은 어느 것인가요?","options":[{"t":"6.3 ÷ 7","correct":true},{"t":"9.6 ÷ 8","mis":"M6-1-u3-X12"},{"t":"5.5 ÷ 5","mis":"M6-1-u3-X12"},{"t":"12.6 ÷ 6","mis":"M6-1-u3-X12"}],"explanation":["몫이 1보다 작으려면 나누어지는 수가 나누는 수보다 작아야 해요.","나누어지는 수와 나누는 수를 하나씩 견주어 봐요.","6.3 ÷ 7만 나누어지는 수가 더 작아요 — 몫은 0.9예요."]},{"stem":"이번에는 다른 보기예요. 다음 가운데 몫이 1보다 작은 나눗셈은 어느 것인가요?","options":[{"t":"2.7 ÷ 3","correct":true},{"t":"7.2 ÷ 6","mis":"M6-1-u3-X12"},{"t":"4.4 ÷ 4","mis":"M6-1-u3-X12"},{"t":"8.1 ÷ 3","mis":"M6-1-u3-X12"}],"explanation":["몫이 1보다 작으려면 나누어지는 수가 나누는 수보다 작아야 해요.","나누어지는 수와 나누는 수를 하나씩 견주어 봐요.","2.7 ÷ 3만 나누어지는 수가 더 작아요 — 몫은 0.9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L04_basic#7','math',6,1,'u3','L04','g6_1_math_u3_L04_basic','lesson_basic','M6-1-u3-C3',2,'mc','auto','동물병원에서 몸무게를 재어 보니 강아지는 3.2 kg, 고양이는 4 kg이었어요. 강아지 몸무게는 고양이 몸무게의 몇 배인가요?',ARRAY['M6-1-u3-X05','M6-1-u3-X09','M6-1-u3-X02']::text[],true,'{"seq":7,"concept":"M6-1-u3-C3","difficulty":2,"kind":"mc","stem":"동물병원에서 몸무게를 재어 보니 강아지는 3.2 kg, 고양이는 4 kg이었어요. 강아지 몸무게는 고양이 몸무게의 몇 배인가요?","options":[{"t":"0.8배","correct":true},{"t":"8배","mis":"M6-1-u3-X05"},{"t":"1.25배","mis":"M6-1-u3-X09"},{"t":"0.08배","mis":"M6-1-u3-X02"}],"explanation":["「강아지는 고양이의 몇 배」니 3.2를 4로 나누어요.","자연수의 나눗셈으로 바꾸어 봐요 — 32 ÷ 4 = 8이에요.","몫이 1보다 작으니 일의 자리에 0을 써서 자리를 지켜요 — 3.2 ÷ 4 = 0.8이에요."],"variant_rule":{"alt":[{"stem":"동물병원에서 몸무게를 재어 보니 토끼는 2.7 kg, 강아지는 3 kg이었어요. 토끼 몸무게는 강아지 몸무게의 몇 배인가요?","options":[{"t":"0.9배","correct":true},{"t":"9배","mis":"M6-1-u3-X05"},{"t":"0.09배","mis":"M6-1-u3-X02"},{"t":"0.3배","mis":"M6-1-u3-X10"}],"explanation":["「토끼는 강아지의 몇 배」니 2.7을 3으로 나누어요.","자연수의 나눗셈으로 바꾸어 봐요 — 27 ÷ 3 = 9예요.","몫이 1보다 작으니 일의 자리에 0을 써서 자리를 지켜요 — 2.7 ÷ 3 = 0.9예요."]},{"stem":"동물병원에서 몸무게를 재어 보니 고양이는 4.2 kg, 강아지는 6 kg이었어요. 고양이 몸무게는 강아지 몸무게의 몇 배인가요?","options":[{"t":"0.7배","correct":true},{"t":"7배","mis":"M6-1-u3-X05"},{"t":"0.07배","mis":"M6-1-u3-X02"},{"t":"1.8배","mis":"M6-1-u3-X10"}],"explanation":["「고양이는 강아지의 몇 배」니 4.2를 6으로 나누어요.","자연수의 나눗셈으로 바꾸어 봐요 — 42 ÷ 6 = 7이에요.","몫이 1보다 작으니 일의 자리에 0을 써서 자리를 지켜요 — 4.2 ÷ 6 = 0.7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L04_basic#8','math',6,1,'u3','L04','g6_1_math_u3_L04_basic','lesson_basic','M6-1-u3-C3',2,'mc','auto','3.2 ÷ 4의 몫 0.8에서 일의 자리 0을 지우면 어떻게 되나요?',ARRAY['M6-1-u3-X05','M6-1-u3-X02','M6-1-u3-X13']::text[],true,'{"seq":8,"concept":"M6-1-u3-C3","difficulty":2,"kind":"mc","stem":"3.2 ÷ 4의 몫 0.8에서 일의 자리 0을 지우면 어떻게 되나요?","options":[{"t":"8이 되어 10배나 큰 다른 수가 돼요","correct":true},{"t":"0.8 그대로예요","mis":"M6-1-u3-X05"},{"t":"0.08이 돼요","mis":"M6-1-u3-X02"},{"t":"1.8이 돼요","mis":"M6-1-u3-X13"}],"explanation":["몫이 1보다 작으면 일의 자리에 쓸 숫자가 없어요.","그 자리에 0을 써야 소수점이 제자리에 와요.","0은 자리를 지키는 숫자예요 — 0.8과 8은 10배 차이가 나요."],"variant_rule":{"alt":[{"stem":"몫이 1보다 작을 때 일의 자리에 0을 쓰는 까닭은 무엇인가요?","options":[{"t":"0이 자리를 지켜 소수점의 자리가 바르게 되기 때문에","correct":true},{"t":"보기 좋게 하려고","mis":"M6-1-u3-X05"},{"t":"몫이 1보다 커지기 때문에","mis":"M6-1-u3-X12"},{"t":"나머지를 나타내려고","mis":"M6-1-u3-X06"}],"explanation":["몫이 1보다 작으면 일의 자리에 쓸 숫자가 없어요.","그 자리에 0을 써야 소수점이 제자리에 와요.","0은 자리를 지키는 숫자예요 — 0.8과 8은 10배 차이가 나요."]},{"stem":"5.72 ÷ 11의 몫을 52라고 쓴 친구는 무엇을 빠뜨렸나요?","options":[{"t":"일의 자리 0과 소수점","correct":true},{"t":"나머지","mis":"M6-1-u3-X06"},{"t":"몫 가운데 0","mis":"M6-1-u3-X07"},{"t":"나누는 수","mis":"M6-1-u3-X13"}],"explanation":["몫이 1보다 작으면 일의 자리에 쓸 숫자가 없어요.","그 자리에 0을 써야 소수점이 제자리에 와요.","0은 자리를 지키는 숫자예요 — 0.8과 8은 10배 차이가 나요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L04_basic#9','math',6,1,'u3','L04','g6_1_math_u3_L04_basic','lesson_basic','M6-1-u3-C3',2,'ox','auto','3.2 ÷ 4의 몫은 1보다 작아요.',ARRAY['M6-1-u3-X12']::text[],true,'{"seq":9,"concept":"M6-1-u3-C3","difficulty":2,"kind":"ox","stem":"3.2 ÷ 4의 몫은 1보다 작아요.","answer":"O","reason_options":[{"t":"나누어지는 수 3.2가 나누는 수 4보다 작기 때문에","correct":true},{"t":"소수를 나누면 몫은 언제나 1보다 작기 때문에","mis":"M6-1-u3-X12"}],"mis":"M6-1-u3-X12","explanation":["나누어지는 수가 나누는 수보다 작으면 몫은 1보다 작아요.","이때 몫의 일의 자리에 0을 써요.","0은 자리를 지키는 숫자예요."],"variant_rule":{"alt":[{"stem":"몫이 1보다 작으면 일의 자리는 비워 두어도 돼요.","answer":"X","reason_options":[{"t":"일의 자리에 0을 써야 소수점이 제자리에 오기 때문에","correct":true},{"t":"0은 아무것도 없다는 뜻이라 쓰지 않아도 되기 때문에","mis":"M6-1-u3-X05"}],"explanation":["나누어지는 수가 나누는 수보다 작으면 몫은 1보다 작아요.","이때 몫의 일의 자리에 0을 써요.","0은 자리를 지키는 숫자예요."]},{"stem":"0.8과 8은 같은 수예요.","answer":"X","reason_options":[{"t":"0.8은 8의 ⟨1/10⟩배인 다른 수이기 때문에","correct":true},{"t":"앞의 0은 없어도 되는 숫자이기 때문에","mis":"M6-1-u3-X05"}],"explanation":["나누어지는 수가 나누는 수보다 작으면 몫은 1보다 작아요.","이때 몫의 일의 자리에 0을 써요.","0은 자리를 지키는 숫자예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L04_basic#10','math',6,1,'u3','L04','g6_1_math_u3_L04_basic','lesson_basic','M6-1-u3-C3',3,'sa','auto','0.□가 5.6 ÷ 8의 몫보다 작아요. □ 안에 들어갈 수 있는 가장 큰 자연수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u3-C3","difficulty":3,"kind":"sa","stem":"0.□가 5.6 ÷ 8의 몫보다 작아요. □ 안에 들어갈 수 있는 가장 큰 자연수는 무엇인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 56 ÷ 8 = 7이에요.","몫이 1보다 작으니 일의 자리에 0을 써서 자리를 지켜요 — 5.6 ÷ 8 = 0.7이에요.","0.7보다 작은 0.□ 가운데 가장 큰 것은 0.6 — □는 6이에요."],"mis":"M6-1-u3-X14","variant_rule":{"alt":[{"stem":"0.□가 5.4 ÷ 9의 몫보다 작아요. □ 안에 들어갈 수 있는 가장 큰 자연수는 무엇인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 54 ÷ 9 = 6이에요.","몫이 1보다 작으니 일의 자리에 0을 써서 자리를 지켜요 — 5.4 ÷ 9 = 0.6이에요.","0.6보다 작은 0.□ 가운데 가장 큰 것은 0.5 — □는 5예요."]},{"stem":"0.□가 6.4 ÷ 8의 몫보다 작아요. □ 안에 들어갈 수 있는 가장 큰 자연수는 무엇인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 64 ÷ 8 = 8이에요.","몫이 1보다 작으니 일의 자리에 0을 써서 자리를 지켜요 — 6.4 ÷ 8 = 0.8이에요.","0.8보다 작은 0.□ 가운데 가장 큰 것은 0.7 — □는 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L04_challenge#1','math',6,1,'u3','L04','g6_1_math_u3_L04_challenge','lesson_challenge','M6-1-u3-C2',2,'mc','auto','우유 1.44 L를 컵 4개에 똑같이 나누어 담았어요. 컵 하나에 담긴 우유는 몇 mL인가요?',ARRAY['M6-1-u3-X11']::text[],true,'{"seq":1,"concept":"M6-1-u3-C2","difficulty":2,"kind":"mc","stem":"우유 1.44 L를 컵 4개에 똑같이 나누어 담았어요. 컵 하나에 담긴 우유는 몇 mL인가요?","options":[{"t":"360 mL","correct":true},{"t":"36 mL","mis":"M6-1-u3-X11"},{"t":"3600 mL","mis":"M6-1-u3-X11"},{"t":"3.6 mL","mis":"M6-1-u3-X11"}],"explanation":["1.44 ÷ 4 = 0.36 (L)예요.","1 L는 1000 mL예요.","0.36 L는 360 mL예요."],"variant_rule":{"alt":[{"stem":"우유 1.35 L를 컵 3개에 똑같이 나누어 담았어요. 컵 하나에 담긴 우유는 몇 mL인가요?","options":[{"t":"450 mL","correct":true},{"t":"45 mL","mis":"M6-1-u3-X11"},{"t":"4500 mL","mis":"M6-1-u3-X11"},{"t":"4.5 mL","mis":"M6-1-u3-X11"}],"explanation":["1.35 ÷ 3 = 0.45 (L)예요.","1 L는 1000 mL예요.","0.45 L는 450 mL예요."]},{"stem":"우유 1.75 L를 컵 5개에 똑같이 나누어 담았어요. 컵 하나에 담긴 우유는 몇 mL인가요?","options":[{"t":"350 mL","correct":true},{"t":"35 mL","mis":"M6-1-u3-X11"},{"t":"3500 mL","mis":"M6-1-u3-X11"},{"t":"3.5 mL","mis":"M6-1-u3-X11"}],"explanation":["1.75 ÷ 5 = 0.35 (L)예요.","1 L는 1000 mL예요.","0.35 L는 350 mL예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L04_challenge#2','math',6,1,'u3','L04','g6_1_math_u3_L04_challenge','lesson_challenge','M6-1-u3-C3',2,'mc','auto','2.38 ÷ 7의 몫은 얼마인가요?',ARRAY['M6-1-u3-X05','M6-1-u3-X02','M6-1-u3-X01']::text[],true,'{"seq":2,"concept":"M6-1-u3-C3","difficulty":2,"kind":"mc","stem":"2.38 ÷ 7의 몫은 얼마인가요?","options":[{"t":"0.34","correct":true},{"t":"3.4","mis":"M6-1-u3-X05"},{"t":"0.034","mis":"M6-1-u3-X02"},{"t":"34","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 238 ÷ 7 = 34예요.","2.38은 238의 ⟨1/100⟩배라서 몫도 34의 ⟨1/100⟩배예요.","몫이 1보다 작으니 일의 자리에 0을 써서 자리를 지켜요 — 2.38 ÷ 7 = 0.34예요."],"variant_rule":{"alt":[{"stem":"5.72 ÷ 11의 몫은 얼마인가요?","options":[{"t":"0.52","correct":true},{"t":"5.2","mis":"M6-1-u3-X05"},{"t":"0.052","mis":"M6-1-u3-X02"},{"t":"52","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 572 ÷ 11 = 52예요.","5.72는 572의 ⟨1/100⟩배라서 몫도 52의 ⟨1/100⟩배예요.","몫이 1보다 작으니 일의 자리에 0을 써서 자리를 지켜요 — 5.72 ÷ 11 = 0.52예요."]},{"stem":"3.15 ÷ 9의 몫은 얼마인가요?","options":[{"t":"0.35","correct":true},{"t":"3.5","mis":"M6-1-u3-X05"},{"t":"0.035","mis":"M6-1-u3-X02"},{"t":"35","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 315 ÷ 9 = 35예요.","3.15는 315의 ⟨1/100⟩배라서 몫도 35의 ⟨1/100⟩배예요.","몫이 1보다 작으니 일의 자리에 0을 써서 자리를 지켜요 — 3.15 ÷ 9 = 0.35예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L04_challenge#3','math',6,1,'u3','L04','g6_1_math_u3_L04_challenge','lesson_challenge','M6-1-u3-C3',3,'mc','auto','친구가 3.2 ÷ 4의 몫을 8이라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u3-X13','M6-1-u3-X06']::text[],true,'{"seq":3,"concept":"M6-1-u3-C3","difficulty":3,"kind":"mc","stem":"친구가 3.2 ÷ 4의 몫을 8이라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"몫이 1보다 작은데 일의 자리 0과 소수점을 쓰지 않아서","correct":true},{"t":"나누는 수를 잘못 써서","mis":"M6-1-u3-X13"},{"t":"곱셈을 잘못해서","mis":"M6-1-u3-X13"},{"t":"0을 내려 계산하지 않아서","mis":"M6-1-u3-X06"}],"explanation":["3.2는 4보다 작아 몫이 1보다 작아요.","자연수의 나눗셈으로 바꾸어 봐요 — 32 ÷ 4 = 8이에요.","일의 자리에 0을 쓰고 소수점을 찍어 0.8이에요."],"variant_rule":{"alt":[{"stem":"친구가 5.72 ÷ 11의 몫을 52라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"몫이 1보다 작은데 일의 자리 0과 소수점을 쓰지 않아서","correct":true},{"t":"나누는 수를 잘못 써서","mis":"M6-1-u3-X13"},{"t":"곱셈을 잘못해서","mis":"M6-1-u3-X13"},{"t":"0을 내려 계산하지 않아서","mis":"M6-1-u3-X06"}],"explanation":["5.72는 11보다 작아 몫이 1보다 작아요.","자연수의 나눗셈으로 바꾸어 봐요 — 572 ÷ 11 = 52예요.","일의 자리에 0을 쓰고 소수점을 찍어 0.52예요."]},{"stem":"친구가 4.32 ÷ 8의 몫을 54라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"몫이 1보다 작은데 일의 자리 0과 소수점을 쓰지 않아서","correct":true},{"t":"나누는 수를 잘못 써서","mis":"M6-1-u3-X13"},{"t":"곱셈을 잘못해서","mis":"M6-1-u3-X13"},{"t":"0을 내려 계산하지 않아서","mis":"M6-1-u3-X06"}],"explanation":["4.32는 8보다 작아 몫이 1보다 작아요.","자연수의 나눗셈으로 바꾸어 봐요 — 432 ÷ 8 = 54예요.","일의 자리에 0을 쓰고 소수점을 찍어 0.54예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L04_challenge#4','math',6,1,'u3','L04','g6_1_math_u3_L04_challenge','lesson_challenge','M6-1-u3-C3',3,'error','auto','5.6 ÷ 7을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u3-X05','M6-1-u3-X14']::text[],true,'{"seq":4,"concept":"M6-1-u3-C3","difficulty":3,"kind":"error","stem":"5.6 ÷ 7을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「몫은 8이야. 앞의 0은 안 써도 돼.」","correct":true,"mis_target":"M6-1-u3-X05"},{"t":"이현 — 「5.6이 7보다 작으니 몫은 1보다 작아.」","mis":"M6-1-u3-X14"},{"t":"서아 — 「몫은 0.8이야.」","mis":"M6-1-u3-X14"}],"explanation":["5.6은 7보다 작아 몫이 1보다 작아요.","몫이 1보다 작으니 일의 자리에 0을 써서 자리를 지켜요 — 5.6 ÷ 7 = 0.8이에요.","준희는 일의 자리 0을 빠뜨렸어요."],"variant_rule":{"alt":[{"stem":"2.38 ÷ 7을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「몫은 34야. 앞의 0은 안 써도 돼.」","correct":true,"mis_target":"M6-1-u3-X05"},{"t":"수아 — 「2.38이 7보다 작으니 몫은 1보다 작아.」","mis":"M6-1-u3-X14"},{"t":"도윤 — 「몫은 0.34야.」","mis":"M6-1-u3-X14"}],"explanation":["2.38은 7보다 작아 몫이 1보다 작아요.","몫이 1보다 작으니 일의 자리에 0을 써서 자리를 지켜요 — 2.38 ÷ 7 = 0.34예요.","서호는 일의 자리 0을 빠뜨렸어요."]},{"stem":"3.15 ÷ 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「몫은 63이야. 앞의 0은 안 써도 돼.」","correct":true,"mis_target":"M6-1-u3-X05"},{"t":"나린 — 「3.15가 5보다 작으니 몫은 1보다 작아.」","mis":"M6-1-u3-X14"},{"t":"유진 — 「몫은 0.63이야.」","mis":"M6-1-u3-X14"}],"explanation":["3.15는 5보다 작아 몫이 1보다 작아요.","몫이 1보다 작으니 일의 자리에 0을 써서 자리를 지켜요 — 3.15 ÷ 5 = 0.63이에요.","가온은 일의 자리 0을 빠뜨렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L04_challenge#5','math',6,1,'u3','L04','g6_1_math_u3_L04_challenge','lesson_challenge','M6-1-u3-C3',3,'ox','auto','5.6 ÷ 7의 몫은 8이에요.',ARRAY['M6-1-u3-X05']::text[],true,'{"seq":5,"concept":"M6-1-u3-C3","difficulty":3,"kind":"ox","stem":"5.6 ÷ 7의 몫은 8이에요.","answer":"X","reason_options":[{"t":"몫이 1보다 작아 일의 자리에 0을 써서 0.8이기 때문에","correct":true},{"t":"56 ÷ 7 = 8이니 몫도 8이기 때문에","mis":"M6-1-u3-X05"}],"mis":"M6-1-u3-X05","explanation":["나누어지는 수가 나누는 수보다 작으면 몫은 1보다 작아요.","이때 몫의 일의 자리에 0을 써요.","0은 자리를 지키는 숫자예요."],"variant_rule":{"alt":[{"stem":"8.4 ÷ 8의 몫은 1보다 커요.","answer":"O","reason_options":[{"t":"나누어지는 수 8.4가 나누는 수 8보다 크기 때문에","correct":true},{"t":"나누는 수가 자연수이면 몫은 1보다 작기 때문에","mis":"M6-1-u3-X12"}],"explanation":["나누어지는 수가 나누는 수보다 작으면 몫은 1보다 작아요.","이때 몫의 일의 자리에 0을 써요.","0은 자리를 지키는 숫자예요."]},{"stem":"2.38 ÷ 7과 238 ÷ 7의 몫은 같아요.","answer":"X","reason_options":[{"t":"2.38은 238의 ⟨1/100⟩배라 몫도 ⟨1/100⟩배이기 때문에","correct":true},{"t":"나누는 수가 같으면 몫이 같기 때문에","mis":"M6-1-u3-X01"}],"explanation":["나누어지는 수가 나누는 수보다 작으면 몫은 1보다 작아요.","이때 몫의 일의 자리에 0을 써요.","0은 자리를 지키는 숫자예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L04_challenge#6','math',6,1,'u3','L04','g6_1_math_u3_L04_challenge','lesson_challenge','M6-1-u3-C1',3,'match','auto','나눗셈식과 몫을 알맞게 이으세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u3-C1","difficulty":3,"kind":"match","stem":"나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"3.2 ÷ 4","r":"0.8"},{"l":"2.38 ÷ 7","r":"0.34"},{"l":"5.72 ÷ 11","r":"0.52"}],"mis":"M6-1-u3-X02","explanation":["자연수의 나눗셈으로 몫을 구한 뒤 같은 배율만큼 작게 해요.","3.2 ÷ 4 = 0.8, 2.38 ÷ 7 = 0.34, 5.72 ÷ 11 = 0.52예요.","어림한 값과 견주어 소수점 자리를 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"5.6 ÷ 7","r":"0.8"},{"l":"3.15 ÷ 5","r":"0.63"},{"l":"4.32 ÷ 8","r":"0.54"}],"explanation":["자연수의 나눗셈으로 몫을 구한 뒤 같은 배율만큼 작게 해요.","5.6 ÷ 7 = 0.8, 3.15 ÷ 5 = 0.63, 4.32 ÷ 8 = 0.54예요.","어림한 값과 견주어 소수점 자리를 확인해요."]},{"stem":"이번에는 다른 보기예요. 나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"4.5 ÷ 9","r":"0.5"},{"l":"3.84 ÷ 8","r":"0.48"},{"l":"1.95 ÷ 3","r":"0.65"}],"explanation":["자연수의 나눗셈으로 몫을 구한 뒤 같은 배율만큼 작게 해요.","4.5 ÷ 9 = 0.5, 3.84 ÷ 8 = 0.48, 1.95 ÷ 3 = 0.65예요.","어림한 값과 견주어 소수점 자리를 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L04_challenge#7','math',6,1,'u3','L04','g6_1_math_u3_L04_challenge','lesson_challenge','M6-1-u3-C3',3,'mc','auto','어떤 수를 6으로 나누었더니 몫이 0.45가 되었어요. 어떤 수를 9로 나눈 몫은 얼마인가요?',ARRAY['M6-1-u3-X14','M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":7,"concept":"M6-1-u3-C3","difficulty":3,"kind":"mc","stem":"어떤 수를 6으로 나누었더니 몫이 0.45가 되었어요. 어떤 수를 9로 나눈 몫은 얼마인가요?","options":[{"t":"0.3","correct":true},{"t":"2.7","mis":"M6-1-u3-X14"},{"t":"3","mis":"M6-1-u3-X01"},{"t":"0.03","mis":"M6-1-u3-X02"}],"explanation":["어떤 수는 0.45 × 6 = 2.7이에요.","이제 2.7 ÷ 9를 계산해요.","2.7 ÷ 9 = 0.3이에요."],"variant_rule":{"alt":[{"stem":"어떤 수를 4로 나누었더니 몫이 0.36이 되었어요. 어떤 수를 6으로 나눈 몫은 얼마인가요?","options":[{"t":"0.24","correct":true},{"t":"1.44","mis":"M6-1-u3-X14"},{"t":"2.4","mis":"M6-1-u3-X01"},{"t":"0.024","mis":"M6-1-u3-X02"}],"explanation":["어떤 수는 0.36 × 4 = 1.44예요.","이제 1.44 ÷ 6을 계산해요.","1.44 ÷ 6 = 0.24예요."]},{"stem":"어떤 수를 8로 나누었더니 몫이 0.12가 되었어요. 어떤 수를 3으로 나눈 몫은 얼마인가요?","options":[{"t":"0.32","correct":true},{"t":"0.96","mis":"M6-1-u3-X14"},{"t":"3.2","mis":"M6-1-u3-X01"},{"t":"0.032","mis":"M6-1-u3-X02"}],"explanation":["어떤 수는 0.12 × 8 = 0.96이에요.","이제 0.96 ÷ 3을 계산해요.","0.96 ÷ 3 = 0.32예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L04_challenge#8','math',6,1,'u3','L04','g6_1_math_u3_L04_challenge','lesson_challenge','M6-1-u3-C3',4,'mc','auto','몫이 가장 작은 나눗셈은 어느 것인가요?',ARRAY['M6-1-u3-X14']::text[],true,'{"seq":8,"concept":"M6-1-u3-C3","difficulty":4,"kind":"mc","stem":"몫이 가장 작은 나눗셈은 어느 것인가요?","options":[{"t":"2.38 ÷ 7","correct":true},{"t":"3.2 ÷ 4","mis":"M6-1-u3-X14"},{"t":"5.72 ÷ 11","mis":"M6-1-u3-X14"},{"t":"4.5 ÷ 9","mis":"M6-1-u3-X14"}],"explanation":["몫을 하나씩 구해 견주어요.","3.2 ÷ 4 = 0.8, 2.38 ÷ 7 = 0.34, 5.72 ÷ 11 = 0.52, 4.5 ÷ 9 = 0.5예요.","가장 작은 것은 2.38 ÷ 7이에요."],"variant_rule":{"alt":[{"stem":"몫이 가장 큰 나눗셈은 어느 것인가요?","options":[{"t":"5.6 ÷ 7","correct":true},{"t":"3.15 ÷ 5","mis":"M6-1-u3-X14"},{"t":"4.32 ÷ 8","mis":"M6-1-u3-X14"},{"t":"1.95 ÷ 3","mis":"M6-1-u3-X14"}],"explanation":["몫을 하나씩 구해 견주어요.","5.6 ÷ 7 = 0.8, 3.15 ÷ 5 = 0.63, 4.32 ÷ 8 = 0.54, 1.95 ÷ 3 = 0.65예요.","가장 큰 것은 5.6 ÷ 7이에요."]},{"stem":"이번에는 다른 보기예요. 몫이 가장 작은 나눗셈은 어느 것인가요?","options":[{"t":"2.38 ÷ 7","correct":true},{"t":"4.5 ÷ 9","mis":"M6-1-u3-X14"},{"t":"6.3 ÷ 9","mis":"M6-1-u3-X14"},{"t":"3.84 ÷ 8","mis":"M6-1-u3-X14"}],"explanation":["몫을 하나씩 구해 견주어요.","4.5 ÷ 9 = 0.5, 2.38 ÷ 7 = 0.34, 6.3 ÷ 9 = 0.7, 3.84 ÷ 8 = 0.48이에요.","가장 작은 것은 2.38 ÷ 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L04_challenge#9','math',6,1,'u3','L04','g6_1_math_u3_L04_challenge','lesson_challenge','M6-1-u3-C3',4,'sa','auto','0.□가 4.9 ÷ 7의 몫보다 크고 1보다 작아요. □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u3-C3","difficulty":4,"kind":"sa","stem":"0.□가 4.9 ÷ 7의 몫보다 크고 1보다 작아요. □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 49 ÷ 7 = 7이에요.","몫이 1보다 작으니 일의 자리에 0을 써서 자리를 지켜요 — 4.9 ÷ 7 = 0.7이에요.","□는 8부터 9까지 — 9 − 7 = 2개예요."],"mis":"M6-1-u3-X14","variant_rule":{"alt":[{"stem":"0.□가 5.4 ÷ 9의 몫보다 크고 1보다 작아요. □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 54 ÷ 9 = 6이에요.","몫이 1보다 작으니 일의 자리에 0을 써서 자리를 지켜요 — 5.4 ÷ 9 = 0.6이에요.","□는 7부터 9까지 — 9 − 6 = 3개예요."]},{"stem":"0.□가 2.4 ÷ 6의 몫보다 크고 1보다 작아요. □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 24 ÷ 6 = 4예요.","몫이 1보다 작으니 일의 자리에 0을 써서 자리를 지켜요 — 2.4 ÷ 6 = 0.4예요.","□는 5부터 9까지 — 9 − 4 = 5개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L04_challenge#10','math',6,1,'u3','L04','g6_1_math_u3_L04_challenge','lesson_challenge','M6-1-u3-C3',4,'essay','teacher','동물병원에서 강아지는 3.2 kg, 고양이는 4 kg이었어요. 강아지 몸무게가 고양이 몸무게의 몇 배인지 구하고, 몫의 일의 자리에 0을 써야 하는 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u3-C3","difficulty":4,"kind":"essay","stem":"동물병원에서 강아지는 3.2 kg, 고양이는 4 kg이었어요. 강아지 몸무게가 고양이 몸무게의 몇 배인지 구하고, 몫의 일의 자리에 0을 써야 하는 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 3.2 ÷ 4를 계산한다. 32 ÷ 4 = 8이고 3.2는 32의 10분의 1배이므로 몫은 0.8이다. 강아지는 고양이의 0.8배이다. 나누어지는 수가 나누는 수보다 작아 몫이 1보다 작으므로 일의 자리에 0을 써서 자리를 지켜야 한다. 0을 빼면 8이 되어 10배 큰 다른 수가 된다.","scoring_points":["3.2 ÷ 4로 식을 세웠는가","0.8배를 구했는가","0을 빼면 다른 수가 된다는 까닭을 썼는가"]},"explanation":["3.2 ÷ 4를 계산해요.","몫은 0.8 — 0.8배예요.","0은 자리를 지키는 숫자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L05_basic#1','math',6,1,'u3','L05','g6_1_math_u3_L05_basic','lesson_basic','M6-1-u3-C4',1,'mc','auto','4.6 ÷ 4의 몫은 얼마인가요?',ARRAY['M6-1-u3-X06','M6-1-u3-X01']::text[],true,'{"seq":1,"concept":"M6-1-u3-C4","difficulty":1,"kind":"mc","stem":"4.6 ÷ 4의 몫은 얼마인가요?","options":[{"t":"1.15","correct":true},{"t":"1.1","mis":"M6-1-u3-X06"},{"t":"1.12","mis":"M6-1-u3-X06"},{"t":"11.5","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 460 ÷ 4 = 115예요.","4.6은 460의 ⟨1/100⟩배라서 몫도 115의 ⟨1/100⟩배예요.","나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 4.6 ÷ 4 = 1.15예요."],"variant_rule":{"alt":[{"stem":"6.7 ÷ 5의 몫은 얼마인가요?","options":[{"t":"1.34","correct":true},{"t":"1.3","mis":"M6-1-u3-X06"},{"t":"1.32","mis":"M6-1-u3-X06"},{"t":"13.4","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 670 ÷ 5 = 134예요.","6.7은 670의 ⟨1/100⟩배라서 몫도 134의 ⟨1/100⟩배예요.","나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 6.7 ÷ 5 = 1.34예요."]},{"stem":"8.3 ÷ 2의 몫은 얼마인가요?","options":[{"t":"4.15","correct":true},{"t":"4.1","mis":"M6-1-u3-X06"},{"t":"4.11","mis":"M6-1-u3-X06"},{"t":"41.5","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 830 ÷ 2 = 415예요.","8.3은 830의 ⟨1/100⟩배라서 몫도 415의 ⟨1/100⟩배예요.","나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 8.3 ÷ 2 = 4.15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L05_basic#2','math',6,1,'u3','L05','g6_1_math_u3_L05_basic','lesson_basic','M6-1-u3-C4',1,'sa','auto','8.3 ÷ 2의 몫에서 소수 둘째 자리 숫자는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u3-C4","difficulty":1,"kind":"sa","stem":"8.3 ÷ 2의 몫에서 소수 둘째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 830 ÷ 2 = 415예요.","나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 8.3 ÷ 2 = 4.15예요.","4.15의 소수 둘째 자리 숫자는 5예요."],"mis":"M6-1-u3-X13","variant_rule":{"alt":[{"stem":"4.6 ÷ 4의 몫에서 소수 둘째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 460 ÷ 4 = 115예요.","나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 4.6 ÷ 4 = 1.15예요.","1.15의 소수 둘째 자리 숫자는 5예요."]},{"stem":"6.7 ÷ 5의 몫에서 소수 둘째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 670 ÷ 5 = 134예요.","나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 6.7 ÷ 5 = 1.34예요.","1.34의 소수 둘째 자리 숫자는 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L05_basic#3','math',6,1,'u3','L05','g6_1_math_u3_L05_basic','lesson_basic','M6-1-u3-C4',1,'mc','auto','4.6 ÷ 4를 계산하다가 소수 첫째 자리까지 나누었더니 2가 남았어요. 다음에 할 일로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u3-X06','M6-1-u3-X13']::text[],true,'{"seq":3,"concept":"M6-1-u3-C4","difficulty":1,"kind":"mc","stem":"4.6 ÷ 4를 계산하다가 소수 첫째 자리까지 나누었더니 2가 남았어요. 다음에 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"소수점 아래에 0을 하나 내려 계산을 이어 가요","correct":true},{"t":"남은 2를 몫 뒤에 붙여 써요","mis":"M6-1-u3-X06"},{"t":"나누어떨어지지 않는다고 답해요","mis":"M6-1-u3-X06"},{"t":"나누는 수를 바꾸어 다시 나누어요","mis":"M6-1-u3-X13"}],"explanation":["4.6은 4.60과 같은 수예요.","소수점 아래 끝자리에 0을 붙여도 수의 크기는 그대로예요.","그래서 0을 내려 이어 계산하면 4.6 ÷ 4 = 1.15예요."],"variant_rule":{"alt":[{"stem":"6.7 ÷ 5를 계산하다가 소수 첫째 자리까지 나누었더니 2가 남았어요. 다음에 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"소수점 아래에 0을 하나 내려 계산을 이어 가요","correct":true},{"t":"남은 2를 몫 뒤에 붙여 써요","mis":"M6-1-u3-X06"},{"t":"나누어떨어지지 않는다고 답해요","mis":"M6-1-u3-X06"},{"t":"나누는 수를 바꾸어 다시 나누어요","mis":"M6-1-u3-X13"}],"explanation":["6.7은 6.70과 같은 수예요.","소수점 아래 끝자리에 0을 붙여도 수의 크기는 그대로예요.","그래서 0을 내려 이어 계산하면 6.7 ÷ 5 = 1.34예요."]},{"stem":"8.3 ÷ 2를 계산하다가 소수 첫째 자리까지 나누었더니 1이 남았어요. 다음에 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"소수점 아래에 0을 하나 내려 계산을 이어 가요","correct":true},{"t":"남은 1을 몫 뒤에 붙여 써요","mis":"M6-1-u3-X06"},{"t":"나누어떨어지지 않는다고 답해요","mis":"M6-1-u3-X06"},{"t":"나누는 수를 바꾸어 다시 나누어요","mis":"M6-1-u3-X13"}],"explanation":["8.3은 8.30과 같은 수예요.","소수점 아래 끝자리에 0을 붙여도 수의 크기는 그대로예요.","그래서 0을 내려 이어 계산하면 8.3 ÷ 2 = 4.15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L05_basic#4','math',6,1,'u3','L05','g6_1_math_u3_L05_basic','lesson_basic','M6-1-u3-C4',1,'ox','auto','4.6과 4.60은 같은 수예요.',ARRAY['M6-1-u3-X06']::text[],true,'{"seq":4,"concept":"M6-1-u3-C4","difficulty":1,"kind":"ox","stem":"4.6과 4.60은 같은 수예요.","answer":"O","reason_options":[{"t":"소수점 아래 끝자리에 0을 붙여도 수의 크기는 그대로이기 때문에","correct":true},{"t":"0이 하나 붙어 10배가 되기 때문에","mis":"M6-1-u3-X06"}],"mis":"M6-1-u3-X06","explanation":["4.6 = 4.60 = 4.600 — 소수점 아래 끝자리에 0을 붙여도 수의 크기는 같아요.","그래서 나머지가 남으면 0을 내려 계산을 이어 가요.","남은 수를 몫 뒤에 붙이면 안 돼요."],"variant_rule":{"alt":[{"stem":"6.7 ÷ 5는 0을 하나 내려 계산하면 나누어떨어져요.","answer":"O","reason_options":[{"t":"6.7 = 6.70으로 보고 계산하면 몫이 1.34로 끝나기 때문에","correct":true},{"t":"5로 나누면 언제나 나누어떨어지지 않기 때문에","mis":"M6-1-u3-X06"}],"explanation":["4.6 = 4.60 = 4.600 — 소수점 아래 끝자리에 0을 붙여도 수의 크기는 같아요.","그래서 나머지가 남으면 0을 내려 계산을 이어 가요.","남은 수를 몫 뒤에 붙이면 안 돼요."]},{"stem":"8.3 ÷ 2의 몫은 4.15예요.","answer":"O","reason_options":[{"t":"8.3 = 8.30으로 보고 830 ÷ 2 = 415를 이용하면 4.15이기 때문에","correct":true},{"t":"남은 1을 뒤에 붙이면 4.11이기 때문에","mis":"M6-1-u3-X06"}],"explanation":["4.6 = 4.60 = 4.600 — 소수점 아래 끝자리에 0을 붙여도 수의 크기는 같아요.","그래서 나머지가 남으면 0을 내려 계산을 이어 가요.","남은 수를 몫 뒤에 붙이면 안 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L05_basic#5','math',6,1,'u3','L05','g6_1_math_u3_L05_basic','lesson_basic','M6-1-u3-C4',2,'mc','auto','5.4 ÷ 8의 몫은 얼마인가요?',ARRAY['M6-1-u3-X06','M6-1-u3-X01']::text[],true,'{"seq":5,"concept":"M6-1-u3-C4","difficulty":2,"kind":"mc","stem":"5.4 ÷ 8의 몫은 얼마인가요?","options":[{"t":"0.675","correct":true},{"t":"0.6","mis":"M6-1-u3-X06"},{"t":"0.66","mis":"M6-1-u3-X06"},{"t":"6.75","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 5400 ÷ 8 = 675예요.","5.4는 5400의 ⟨1/1000⟩배라서 몫도 675의 ⟨1/1000⟩배예요.","나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 5.4 ÷ 8 = 0.675예요."],"variant_rule":{"alt":[{"stem":"6.6 ÷ 4의 몫은 얼마인가요?","options":[{"t":"1.65","correct":true},{"t":"1.6","mis":"M6-1-u3-X06"},{"t":"1.62","mis":"M6-1-u3-X06"},{"t":"16.5","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 660 ÷ 4 = 165예요.","6.6은 660의 ⟨1/100⟩배라서 몫도 165의 ⟨1/100⟩배예요.","나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 6.6 ÷ 4 = 1.65예요."]},{"stem":"2.1 ÷ 6의 몫은 얼마인가요?","options":[{"t":"0.35","correct":true},{"t":"0.3","mis":"M6-1-u3-X06"},{"t":"0.33","mis":"M6-1-u3-X06"},{"t":"3.5","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 210 ÷ 6 = 35예요.","2.1은 210의 ⟨1/100⟩배라서 몫도 35의 ⟨1/100⟩배예요.","나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 2.1 ÷ 6 = 0.35예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L05_basic#6','math',6,1,'u3','L05','g6_1_math_u3_L05_basic','lesson_basic','M6-1-u3-C4',2,'mc','auto','둘레가 6.7 m인 정오각형 모양이 있어요. 한 변의 길이는 몇 m인가요?',ARRAY['M6-1-u3-X06','M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":6,"concept":"M6-1-u3-C4","difficulty":2,"kind":"mc","stem":"둘레가 6.7 m인 정오각형 모양이 있어요. 한 변의 길이는 몇 m인가요?","options":[{"t":"1.34 m","correct":true},{"t":"1.3 m","mis":"M6-1-u3-X06"},{"t":"13.4 m","mis":"M6-1-u3-X01"},{"t":"0.134 m","mis":"M6-1-u3-X02"}],"explanation":["정오각형은 5개의 변의 길이가 모두 같아요.","한 변의 길이는 둘레를 변의 수로 나누어 구해요.","나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 6.7 ÷ 5 = 1.34예요."],"variant_rule":{"alt":[{"stem":"둘레가 9.8 m인 정사각형 모양이 있어요. 한 변의 길이는 몇 m인가요?","options":[{"t":"2.45 m","correct":true},{"t":"2.4 m","mis":"M6-1-u3-X06"},{"t":"24.5 m","mis":"M6-1-u3-X01"},{"t":"0.245 m","mis":"M6-1-u3-X02"}],"explanation":["정사각형은 4개의 변의 길이가 모두 같아요.","한 변의 길이는 둘레를 변의 수로 나누어 구해요.","나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 9.8 ÷ 4 = 2.45예요."]},{"stem":"둘레가 7.5 m인 정육각형 모양이 있어요. 한 변의 길이는 몇 m인가요?","options":[{"t":"1.25 m","correct":true},{"t":"1.2 m","mis":"M6-1-u3-X06"},{"t":"12.5 m","mis":"M6-1-u3-X01"},{"t":"0.125 m","mis":"M6-1-u3-X02"}],"explanation":["정육각형은 6개의 변의 길이가 모두 같아요.","한 변의 길이는 둘레를 변의 수로 나누어 구해요.","나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 7.5 ÷ 6 = 1.25예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L05_basic#7','math',6,1,'u3','L05','g6_1_math_u3_L05_basic','lesson_basic','M6-1-u3-C4',2,'mc','auto','친구가 4.6 ÷ 4의 몫을 1.12라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X05','M6-1-u3-X07']::text[],true,'{"seq":7,"concept":"M6-1-u3-C4","difficulty":2,"kind":"mc","stem":"친구가 4.6 ÷ 4의 몫을 1.12라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"남은 2를 몫 뒤에 그대로 붙여 써서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"},{"t":"몫 가운데 0을 빠뜨려서","mis":"M6-1-u3-X07"}],"explanation":["소수 첫째 자리까지 나누면 몫은 1.1이고 2가 남아요.","남은 수는 몫이 아니라 0을 내려 계속 나눌 수예요.","0을 내려 계산하면 몫은 1.15예요."],"variant_rule":{"alt":[{"stem":"친구가 6.7 ÷ 5의 몫을 1.32라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"남은 2를 몫 뒤에 그대로 붙여 써서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"},{"t":"몫 가운데 0을 빠뜨려서","mis":"M6-1-u3-X07"}],"explanation":["소수 첫째 자리까지 나누면 몫은 1.3이고 2가 남아요.","남은 수는 몫이 아니라 0을 내려 계속 나눌 수예요.","0을 내려 계산하면 몫은 1.34예요."]},{"stem":"친구가 9.8 ÷ 4의 몫을 2.42라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"남은 2를 몫 뒤에 그대로 붙여 써서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"},{"t":"몫 가운데 0을 빠뜨려서","mis":"M6-1-u3-X07"}],"explanation":["소수 첫째 자리까지 나누면 몫은 2.4이고 2가 남아요.","남은 수는 몫이 아니라 0을 내려 계속 나눌 수예요.","0을 내려 계산하면 몫은 2.45예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L05_basic#8','math',6,1,'u3','L05','g6_1_math_u3_L05_basic','lesson_basic','M6-1-u3-C2',2,'mc','auto','물 5.4 L를 병 8개에 똑같이 나누어 담았어요. 병 하나에 담긴 물은 몇 mL인가요?',ARRAY['M6-1-u3-X11']::text[],true,'{"seq":8,"concept":"M6-1-u3-C2","difficulty":2,"kind":"mc","stem":"물 5.4 L를 병 8개에 똑같이 나누어 담았어요. 병 하나에 담긴 물은 몇 mL인가요?","options":[{"t":"675 mL","correct":true},{"t":"67.5 mL","mis":"M6-1-u3-X11"},{"t":"6750 mL","mis":"M6-1-u3-X11"},{"t":"6.75 mL","mis":"M6-1-u3-X11"}],"explanation":["5.4 ÷ 8 = 0.675 (L)예요.","1 L는 1000 mL예요.","0.675 L는 675 mL예요."],"variant_rule":{"alt":[{"stem":"물 3.3 L를 병 4개에 똑같이 나누어 담았어요. 병 하나에 담긴 물은 몇 mL인가요?","options":[{"t":"825 mL","correct":true},{"t":"82.5 mL","mis":"M6-1-u3-X11"},{"t":"8250 mL","mis":"M6-1-u3-X11"},{"t":"8.25 mL","mis":"M6-1-u3-X11"}],"explanation":["3.3 ÷ 4 = 0.825 (L)예요.","1 L는 1000 mL예요.","0.825 L는 825 mL예요."]},{"stem":"물 7.4 L를 병 8개에 똑같이 나누어 담았어요. 병 하나에 담긴 물은 몇 mL인가요?","options":[{"t":"925 mL","correct":true},{"t":"92.5 mL","mis":"M6-1-u3-X11"},{"t":"9250 mL","mis":"M6-1-u3-X11"},{"t":"9.25 mL","mis":"M6-1-u3-X11"}],"explanation":["7.4 ÷ 8 = 0.925 (L)예요.","1 L는 1000 mL예요.","0.925 L는 925 mL예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L05_basic#9','math',6,1,'u3','L05','g6_1_math_u3_L05_basic','lesson_basic','M6-1-u3-C1',2,'match','auto','나눗셈식과 몫을 알맞게 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u3-C1","difficulty":2,"kind":"match","stem":"나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"4.6 ÷ 4","r":"1.15"},{"l":"6.7 ÷ 5","r":"1.34"},{"l":"8.3 ÷ 2","r":"4.15"}],"mis":"M6-1-u3-X02","explanation":["자연수의 나눗셈으로 몫을 구한 뒤 같은 배율만큼 작게 해요.","4.6 ÷ 4 = 1.15, 6.7 ÷ 5 = 1.34, 8.3 ÷ 2 = 4.15예요.","어림한 값과 견주어 소수점 자리를 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"5.4 ÷ 8","r":"0.675"},{"l":"6.6 ÷ 4","r":"1.65"},{"l":"2.1 ÷ 6","r":"0.35"}],"explanation":["자연수의 나눗셈으로 몫을 구한 뒤 같은 배율만큼 작게 해요.","5.4 ÷ 8 = 0.675, 6.6 ÷ 4 = 1.65, 2.1 ÷ 6 = 0.35예요.","어림한 값과 견주어 소수점 자리를 확인해요."]},{"stem":"이번에는 다른 보기예요. 나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"9.8 ÷ 4","r":"2.45"},{"l":"7.5 ÷ 6","r":"1.25"},{"l":"8.7 ÷ 6","r":"1.45"}],"explanation":["자연수의 나눗셈으로 몫을 구한 뒤 같은 배율만큼 작게 해요.","9.8 ÷ 4 = 2.45, 7.5 ÷ 6 = 1.25, 8.7 ÷ 6 = 1.45예요.","어림한 값과 견주어 소수점 자리를 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L05_basic#10','math',6,1,'u3','L05','g6_1_math_u3_L05_basic','lesson_basic','M6-1-u3-C4',3,'mc','auto','찰흙 8.7 kg을 여섯 명이 똑같이 나누어 가졌어요. 한 명이 가진 찰흙은 몇 g인가요?',ARRAY['M6-1-u3-X11','M6-1-u3-X06']::text[],true,'{"seq":10,"concept":"M6-1-u3-C4","difficulty":3,"kind":"mc","stem":"찰흙 8.7 kg을 여섯 명이 똑같이 나누어 가졌어요. 한 명이 가진 찰흙은 몇 g인가요?","options":[{"t":"1450 g","correct":true},{"t":"145 g","mis":"M6-1-u3-X11"},{"t":"1400 g","mis":"M6-1-u3-X06"},{"t":"14500 g","mis":"M6-1-u3-X11"}],"explanation":["나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 8.7 ÷ 6 = 1.45예요.","1 kg은 1000 g이에요.","1.45 kg은 1450 g이에요."],"variant_rule":{"alt":[{"stem":"찰흙 5.1 kg을 여섯 명이 똑같이 나누어 가졌어요. 한 명이 가진 찰흙은 몇 g인가요?","options":[{"t":"850 g","correct":true},{"t":"85 g","mis":"M6-1-u3-X11"},{"t":"800 g","mis":"M6-1-u3-X06"},{"t":"8500 g","mis":"M6-1-u3-X11"}],"explanation":["나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 5.1 ÷ 6 = 0.85예요.","1 kg은 1000 g이에요.","0.85 kg은 850 g이에요."]},{"stem":"찰흙 9.3 kg을 여섯 명이 똑같이 나누어 가졌어요. 한 명이 가진 찰흙은 몇 g인가요?","options":[{"t":"1550 g","correct":true},{"t":"155 g","mis":"M6-1-u3-X11"},{"t":"1500 g","mis":"M6-1-u3-X06"},{"t":"15500 g","mis":"M6-1-u3-X11"}],"explanation":["나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 9.3 ÷ 6 = 1.55예요.","1 kg은 1000 g이에요.","1.55 kg은 1550 g이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L05_challenge#1','math',6,1,'u3','L05','g6_1_math_u3_L05_challenge','lesson_challenge','M6-1-u3-C4',2,'mc','auto','8.7 ÷ 6의 몫은 얼마인가요?',ARRAY['M6-1-u3-X06','M6-1-u3-X01']::text[],true,'{"seq":1,"concept":"M6-1-u3-C4","difficulty":2,"kind":"mc","stem":"8.7 ÷ 6의 몫은 얼마인가요?","options":[{"t":"1.45","correct":true},{"t":"1.4","mis":"M6-1-u3-X06"},{"t":"1.43","mis":"M6-1-u3-X06"},{"t":"14.5","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 870 ÷ 6 = 145예요.","8.7은 870의 ⟨1/100⟩배라서 몫도 145의 ⟨1/100⟩배예요.","나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 8.7 ÷ 6 = 1.45예요."],"variant_rule":{"alt":[{"stem":"5.1 ÷ 6의 몫은 얼마인가요?","options":[{"t":"0.85","correct":true},{"t":"0.8","mis":"M6-1-u3-X06"},{"t":"0.83","mis":"M6-1-u3-X06"},{"t":"8.5","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 510 ÷ 6 = 85예요.","5.1은 510의 ⟨1/100⟩배라서 몫도 85의 ⟨1/100⟩배예요.","나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 5.1 ÷ 6 = 0.85예요."]},{"stem":"9.3 ÷ 6의 몫은 얼마인가요?","options":[{"t":"1.55","correct":true},{"t":"1.5","mis":"M6-1-u3-X06"},{"t":"1.53","mis":"M6-1-u3-X06"},{"t":"15.5","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 930 ÷ 6 = 155예요.","9.3은 930의 ⟨1/100⟩배라서 몫도 155의 ⟨1/100⟩배예요.","나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 9.3 ÷ 6 = 1.55예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L05_challenge#2','math',6,1,'u3','L05','g6_1_math_u3_L05_challenge','lesson_challenge','M6-1-u3-C4',2,'sa','auto','5.4 ÷ 8의 몫에서 소수 셋째 자리 숫자는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u3-C4","difficulty":2,"kind":"sa","stem":"5.4 ÷ 8의 몫에서 소수 셋째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 5400 ÷ 8 = 675예요.","나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 5.4 ÷ 8 = 0.675예요.","0.675의 소수 셋째 자리 숫자는 5예요."],"mis":"M6-1-u3-X13","variant_rule":{"alt":[{"stem":"3.3 ÷ 4의 몫에서 소수 셋째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 3300 ÷ 4 = 825예요.","나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 3.3 ÷ 4 = 0.825예요.","0.825의 소수 셋째 자리 숫자는 5예요."]},{"stem":"7.4 ÷ 8의 몫에서 소수 둘째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 7400 ÷ 8 = 925예요.","나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 7.4 ÷ 8 = 0.925예요.","0.925의 소수 둘째 자리 숫자는 2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L05_challenge#3','math',6,1,'u3','L05','g6_1_math_u3_L05_challenge','lesson_challenge','M6-1-u3-C4',3,'error','auto','4.6 ÷ 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u3-X06','M6-1-u3-X14']::text[],true,'{"seq":3,"concept":"M6-1-u3-C4","difficulty":3,"kind":"error","stem":"4.6 ÷ 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「소수 첫째 자리까지 나누었으니 몫은 1.1이야.」","correct":true,"mis_target":"M6-1-u3-X06"},{"t":"이현 — 「4.6은 4.60과 같은 수야.」","mis":"M6-1-u3-X14"},{"t":"서아 — 「0을 내려 계산하면 몫은 1.15야.」","mis":"M6-1-u3-X14"}],"explanation":["소수 첫째 자리까지 나누면 나머지가 남아요.","0을 내려 계산을 이어 가야 해요.","준희는 계산을 멈추었어요 — 바른 몫은 1.15예요."],"variant_rule":{"alt":[{"stem":"6.7 ÷ 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「소수 첫째 자리까지 나누었으니 몫은 1.3이야.」","correct":true,"mis_target":"M6-1-u3-X06"},{"t":"수아 — 「6.7은 6.70과 같은 수야.」","mis":"M6-1-u3-X14"},{"t":"도윤 — 「0을 내려 계산하면 몫은 1.34야.」","mis":"M6-1-u3-X14"}],"explanation":["소수 첫째 자리까지 나누면 나머지가 남아요.","0을 내려 계산을 이어 가야 해요.","서호는 계산을 멈추었어요 — 바른 몫은 1.34예요."]},{"stem":"8.7 ÷ 6을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「소수 첫째 자리까지 나누었으니 몫은 1.4야.」","correct":true,"mis_target":"M6-1-u3-X06"},{"t":"나린 — 「8.7은 8.70과 같은 수야.」","mis":"M6-1-u3-X14"},{"t":"유진 — 「0을 내려 계산하면 몫은 1.45야.」","mis":"M6-1-u3-X14"}],"explanation":["소수 첫째 자리까지 나누면 나머지가 남아요.","0을 내려 계산을 이어 가야 해요.","가온은 계산을 멈추었어요 — 바른 몫은 1.45예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L05_challenge#4','math',6,1,'u3','L05','g6_1_math_u3_L05_challenge','lesson_challenge','M6-1-u3-C4',3,'ox','auto','4.6 ÷ 4를 소수 첫째 자리까지 나누고 2가 남으면 몫은 1.1이에요.',ARRAY['M6-1-u3-X06']::text[],true,'{"seq":4,"concept":"M6-1-u3-C4","difficulty":3,"kind":"ox","stem":"4.6 ÷ 4를 소수 첫째 자리까지 나누고 2가 남으면 몫은 1.1이에요.","answer":"X","reason_options":[{"t":"0을 내려 계산을 이어 가면 몫은 1.15이기 때문에","correct":true},{"t":"나누어지는 수의 자리가 끝나면 계산도 끝나기 때문에","mis":"M6-1-u3-X06"}],"mis":"M6-1-u3-X06","explanation":["4.6 = 4.60 = 4.600 — 소수점 아래 끝자리에 0을 붙여도 수의 크기는 같아요.","그래서 나머지가 남으면 0을 내려 계산을 이어 가요.","남은 수를 몫 뒤에 붙이면 안 돼요."],"variant_rule":{"alt":[{"stem":"소수점 아래에 0을 내리면 나누어지는 수가 10배가 돼요.","answer":"X","reason_options":[{"t":"끝자리 뒤 0은 수의 크기를 바꾸지 않기 때문에","correct":true},{"t":"0을 붙이면 자리가 하나 늘기 때문에","mis":"M6-1-u3-X06"}],"explanation":["4.6 = 4.60 = 4.600 — 소수점 아래 끝자리에 0을 붙여도 수의 크기는 같아요.","그래서 나머지가 남으면 0을 내려 계산을 이어 가요.","남은 수를 몫 뒤에 붙이면 안 돼요."]},{"stem":"나머지가 남으면 소수의 나눗셈은 몫을 구할 수 없어요.","answer":"X","reason_options":[{"t":"소수점 아래에 0을 내려 계산을 이어 갈 수 있기 때문에","correct":true},{"t":"나머지는 몫 뒤에 붙여 쓰기 때문에","mis":"M6-1-u3-X06"}],"explanation":["4.6 = 4.60 = 4.600 — 소수점 아래 끝자리에 0을 붙여도 수의 크기는 같아요.","그래서 나머지가 남으면 0을 내려 계산을 이어 가요.","남은 수를 몫 뒤에 붙이면 안 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L05_challenge#5','math',6,1,'u3','L05','g6_1_math_u3_L05_challenge','lesson_challenge','M6-1-u3-C4',3,'mc','auto','친구가 5.4 ÷ 8의 몫을 0.6이라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X05','M6-1-u3-X13']::text[],true,'{"seq":5,"concept":"M6-1-u3-C4","difficulty":3,"kind":"mc","stem":"친구가 5.4 ÷ 8의 몫을 0.6이라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나머지가 남았는데 0을 내려 계산을 이어 가지 않아서","correct":true},{"t":"몫의 소수점을 잘못 찍어서","mis":"M6-1-u3-X01"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"},{"t":"나누는 수를 잘못 써서","mis":"M6-1-u3-X13"}],"explanation":["소수 첫째 자리까지 나누면 나머지가 남아요.","5.4 = 5.40으로 보고 0을 내려 계산을 이어 가요.","바른 몫은 0.675예요."],"variant_rule":{"alt":[{"stem":"친구가 6.6 ÷ 4의 몫을 1.6이라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나머지가 남았는데 0을 내려 계산을 이어 가지 않아서","correct":true},{"t":"몫의 소수점을 잘못 찍어서","mis":"M6-1-u3-X01"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"},{"t":"나누는 수를 잘못 써서","mis":"M6-1-u3-X13"}],"explanation":["소수 첫째 자리까지 나누면 나머지가 남아요.","6.6 = 6.60으로 보고 0을 내려 계산을 이어 가요.","바른 몫은 1.65예요."]},{"stem":"친구가 9.3 ÷ 6의 몫을 1.5라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나머지가 남았는데 0을 내려 계산을 이어 가지 않아서","correct":true},{"t":"몫의 소수점을 잘못 찍어서","mis":"M6-1-u3-X01"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"},{"t":"나누는 수를 잘못 써서","mis":"M6-1-u3-X13"}],"explanation":["소수 첫째 자리까지 나누면 나머지가 남아요.","9.3 = 9.30으로 보고 0을 내려 계산을 이어 가요.","바른 몫은 1.55예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L05_challenge#6','math',6,1,'u3','L05','g6_1_math_u3_L05_challenge','lesson_challenge','M6-1-u3-C4',3,'sa','auto','6.7 ÷ 5를 나누어떨어질 때까지 계산하려면 소수점 아래에 0을 몇 번 내려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u3-C4","difficulty":3,"kind":"sa","stem":"6.7 ÷ 5를 나누어떨어질 때까지 계산하려면 소수점 아래에 0을 몇 번 내려야 하나요? 숫자로 쓰세요.","answer":["1"],"explanation":["6.7은 소수 한 자리 수예요.","몫 1.34는 소수 두 자리까지 있어요.","그 차만큼 0을 내려요 — 1번이에요."],"mis":"M6-1-u3-X06","variant_rule":{"alt":[{"stem":"5.4 ÷ 8을 나누어떨어질 때까지 계산하려면 소수점 아래에 0을 몇 번 내려야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["5.4는 소수 한 자리 수예요.","몫 0.675는 소수 세 자리까지 있어요.","그 차만큼 0을 내려요 — 2번이에요."]},{"stem":"2.1 ÷ 8을 나누어떨어질 때까지 계산하려면 소수점 아래에 0을 몇 번 내려야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["2.1은 소수 한 자리 수예요.","몫 0.2625는 소수 네 자리까지 있어요.","그 차만큼 0을 내려요 — 3번이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L05_challenge#7','math',6,1,'u3','L05','g6_1_math_u3_L05_challenge','lesson_challenge','M6-1-u3-C4',3,'mc','auto','둘레가 5.4 m인 정팔각형 모양이 있어요. 한 변의 길이는 몇 m인가요?',ARRAY['M6-1-u3-X06','M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":7,"concept":"M6-1-u3-C4","difficulty":3,"kind":"mc","stem":"둘레가 5.4 m인 정팔각형 모양이 있어요. 한 변의 길이는 몇 m인가요?","options":[{"t":"0.675 m","correct":true},{"t":"0.6 m","mis":"M6-1-u3-X06"},{"t":"6.75 m","mis":"M6-1-u3-X01"},{"t":"0.0675 m","mis":"M6-1-u3-X02"}],"explanation":["정팔각형은 8개의 변의 길이가 모두 같아요.","한 변의 길이는 둘레를 변의 수로 나누어 구해요.","나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 5.4 ÷ 8 = 0.675예요."],"variant_rule":{"alt":[{"stem":"둘레가 8.1 m인 정육각형 모양이 있어요. 한 변의 길이는 몇 m인가요?","options":[{"t":"1.35 m","correct":true},{"t":"1.3 m","mis":"M6-1-u3-X06"},{"t":"13.5 m","mis":"M6-1-u3-X01"},{"t":"0.135 m","mis":"M6-1-u3-X02"}],"explanation":["정육각형은 6개의 변의 길이가 모두 같아요.","한 변의 길이는 둘레를 변의 수로 나누어 구해요.","나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 8.1 ÷ 6 = 1.35예요."]},{"stem":"둘레가 4.5 m인 정사각형 모양이 있어요. 한 변의 길이는 몇 m인가요?","options":[{"t":"1.125 m","correct":true},{"t":"1.1 m","mis":"M6-1-u3-X06"},{"t":"11.25 m","mis":"M6-1-u3-X01"},{"t":"0.1125 m","mis":"M6-1-u3-X02"}],"explanation":["정사각형은 4개의 변의 길이가 모두 같아요.","한 변의 길이는 둘레를 변의 수로 나누어 구해요.","나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 4.5 ÷ 4 = 1.125예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L05_challenge#8','math',6,1,'u3','L05','g6_1_math_u3_L05_challenge','lesson_challenge','M6-1-u3-C4',4,'mc','auto','어떤 수를 4로 나누어야 할 것을 잘못하여 5로 나누었더니 몫이 1.34가 되었어요. 바르게 계산한 몫은 얼마인가요?',ARRAY['M6-1-u3-X14','M6-1-u3-X06','M6-1-u3-X01']::text[],true,'{"seq":8,"concept":"M6-1-u3-C4","difficulty":4,"kind":"mc","stem":"어떤 수를 4로 나누어야 할 것을 잘못하여 5로 나누었더니 몫이 1.34가 되었어요. 바르게 계산한 몫은 얼마인가요?","options":[{"t":"1.675","correct":true},{"t":"1.34","mis":"M6-1-u3-X14"},{"t":"1.67","mis":"M6-1-u3-X06"},{"t":"16.75","mis":"M6-1-u3-X01"}],"explanation":["어떤 수는 1.34 × 5 = 6.7이에요.","바르게 계산하면 6.7 ÷ 4예요.","0을 내려 계산하면 6.7 ÷ 4 = 1.675예요."],"variant_rule":{"alt":[{"stem":"어떤 수를 8로 나누어야 할 것을 잘못하여 6으로 나누었더니 몫이 0.9가 되었어요. 바르게 계산한 몫은 얼마인가요?","options":[{"t":"0.675","correct":true},{"t":"0.9","mis":"M6-1-u3-X14"},{"t":"0.6","mis":"M6-1-u3-X06"},{"t":"6.75","mis":"M6-1-u3-X01"}],"explanation":["어떤 수는 0.9 × 6 = 5.4예요.","바르게 계산하면 5.4 ÷ 8이에요.","0을 내려 계산하면 5.4 ÷ 8 = 0.675예요."]},{"stem":"어떤 수를 6으로 나누어야 할 것을 잘못하여 3으로 나누었더니 몫이 2.9가 되었어요. 바르게 계산한 몫은 얼마인가요?","options":[{"t":"1.45","correct":true},{"t":"2.9","mis":"M6-1-u3-X14"},{"t":"1.4","mis":"M6-1-u3-X06"},{"t":"14.5","mis":"M6-1-u3-X01"}],"explanation":["어떤 수는 2.9 × 3 = 8.7이에요.","바르게 계산하면 8.7 ÷ 6이에요.","0을 내려 계산하면 8.7 ÷ 6 = 1.45예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L05_challenge#9','math',6,1,'u3','L05','g6_1_math_u3_L05_challenge','lesson_challenge','M6-1-u3-C3',4,'mc','auto','몫이 가장 큰 나눗셈은 어느 것인가요?',ARRAY['M6-1-u3-X14']::text[],true,'{"seq":9,"concept":"M6-1-u3-C3","difficulty":4,"kind":"mc","stem":"몫이 가장 큰 나눗셈은 어느 것인가요?","options":[{"t":"8.3 ÷ 2","correct":true},{"t":"4.6 ÷ 4","mis":"M6-1-u3-X14"},{"t":"6.7 ÷ 5","mis":"M6-1-u3-X14"},{"t":"5.4 ÷ 8","mis":"M6-1-u3-X14"}],"explanation":["몫을 하나씩 구해 견주어요.","4.6 ÷ 4 = 1.15, 6.7 ÷ 5 = 1.34, 5.4 ÷ 8 = 0.675, 8.3 ÷ 2 = 4.15예요.","가장 큰 것은 8.3 ÷ 2예요."],"variant_rule":{"alt":[{"stem":"몫이 가장 작은 나눗셈은 어느 것인가요?","options":[{"t":"2.1 ÷ 6","correct":true},{"t":"8.7 ÷ 6","mis":"M6-1-u3-X14"},{"t":"6.6 ÷ 4","mis":"M6-1-u3-X14"},{"t":"5.1 ÷ 6","mis":"M6-1-u3-X14"}],"explanation":["몫을 하나씩 구해 견주어요.","8.7 ÷ 6 = 1.45, 6.6 ÷ 4 = 1.65, 5.1 ÷ 6 = 0.85, 2.1 ÷ 6 = 0.35예요.","가장 작은 것은 2.1 ÷ 6이에요."]},{"stem":"이번에는 다른 보기예요. 몫이 가장 큰 나눗셈은 어느 것인가요?","options":[{"t":"9.8 ÷ 4","correct":true},{"t":"7.5 ÷ 6","mis":"M6-1-u3-X14"},{"t":"3.3 ÷ 4","mis":"M6-1-u3-X14"},{"t":"8.1 ÷ 6","mis":"M6-1-u3-X14"}],"explanation":["몫을 하나씩 구해 견주어요.","9.8 ÷ 4 = 2.45, 7.5 ÷ 6 = 1.25, 3.3 ÷ 4 = 0.825, 8.1 ÷ 6 = 1.35예요.","가장 큰 것은 9.8 ÷ 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L05_challenge#10','math',6,1,'u3','L05','g6_1_math_u3_L05_challenge','lesson_challenge','M6-1-u3-C4',4,'essay','teacher','넓이가 4.6 m²인 벽을 칠하는 데 페인트 4통을 똑같이 썼어요. 4.6 ÷ 4를 계산하다가 2가 남았을 때 어떻게 해야 하는지 쓰고, 페인트 한 통으로 칠한 넓이를 구해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u3-C4","difficulty":4,"kind":"essay","stem":"넓이가 4.6 m²인 벽을 칠하는 데 페인트 4통을 똑같이 썼어요. 4.6 ÷ 4를 계산하다가 2가 남았을 때 어떻게 해야 하는지 쓰고, 페인트 한 통으로 칠한 넓이를 구해 보세요.","answer_guide":{"answer":"예: 4.6은 4.60과 같은 수이므로 소수점 아래에 0을 하나 내려 계산을 이어 간다. 남은 2에 0을 내리면 20 ÷ 4 = 5로 나누어떨어진다. 그래서 4.6 ÷ 4 = 1.15이고 페인트 한 통으로 1.15 m²를 칠했다.","scoring_points":["4.6 = 4.60이라는 까닭을 썼는가","0을 내려 계산을 이어 갔는가","1.15 m²를 구했는가"]},"explanation":["4.6 = 4.60이에요.","0을 내려 20 ÷ 4 = 5를 이어 계산해요.","한 통으로 1.15 m²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L06_basic#1','math',6,1,'u3','L06','g6_1_math_u3_L06_basic','lesson_basic','M6-1-u3-C5',1,'mc','auto','18.1 ÷ 2의 몫은 얼마인가요?',ARRAY['M6-1-u3-X07','M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":1,"concept":"M6-1-u3-C5","difficulty":1,"kind":"mc","stem":"18.1 ÷ 2의 몫은 얼마인가요?","options":[{"t":"9.05","correct":true},{"t":"9.5","mis":"M6-1-u3-X07"},{"t":"90.5","mis":"M6-1-u3-X01"},{"t":"0.905","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1810 ÷ 2 = 905예요.","18.1은 1810의 ⟨1/100⟩배라서 몫도 905의 ⟨1/100⟩배예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 18.1 ÷ 2 = 9.05예요."],"variant_rule":{"alt":[{"stem":"16.4 ÷ 8의 몫은 얼마인가요?","options":[{"t":"2.05","correct":true},{"t":"2.5","mis":"M6-1-u3-X07"},{"t":"20.5","mis":"M6-1-u3-X01"},{"t":"0.205","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1640 ÷ 8 = 205예요.","16.4는 1640의 ⟨1/100⟩배라서 몫도 205의 ⟨1/100⟩배예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 16.4 ÷ 8 = 2.05예요."]},{"stem":"24.3 ÷ 6의 몫은 얼마인가요?","options":[{"t":"4.05","correct":true},{"t":"4.5","mis":"M6-1-u3-X07"},{"t":"40.5","mis":"M6-1-u3-X01"},{"t":"0.405","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 2430 ÷ 6 = 405예요.","24.3은 2430의 ⟨1/100⟩배라서 몫도 405의 ⟨1/100⟩배예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 24.3 ÷ 6 = 4.05예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L06_basic#2','math',6,1,'u3','L06','g6_1_math_u3_L06_basic','lesson_basic','M6-1-u3-C5',1,'mc','auto','1810 ÷ 2 = 905예요. 그러면 18.1 ÷ 2의 몫은 얼마인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":2,"concept":"M6-1-u3-C5","difficulty":1,"kind":"mc","stem":"1810 ÷ 2 = 905예요. 그러면 18.1 ÷ 2의 몫은 얼마인가요?","options":[{"t":"9.05","correct":true},{"t":"90.5","mis":"M6-1-u3-X01"},{"t":"0.905","mis":"M6-1-u3-X02"},{"t":"905","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 2는 그대로예요.","나누어지는 수 18.1은 1810의 ⟨1/100⟩배예요.","그래서 몫도 905의 ⟨1/100⟩배 — 9.05예요."],"variant_rule":{"alt":[{"stem":"1230 ÷ 6 = 205예요. 그러면 12.3 ÷ 6의 몫은 얼마인가요?","options":[{"t":"2.05","correct":true},{"t":"20.5","mis":"M6-1-u3-X01"},{"t":"0.205","mis":"M6-1-u3-X02"},{"t":"205","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 6은 그대로예요.","나누어지는 수 12.3은 1230의 ⟨1/100⟩배예요.","그래서 몫도 205의 ⟨1/100⟩배 — 2.05예요."]},{"stem":"40 ÷ 5 = 8이에요. 그러면 0.4 ÷ 5의 몫은 얼마인가요?","options":[{"t":"0.08","correct":true},{"t":"0.8","mis":"M6-1-u3-X01"},{"t":"0.008","mis":"M6-1-u3-X02"},{"t":"8","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 5는 그대로예요.","나누어지는 수 0.4는 40의 ⟨1/100⟩배예요.","그래서 몫도 8의 ⟨1/100⟩배 — 0.08이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L06_basic#3','math',6,1,'u3','L06','g6_1_math_u3_L06_basic','lesson_basic','M6-1-u3-C5',1,'sa','auto','12.3 ÷ 6의 몫에서 소수 둘째 자리 숫자는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u3-C5","difficulty":1,"kind":"sa","stem":"12.3 ÷ 6의 몫에서 소수 둘째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1230 ÷ 6 = 205예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 12.3 ÷ 6 = 2.05예요.","2.05의 소수 둘째 자리 숫자는 5예요."],"mis":"M6-1-u3-X13","variant_rule":{"alt":[{"stem":"24.48 ÷ 8의 몫에서 소수 둘째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 2448 ÷ 8 = 306이에요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 24.48 ÷ 8 = 3.06이에요.","3.06의 소수 둘째 자리 숫자는 6이에요."]},{"stem":"7.28 ÷ 7의 몫에서 소수 둘째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 728 ÷ 7 = 104예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 7.28 ÷ 7 = 1.04예요.","1.04의 소수 둘째 자리 숫자는 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L06_basic#4','math',6,1,'u3','L06','g6_1_math_u3_L06_basic','lesson_basic','M6-1-u3-C5',1,'mc','auto','9.05에서 0을 빠뜨리고 쓰면 어떻게 되나요?',ARRAY['M6-1-u3-X07','M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":4,"concept":"M6-1-u3-C5","difficulty":1,"kind":"mc","stem":"9.05에서 0을 빠뜨리고 쓰면 어떻게 되나요?","options":[{"t":"9.5가 되어 전혀 다른 수가 돼요","correct":true},{"t":"9.05 그대로예요","mis":"M6-1-u3-X07"},{"t":"90.5가 돼요","mis":"M6-1-u3-X01"},{"t":"0.905가 돼요","mis":"M6-1-u3-X02"}],"explanation":["수를 내려도 나누어야 할 수가 나누는 수보다 작으면 몫에 0을 써요.","그리고 수를 하나 더 내려 계산을 이어 가요.","이 0을 빠뜨리면 9.05가 9.5처럼 전혀 다른 수가 돼요."],"variant_rule":{"alt":[{"stem":"18.1 ÷ 2를 세로로 계산할 때 18을 나눈 뒤 1을 내렸더니 2보다 작아요. 다음에 할 일은 무엇인가요?","options":[{"t":"몫에 0을 쓰고 수를 하나 더 내려요","correct":true},{"t":"남은 1을 몫 뒤에 붙여요","mis":"M6-1-u3-X06"},{"t":"계산을 멈춰요","mis":"M6-1-u3-X06"},{"t":"나누는 수를 1로 바꿔요","mis":"M6-1-u3-X13"}],"explanation":["수를 내려도 나누어야 할 수가 나누는 수보다 작으면 몫에 0을 써요.","그리고 수를 하나 더 내려 계산을 이어 가요.","이 0을 빠뜨리면 9.05가 9.5처럼 전혀 다른 수가 돼요."]},{"stem":"몫의 소수 첫째 자리에 쓴 0은 어떤 구실을 하나요?","options":[{"t":"소수 첫째 자리를 지켜 다음 숫자가 제자리에 오게 해요","correct":true},{"t":"아무 구실도 없어 지워도 돼요","mis":"M6-1-u3-X07"},{"t":"몫을 10배 크게 해요","mis":"M6-1-u3-X01"},{"t":"나머지를 나타내요","mis":"M6-1-u3-X06"}],"explanation":["수를 내려도 나누어야 할 수가 나누는 수보다 작으면 몫에 0을 써요.","그리고 수를 하나 더 내려 계산을 이어 가요.","이 0을 빠뜨리면 9.05가 9.5처럼 전혀 다른 수가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L06_basic#5','math',6,1,'u3','L06','g6_1_math_u3_L06_basic','lesson_basic','M6-1-u3-C5',2,'mc','auto','7.28 ÷ 7의 몫은 얼마인가요?',ARRAY['M6-1-u3-X07','M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":5,"concept":"M6-1-u3-C5","difficulty":2,"kind":"mc","stem":"7.28 ÷ 7의 몫은 얼마인가요?","options":[{"t":"1.04","correct":true},{"t":"1.4","mis":"M6-1-u3-X07"},{"t":"10.4","mis":"M6-1-u3-X01"},{"t":"0.104","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 728 ÷ 7 = 104예요.","7.28은 728의 ⟨1/100⟩배라서 몫도 104의 ⟨1/100⟩배예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 7.28 ÷ 7 = 1.04예요."],"variant_rule":{"alt":[{"stem":"24.48 ÷ 8의 몫은 얼마인가요?","options":[{"t":"3.06","correct":true},{"t":"3.6","mis":"M6-1-u3-X07"},{"t":"30.6","mis":"M6-1-u3-X01"},{"t":"0.306","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 2448 ÷ 8 = 306이에요.","24.48은 2448의 ⟨1/100⟩배라서 몫도 306의 ⟨1/100⟩배예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 24.48 ÷ 8 = 3.06이에요."]},{"stem":"15.3 ÷ 5의 몫은 얼마인가요?","options":[{"t":"3.06","correct":true},{"t":"3.6","mis":"M6-1-u3-X07"},{"t":"30.6","mis":"M6-1-u3-X01"},{"t":"0.306","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1530 ÷ 5 = 306이에요.","15.3은 1530의 ⟨1/100⟩배라서 몫도 306의 ⟨1/100⟩배예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 15.3 ÷ 5 = 3.06이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L06_basic#6','math',6,1,'u3','L06','g6_1_math_u3_L06_basic','lesson_basic','M6-1-u3-C5',2,'mc','auto','물 16.4 L를 8일 동안 매일 같은 양씩 마셨어요. 하루에 마신 물은 몇 L인가요?',ARRAY['M6-1-u3-X07','M6-1-u3-X10','M6-1-u3-X01']::text[],true,'{"seq":6,"concept":"M6-1-u3-C5","difficulty":2,"kind":"mc","stem":"물 16.4 L를 8일 동안 매일 같은 양씩 마셨어요. 하루에 마신 물은 몇 L인가요?","options":[{"t":"2.05 L","correct":true},{"t":"2.5 L","mis":"M6-1-u3-X07"},{"t":"131.2 L","mis":"M6-1-u3-X10"},{"t":"20.5 L","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1640 ÷ 8 = 205예요.","16.4는 1640의 ⟨1/100⟩배라서 몫도 205의 ⟨1/100⟩배예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 16.4 ÷ 8 = 2.05예요."],"variant_rule":{"alt":[{"stem":"물 18.27 L를 9일 동안 매일 같은 양씩 마셨어요. 하루에 마신 물은 몇 L인가요?","options":[{"t":"2.03 L","correct":true},{"t":"2.3 L","mis":"M6-1-u3-X07"},{"t":"164.43 L","mis":"M6-1-u3-X10"},{"t":"20.3 L","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1827 ÷ 9 = 203이에요.","18.27은 1827의 ⟨1/100⟩배라서 몫도 203의 ⟨1/100⟩배예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 18.27 ÷ 9 = 2.03이에요."]},{"stem":"물 25.2 L를 5일 동안 매일 같은 양씩 마셨어요. 하루에 마신 물은 몇 L인가요?","options":[{"t":"5.04 L","correct":true},{"t":"5.4 L","mis":"M6-1-u3-X07"},{"t":"126 L","mis":"M6-1-u3-X10"},{"t":"50.4 L","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 2520 ÷ 5 = 504예요.","25.2는 2520의 ⟨1/100⟩배라서 몫도 504의 ⟨1/100⟩배예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 25.2 ÷ 5 = 5.04예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L06_basic#7','math',6,1,'u3','L06','g6_1_math_u3_L06_basic','lesson_basic','M6-1-u3-C5',2,'mc','auto','끈 7.28 m를 똑같이 일곱 도막으로 잘랐어요. 한 도막의 길이는 몇 cm인가요?',ARRAY['M6-1-u3-X07','M6-1-u3-X11']::text[],true,'{"seq":7,"concept":"M6-1-u3-C5","difficulty":2,"kind":"mc","stem":"끈 7.28 m를 똑같이 일곱 도막으로 잘랐어요. 한 도막의 길이는 몇 cm인가요?","options":[{"t":"104 cm","correct":true},{"t":"140 cm","mis":"M6-1-u3-X07"},{"t":"10.4 cm","mis":"M6-1-u3-X11"},{"t":"1040 cm","mis":"M6-1-u3-X11"}],"explanation":["내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 7.28 ÷ 7 = 1.04예요.","1 m는 100 cm예요.","1.04 m는 104 cm예요."],"variant_rule":{"alt":[{"stem":"끈 6.18 m를 똑같이 여섯 도막으로 잘랐어요. 한 도막의 길이는 몇 cm인가요?","options":[{"t":"103 cm","correct":true},{"t":"130 cm","mis":"M6-1-u3-X07"},{"t":"10.3 cm","mis":"M6-1-u3-X11"},{"t":"1030 cm","mis":"M6-1-u3-X11"}],"explanation":["내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 6.18 ÷ 6 = 1.03이에요.","1 m는 100 cm예요.","1.03 m는 103 cm예요."]},{"stem":"끈 5.15 m를 똑같이 다섯 도막으로 잘랐어요. 한 도막의 길이는 몇 cm인가요?","options":[{"t":"103 cm","correct":true},{"t":"130 cm","mis":"M6-1-u3-X07"},{"t":"10.3 cm","mis":"M6-1-u3-X11"},{"t":"1030 cm","mis":"M6-1-u3-X11"}],"explanation":["내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 5.15 ÷ 5 = 1.03이에요.","1 m는 100 cm예요.","1.03 m는 103 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L06_basic#8','math',6,1,'u3','L06','g6_1_math_u3_L06_basic','lesson_basic','M6-1-u3-C5',2,'ox','auto','18.1 ÷ 2의 몫은 9.5예요.',ARRAY['M6-1-u3-X07']::text[],true,'{"seq":8,"concept":"M6-1-u3-C5","difficulty":2,"kind":"ox","stem":"18.1 ÷ 2의 몫은 9.5예요.","answer":"X","reason_options":[{"t":"1을 내리면 2보다 작아 몫에 0을 써서 9.05이기 때문에","correct":true},{"t":"18 ÷ 2 = 9이고 1을 2로 나누면 0.5이기 때문에","mis":"M6-1-u3-X07"}],"mis":"M6-1-u3-X07","explanation":["수를 내려도 나누어야 할 수가 나누는 수보다 작으면 몫에 0을 써요.","그리고 수를 하나 더 내려 계산을 이어 가요.","이 0을 빠뜨리면 전혀 다른 수가 돼요."],"variant_rule":{"alt":[{"stem":"0.4 ÷ 5의 몫은 0.08이에요.","answer":"O","reason_options":[{"t":"40 ÷ 5 = 8이고 0.4는 40의 ⟨1/100⟩배이기 때문에","correct":true},{"t":"4 ÷ 5 = 0.8이니 몫도 0.8이기 때문에","mis":"M6-1-u3-X07"}],"explanation":["수를 내려도 나누어야 할 수가 나누는 수보다 작으면 몫에 0을 써요.","그리고 수를 하나 더 내려 계산을 이어 가요.","이 0을 빠뜨리면 전혀 다른 수가 돼요."]},{"stem":"내린 수가 나누는 수보다 작으면 그 자리는 비워 두고 다음 수를 내려요.","answer":"X","reason_options":[{"t":"비워 두지 않고 몫에 0을 써야 자리가 맞기 때문에","correct":true},{"t":"빈자리는 나중에 채우면 되기 때문에","mis":"M6-1-u3-X07"}],"explanation":["수를 내려도 나누어야 할 수가 나누는 수보다 작으면 몫에 0을 써요.","그리고 수를 하나 더 내려 계산을 이어 가요.","이 0을 빠뜨리면 전혀 다른 수가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L06_basic#9','math',6,1,'u3','L06','g6_1_math_u3_L06_basic','lesson_basic','M6-1-u3-C5',2,'mc','auto','친구가 18.1 ÷ 2의 몫을 9.5라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X06','M6-1-u3-X05']::text[],true,'{"seq":9,"concept":"M6-1-u3-C5","difficulty":2,"kind":"mc","stem":"친구가 18.1 ÷ 2의 몫을 9.5라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"내린 수가 나누는 수보다 작을 때 몫에 0을 쓰지 않아서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"0을 내려 계산하지 않아서","mis":"M6-1-u3-X06"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1810 ÷ 2 = 905예요.","내린 수가 2보다 작으면 몫에 0을 쓰고 하나 더 내려야 해요.","바른 몫은 9.05이고 9.5는 다른 수예요."],"variant_rule":{"alt":[{"stem":"친구가 12.3 ÷ 6의 몫을 2.5라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"내린 수가 나누는 수보다 작을 때 몫에 0을 쓰지 않아서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"0을 내려 계산하지 않아서","mis":"M6-1-u3-X06"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1230 ÷ 6 = 205예요.","내린 수가 6보다 작으면 몫에 0을 쓰고 하나 더 내려야 해요.","바른 몫은 2.05이고 2.5는 다른 수예요."]},{"stem":"친구가 16.4 ÷ 8의 몫을 2.5라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"내린 수가 나누는 수보다 작을 때 몫에 0을 쓰지 않아서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"0을 내려 계산하지 않아서","mis":"M6-1-u3-X06"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1640 ÷ 8 = 205예요.","내린 수가 8보다 작으면 몫에 0을 쓰고 하나 더 내려야 해요.","바른 몫은 2.05이고 2.5는 다른 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L06_basic#10','math',6,1,'u3','L06','g6_1_math_u3_L06_basic','lesson_basic','M6-1-u3-C5',3,'sa','auto','6.0□가 48.4 ÷ 8의 몫보다 커요. □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u3-C5","difficulty":3,"kind":"sa","stem":"6.0□가 48.4 ÷ 8의 몫보다 커요. □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 4840 ÷ 8 = 605예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 48.4 ÷ 8 = 6.05예요.","6.0□ > 6.05 — □는 6부터 9까지, 4개예요."],"mis":"M6-1-u3-X07","variant_rule":{"alt":[{"stem":"4.0□가 24.3 ÷ 6의 몫보다 커요. □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 2430 ÷ 6 = 405예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 24.3 ÷ 6 = 4.05예요.","4.0□ > 4.05 — □는 6부터 9까지, 4개예요."]},{"stem":"3.0□가 15.3 ÷ 5의 몫보다 작아요. □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1530 ÷ 5 = 306이에요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 15.3 ÷ 5 = 3.06이에요.","3.0□ < 3.06 — □는 1부터 5까지, 5개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L06_challenge#1','math',6,1,'u3','L06','g6_1_math_u3_L06_challenge','lesson_challenge','M6-1-u3-C5',2,'mc','auto','5.25 ÷ 5의 몫은 얼마인가요?',ARRAY['M6-1-u3-X07','M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":1,"concept":"M6-1-u3-C5","difficulty":2,"kind":"mc","stem":"5.25 ÷ 5의 몫은 얼마인가요?","options":[{"t":"1.05","correct":true},{"t":"1.5","mis":"M6-1-u3-X07"},{"t":"10.5","mis":"M6-1-u3-X01"},{"t":"0.105","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 525 ÷ 5 = 105예요.","5.25는 525의 ⟨1/100⟩배라서 몫도 105의 ⟨1/100⟩배예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 5.25 ÷ 5 = 1.05예요."],"variant_rule":{"alt":[{"stem":"30.3 ÷ 6의 몫은 얼마인가요?","options":[{"t":"5.05","correct":true},{"t":"5.5","mis":"M6-1-u3-X07"},{"t":"50.5","mis":"M6-1-u3-X01"},{"t":"0.505","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 3030 ÷ 6 = 505예요.","30.3은 3030의 ⟨1/100⟩배라서 몫도 505의 ⟨1/100⟩배예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 30.3 ÷ 6 = 5.05예요."]},{"stem":"16.24 ÷ 8의 몫은 얼마인가요?","options":[{"t":"2.03","correct":true},{"t":"2.3","mis":"M6-1-u3-X07"},{"t":"20.3","mis":"M6-1-u3-X01"},{"t":"0.203","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1624 ÷ 8 = 203이에요.","16.24는 1624의 ⟨1/100⟩배라서 몫도 203의 ⟨1/100⟩배예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 16.24 ÷ 8 = 2.03이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L06_challenge#2','math',6,1,'u3','L06','g6_1_math_u3_L06_challenge','lesson_challenge','M6-1-u3-C5',2,'sa','auto','30.3 ÷ 6의 몫에서 소수 둘째 자리 숫자는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u3-C5","difficulty":2,"kind":"sa","stem":"30.3 ÷ 6의 몫에서 소수 둘째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 3030 ÷ 6 = 505예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 30.3 ÷ 6 = 5.05예요.","5.05의 소수 둘째 자리 숫자는 5예요."],"mis":"M6-1-u3-X13","variant_rule":{"alt":[{"stem":"16.24 ÷ 8의 몫에서 소수 둘째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1624 ÷ 8 = 203이에요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 16.24 ÷ 8 = 2.03이에요.","2.03의 소수 둘째 자리 숫자는 3이에요."]},{"stem":"18.27 ÷ 9의 몫에서 소수 둘째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1827 ÷ 9 = 203이에요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 18.27 ÷ 9 = 2.03이에요.","2.03의 소수 둘째 자리 숫자는 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L06_challenge#3','math',6,1,'u3','L06','g6_1_math_u3_L06_challenge','lesson_challenge','M6-1-u3-C5',3,'error','auto','18.1 ÷ 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u3-X07','M6-1-u3-X14']::text[],true,'{"seq":3,"concept":"M6-1-u3-C5","difficulty":3,"kind":"error","stem":"18.1 ÷ 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「몫은 9.5야.」","correct":true,"mis_target":"M6-1-u3-X07"},{"t":"이현 — 「몫은 9보다 조금 커.」","mis":"M6-1-u3-X14"},{"t":"서아 — 「몫의 소수 첫째 자리에 0이 들어가.」","mis":"M6-1-u3-X14"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1810 ÷ 2 = 905예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 18.1 ÷ 2 = 9.05예요.","준희는 몫 가운데 0을 빠뜨렸어요."],"variant_rule":{"alt":[{"stem":"24.3 ÷ 6을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「몫은 4.5야.」","correct":true,"mis_target":"M6-1-u3-X07"},{"t":"수아 — 「몫은 4보다 조금 커.」","mis":"M6-1-u3-X14"},{"t":"도윤 — 「몫의 소수 첫째 자리에 0이 들어가.」","mis":"M6-1-u3-X14"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 2430 ÷ 6 = 405예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 24.3 ÷ 6 = 4.05예요.","서호는 몫 가운데 0을 빠뜨렸어요."]},{"stem":"7.28 ÷ 7을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「몫은 1.4야.」","correct":true,"mis_target":"M6-1-u3-X07"},{"t":"나린 — 「몫은 1보다 조금 커.」","mis":"M6-1-u3-X14"},{"t":"유진 — 「몫의 소수 첫째 자리에 0이 들어가.」","mis":"M6-1-u3-X14"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 728 ÷ 7 = 104예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 7.28 ÷ 7 = 1.04예요.","가온은 몫 가운데 0을 빠뜨렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L06_challenge#4','math',6,1,'u3','L06','g6_1_math_u3_L06_challenge','lesson_challenge','M6-1-u3-C5',3,'ox','auto','9.05와 9.5는 같은 수예요.',ARRAY['M6-1-u3-X07']::text[],true,'{"seq":4,"concept":"M6-1-u3-C5","difficulty":3,"kind":"ox","stem":"9.05와 9.5는 같은 수예요.","answer":"X","reason_options":[{"t":"9.05의 0은 소수 첫째 자리를 지키는 숫자라 두 수는 다르기 때문에","correct":true},{"t":"가운데 0은 없어도 되는 숫자이기 때문에","mis":"M6-1-u3-X07"}],"mis":"M6-1-u3-X07","explanation":["수를 내려도 나누어야 할 수가 나누는 수보다 작으면 몫에 0을 써요.","그리고 수를 하나 더 내려 계산을 이어 가요.","이 0을 빠뜨리면 전혀 다른 수가 돼요."],"variant_rule":{"alt":[{"stem":"12.3 ÷ 6의 몫의 소수 첫째 자리 숫자는 0이에요.","answer":"O","reason_options":[{"t":"12.3 ÷ 6 = 2.05이기 때문에","correct":true},{"t":"12 ÷ 6 = 2라서 첫째 자리는 비어 있기 때문에","mis":"M6-1-u3-X07"}],"explanation":["수를 내려도 나누어야 할 수가 나누는 수보다 작으면 몫에 0을 써요.","그리고 수를 하나 더 내려 계산을 이어 가요.","이 0을 빠뜨리면 전혀 다른 수가 돼요."]},{"stem":"16.4 ÷ 8의 몫은 2.05예요.","answer":"O","reason_options":[{"t":"1640 ÷ 8 = 205이고 16.4는 1640의 ⟨1/100⟩배이기 때문에","correct":true},{"t":"16 ÷ 8 = 2이고 4 ÷ 8 = 0.5이기 때문에","mis":"M6-1-u3-X07"}],"explanation":["수를 내려도 나누어야 할 수가 나누는 수보다 작으면 몫에 0을 써요.","그리고 수를 하나 더 내려 계산을 이어 가요.","이 0을 빠뜨리면 전혀 다른 수가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L06_challenge#5','math',6,1,'u3','L06','g6_1_math_u3_L06_challenge','lesson_challenge','M6-1-u3-C5',3,'mc','auto','몫의 소수 첫째 자리에 0이 들어가는 나눗셈은 어느 것인가요?',ARRAY['M6-1-u3-X12']::text[],true,'{"seq":5,"concept":"M6-1-u3-C5","difficulty":3,"kind":"mc","stem":"몫의 소수 첫째 자리에 0이 들어가는 나눗셈은 어느 것인가요?","options":[{"t":"18.1 ÷ 2","correct":true},{"t":"19.8 ÷ 4","mis":"M6-1-u3-X12"},{"t":"11.7 ÷ 3","mis":"M6-1-u3-X12"},{"t":"3.2 ÷ 4","mis":"M6-1-u3-X12"}],"explanation":["몫을 하나씩 구해 소수 첫째 자리 숫자를 봐요.","18.1 ÷ 2 = 9.05, 19.8 ÷ 4 = 4.95, 11.7 ÷ 3 = 3.9, 3.2 ÷ 4 = 0.8이에요.","소수 첫째 자리가 0인 것은 18.1 ÷ 2예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 몫의 소수 첫째 자리에 0이 들어가는 나눗셈은 어느 것인가요?","options":[{"t":"24.48 ÷ 8","correct":true},{"t":"6.7 ÷ 5","mis":"M6-1-u3-X12"},{"t":"34.5 ÷ 5","mis":"M6-1-u3-X12"},{"t":"8.3 ÷ 2","mis":"M6-1-u3-X12"}],"explanation":["몫을 하나씩 구해 소수 첫째 자리 숫자를 봐요.","6.7 ÷ 5 = 1.34, 24.48 ÷ 8 = 3.06, 34.5 ÷ 5 = 6.9, 8.3 ÷ 2 = 4.15예요.","소수 첫째 자리가 0인 것은 24.48 ÷ 8이에요."]},{"stem":"이번에는 다른 보기예요. 몫의 소수 첫째 자리에 0이 들어가는 나눗셈은 어느 것인가요?","options":[{"t":"15.3 ÷ 5","correct":true},{"t":"5.6 ÷ 7","mis":"M6-1-u3-X12"},{"t":"9.8 ÷ 4","mis":"M6-1-u3-X12"},{"t":"22.68 ÷ 4","mis":"M6-1-u3-X12"}],"explanation":["몫을 하나씩 구해 소수 첫째 자리 숫자를 봐요.","5.6 ÷ 7 = 0.8, 9.8 ÷ 4 = 2.45, 22.68 ÷ 4 = 5.67, 15.3 ÷ 5 = 3.06이에요.","소수 첫째 자리가 0인 것은 15.3 ÷ 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L06_challenge#6','math',6,1,'u3','L06','g6_1_math_u3_L06_challenge','lesson_challenge','M6-1-u3-C5',3,'mc','auto','강변을 자전거로 같은 빠르기로 달려 18.1 km를 가는 데 2시간이 걸렸어요. 한 시간 동안 몇 km를 달렸나요?',ARRAY['M6-1-u3-X07','M6-1-u3-X10','M6-1-u3-X01']::text[],true,'{"seq":6,"concept":"M6-1-u3-C5","difficulty":3,"kind":"mc","stem":"강변을 자전거로 같은 빠르기로 달려 18.1 km를 가는 데 2시간이 걸렸어요. 한 시간 동안 몇 km를 달렸나요?","options":[{"t":"9.05 km","correct":true},{"t":"9.5 km","mis":"M6-1-u3-X07"},{"t":"36.2 km","mis":"M6-1-u3-X10"},{"t":"90.5 km","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1810 ÷ 2 = 905예요.","18.1은 1810의 ⟨1/100⟩배라서 몫도 905의 ⟨1/100⟩배예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 18.1 ÷ 2 = 9.05예요."],"variant_rule":{"alt":[{"stem":"강변을 자전거로 같은 빠르기로 달려 24.3 km를 가는 데 6시간이 걸렸어요. 한 시간 동안 몇 km를 달렸나요?","options":[{"t":"4.05 km","correct":true},{"t":"4.5 km","mis":"M6-1-u3-X07"},{"t":"145.8 km","mis":"M6-1-u3-X10"},{"t":"40.5 km","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 2430 ÷ 6 = 405예요.","24.3은 2430의 ⟨1/100⟩배라서 몫도 405의 ⟨1/100⟩배예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 24.3 ÷ 6 = 4.05예요."]},{"stem":"강변을 자전거로 같은 빠르기로 달려 12.15 km를 가는 데 3시간이 걸렸어요. 한 시간 동안 몇 km를 달렸나요?","options":[{"t":"4.05 km","correct":true},{"t":"4.5 km","mis":"M6-1-u3-X07"},{"t":"36.45 km","mis":"M6-1-u3-X10"},{"t":"40.5 km","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1215 ÷ 3 = 405예요.","12.15는 1215의 ⟨1/100⟩배라서 몫도 405의 ⟨1/100⟩배예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 12.15 ÷ 3 = 4.05예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L06_challenge#7','math',6,1,'u3','L06','g6_1_math_u3_L06_challenge','lesson_challenge','M6-1-u3-C1',3,'match','auto','나눗셈식과 몫을 알맞게 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u3-C1","difficulty":3,"kind":"match","stem":"나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"18.1 ÷ 2","r":"9.05"},{"l":"16.4 ÷ 8","r":"2.05"},{"l":"24.3 ÷ 6","r":"4.05"}],"mis":"M6-1-u3-X02","explanation":["자연수의 나눗셈으로 몫을 구한 뒤 같은 배율만큼 작게 해요.","18.1 ÷ 2 = 9.05, 16.4 ÷ 8 = 2.05, 24.3 ÷ 6 = 4.05예요.","어림한 값과 견주어 소수점 자리를 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"7.28 ÷ 7","r":"1.04"},{"l":"24.48 ÷ 8","r":"3.06"},{"l":"20.2 ÷ 5","r":"4.04"}],"explanation":["자연수의 나눗셈으로 몫을 구한 뒤 같은 배율만큼 작게 해요.","7.28 ÷ 7 = 1.04, 24.48 ÷ 8 = 3.06, 20.2 ÷ 5 = 4.04예요.","어림한 값과 견주어 소수점 자리를 확인해요."]},{"stem":"이번에는 다른 보기예요. 나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"5.25 ÷ 5","r":"1.05"},{"l":"30.3 ÷ 6","r":"5.05"},{"l":"16.24 ÷ 8","r":"2.03"}],"explanation":["자연수의 나눗셈으로 몫을 구한 뒤 같은 배율만큼 작게 해요.","5.25 ÷ 5 = 1.05, 30.3 ÷ 6 = 5.05, 16.24 ÷ 8 = 2.03이에요.","어림한 값과 견주어 소수점 자리를 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L06_challenge#8','math',6,1,'u3','L06','g6_1_math_u3_L06_challenge','lesson_challenge','M6-1-u3-C5',4,'mc','auto','어떤 수를 8로 나누었더니 몫이 2.05가 되었어요. 어떤 수를 5로 나눈 몫은 얼마인가요?',ARRAY['M6-1-u3-X14','M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":8,"concept":"M6-1-u3-C5","difficulty":4,"kind":"mc","stem":"어떤 수를 8로 나누었더니 몫이 2.05가 되었어요. 어떤 수를 5로 나눈 몫은 얼마인가요?","options":[{"t":"3.28","correct":true},{"t":"16.4","mis":"M6-1-u3-X14"},{"t":"32.8","mis":"M6-1-u3-X01"},{"t":"0.328","mis":"M6-1-u3-X02"}],"explanation":["어떤 수는 2.05 × 8 = 16.4예요.","이제 16.4 ÷ 5를 계산해요.","16.4 ÷ 5 = 3.28이에요."],"variant_rule":{"alt":[{"stem":"어떤 수를 6으로 나누었더니 몫이 4.05가 되었어요. 어떤 수를 5로 나눈 몫은 얼마인가요?","options":[{"t":"4.86","correct":true},{"t":"24.3","mis":"M6-1-u3-X14"},{"t":"48.6","mis":"M6-1-u3-X01"},{"t":"0.486","mis":"M6-1-u3-X02"}],"explanation":["어떤 수는 4.05 × 6 = 24.3이에요.","이제 24.3 ÷ 5를 계산해요.","24.3 ÷ 5 = 4.86이에요."]},{"stem":"어떤 수를 7로 나누었더니 몫이 1.04가 되었어요. 어떤 수를 4로 나눈 몫은 얼마인가요?","options":[{"t":"1.82","correct":true},{"t":"7.28","mis":"M6-1-u3-X14"},{"t":"18.2","mis":"M6-1-u3-X01"},{"t":"0.182","mis":"M6-1-u3-X02"}],"explanation":["어떤 수는 1.04 × 7 = 7.28이에요.","이제 7.28 ÷ 4를 계산해요.","7.28 ÷ 4 = 1.82예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L06_challenge#9','math',6,1,'u3','L06','g6_1_math_u3_L06_challenge','lesson_challenge','M6-1-u3-C5',4,'sa','auto','친구가 18.1 ÷ 2의 몫에서 0을 빠뜨려 9.5라고 썼어요. 친구가 쓴 수와 바른 몫의 차는 0.01이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u3-C5","difficulty":4,"kind":"sa","stem":"친구가 18.1 ÷ 2의 몫에서 0을 빠뜨려 9.5라고 썼어요. 친구가 쓴 수와 바른 몫의 차는 0.01이 몇 개인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["바른 몫은 9.05예요.","9.5 − 9.05 = 0.45예요.","0.45는 0.01이 45개예요 — 0 하나가 이만큼 차이를 만들어요."],"mis":"M6-1-u3-X07","variant_rule":{"alt":[{"stem":"친구가 12.3 ÷ 6의 몫에서 0을 빠뜨려 2.5라고 썼어요. 친구가 쓴 수와 바른 몫의 차는 0.01이 몇 개인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["바른 몫은 2.05예요.","2.5 − 2.05 = 0.45예요.","0.45는 0.01이 45개예요 — 0 하나가 이만큼 차이를 만들어요."]},{"stem":"친구가 7.28 ÷ 7의 몫에서 0을 빠뜨려 1.4라고 썼어요. 친구가 쓴 수와 바른 몫의 차는 0.01이 몇 개인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["바른 몫은 1.04예요.","1.4 − 1.04 = 0.36이에요.","0.36은 0.01이 36개예요 — 0 하나가 이만큼 차이를 만들어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L06_challenge#10','math',6,1,'u3','L06','g6_1_math_u3_L06_challenge','lesson_challenge','M6-1-u3-C5',4,'essay','teacher','강변을 자전거로 같은 빠르기로 18.1 km를 달리는 데 2시간이 걸렸어요. 한 시간 동안 달린 거리를 구하고, 친구가 쓴 9.5 km가 왜 틀렸는지 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u3-C5","difficulty":4,"kind":"essay","stem":"강변을 자전거로 같은 빠르기로 18.1 km를 달리는 데 2시간이 걸렸어요. 한 시간 동안 달린 거리를 구하고, 친구가 쓴 9.5 km가 왜 틀렸는지 설명해 보세요.","answer_guide":{"answer":"예: 18.1 ÷ 2를 계산한다. 18을 2로 나누면 9이고 1을 내렸지만 1은 2보다 작으므로 몫에 0을 쓰고 수를 하나 더 내려 10 ÷ 2 = 5로 계산한다. 그래서 몫은 9.05이고 한 시간에 9.05 km를 달렸다. 9.5는 몫 가운데 0을 빠뜨려 전혀 다른 수가 되었다.","scoring_points":["몫에 0을 쓰고 하나 더 내렸는가","9.05 km를 구했는가","9.5는 0을 빠뜨린 것이라고 설명했는가"]},"explanation":["1을 내려도 2보다 작아 몫에 0을 써요.","18.1 ÷ 2 = 9.05 — 9.05 km예요.","9.5는 0을 빠뜨렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L07_basic#1','math',6,1,'u3','L07','g6_1_math_u3_L07_basic','lesson_basic','M6-1-u3-C6',1,'mc','auto','6 ÷ 5의 몫은 얼마인가요?',ARRAY['M6-1-u3-X08','M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":1,"concept":"M6-1-u3-C6","difficulty":1,"kind":"mc","stem":"6 ÷ 5의 몫은 얼마인가요?","options":[{"t":"1.2","correct":true},{"t":"1.1","mis":"M6-1-u3-X08"},{"t":"12","mis":"M6-1-u3-X01"},{"t":"0.12","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 60 ÷ 5 = 12예요.","6은 60의 ⟨1/10⟩배라서 몫도 12의 ⟨1/10⟩배예요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 6 ÷ 5 = 1.2예요."],"variant_rule":{"alt":[{"stem":"3 ÷ 4의 몫은 얼마인가요?","options":[{"t":"0.75","correct":true},{"t":"0.3","mis":"M6-1-u3-X08"},{"t":"7.5","mis":"M6-1-u3-X01"},{"t":"0.075","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 300 ÷ 4 = 75예요.","3은 300의 ⟨1/100⟩배라서 몫도 75의 ⟨1/100⟩배예요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 3 ÷ 4 = 0.75예요."]},{"stem":"9 ÷ 6의 몫은 얼마인가요?","options":[{"t":"1.5","correct":true},{"t":"1.3","mis":"M6-1-u3-X08"},{"t":"15","mis":"M6-1-u3-X01"},{"t":"0.15","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 90 ÷ 6 = 15예요.","9는 90의 ⟨1/10⟩배라서 몫도 15의 ⟨1/10⟩배예요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 9 ÷ 6 = 1.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L07_basic#2','math',6,1,'u3','L07','g6_1_math_u3_L07_basic','lesson_basic','M6-1-u3-C6',1,'sa','auto','6 ÷ 5의 몫을 분수로 쓰면 ⟨6/5⟩이에요. 분모를 10으로 고치면 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u3-C6","difficulty":1,"kind":"sa","stem":"6 ÷ 5의 몫을 분수로 쓰면 ⟨6/5⟩이에요. 분모를 10으로 고치면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["분모 5를 10으로 만들려면 분모와 분자에 2를 곱해요.","⟨6/5⟩ = ⟨12/10⟩예요.","분자는 12이고 소수로 쓰면 1.2예요."],"mis":"M6-1-u3-X13","variant_rule":{"alt":[{"stem":"3 ÷ 4의 몫을 분수로 쓰면 ⟨3/4⟩이에요. 분모를 100으로 고치면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["분모 4를 100으로 만들려면 분모와 분자에 25를 곱해요.","⟨3/4⟩ = ⟨75/100⟩예요.","분자는 75이고 소수로 쓰면 0.75예요."]},{"stem":"7 ÷ 2의 몫을 분수로 쓰면 ⟨7/2⟩이에요. 분모를 10으로 고치면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["분모 2를 10으로 만들려면 분모와 분자에 5를 곱해요.","⟨7/2⟩ = ⟨35/10⟩예요.","분자는 35이고 소수로 쓰면 3.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L07_basic#3','math',6,1,'u3','L07','g6_1_math_u3_L07_basic','lesson_basic','M6-1-u3-C6',1,'mc','auto','6 ÷ 5를 세로셈으로 계산할 때 6을 어떻게 보아야 하나요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":3,"concept":"M6-1-u3-C6","difficulty":1,"kind":"mc","stem":"6 ÷ 5를 세로셈으로 계산할 때 6을 어떻게 보아야 하나요?","options":[{"t":"6.0으로 봐요","correct":true},{"t":"60으로 봐요","mis":"M6-1-u3-X01"},{"t":"0.6으로 봐요","mis":"M6-1-u3-X02"},{"t":"⟨6/10⟩으로 봐요","mis":"M6-1-u3-X02"}],"explanation":["자연수의 소수점은 자연수 바로 뒤에 있어요.","6 = 6.0 = 6.00이에요.","그래서 6을 6.0으로 보고 0을 내려 계산해요."],"variant_rule":{"alt":[{"stem":"9 ÷ 6을 세로셈으로 계산할 때 9를 어떻게 보아야 하나요?","options":[{"t":"9.0으로 봐요","correct":true},{"t":"90으로 봐요","mis":"M6-1-u3-X01"},{"t":"0.9로 봐요","mis":"M6-1-u3-X02"},{"t":"⟨9/10⟩로 봐요","mis":"M6-1-u3-X02"}],"explanation":["자연수의 소수점은 자연수 바로 뒤에 있어요.","9 = 9.0 = 9.00이에요.","그래서 9를 9.0으로 보고 0을 내려 계산해요."]},{"stem":"7 ÷ 4를 세로셈으로 계산할 때 7을 어떻게 보아야 하나요?","options":[{"t":"7.0으로 봐요","correct":true},{"t":"70으로 봐요","mis":"M6-1-u3-X01"},{"t":"0.7로 봐요","mis":"M6-1-u3-X02"},{"t":"⟨7/10⟩로 봐요","mis":"M6-1-u3-X02"}],"explanation":["자연수의 소수점은 자연수 바로 뒤에 있어요.","7 = 7.0 = 7.00이에요.","그래서 7을 7.0으로 보고 0을 내려 계산해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L07_basic#4','math',6,1,'u3','L07','g6_1_math_u3_L07_basic','lesson_basic','M6-1-u3-C6',1,'sa','auto','40 ÷ 16의 몫에서 소수 첫째 자리 숫자는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u3-C6","difficulty":1,"kind":"sa","stem":"40 ÷ 16의 몫에서 소수 첫째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 400 ÷ 16 = 25예요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 40 ÷ 16 = 2.5예요.","2.5의 소수 첫째 자리 숫자는 5예요."],"mis":"M6-1-u3-X13","variant_rule":{"alt":[{"stem":"9 ÷ 4의 몫에서 소수 둘째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 900 ÷ 4 = 225예요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 9 ÷ 4 = 2.25예요.","2.25의 소수 둘째 자리 숫자는 5예요."]},{"stem":"14 ÷ 8의 몫에서 소수 첫째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1400 ÷ 8 = 175예요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 14 ÷ 8 = 1.75예요.","1.75의 소수 첫째 자리 숫자는 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L07_basic#5','math',6,1,'u3','L07','g6_1_math_u3_L07_basic','lesson_basic','M6-1-u3-C6',2,'mc','auto','통조림 6개의 무게가 9 kg이에요. 무게가 모두 같다면 통조림 한 개의 무게는 몇 kg인가요?',ARRAY['M6-1-u3-X08','M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":5,"concept":"M6-1-u3-C6","difficulty":2,"kind":"mc","stem":"통조림 6개의 무게가 9 kg이에요. 무게가 모두 같다면 통조림 한 개의 무게는 몇 kg인가요?","options":[{"t":"1.5 kg","correct":true},{"t":"1.3 kg","mis":"M6-1-u3-X08"},{"t":"15 kg","mis":"M6-1-u3-X01"},{"t":"0.15 kg","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 90 ÷ 6 = 15예요.","9는 90의 ⟨1/10⟩배라서 몫도 15의 ⟨1/10⟩배예요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 9 ÷ 6 = 1.5예요."],"variant_rule":{"alt":[{"stem":"통조림 8개의 무게가 14 kg이에요. 무게가 모두 같다면 통조림 한 개의 무게는 몇 kg인가요?","options":[{"t":"1.75 kg","correct":true},{"t":"1.6 kg","mis":"M6-1-u3-X08"},{"t":"17.5 kg","mis":"M6-1-u3-X01"},{"t":"0.175 kg","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1400 ÷ 8 = 175예요.","14는 1400의 ⟨1/100⟩배라서 몫도 175의 ⟨1/100⟩배예요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 14 ÷ 8 = 1.75예요."]},{"stem":"통조림 6개의 무게가 21 kg이에요. 무게가 모두 같다면 통조림 한 개의 무게는 몇 kg인가요?","options":[{"t":"3.5 kg","correct":true},{"t":"3.3 kg","mis":"M6-1-u3-X08"},{"t":"35 kg","mis":"M6-1-u3-X01"},{"t":"0.35 kg","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 210 ÷ 6 = 35예요.","21은 210의 ⟨1/10⟩배라서 몫도 35의 ⟨1/10⟩배예요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 21 ÷ 6 = 3.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L07_basic#6','math',6,1,'u3','L07','g6_1_math_u3_L07_basic','lesson_basic','M6-1-u3-C6',2,'sa','auto','리본 9 m를 똑같이 열두 도막으로 잘랐어요. 한 도막의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u3-C6","difficulty":2,"kind":"sa","stem":"리본 9 m를 똑같이 열두 도막으로 잘랐어요. 한 도막의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 9 ÷ 12 = 0.75예요.","1 m는 100 cm예요.","0.75 m는 75 cm예요."],"mis":"M6-1-u3-X11","variant_rule":{"alt":[{"stem":"리본 7 m를 똑같이 스무 도막으로 잘랐어요. 한 도막의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 7 ÷ 20 = 0.35예요.","1 m는 100 cm예요.","0.35 m는 35 cm예요."]},{"stem":"리본 9 m를 똑같이 스무 도막으로 잘랐어요. 한 도막의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 9 ÷ 20 = 0.45예요.","1 m는 100 cm예요.","0.45 m는 45 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L07_basic#7','math',6,1,'u3','L07','g6_1_math_u3_L07_basic','lesson_basic','M6-1-u3-C6',2,'mc','auto','분수 광장의 분수대는 가로가 6 m, 세로가 5 m예요. 가로는 세로의 몇 배인가요?',ARRAY['M6-1-u3-X08','M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":7,"concept":"M6-1-u3-C6","difficulty":2,"kind":"mc","stem":"분수 광장의 분수대는 가로가 6 m, 세로가 5 m예요. 가로는 세로의 몇 배인가요?","options":[{"t":"1.2배","correct":true},{"t":"1.1배","mis":"M6-1-u3-X08"},{"t":"12배","mis":"M6-1-u3-X01"},{"t":"0.12배","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 60 ÷ 5 = 12예요.","6은 60의 ⟨1/10⟩배라서 몫도 12의 ⟨1/10⟩배예요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 6 ÷ 5 = 1.2예요."],"variant_rule":{"alt":[{"stem":"분수 광장의 분수대는 가로가 9 m, 세로가 4 m예요. 가로는 세로의 몇 배인가요?","options":[{"t":"2.25배","correct":true},{"t":"2.1배","mis":"M6-1-u3-X08"},{"t":"22.5배","mis":"M6-1-u3-X01"},{"t":"0.225배","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 900 ÷ 4 = 225예요.","9는 900의 ⟨1/100⟩배라서 몫도 225의 ⟨1/100⟩배예요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 9 ÷ 4 = 2.25예요."]},{"stem":"분수 광장의 분수대는 가로가 7 m, 세로가 5 m예요. 가로는 세로의 몇 배인가요?","options":[{"t":"1.4배","correct":true},{"t":"1.2배","mis":"M6-1-u3-X08"},{"t":"14배","mis":"M6-1-u3-X01"},{"t":"0.14배","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 70 ÷ 5 = 14예요.","7은 70의 ⟨1/10⟩배라서 몫도 14의 ⟨1/10⟩배예요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 7 ÷ 5 = 1.4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L07_basic#8','math',6,1,'u3','L07','g6_1_math_u3_L07_basic','lesson_basic','M6-1-u3-C6',2,'ox','auto','6 ÷ 5의 몫은 1.1이에요.',ARRAY['M6-1-u3-X08']::text[],true,'{"seq":8,"concept":"M6-1-u3-C6","difficulty":2,"kind":"ox","stem":"6 ÷ 5의 몫은 1.1이에요.","answer":"X","reason_options":[{"t":"나머지 1에 0을 내려 10 ÷ 5 = 2를 이어 계산하면 1.2이기 때문에","correct":true},{"t":"6 ÷ 5 = 1 … 1이라 나머지를 소수로 쓰기 때문에","mis":"M6-1-u3-X08"}],"mis":"M6-1-u3-X08","explanation":["자연수의 소수점은 자연수 바로 뒤에 있어요 — 6 = 6.0이에요.","나머지가 남으면 0을 내려 계산을 이어 가요.","몫을 분수로 쓴 뒤 분모를 10·100으로 고쳐 소수로 나타낼 수도 있어요."],"variant_rule":{"alt":[{"stem":"(자연수)÷(자연수)의 몫도 소수로 나타낼 수 있어요.","answer":"O","reason_options":[{"t":"자연수를 6 = 6.0처럼 보고 0을 내려 계산할 수 있기 때문에","correct":true},{"t":"나머지가 있으면 소수로 나타낼 수 없기 때문에","mis":"M6-1-u3-X08"}],"explanation":["자연수의 소수점은 자연수 바로 뒤에 있어요 — 6 = 6.0이에요.","나머지가 남으면 0을 내려 계산을 이어 가요.","몫을 분수로 쓴 뒤 분모를 10·100으로 고쳐 소수로 나타낼 수도 있어요."]},{"stem":"자연수의 소수점은 자연수 바로 뒤에 있다고 볼 수 있어요.","answer":"O","reason_options":[{"t":"6 = 6.0 = 6.00처럼 쓸 수 있기 때문에","correct":true},{"t":"자연수에는 소수점이 없어 0을 내릴 수 없기 때문에","mis":"M6-1-u3-X08"}],"explanation":["자연수의 소수점은 자연수 바로 뒤에 있어요 — 6 = 6.0이에요.","나머지가 남으면 0을 내려 계산을 이어 가요.","몫을 분수로 쓴 뒤 분모를 10·100으로 고쳐 소수로 나타낼 수도 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L07_basic#9','math',6,1,'u3','L07','g6_1_math_u3_L07_basic','lesson_basic','M6-1-u3-C1',2,'match','auto','나눗셈식과 몫을 알맞게 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u3-C1","difficulty":2,"kind":"match","stem":"나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"6 ÷ 5","r":"1.2"},{"l":"3 ÷ 4","r":"0.75"},{"l":"9 ÷ 6","r":"1.5"}],"mis":"M6-1-u3-X02","explanation":["자연수의 나눗셈으로 몫을 구한 뒤 같은 배율만큼 작게 해요.","6 ÷ 5 = 1.2, 3 ÷ 4 = 0.75, 9 ÷ 6 = 1.5예요.","어림한 값과 견주어 소수점 자리를 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"7 ÷ 4","r":"1.75"},{"l":"9 ÷ 4","r":"2.25"},{"l":"15 ÷ 8","r":"1.875"}],"explanation":["자연수의 나눗셈으로 몫을 구한 뒤 같은 배율만큼 작게 해요.","7 ÷ 4 = 1.75, 9 ÷ 4 = 2.25, 15 ÷ 8 = 1.875예요.","어림한 값과 견주어 소수점 자리를 확인해요."]},{"stem":"이번에는 다른 보기예요. 나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"7 ÷ 2","r":"3.5"},{"l":"21 ÷ 4","r":"5.25"},{"l":"40 ÷ 16","r":"2.5"}],"explanation":["자연수의 나눗셈으로 몫을 구한 뒤 같은 배율만큼 작게 해요.","7 ÷ 2 = 3.5, 21 ÷ 4 = 5.25, 40 ÷ 16 = 2.5예요.","어림한 값과 견주어 소수점 자리를 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L07_basic#10','math',6,1,'u3','L07','g6_1_math_u3_L07_basic','lesson_basic','M6-1-u3-C6',3,'mc','auto','친구가 6 ÷ 5 = 1 … 1을 보고 몫을 1.1로 나타냈어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X09','M6-1-u3-X05']::text[],true,'{"seq":10,"concept":"M6-1-u3-C6","difficulty":3,"kind":"mc","stem":"친구가 6 ÷ 5 = 1 … 1을 보고 몫을 1.1로 나타냈어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나머지 1을 그대로 소수 부분으로 써서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"나누는 수와 나누어지는 수를 바꾸어서","mis":"M6-1-u3-X09"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["나머지 1은 아직 나누지 않은 양이라 몫의 소수 부분이 아니에요.","6을 6.0으로 보고 0을 내려 계산을 이어 가요.","바른 몫은 1.2예요."],"variant_rule":{"alt":[{"stem":"친구가 9 ÷ 6 = 1 … 3을 보고 몫을 1.3으로 나타냈어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나머지 3을 그대로 소수 부분으로 써서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"나누는 수와 나누어지는 수를 바꾸어서","mis":"M6-1-u3-X09"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["나머지 3은 아직 나누지 않은 양이라 몫의 소수 부분이 아니에요.","9를 9.0으로 보고 0을 내려 계산을 이어 가요.","바른 몫은 1.5예요."]},{"stem":"친구가 7 ÷ 4 = 1 … 3을 보고 몫을 1.3으로 나타냈어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나머지 3을 그대로 소수 부분으로 써서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"나누는 수와 나누어지는 수를 바꾸어서","mis":"M6-1-u3-X09"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["나머지 3은 아직 나누지 않은 양이라 몫의 소수 부분이 아니에요.","7을 7.0으로 보고 0을 내려 계산을 이어 가요.","바른 몫은 1.75예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L07_challenge#1','math',6,1,'u3','L07','g6_1_math_u3_L07_challenge','lesson_challenge','M6-1-u3-C6',2,'mc','auto','17 ÷ 4의 몫은 얼마인가요?',ARRAY['M6-1-u3-X08','M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":1,"concept":"M6-1-u3-C6","difficulty":2,"kind":"mc","stem":"17 ÷ 4의 몫은 얼마인가요?","options":[{"t":"4.25","correct":true},{"t":"4.1","mis":"M6-1-u3-X08"},{"t":"42.5","mis":"M6-1-u3-X01"},{"t":"0.425","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1700 ÷ 4 = 425예요.","17은 1700의 ⟨1/100⟩배라서 몫도 425의 ⟨1/100⟩배예요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 17 ÷ 4 = 4.25예요."],"variant_rule":{"alt":[{"stem":"33 ÷ 8의 몫은 얼마인가요?","options":[{"t":"4.125","correct":true},{"t":"4.1","mis":"M6-1-u3-X08"},{"t":"41.25","mis":"M6-1-u3-X01"},{"t":"0.4125","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 33000 ÷ 8 = 4125예요.","33은 33000의 ⟨1/1000⟩배라서 몫도 4125의 ⟨1/1000⟩배예요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 33 ÷ 8 = 4.125예요."]},{"stem":"7 ÷ 8의 몫은 얼마인가요?","options":[{"t":"0.875","correct":true},{"t":"0.7","mis":"M6-1-u3-X08"},{"t":"8.75","mis":"M6-1-u3-X01"},{"t":"0.0875","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 7000 ÷ 8 = 875예요.","7은 7000의 ⟨1/1000⟩배라서 몫도 875의 ⟨1/1000⟩배예요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 7 ÷ 8 = 0.875예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L07_challenge#2','math',6,1,'u3','L07','g6_1_math_u3_L07_challenge','lesson_challenge','M6-1-u3-C6',2,'sa','auto','7 ÷ 20의 몫을 분수로 쓰면 ⟨7/20⟩이에요. 분모를 100으로 고치면 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u3-C6","difficulty":2,"kind":"sa","stem":"7 ÷ 20의 몫을 분수로 쓰면 ⟨7/20⟩이에요. 분모를 100으로 고치면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["분모 20을 100으로 만들려면 분모와 분자에 5를 곱해요.","⟨7/20⟩ = ⟨35/100⟩예요.","분자는 35이고 소수로 쓰면 0.35예요."],"mis":"M6-1-u3-X13","variant_rule":{"alt":[{"stem":"9 ÷ 25의 몫을 분수로 쓰면 ⟨9/25⟩예요. 분모를 100으로 고치면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["분모 25를 100으로 만들려면 분모와 분자에 4를 곱해요.","⟨9/25⟩ = ⟨36/100⟩이에요.","분자는 36이고 소수로 쓰면 0.36이에요."]},{"stem":"3 ÷ 5의 몫을 분수로 쓰면 ⟨3/5⟩이에요. 분모를 10으로 고치면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["분모 5를 10으로 만들려면 분모와 분자에 2를 곱해요.","⟨3/5⟩ = ⟨6/10⟩이에요.","분자는 6이고 소수로 쓰면 0.6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L07_challenge#3','math',6,1,'u3','L07','g6_1_math_u3_L07_challenge','lesson_challenge','M6-1-u3-C6',3,'error','auto','6 ÷ 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u3-X08','M6-1-u3-X14']::text[],true,'{"seq":3,"concept":"M6-1-u3-C6","difficulty":3,"kind":"error","stem":"6 ÷ 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「1 … 1이니 몫은 1.1이야.」","correct":true,"mis_target":"M6-1-u3-X08"},{"t":"이현 — 「6을 6.0으로 보고 0을 내려.」","mis":"M6-1-u3-X14"},{"t":"서아 — 「몫은 1.2야.」","mis":"M6-1-u3-X14"}],"explanation":["나머지 1은 아직 나누지 않은 양이에요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 6 ÷ 5 = 1.2예요.","준희는 나머지를 소수 부분으로 잘못 썼어요."],"variant_rule":{"alt":[{"stem":"9 ÷ 6을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「1 … 3이니 몫은 1.3이야.」","correct":true,"mis_target":"M6-1-u3-X08"},{"t":"수아 — 「9를 9.0으로 보고 0을 내려.」","mis":"M6-1-u3-X14"},{"t":"도윤 — 「몫은 1.5야.」","mis":"M6-1-u3-X14"}],"explanation":["나머지 3은 아직 나누지 않은 양이에요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 9 ÷ 6 = 1.5예요.","서호는 나머지를 소수 부분으로 잘못 썼어요."]},{"stem":"17 ÷ 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「4 … 1이니 몫은 4.1이야.」","correct":true,"mis_target":"M6-1-u3-X08"},{"t":"나린 — 「17을 17.0으로 보고 0을 내려.」","mis":"M6-1-u3-X14"},{"t":"유진 — 「몫은 4.25야.」","mis":"M6-1-u3-X14"}],"explanation":["나머지 1은 아직 나누지 않은 양이에요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 17 ÷ 4 = 4.25예요.","가온은 나머지를 소수 부분으로 잘못 썼어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L07_challenge#4','math',6,1,'u3','L07','g6_1_math_u3_L07_challenge','lesson_challenge','M6-1-u3-C6',3,'ox','auto','3 ÷ 4의 몫은 0.75예요.',ARRAY['M6-1-u3-X09']::text[],true,'{"seq":4,"concept":"M6-1-u3-C6","difficulty":3,"kind":"ox","stem":"3 ÷ 4의 몫은 0.75예요.","answer":"O","reason_options":[{"t":"⟨3/4⟩ = ⟨75/100⟩ = 0.75이기 때문에","correct":true},{"t":"4 ÷ 3을 계산해야 하기 때문에","mis":"M6-1-u3-X09"}],"mis":"M6-1-u3-X09","explanation":["자연수의 소수점은 자연수 바로 뒤에 있어요 — 6 = 6.0이에요.","나머지가 남으면 0을 내려 계산을 이어 가요.","몫을 분수로 쓴 뒤 분모를 10·100으로 고쳐 소수로 나타낼 수도 있어요."],"variant_rule":{"alt":[{"stem":"9 ÷ 6의 몫은 1.3이에요.","answer":"X","reason_options":[{"t":"9를 9.0으로 보고 계산하면 1.5이기 때문에","correct":true},{"t":"9 ÷ 6 = 1 … 3이라 1.3이기 때문에","mis":"M6-1-u3-X08"}],"explanation":["자연수의 소수점은 자연수 바로 뒤에 있어요 — 6 = 6.0이에요.","나머지가 남으면 0을 내려 계산을 이어 가요.","몫을 분수로 쓴 뒤 분모를 10·100으로 고쳐 소수로 나타낼 수도 있어요."]},{"stem":"40 ÷ 16의 몫은 25예요.","answer":"X","reason_options":[{"t":"40을 40.0으로 보고 계산하면 몫은 2.5이기 때문에","correct":true},{"t":"400 ÷ 16 = 25이기 때문에","mis":"M6-1-u3-X01"}],"explanation":["자연수의 소수점은 자연수 바로 뒤에 있어요 — 6 = 6.0이에요.","나머지가 남으면 0을 내려 계산을 이어 가요.","몫을 분수로 쓴 뒤 분모를 10·100으로 고쳐 소수로 나타낼 수도 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L07_challenge#5','math',6,1,'u3','L07','g6_1_math_u3_L07_challenge','lesson_challenge','M6-1-u3-C6',3,'sa','auto','수 카드 2, 3, 4, 6 가운데 세 장으로 소수 두 자리 수를 만들고, 남은 한 장을 나누는 수로 하여 몫이 가장 작은 나눗셈을 만들어요. 나누는 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u3-C6","difficulty":3,"kind":"sa","stem":"수 카드 2, 3, 4, 6 가운데 세 장으로 소수 두 자리 수를 만들고, 남은 한 장을 나누는 수로 하여 몫이 가장 작은 나눗셈을 만들어요. 나누는 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["몫이 작으려면 나누어지는 수는 작게, 나누는 수는 크게 해요.","가장 큰 카드 6을 나누는 수로 하고 남은 카드로 가장 작은 수 2.34를 만들어요.","2.34 ÷ 6 = 0.39 — 나누는 수는 6이에요."],"mis":"M6-1-u3-X14","variant_rule":{"alt":[{"stem":"수 카드 1, 5, 7, 8 가운데 세 장으로 소수 두 자리 수를 만들고, 남은 한 장을 나누는 수로 하여 몫이 가장 작은 나눗셈을 만들어요. 나누는 수는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["몫이 작으려면 나누어지는 수는 작게, 나누는 수는 크게 해요.","가장 큰 카드 8을 나누는 수로 하고 남은 카드로 가장 작은 수 1.57을 만들어요.","1.57 ÷ 8 = 0.19625 — 나누는 수는 8이에요."]},{"stem":"수 카드 2, 4, 5, 8 가운데 세 장으로 소수 두 자리 수를 만들고, 남은 한 장을 나누는 수로 하여 몫이 가장 작은 나눗셈을 만들어요. 나누는 수는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["몫이 작으려면 나누어지는 수는 작게, 나누는 수는 크게 해요.","가장 큰 카드 8을 나누는 수로 하고 남은 카드로 가장 작은 수 2.45를 만들어요.","2.45 ÷ 8 = 0.30625 — 나누는 수는 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L07_challenge#6','math',6,1,'u3','L07','g6_1_math_u3_L07_challenge','lesson_challenge','M6-1-u3-C6',3,'mc','auto','주스 7 L를 병 8개에 똑같이 나누어 담았어요. 한 병에 담긴 주스는 몇 L인가요?',ARRAY['M6-1-u3-X08','M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":6,"concept":"M6-1-u3-C6","difficulty":3,"kind":"mc","stem":"주스 7 L를 병 8개에 똑같이 나누어 담았어요. 한 병에 담긴 주스는 몇 L인가요?","options":[{"t":"0.875 L","correct":true},{"t":"0.7 L","mis":"M6-1-u3-X08"},{"t":"8.75 L","mis":"M6-1-u3-X01"},{"t":"0.0875 L","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 7000 ÷ 8 = 875예요.","7은 7000의 ⟨1/1000⟩배라서 몫도 875의 ⟨1/1000⟩배예요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 7 ÷ 8 = 0.875예요."],"variant_rule":{"alt":[{"stem":"주스 15 L를 병 4개에 똑같이 나누어 담았어요. 한 병에 담긴 주스는 몇 L인가요?","options":[{"t":"3.75 L","correct":true},{"t":"3.3 L","mis":"M6-1-u3-X08"},{"t":"37.5 L","mis":"M6-1-u3-X01"},{"t":"0.375 L","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1500 ÷ 4 = 375예요.","15는 1500의 ⟨1/100⟩배라서 몫도 375의 ⟨1/100⟩배예요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 15 ÷ 4 = 3.75예요."]},{"stem":"주스 11 L를 병 8개에 똑같이 나누어 담았어요. 한 병에 담긴 주스는 몇 L인가요?","options":[{"t":"1.375 L","correct":true},{"t":"1.3 L","mis":"M6-1-u3-X08"},{"t":"13.75 L","mis":"M6-1-u3-X01"},{"t":"0.1375 L","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 11000 ÷ 8 = 1375예요.","11은 11000의 ⟨1/1000⟩배라서 몫도 1375의 ⟨1/1000⟩배예요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 11 ÷ 8 = 1.375예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L07_challenge#7','math',6,1,'u3','L07','g6_1_math_u3_L07_challenge','lesson_challenge','M6-1-u3-C6',3,'mc','auto','친구가 17 ÷ 4 = 4 … 1을 보고 몫을 4.1로 나타냈어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X09','M6-1-u3-X05']::text[],true,'{"seq":7,"concept":"M6-1-u3-C6","difficulty":3,"kind":"mc","stem":"친구가 17 ÷ 4 = 4 … 1을 보고 몫을 4.1로 나타냈어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나머지 1을 그대로 소수 부분으로 써서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"나누는 수와 나누어지는 수를 바꾸어서","mis":"M6-1-u3-X09"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["나머지 1은 아직 나누지 않은 양이라 몫의 소수 부분이 아니에요.","17을 17.0으로 보고 0을 내려 계산을 이어 가요.","바른 몫은 4.25예요."],"variant_rule":{"alt":[{"stem":"친구가 21 ÷ 6 = 3 … 3을 보고 몫을 3.3으로 나타냈어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나머지 3을 그대로 소수 부분으로 써서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"나누는 수와 나누어지는 수를 바꾸어서","mis":"M6-1-u3-X09"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["나머지 3은 아직 나누지 않은 양이라 몫의 소수 부분이 아니에요.","21을 21.0으로 보고 0을 내려 계산을 이어 가요.","바른 몫은 3.5예요."]},{"stem":"친구가 33 ÷ 8 = 4 … 1을 보고 몫을 4.1로 나타냈어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나머지 1을 그대로 소수 부분으로 써서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"나누는 수와 나누어지는 수를 바꾸어서","mis":"M6-1-u3-X09"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["나머지 1은 아직 나누지 않은 양이라 몫의 소수 부분이 아니에요.","33을 33.0으로 보고 0을 내려 계산을 이어 가요.","바른 몫은 4.125예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L07_challenge#8','math',6,1,'u3','L07','g6_1_math_u3_L07_challenge','lesson_challenge','M6-1-u3-C6',4,'sa','auto','어떤 자연수를 8로 나누었더니 몫이 4.125가 되었어요. 어떤 자연수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u3-C6","difficulty":4,"kind":"sa","stem":"어떤 자연수를 8로 나누었더니 몫이 4.125가 되었어요. 어떤 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["33"],"explanation":["나눗셈과 곱셈은 거꾸로 셈이에요.","어떤 수 = 4.125 × 8이에요.","4.125 × 8 = 33이에요."],"mis":"M6-1-u3-X10","variant_rule":{"alt":[{"stem":"어떤 자연수를 4로 나누었더니 몫이 2.75가 되었어요. 어떤 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["나눗셈과 곱셈은 거꾸로 셈이에요.","어떤 수 = 2.75 × 4예요.","2.75 × 4 = 11이에요."]},{"stem":"어떤 자연수를 5로 나누었더니 몫이 3.4가 되었어요. 어떤 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["나눗셈과 곱셈은 거꾸로 셈이에요.","어떤 수 = 3.4 × 5예요.","3.4 × 5 = 17이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L07_challenge#9','math',6,1,'u3','L07','g6_1_math_u3_L07_challenge','lesson_challenge','M6-1-u3-C6',4,'mc','auto','22 ÷ 8의 몫은 얼마인가요?',ARRAY['M6-1-u3-X08','M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":9,"concept":"M6-1-u3-C6","difficulty":4,"kind":"mc","stem":"22 ÷ 8의 몫은 얼마인가요?","options":[{"t":"2.75","correct":true},{"t":"2.6","mis":"M6-1-u3-X08"},{"t":"27.5","mis":"M6-1-u3-X01"},{"t":"0.275","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 2200 ÷ 8 = 275예요.","22는 2200의 ⟨1/100⟩배라서 몫도 275의 ⟨1/100⟩배예요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 22 ÷ 8 = 2.75예요."],"variant_rule":{"alt":[{"stem":"26 ÷ 8의 몫은 얼마인가요?","options":[{"t":"3.25","correct":true},{"t":"3.2","mis":"M6-1-u3-X08"},{"t":"32.5","mis":"M6-1-u3-X01"},{"t":"0.325","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 2600 ÷ 8 = 325예요.","26은 2600의 ⟨1/100⟩배라서 몫도 325의 ⟨1/100⟩배예요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 26 ÷ 8 = 3.25예요."]},{"stem":"18 ÷ 8의 몫은 얼마인가요?","options":[{"t":"2.25","correct":true},{"t":"2.2","mis":"M6-1-u3-X08"},{"t":"22.5","mis":"M6-1-u3-X01"},{"t":"0.225","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1800 ÷ 8 = 225예요.","18은 1800의 ⟨1/100⟩배라서 몫도 225의 ⟨1/100⟩배예요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 18 ÷ 8 = 2.25예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L07_challenge#10','math',6,1,'u3','L07','g6_1_math_u3_L07_challenge','lesson_challenge','M6-1-u3-C6',4,'essay','teacher','분수 광장의 분수대는 가로가 6 m, 세로가 5 m예요. 가로가 세로의 몇 배인지 두 가지 방법(분수로 나타낸 뒤 소수로 바꾸기, 세로셈)으로 구해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u3-C6","difficulty":4,"kind":"essay","stem":"분수 광장의 분수대는 가로가 6 m, 세로가 5 m예요. 가로가 세로의 몇 배인지 두 가지 방법(분수로 나타낸 뒤 소수로 바꾸기, 세로셈)으로 구해 보세요.","answer_guide":{"answer":"예: 6 ÷ 5의 몫은 5분의 6이다. 분모를 10으로 고치면 10분의 12이고 이것을 소수로 쓰면 1.2이다. 세로셈에서는 6을 6.0으로 보고 6 ÷ 5 = 1 … 1에서 남은 1에 0을 내려 10 ÷ 5 = 2를 계산해 1.2이다. 가로는 세로의 1.2배이다.","scoring_points":["⟨6/5⟩ = ⟨12/10⟩ = 1.2로 구했는가","6을 6.0으로 보고 0을 내려 세로셈으로 구했는가","1.2배라고 답했는가"]},"explanation":["⟨6/5⟩ = ⟨12/10⟩ = 1.2예요.","6을 6.0으로 보고 0을 내려요.","가로는 세로의 1.2배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L08_basic#1','math',6,1,'u3','L08','g6_1_math_u3_L08_basic','lesson_basic','M6-1-u3-C7',1,'sa','auto','가 상자에는 무게가 같은 수박 3통이 18.3 kg 들어 있어요. 18.3을 18로 어림하면 수박 한 통은 약 몇 kg인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u3-C7","difficulty":1,"kind":"sa","stem":"가 상자에는 무게가 같은 수박 3통이 18.3 kg 들어 있어요. 18.3을 18로 어림하면 수박 한 통은 약 몇 kg인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["18.3에 가까우면서 3으로 나누기 쉬운 수는 18이에요.","18 ÷ 3 = 6이에요.","수박 한 통은 약 6 kg이에요."],"mis":"M6-1-u3-X12","variant_rule":{"alt":[{"stem":"나 상자에는 무게가 같은 수박 4통이 19.8 kg 들어 있어요. 19.8을 20으로 어림하면 수박 한 통은 약 몇 kg인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["19.8에 가까우면서 4로 나누기 쉬운 수는 20이에요.","20 ÷ 4 = 5예요.","수박 한 통은 약 5 kg이에요."]},{"stem":"다 상자에는 무게가 같은 수박 5통이 20.2 kg 들어 있어요. 20.2를 20으로 어림하면 수박 한 통은 약 몇 kg인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["20.2에 가까우면서 5로 나누기 쉬운 수는 20이에요.","20 ÷ 5 = 4예요.","수박 한 통은 약 4 kg이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L08_basic#2','math',6,1,'u3','L08','g6_1_math_u3_L08_basic','lesson_basic','M6-1-u3-C7',1,'mc','auto','가 상자에는 무게가 같은 수박 3통이 18.3 kg 들어 있어요. 수박 한 통의 무게는 몇 kg인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02','M6-1-u3-X10']::text[],true,'{"seq":2,"concept":"M6-1-u3-C7","difficulty":1,"kind":"mc","stem":"가 상자에는 무게가 같은 수박 3통이 18.3 kg 들어 있어요. 수박 한 통의 무게는 몇 kg인가요?","options":[{"t":"6.1 kg","correct":true},{"t":"61 kg","mis":"M6-1-u3-X01"},{"t":"0.61 kg","mis":"M6-1-u3-X02"},{"t":"54.9 kg","mis":"M6-1-u3-X10"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 183 ÷ 3 = 61이에요.","18.3은 183의 ⟨1/10⟩배라서 몫도 61의 ⟨1/10⟩배예요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 18.3 ÷ 3 = 6.1이에요."],"variant_rule":{"alt":[{"stem":"나 상자에는 무게가 같은 수박 4통이 19.8 kg 들어 있어요. 수박 한 통의 무게는 몇 kg인가요?","options":[{"t":"4.95 kg","correct":true},{"t":"49.5 kg","mis":"M6-1-u3-X01"},{"t":"0.495 kg","mis":"M6-1-u3-X02"},{"t":"79.2 kg","mis":"M6-1-u3-X10"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1980 ÷ 4 = 495예요.","19.8은 1980의 ⟨1/100⟩배라서 몫도 495의 ⟨1/100⟩배예요.","나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 19.8 ÷ 4 = 4.95예요."]},{"stem":"다 상자에는 무게가 같은 수박 5통이 20.2 kg 들어 있어요. 수박 한 통의 무게는 몇 kg인가요?","options":[{"t":"4.04 kg","correct":true},{"t":"4.4 kg","mis":"M6-1-u3-X07"},{"t":"40.4 kg","mis":"M6-1-u3-X01"},{"t":"0.404 kg","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 2020 ÷ 5 = 404예요.","20.2는 2020의 ⟨1/100⟩배라서 몫도 404의 ⟨1/100⟩배예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 20.2 ÷ 5 = 4.04예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L08_basic#3','math',6,1,'u3','L08','g6_1_math_u3_L08_basic','lesson_basic','M6-1-u3-C7',1,'mc','auto','어림한 값과 계산한 값이 크게 다를 때 가장 먼저 할 일은 무엇인가요?',ARRAY['M6-1-u3-X12','M6-1-u3-X14','M6-1-u3-X13']::text[],true,'{"seq":3,"concept":"M6-1-u3-C7","difficulty":1,"kind":"mc","stem":"어림한 값과 계산한 값이 크게 다를 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"계산 과정을 다시 확인해요","correct":true},{"t":"어림한 값을 답으로 써요","mis":"M6-1-u3-X12"},{"t":"문제의 수를 바꿔요","mis":"M6-1-u3-X14"},{"t":"나누는 수를 줄여요","mis":"M6-1-u3-X13"}],"explanation":["어림은 계산하기 쉬운 자연수로 바꾸어 몫의 크기를 짐작하는 것이에요.","계산 결과가 어림과 크게 다르면 어딘가 잘못 계산했다는 신호예요.","그래서 어림은 계산을 검토하는 잣대가 돼요."],"variant_rule":{"alt":[{"stem":"나눗셈을 하기 전에 몫을 어림하면 좋은 점은 무엇인가요?","options":[{"t":"계산 결과가 맞는지 스스로 확인할 수 있어요","correct":true},{"t":"계산을 하지 않아도 정확한 몫을 알 수 있어요","mis":"M6-1-u3-X12"},{"t":"나머지가 생기지 않아요","mis":"M6-1-u3-X06"},{"t":"소수점을 찍지 않아도 돼요","mis":"M6-1-u3-X01"}],"explanation":["어림은 계산하기 쉬운 자연수로 바꾸어 몫의 크기를 짐작하는 것이에요.","계산 결과가 어림과 크게 다르면 어딘가 잘못 계산했다는 신호예요.","그래서 어림은 계산을 검토하는 잣대가 돼요."]},{"stem":"18.3 ÷ 3을 어림할 때 18.3을 어떤 수로 보면 좋을까요?","options":[{"t":"18","correct":true},{"t":"20","mis":"M6-1-u3-X12"},{"t":"10","mis":"M6-1-u3-X12"},{"t":"183","mis":"M6-1-u3-X01"}],"explanation":["어림은 계산하기 쉬운 자연수로 바꾸어 몫의 크기를 짐작하는 것이에요.","계산 결과가 어림과 크게 다르면 어딘가 잘못 계산했다는 신호예요.","그래서 어림은 계산을 검토하는 잣대가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L08_basic#4','math',6,1,'u3','L08','g6_1_math_u3_L08_basic','lesson_basic','M6-1-u3-C7',1,'ox','auto','18.3 ÷ 3의 몫은 약 6이에요.',ARRAY['M6-1-u3-X12']::text[],true,'{"seq":4,"concept":"M6-1-u3-C7","difficulty":1,"kind":"ox","stem":"18.3 ÷ 3의 몫은 약 6이에요.","answer":"O","reason_options":[{"t":"18.3을 18로 어림하면 18 ÷ 3 = 6이기 때문에","correct":true},{"t":"18.3을 20으로 어림하면 7이기 때문에","mis":"M6-1-u3-X12"}],"mis":"M6-1-u3-X12","explanation":["어림은 나누어지는 수를 계산하기 쉬운 자연수로 바꾸어 몫을 짐작하는 것이에요.","어림으로 답을 먼저 고르고 계산으로 확인해요.","어림과 계산이 크게 다르면 계산을 다시 확인해요."],"variant_rule":{"alt":[{"stem":"어림한 값과 계산한 값이 크게 달라도 계산한 값을 그대로 믿어요.","answer":"X","reason_options":[{"t":"크게 다르면 계산이 잘못되었다는 신호이기 때문에","correct":true},{"t":"계산한 값이 언제나 정확하기 때문에","mis":"M6-1-u3-X12"}],"explanation":["어림은 나누어지는 수를 계산하기 쉬운 자연수로 바꾸어 몫을 짐작하는 것이에요.","어림으로 답을 먼저 고르고 계산으로 확인해요.","어림과 계산이 크게 다르면 계산을 다시 확인해요."]},{"stem":"어림만으로도 수박 한 통이 가장 무거운 상자를 먼저 고를 수 있어요.","answer":"O","reason_options":[{"t":"어림한 몫의 크기를 견주면 어느 것이 큰지 알 수 있기 때문에","correct":true},{"t":"어림은 정확하지 않아 고를 수 없기 때문에","mis":"M6-1-u3-X12"}],"explanation":["어림은 나누어지는 수를 계산하기 쉬운 자연수로 바꾸어 몫을 짐작하는 것이에요.","어림으로 답을 먼저 고르고 계산으로 확인해요.","어림과 계산이 크게 다르면 계산을 다시 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L08_basic#5','math',6,1,'u3','L08','g6_1_math_u3_L08_basic','lesson_basic','M6-1-u3-C7',2,'mc','auto','가 상자 3통 18.3 kg · 나 상자 4통 19.8 kg · 다 상자 5통 20.2 kg — 수박 한 통이 가장 무거운 상자는 어느 것인가요?',ARRAY['M6-1-u3-X12','M6-1-u3-X14']::text[],true,'{"seq":5,"concept":"M6-1-u3-C7","difficulty":2,"kind":"mc","stem":"가 상자 3통 18.3 kg · 나 상자 4통 19.8 kg · 다 상자 5통 20.2 kg — 수박 한 통이 가장 무거운 상자는 어느 것인가요?","options":[{"t":"가 상자","correct":true},{"t":"나 상자","mis":"M6-1-u3-X12"},{"t":"다 상자","mis":"M6-1-u3-X14"},{"t":"모두 같아요","mis":"M6-1-u3-X12"}],"explanation":["먼저 어림해요 — 18 ÷ 3 = 6, 20 ÷ 4 = 5, 20 ÷ 5 = 4예요.","계산으로 확인하면 가 6.1 kg, 나 4.95 kg, 다 4.04 kg이에요.","수박 한 통이 가장 무거운 것은 가 상자예요."],"variant_rule":{"alt":[{"stem":"라 상자 6통 25.2 kg · 마 상자 5통 14.5 kg · 바 상자 4통 22.4 kg — 수박 한 통이 가장 무거운 상자는 어느 것인가요?","options":[{"t":"바 상자","correct":true},{"t":"라 상자","mis":"M6-1-u3-X12"},{"t":"마 상자","mis":"M6-1-u3-X14"},{"t":"모두 같아요","mis":"M6-1-u3-X12"}],"explanation":["먼저 어림해요 — 24 ÷ 6 = 4, 15 ÷ 5 = 3, 24 ÷ 4 = 6이에요.","계산으로 확인하면 라 4.2 kg, 마 2.9 kg, 바 5.6 kg이에요.","수박 한 통이 가장 무거운 것은 바 상자예요."]},{"stem":"사 상자 3통 16.2 kg · 마 상자 5통 14.5 kg · 다 상자 5통 20.2 kg — 수박 한 통이 가장 무거운 상자는 어느 것인가요?","options":[{"t":"사 상자","correct":true},{"t":"마 상자","mis":"M6-1-u3-X14"},{"t":"다 상자","mis":"M6-1-u3-X12"},{"t":"모두 같아요","mis":"M6-1-u3-X12"}],"explanation":["먼저 어림해요 — 15 ÷ 3 = 5, 15 ÷ 5 = 3, 20 ÷ 5 = 4예요.","계산으로 확인하면 사 5.4 kg, 마 2.9 kg, 다 4.04 kg이에요.","수박 한 통이 가장 무거운 것은 사 상자예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L08_basic#6','math',6,1,'u3','L08','g6_1_math_u3_L08_basic','lesson_basic','M6-1-u3-C7',2,'sa','auto','20.2 ÷ 5의 몫에서 소수 둘째 자리 숫자는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u3-C7","difficulty":2,"kind":"sa","stem":"20.2 ÷ 5의 몫에서 소수 둘째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 2020 ÷ 5 = 404예요.","20.2 ÷ 5 = 4.04예요.","4.04의 소수 둘째 자리 숫자는 4예요."],"mis":"M6-1-u3-X13","variant_rule":{"alt":[{"stem":"19.8 ÷ 4의 몫에서 소수 첫째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1980 ÷ 4 = 495예요.","19.8 ÷ 4 = 4.95예요.","4.95의 소수 첫째 자리 숫자는 9예요."]},{"stem":"25.2 ÷ 6의 몫에서 소수 첫째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 252 ÷ 6 = 42예요.","25.2 ÷ 6 = 4.2예요.","4.2의 소수 첫째 자리 숫자는 2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L08_basic#7','math',6,1,'u3','L08','g6_1_math_u3_L08_basic','lesson_basic','M6-1-u3-C7',2,'mc','auto','친구가 19.8 ÷ 4의 몫을 49.5라고 했어요. 어림으로 잘못을 찾은 말로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u3-X12']::text[],true,'{"seq":7,"concept":"M6-1-u3-C7","difficulty":2,"kind":"mc","stem":"친구가 19.8 ÷ 4의 몫을 49.5라고 했어요. 어림으로 잘못을 찾은 말로 알맞은 것은 어느 것인가요?","options":[{"t":"어림하면 약 5라서 49.5는 너무 커요","correct":true},{"t":"어림하면 약 49.5라서 맞아요","mis":"M6-1-u3-X12"},{"t":"어림으로는 알 수 없어요","mis":"M6-1-u3-X12"},{"t":"나누는 수가 자연수라서 맞아요","mis":"M6-1-u3-X12"}],"explanation":["19.8을 20으로 어림하면 20 ÷ 4 = 5예요.","49.5는 어림한 값과 크게 달라요.","바른 몫은 4.95예요."],"variant_rule":{"alt":[{"stem":"친구가 18.3 ÷ 3의 몫을 0.61이라고 했어요. 어림으로 잘못을 찾은 말로 알맞은 것은 어느 것인가요?","options":[{"t":"어림하면 약 6라서 0.61은 너무 작아요","correct":true},{"t":"어림하면 약 0.61라서 맞아요","mis":"M6-1-u3-X12"},{"t":"어림으로는 알 수 없어요","mis":"M6-1-u3-X12"},{"t":"나누는 수가 자연수라서 맞아요","mis":"M6-1-u3-X12"}],"explanation":["18.3을 18로 어림하면 18 ÷ 3 = 6이에요.","0.61은 어림한 값과 크게 달라요.","바른 몫은 6.1이에요."]},{"stem":"친구가 25.2 ÷ 6의 몫을 42라고 했어요. 어림으로 잘못을 찾은 말로 알맞은 것은 어느 것인가요?","options":[{"t":"어림하면 약 4라서 42는 너무 커요","correct":true},{"t":"어림하면 약 42라서 맞아요","mis":"M6-1-u3-X12"},{"t":"어림으로는 알 수 없어요","mis":"M6-1-u3-X12"},{"t":"나누는 수가 자연수라서 맞아요","mis":"M6-1-u3-X12"}],"explanation":["25.2를 24로 어림하면 24 ÷ 6 = 4예요.","42는 어림한 값과 크게 달라요.","바른 몫은 4.2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L08_basic#8','math',6,1,'u3','L08','g6_1_math_u3_L08_basic','lesson_basic','M6-1-u3-C7',2,'ox','auto','19.8 ÷ 4의 몫은 49.5예요.',ARRAY['M6-1-u3-X01']::text[],true,'{"seq":8,"concept":"M6-1-u3-C7","difficulty":2,"kind":"ox","stem":"19.8 ÷ 4의 몫은 49.5예요.","answer":"X","reason_options":[{"t":"20 ÷ 4 = 5로 어림되니 몫은 4.95이기 때문에","correct":true},{"t":"198 ÷ 4 = 49.5이기 때문에","mis":"M6-1-u3-X01"}],"mis":"M6-1-u3-X01","explanation":["어림은 나누어지는 수를 계산하기 쉬운 자연수로 바꾸어 몫을 짐작하는 것이에요.","어림으로 답을 먼저 고르고 계산으로 확인해요.","어림과 계산이 크게 다르면 계산을 다시 확인해요."],"variant_rule":{"alt":[{"stem":"20.2 ÷ 5의 몫은 4.4예요.","answer":"X","reason_options":[{"t":"20을 나누고 남은 2는 5보다 작아 몫에 0을 써서 4.04이기 때문에","correct":true},{"t":"20 ÷ 5 = 4이고 2 ÷ 5 = 0.4이기 때문에","mis":"M6-1-u3-X07"}],"explanation":["어림은 나누어지는 수를 계산하기 쉬운 자연수로 바꾸어 몫을 짐작하는 것이에요.","어림으로 답을 먼저 고르고 계산으로 확인해요.","어림과 계산이 크게 다르면 계산을 다시 확인해요."]},{"stem":"어림은 정확한 계산을 대신해요.","answer":"X","reason_options":[{"t":"어림은 몫의 크기를 짐작하고 계산을 검토하는 잣대이기 때문에","correct":true},{"t":"어림한 값이 곧 답이기 때문에","mis":"M6-1-u3-X12"}],"explanation":["어림은 나누어지는 수를 계산하기 쉬운 자연수로 바꾸어 몫을 짐작하는 것이에요.","어림으로 답을 먼저 고르고 계산으로 확인해요.","어림과 계산이 크게 다르면 계산을 다시 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L08_basic#9','math',6,1,'u3','L08','g6_1_math_u3_L08_basic','lesson_basic','M6-1-u3-C7',2,'mc','auto','가 상자에는 무게가 같은 수박 3통이 18.3 kg 들어 있어요. 수박 한 통의 무게는 몇 g인가요?',ARRAY['M6-1-u3-X11']::text[],true,'{"seq":9,"concept":"M6-1-u3-C7","difficulty":2,"kind":"mc","stem":"가 상자에는 무게가 같은 수박 3통이 18.3 kg 들어 있어요. 수박 한 통의 무게는 몇 g인가요?","options":[{"t":"6100 g","correct":true},{"t":"610 g","mis":"M6-1-u3-X11"},{"t":"61000 g","mis":"M6-1-u3-X11"},{"t":"61 g","mis":"M6-1-u3-X11"}],"explanation":["18.3 ÷ 3 = 6.1 (kg)이에요.","1 kg은 1000 g이에요.","6.1 kg은 6100 g이에요."],"variant_rule":{"alt":[{"stem":"나 상자에는 무게가 같은 수박 4통이 19.8 kg 들어 있어요. 수박 한 통의 무게는 몇 g인가요?","options":[{"t":"4950 g","correct":true},{"t":"495 g","mis":"M6-1-u3-X11"},{"t":"49500 g","mis":"M6-1-u3-X11"},{"t":"49.5 g","mis":"M6-1-u3-X11"}],"explanation":["19.8 ÷ 4 = 4.95 (kg)이에요.","1 kg은 1000 g이에요.","4.95 kg은 4950 g이에요."]},{"stem":"다 상자에는 무게가 같은 수박 5통이 20.2 kg 들어 있어요. 수박 한 통의 무게는 몇 g인가요?","options":[{"t":"4040 g","correct":true},{"t":"4400 g","mis":"M6-1-u3-X07"},{"t":"404 g","mis":"M6-1-u3-X11"},{"t":"40400 g","mis":"M6-1-u3-X11"}],"explanation":["20.2 ÷ 5 = 4.04 (kg)이에요.","1 kg은 1000 g이에요.","4.04 kg은 4040 g이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L08_basic#10','math',6,1,'u3','L08','g6_1_math_u3_L08_basic','lesson_basic','M6-1-u3-C7',3,'mc','auto','가 상자는 수박 3통이 18.3 kg, 라 상자는 수박 6통이 25.2 kg이에요. 라 상자의 수박 한 통은 가 상자의 수박 한 통보다 몇 kg 가벼운가요?',ARRAY['M6-1-u3-X14','M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":10,"concept":"M6-1-u3-C7","difficulty":3,"kind":"mc","stem":"가 상자는 수박 3통이 18.3 kg, 라 상자는 수박 6통이 25.2 kg이에요. 라 상자의 수박 한 통은 가 상자의 수박 한 통보다 몇 kg 가벼운가요?","options":[{"t":"1.9 kg","correct":true},{"t":"10.3 kg","mis":"M6-1-u3-X14"},{"t":"19 kg","mis":"M6-1-u3-X01"},{"t":"0.19 kg","mis":"M6-1-u3-X02"}],"explanation":["가 상자 한 통은 18.3 ÷ 3 = 6.1 (kg)이에요.","라 상자 한 통은 25.2 ÷ 6 = 4.2 (kg)이에요.","6.1 − 4.2 = 1.9 (kg) 가벼워요."],"variant_rule":{"alt":[{"stem":"가 상자는 수박 3통이 18.3 kg, 나 상자는 수박 4통이 19.8 kg이에요. 나 상자의 수박 한 통은 가 상자의 수박 한 통보다 몇 kg 가벼운가요?","options":[{"t":"1.15 kg","correct":true},{"t":"11.05 kg","mis":"M6-1-u3-X14"},{"t":"11.5 kg","mis":"M6-1-u3-X01"},{"t":"0.115 kg","mis":"M6-1-u3-X02"}],"explanation":["가 상자 한 통은 18.3 ÷ 3 = 6.1 (kg)이에요.","나 상자 한 통은 19.8 ÷ 4 = 4.95 (kg)이에요.","6.1 − 4.95 = 1.15 (kg) 가벼워요."]},{"stem":"사 상자는 수박 3통이 16.2 kg, 다 상자는 수박 5통이 20.2 kg이에요. 다 상자의 수박 한 통은 사 상자의 수박 한 통보다 몇 kg 가벼운가요?","options":[{"t":"1.36 kg","correct":true},{"t":"9.44 kg","mis":"M6-1-u3-X14"},{"t":"13.6 kg","mis":"M6-1-u3-X01"},{"t":"0.136 kg","mis":"M6-1-u3-X02"}],"explanation":["사 상자 한 통은 16.2 ÷ 3 = 5.4 (kg)이에요.","다 상자 한 통은 20.2 ÷ 5 = 4.04 (kg)이에요.","5.4 − 4.04 = 1.36 (kg) 가벼워요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L08_challenge#1','math',6,1,'u3','L08','g6_1_math_u3_L08_challenge','lesson_challenge','M6-1-u3-C7',2,'mc','auto','어림하여 고르세요. 몫이 5보다 큰 나눗셈은 어느 것인가요?',ARRAY['M6-1-u3-X12']::text[],true,'{"seq":1,"concept":"M6-1-u3-C7","difficulty":2,"kind":"mc","stem":"어림하여 고르세요. 몫이 5보다 큰 나눗셈은 어느 것인가요?","options":[{"t":"20.4 ÷ 3","correct":true},{"t":"19.8 ÷ 4","mis":"M6-1-u3-X12"},{"t":"14.5 ÷ 5","mis":"M6-1-u3-X12"},{"t":"9.6 ÷ 2","mis":"M6-1-u3-X12"}],"explanation":["나누어지는 수를 가까운 자연수로 어림해 몫의 크기를 짐작해요.","20.4 ÷ 3 = 6.8, 19.8 ÷ 4 = 4.95, 14.5 ÷ 5 = 2.9, 9.6 ÷ 2 = 4.8이에요.","5보다 큰 것은 20.4 ÷ 3이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 어림하여 고르세요. 몫이 5보다 큰 나눗셈은 어느 것인가요?","options":[{"t":"16.2 ÷ 3","correct":true},{"t":"19.8 ÷ 4","mis":"M6-1-u3-X12"},{"t":"25.2 ÷ 6","mis":"M6-1-u3-X12"},{"t":"14.5 ÷ 5","mis":"M6-1-u3-X12"}],"explanation":["나누어지는 수를 가까운 자연수로 어림해 몫의 크기를 짐작해요.","16.2 ÷ 3 = 5.4, 19.8 ÷ 4 = 4.95, 25.2 ÷ 6 = 4.2, 14.5 ÷ 5 = 2.9예요.","5보다 큰 것은 16.2 ÷ 3이에요."]},{"stem":"이번에는 다른 보기예요. 어림하여 고르세요. 몫이 5보다 큰 나눗셈은 어느 것인가요?","options":[{"t":"18.3 ÷ 3","correct":true},{"t":"20.2 ÷ 5","mis":"M6-1-u3-X12"},{"t":"14.5 ÷ 5","mis":"M6-1-u3-X12"},{"t":"9.8 ÷ 4","mis":"M6-1-u3-X12"}],"explanation":["나누어지는 수를 가까운 자연수로 어림해 몫의 크기를 짐작해요.","18.3 ÷ 3 = 6.1, 20.2 ÷ 5 = 4.04, 14.5 ÷ 5 = 2.9, 9.8 ÷ 4 = 2.45예요.","5보다 큰 것은 18.3 ÷ 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L08_challenge#2','math',6,1,'u3','L08','g6_1_math_u3_L08_challenge','lesson_challenge','M6-1-u3-C7',2,'mc','auto','라 상자에는 무게가 같은 수박 6통이 25.2 kg 들어 있어요. 수박 한 통의 무게는 몇 kg인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02','M6-1-u3-X10']::text[],true,'{"seq":2,"concept":"M6-1-u3-C7","difficulty":2,"kind":"mc","stem":"라 상자에는 무게가 같은 수박 6통이 25.2 kg 들어 있어요. 수박 한 통의 무게는 몇 kg인가요?","options":[{"t":"4.2 kg","correct":true},{"t":"42 kg","mis":"M6-1-u3-X01"},{"t":"0.42 kg","mis":"M6-1-u3-X02"},{"t":"151.2 kg","mis":"M6-1-u3-X10"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 252 ÷ 6 = 42예요.","25.2는 252의 ⟨1/10⟩배라서 몫도 42의 ⟨1/10⟩배예요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 25.2 ÷ 6 = 4.2예요."],"variant_rule":{"alt":[{"stem":"바 상자에는 무게가 같은 수박 4통이 22.4 kg 들어 있어요. 수박 한 통의 무게는 몇 kg인가요?","options":[{"t":"5.6 kg","correct":true},{"t":"56 kg","mis":"M6-1-u3-X01"},{"t":"0.56 kg","mis":"M6-1-u3-X02"},{"t":"89.6 kg","mis":"M6-1-u3-X10"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 224 ÷ 4 = 56이에요.","22.4는 224의 ⟨1/10⟩배라서 몫도 56의 ⟨1/10⟩배예요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 22.4 ÷ 4 = 5.6이에요."]},{"stem":"아 상자에는 무게가 같은 수박 6통이 30.6 kg 들어 있어요. 수박 한 통의 무게는 몇 kg인가요?","options":[{"t":"5.1 kg","correct":true},{"t":"51 kg","mis":"M6-1-u3-X01"},{"t":"0.51 kg","mis":"M6-1-u3-X02"},{"t":"183.6 kg","mis":"M6-1-u3-X10"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 306 ÷ 6 = 51이에요.","30.6은 306의 ⟨1/10⟩배라서 몫도 51의 ⟨1/10⟩배예요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 30.6 ÷ 6 = 5.1이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L08_challenge#3','math',6,1,'u3','L08','g6_1_math_u3_L08_challenge','lesson_challenge','M6-1-u3-C7',3,'mc','auto','가 상자 3통 18.3 kg · 나 상자 4통 19.8 kg · 다 상자 5통 20.2 kg — 수박 한 통이 가장 가벼운 상자는 어느 것인가요?',ARRAY['M6-1-u3-X14','M6-1-u3-X12']::text[],true,'{"seq":3,"concept":"M6-1-u3-C7","difficulty":3,"kind":"mc","stem":"가 상자 3통 18.3 kg · 나 상자 4통 19.8 kg · 다 상자 5통 20.2 kg — 수박 한 통이 가장 가벼운 상자는 어느 것인가요?","options":[{"t":"다 상자","correct":true},{"t":"가 상자","mis":"M6-1-u3-X14"},{"t":"나 상자","mis":"M6-1-u3-X12"},{"t":"모두 같아요","mis":"M6-1-u3-X12"}],"explanation":["먼저 어림해요 — 18 ÷ 3 = 6, 20 ÷ 4 = 5, 20 ÷ 5 = 4예요.","계산으로 확인하면 가 6.1 kg, 나 4.95 kg, 다 4.04 kg이에요.","수박 한 통이 가장 가벼운 것은 다 상자예요."],"variant_rule":{"alt":[{"stem":"라 상자 6통 25.2 kg · 바 상자 4통 22.4 kg · 아 상자 6통 30.6 kg — 수박 한 통이 가장 가벼운 상자는 어느 것인가요?","options":[{"t":"라 상자","correct":true},{"t":"바 상자","mis":"M6-1-u3-X14"},{"t":"아 상자","mis":"M6-1-u3-X12"},{"t":"모두 같아요","mis":"M6-1-u3-X12"}],"explanation":["먼저 어림해요 — 24 ÷ 6 = 4, 24 ÷ 4 = 6, 30 ÷ 6 = 5예요.","계산으로 확인하면 라 4.2 kg, 바 5.6 kg, 아 5.1 kg이에요.","수박 한 통이 가장 가벼운 것은 라 상자예요."]},{"stem":"마 상자 5통 14.5 kg · 사 상자 3통 16.2 kg · 다 상자 5통 20.2 kg — 수박 한 통이 가장 가벼운 상자는 어느 것인가요?","options":[{"t":"마 상자","correct":true},{"t":"사 상자","mis":"M6-1-u3-X14"},{"t":"다 상자","mis":"M6-1-u3-X12"},{"t":"모두 같아요","mis":"M6-1-u3-X12"}],"explanation":["먼저 어림해요 — 15 ÷ 5 = 3, 15 ÷ 3 = 5, 20 ÷ 5 = 4예요.","계산으로 확인하면 마 2.9 kg, 사 5.4 kg, 다 4.04 kg이에요.","수박 한 통이 가장 가벼운 것은 마 상자예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L08_challenge#4','math',6,1,'u3','L08','g6_1_math_u3_L08_challenge','lesson_challenge','M6-1-u3-C7',3,'error','auto','18.3 ÷ 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u3-X12','M6-1-u3-X14']::text[],true,'{"seq":4,"concept":"M6-1-u3-C7","difficulty":3,"kind":"error","stem":"18.3 ÷ 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「몫은 61이야. 어림은 안 해도 돼.」","correct":true,"mis_target":"M6-1-u3-X12"},{"t":"이현 — 「18.3을 18로 어림하면 몫은 약 6이야.」","mis":"M6-1-u3-X14"},{"t":"서아 — 「계산한 몫은 6.1이야.」","mis":"M6-1-u3-X14"}],"explanation":["18.3을 18로 어림하면 18 ÷ 3 = 6이에요.","61은 어림한 값보다 10배쯤 커요.","준희는 소수점을 잘못 찍고 어림으로 확인하지 않았어요 — 바른 몫은 6.1이에요."],"variant_rule":{"alt":[{"stem":"19.8 ÷ 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「몫은 49.5야. 어림은 안 해도 돼.」","correct":true,"mis_target":"M6-1-u3-X12"},{"t":"수아 — 「19.8을 20으로 어림하면 몫은 약 5야.」","mis":"M6-1-u3-X14"},{"t":"도윤 — 「계산한 몫은 4.95야.」","mis":"M6-1-u3-X14"}],"explanation":["19.8을 20으로 어림하면 20 ÷ 4 = 5예요.","49.5는 어림한 값보다 10배쯤 커요.","서호는 소수점을 잘못 찍고 어림으로 확인하지 않았어요 — 바른 몫은 4.95예요."]},{"stem":"25.2 ÷ 6을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「몫은 42야. 어림은 안 해도 돼.」","correct":true,"mis_target":"M6-1-u3-X12"},{"t":"나린 — 「25.2를 24로 어림하면 몫은 약 4야.」","mis":"M6-1-u3-X14"},{"t":"유진 — 「계산한 몫은 4.2야.」","mis":"M6-1-u3-X14"}],"explanation":["25.2를 24로 어림하면 24 ÷ 6 = 4예요.","42는 어림한 값보다 10배쯤 커요.","가온은 소수점을 잘못 찍고 어림으로 확인하지 않았어요 — 바른 몫은 4.2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L08_challenge#5','math',6,1,'u3','L08','g6_1_math_u3_L08_challenge','lesson_challenge','M6-1-u3-C7',3,'ox','auto','어림한 값과 계산한 값이 크게 달라도 계산한 값을 그대로 믿어요.',ARRAY['M6-1-u3-X12']::text[],true,'{"seq":5,"concept":"M6-1-u3-C7","difficulty":3,"kind":"ox","stem":"어림한 값과 계산한 값이 크게 달라도 계산한 값을 그대로 믿어요.","answer":"X","reason_options":[{"t":"크게 다르면 계산이 잘못되었다는 신호이기 때문에","correct":true},{"t":"계산한 값이 언제나 정확하기 때문에","mis":"M6-1-u3-X12"}],"mis":"M6-1-u3-X12","explanation":["어림은 나누어지는 수를 계산하기 쉬운 자연수로 바꾸어 몫을 짐작하는 것이에요.","어림으로 답을 먼저 고르고 계산으로 확인해요.","어림과 계산이 크게 다르면 계산을 다시 확인해요."],"variant_rule":{"alt":[{"stem":"19.8 ÷ 4의 몫은 49.5예요.","answer":"X","reason_options":[{"t":"20 ÷ 4 = 5로 어림되니 몫은 4.95이기 때문에","correct":true},{"t":"198 ÷ 4 = 49.5이기 때문에","mis":"M6-1-u3-X01"}],"explanation":["어림은 나누어지는 수를 계산하기 쉬운 자연수로 바꾸어 몫을 짐작하는 것이에요.","어림으로 답을 먼저 고르고 계산으로 확인해요.","어림과 계산이 크게 다르면 계산을 다시 확인해요."]},{"stem":"20.2 ÷ 5의 몫은 4.4예요.","answer":"X","reason_options":[{"t":"20을 나누고 남은 2는 5보다 작아 몫에 0을 써서 4.04이기 때문에","correct":true},{"t":"20 ÷ 5 = 4이고 2 ÷ 5 = 0.4이기 때문에","mis":"M6-1-u3-X07"}],"explanation":["어림은 나누어지는 수를 계산하기 쉬운 자연수로 바꾸어 몫을 짐작하는 것이에요.","어림으로 답을 먼저 고르고 계산으로 확인해요.","어림과 계산이 크게 다르면 계산을 다시 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L08_challenge#6','math',6,1,'u3','L08','g6_1_math_u3_L08_challenge','lesson_challenge','M6-1-u3-C7',3,'match','auto','상자와 수박 한 통의 무게를 알맞게 이으세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u3-C7","difficulty":3,"kind":"match","stem":"상자와 수박 한 통의 무게를 알맞게 이으세요.","pairs":[{"l":"가 상자(18.3 kg ÷ 3)","r":"6.1 kg"},{"l":"나 상자(19.8 kg ÷ 4)","r":"4.95 kg"},{"l":"다 상자(20.2 kg ÷ 5)","r":"4.04 kg"}],"mis":"M6-1-u3-X02","explanation":["어림으로 몫의 크기를 먼저 짐작해요.","18.3 ÷ 3 = 6.1, 19.8 ÷ 4 = 4.95, 20.2 ÷ 5 = 4.04예요.","어림한 값과 견주어 소수점을 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 상자와 수박 한 통의 무게를 알맞게 이으세요.","pairs":[{"l":"라 상자(25.2 kg ÷ 6)","r":"4.2 kg"},{"l":"마 상자(14.5 kg ÷ 5)","r":"2.9 kg"},{"l":"바 상자(22.4 kg ÷ 4)","r":"5.6 kg"}],"explanation":["어림으로 몫의 크기를 먼저 짐작해요.","25.2 ÷ 6 = 4.2, 14.5 ÷ 5 = 2.9, 22.4 ÷ 4 = 5.6이에요.","어림한 값과 견주어 소수점을 확인해요."]},{"stem":"이번에는 다른 보기예요. 상자와 수박 한 통의 무게를 알맞게 이으세요.","pairs":[{"l":"사 상자(16.2 kg ÷ 3)","r":"5.4 kg"},{"l":"아 상자(30.6 kg ÷ 6)","r":"5.1 kg"},{"l":"다 상자(20.2 kg ÷ 5)","r":"4.04 kg"}],"explanation":["어림으로 몫의 크기를 먼저 짐작해요.","16.2 ÷ 3 = 5.4, 30.6 ÷ 6 = 5.1, 20.2 ÷ 5 = 4.04예요.","어림한 값과 견주어 소수점을 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L08_challenge#7','math',6,1,'u3','L08','g6_1_math_u3_L08_challenge','lesson_challenge','M6-1-u3-C7',3,'mc','auto','가 상자는 수박 3통이 18.3 kg, 다 상자는 수박 5통이 20.2 kg이에요. 두 상자에서 수박을 한 통씩 꺼냈어요. 두 통의 무게는 모두 몇 kg인가요?',ARRAY['M6-1-u3-X14','M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":7,"concept":"M6-1-u3-C7","difficulty":3,"kind":"mc","stem":"가 상자는 수박 3통이 18.3 kg, 다 상자는 수박 5통이 20.2 kg이에요. 두 상자에서 수박을 한 통씩 꺼냈어요. 두 통의 무게는 모두 몇 kg인가요?","options":[{"t":"10.14 kg","correct":true},{"t":"2.06 kg","mis":"M6-1-u3-X14"},{"t":"101.4 kg","mis":"M6-1-u3-X01"},{"t":"1.014 kg","mis":"M6-1-u3-X02"}],"explanation":["18.3 ÷ 3 = 6.1 (kg)이에요.","20.2 ÷ 5 = 4.04 (kg)이에요.","6.1 + 4.04 = 10.14 (kg)이에요."],"variant_rule":{"alt":[{"stem":"나 상자는 수박 4통이 19.8 kg, 라 상자는 수박 6통이 25.2 kg이에요. 두 상자에서 수박을 한 통씩 꺼냈어요. 두 통의 무게는 모두 몇 kg인가요?","options":[{"t":"9.15 kg","correct":true},{"t":"0.75 kg","mis":"M6-1-u3-X14"},{"t":"91.5 kg","mis":"M6-1-u3-X01"},{"t":"0.915 kg","mis":"M6-1-u3-X02"}],"explanation":["19.8 ÷ 4 = 4.95 (kg)이에요.","25.2 ÷ 6 = 4.2 (kg)이에요.","4.95 + 4.2 = 9.15 (kg)이에요."]},{"stem":"사 상자는 수박 3통이 16.2 kg, 마 상자는 수박 5통이 14.5 kg이에요. 두 상자에서 수박을 한 통씩 꺼냈어요. 두 통의 무게는 모두 몇 kg인가요?","options":[{"t":"8.3 kg","correct":true},{"t":"2.5 kg","mis":"M6-1-u3-X14"},{"t":"83 kg","mis":"M6-1-u3-X01"},{"t":"0.83 kg","mis":"M6-1-u3-X02"}],"explanation":["16.2 ÷ 3 = 5.4 (kg)이에요.","14.5 ÷ 5 = 2.9 (kg)이에요.","5.4 + 2.9 = 8.3 (kg)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L08_challenge#8','math',6,1,'u3','L08','g6_1_math_u3_L08_challenge','lesson_challenge','M6-1-u3-C7',4,'mc','auto','가 상자는 수박 3통이 18.3 kg, 다 상자는 수박 5통이 20.2 kg이에요. 다 상자의 수박 한 통은 가 상자의 수박 한 통보다 몇 kg 가벼운가요?',ARRAY['M6-1-u3-X14','M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":8,"concept":"M6-1-u3-C7","difficulty":4,"kind":"mc","stem":"가 상자는 수박 3통이 18.3 kg, 다 상자는 수박 5통이 20.2 kg이에요. 다 상자의 수박 한 통은 가 상자의 수박 한 통보다 몇 kg 가벼운가요?","options":[{"t":"2.06 kg","correct":true},{"t":"10.14 kg","mis":"M6-1-u3-X14"},{"t":"20.6 kg","mis":"M6-1-u3-X01"},{"t":"0.206 kg","mis":"M6-1-u3-X02"}],"explanation":["가 상자 한 통은 18.3 ÷ 3 = 6.1 (kg)이에요.","다 상자 한 통은 20.2 ÷ 5 = 4.04 (kg)이에요.","6.1 − 4.04 = 2.06 (kg) 가벼워요."],"variant_rule":{"alt":[{"stem":"사 상자는 수박 3통이 16.2 kg, 나 상자는 수박 4통이 19.8 kg이에요. 나 상자의 수박 한 통은 사 상자의 수박 한 통보다 몇 kg 가벼운가요?","options":[{"t":"0.45 kg","correct":true},{"t":"10.35 kg","mis":"M6-1-u3-X14"},{"t":"4.5 kg","mis":"M6-1-u3-X01"},{"t":"0.045 kg","mis":"M6-1-u3-X02"}],"explanation":["사 상자 한 통은 16.2 ÷ 3 = 5.4 (kg)이에요.","나 상자 한 통은 19.8 ÷ 4 = 4.95 (kg)이에요.","5.4 − 4.95 = 0.45 (kg) 가벼워요."]},{"stem":"아 상자는 수박 6통이 30.6 kg, 마 상자는 수박 5통이 14.5 kg이에요. 마 상자의 수박 한 통은 아 상자의 수박 한 통보다 몇 kg 가벼운가요?","options":[{"t":"2.2 kg","correct":true},{"t":"8 kg","mis":"M6-1-u3-X14"},{"t":"22 kg","mis":"M6-1-u3-X01"},{"t":"0.22 kg","mis":"M6-1-u3-X02"}],"explanation":["아 상자 한 통은 30.6 ÷ 6 = 5.1 (kg)이에요.","마 상자 한 통은 14.5 ÷ 5 = 2.9 (kg)이에요.","5.1 − 2.9 = 2.2 (kg) 가벼워요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L08_challenge#9','math',6,1,'u3','L08','g6_1_math_u3_L08_challenge','lesson_challenge','M6-1-u3-C7',4,'sa','auto','19.8 ÷ 4, 20.2 ÷ 5, 18.3 ÷ 3, 25.2 ÷ 6, 14.5 ÷ 5 — 이 가운데 몫이 4보다 크고 5보다 작은 나눗셈은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u3-C7","difficulty":4,"kind":"sa","stem":"19.8 ÷ 4, 20.2 ÷ 5, 18.3 ÷ 3, 25.2 ÷ 6, 14.5 ÷ 5 — 이 가운데 몫이 4보다 크고 5보다 작은 나눗셈은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["먼저 어림하고 계산으로 확인해요.","19.8 ÷ 4 = 4.95, 20.2 ÷ 5 = 4.04, 18.3 ÷ 3 = 6.1, 25.2 ÷ 6 = 4.2, 14.5 ÷ 5 = 2.9예요.","4와 5 사이인 것은 3개예요."],"mis":"M6-1-u3-X12","variant_rule":{"alt":[{"stem":"22.4 ÷ 4, 16.2 ÷ 3, 30.6 ÷ 6, 14.5 ÷ 5, 19.8 ÷ 4 — 이 가운데 몫이 5보다 크고 6보다 작은 나눗셈은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["먼저 어림하고 계산으로 확인해요.","22.4 ÷ 4 = 5.6, 16.2 ÷ 3 = 5.4, 30.6 ÷ 6 = 5.1, 14.5 ÷ 5 = 2.9, 19.8 ÷ 4 = 4.95예요.","5와 6 사이인 것은 3개예요."]},{"stem":"18.3 ÷ 3, 22.4 ÷ 4, 25.2 ÷ 6, 20.2 ÷ 5, 16.2 ÷ 3 — 이 가운데 몫이 4보다 크고 6보다 작은 나눗셈은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["먼저 어림하고 계산으로 확인해요.","18.3 ÷ 3 = 6.1, 22.4 ÷ 4 = 5.6, 25.2 ÷ 6 = 4.2, 20.2 ÷ 5 = 4.04, 16.2 ÷ 3 = 5.4예요.","4와 6 사이인 것은 4개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_L08_challenge#10','math',6,1,'u3','L08','g6_1_math_u3_L08_challenge','lesson_challenge','M6-1-u3-C7',4,'essay','teacher','수박 상자 가는 3통에 18.3 kg, 나는 4통에 19.8 kg, 다는 5통에 20.2 kg이에요. 어림으로 수박 한 통이 가장 무거운 상자를 고르고, 계산으로 확인해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u3-C7","difficulty":4,"kind":"essay","stem":"수박 상자 가는 3통에 18.3 kg, 나는 4통에 19.8 kg, 다는 5통에 20.2 kg이에요. 어림으로 수박 한 통이 가장 무거운 상자를 고르고, 계산으로 확인해 보세요.","answer_guide":{"answer":"예: 18.3을 18, 19.8과 20.2를 20으로 어림하면 18 ÷ 3 = 6, 20 ÷ 4 = 5, 20 ÷ 5 = 4이므로 가 상자가 가장 무겁겠다. 계산하면 18.3 ÷ 3 = 6.1, 19.8 ÷ 4 = 4.95, 20.2 ÷ 5 = 4.04이므로 가 상자의 수박 한 통이 가장 무겁다.","scoring_points":["세 상자를 자연수로 어림했는가","가 상자를 골랐는가","6.1, 4.95, 4.04로 계산해 확인했는가"]},"explanation":["어림하면 6, 5, 4예요.","가 상자가 가장 무겁겠어요.","6.1, 4.95, 4.04로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_a#1','math',6,1,'u3','','g6_1_math_u3_review_a','unit_review','M6-1-u3-C1',1,'mc','auto','585 ÷ 5 = 117이에요. 그러면 5.85 ÷ 5의 몫은 얼마인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":1,"concept":"M6-1-u3-C1","difficulty":1,"kind":"mc","stem":"585 ÷ 5 = 117이에요. 그러면 5.85 ÷ 5의 몫은 얼마인가요?","options":[{"t":"1.17","correct":true},{"t":"11.7","mis":"M6-1-u3-X01"},{"t":"0.117","mis":"M6-1-u3-X02"},{"t":"117","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 5는 그대로예요.","나누어지는 수 5.85는 585의 ⟨1/100⟩배예요.","그래서 몫도 117의 ⟨1/100⟩배 — 1.17이에요."],"variant_rule":{"alt":[{"stem":"648 ÷ 2 = 324예요. 그러면 64.8 ÷ 2의 몫은 얼마인가요?","options":[{"t":"32.4","correct":true},{"t":"324","mis":"M6-1-u3-X01"},{"t":"3.24","mis":"M6-1-u3-X02"},{"t":"3240","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 2는 그대로예요.","나누어지는 수 64.8은 648의 ⟨1/10⟩배예요.","그래서 몫도 324의 ⟨1/10⟩배 — 32.4예요."]},{"stem":"393 ÷ 3 = 131이에요. 그러면 3.93 ÷ 3의 몫은 얼마인가요?","options":[{"t":"1.31","correct":true},{"t":"13.1","mis":"M6-1-u3-X01"},{"t":"0.131","mis":"M6-1-u3-X02"},{"t":"131","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 3은 그대로예요.","나누어지는 수 3.93은 393의 ⟨1/100⟩배예요.","그래서 몫도 131의 ⟨1/100⟩배 — 1.31이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_a#2','math',6,1,'u3','','g6_1_math_u3_review_a','unit_review','M6-1-u3-C1',1,'sa','auto','5.8은 0.1이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u3-C1","difficulty":1,"kind":"sa","stem":"5.8은 0.1이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["58"],"explanation":["0.1이 10개이면 1이에요.","5.8은 5와 소수 부분을 합해 0.1이 58개예요.","그래서 5.8은 0.1이 58개인 수예요."],"mis":"M6-1-u3-X03","variant_rule":{"alt":[{"stem":"4.7은 0.1이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["47"],"explanation":["0.1이 10개이면 1이에요.","4.7은 4와 소수 부분을 합해 0.1이 47개예요.","그래서 4.7은 0.1이 47개인 수예요."]},{"stem":"7.2는 0.1이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["72"],"explanation":["0.1이 10개이면 1이에요.","7.2는 7과 소수 부분을 합해 0.1이 72개예요.","그래서 7.2는 0.1이 72개인 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_a#3','math',6,1,'u3','','g6_1_math_u3_review_a','unit_review','M6-1-u3-C2',1,'mc','auto','58.5 ÷ 5의 몫은 얼마인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":3,"concept":"M6-1-u3-C2","difficulty":1,"kind":"mc","stem":"58.5 ÷ 5의 몫은 얼마인가요?","options":[{"t":"11.7","correct":true},{"t":"117","mis":"M6-1-u3-X01"},{"t":"1.17","mis":"M6-1-u3-X02"},{"t":"1170","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 585 ÷ 5 = 117이에요.","58.5는 585의 ⟨1/10⟩배라서 몫도 117의 ⟨1/10⟩배예요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 58.5 ÷ 5 = 11.7이에요."],"variant_rule":{"alt":[{"stem":"11.7 ÷ 3의 몫은 얼마인가요?","options":[{"t":"3.9","correct":true},{"t":"39","mis":"M6-1-u3-X01"},{"t":"0.39","mis":"M6-1-u3-X02"},{"t":"390","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 117 ÷ 3 = 39예요.","11.7은 117의 ⟨1/10⟩배라서 몫도 39의 ⟨1/10⟩배예요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 11.7 ÷ 3 = 3.9예요."]},{"stem":"34.5 ÷ 5의 몫은 얼마인가요?","options":[{"t":"6.9","correct":true},{"t":"69","mis":"M6-1-u3-X01"},{"t":"0.69","mis":"M6-1-u3-X02"},{"t":"690","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 345 ÷ 5 = 69예요.","34.5는 345의 ⟨1/10⟩배라서 몫도 69의 ⟨1/10⟩배예요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 34.5 ÷ 5 = 6.9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_a#4','math',6,1,'u3','','g6_1_math_u3_review_a','unit_review','M6-1-u3-C3',1,'mc','auto','4.15 ÷ 5의 몫은 얼마인가요?',ARRAY['M6-1-u3-X05','M6-1-u3-X02','M6-1-u3-X01']::text[],true,'{"seq":4,"concept":"M6-1-u3-C3","difficulty":1,"kind":"mc","stem":"4.15 ÷ 5의 몫은 얼마인가요?","options":[{"t":"0.83","correct":true},{"t":"8.3","mis":"M6-1-u3-X05"},{"t":"0.083","mis":"M6-1-u3-X02"},{"t":"83","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 415 ÷ 5 = 83이에요.","4.15는 415의 ⟨1/100⟩배라서 몫도 83의 ⟨1/100⟩배예요.","몫이 1보다 작으니 일의 자리에 0을 써서 자리를 지켜요 — 4.15 ÷ 5 = 0.83이에요."],"variant_rule":{"alt":[{"stem":"3.2 ÷ 4의 몫은 얼마인가요?","options":[{"t":"0.8","correct":true},{"t":"8","mis":"M6-1-u3-X05"},{"t":"0.08","mis":"M6-1-u3-X02"},{"t":"80","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 32 ÷ 4 = 8이에요.","3.2는 32의 ⟨1/10⟩배라서 몫도 8의 ⟨1/10⟩배예요.","몫이 1보다 작으니 일의 자리에 0을 써서 자리를 지켜요 — 3.2 ÷ 4 = 0.8이에요."]},{"stem":"5.72 ÷ 11의 몫은 얼마인가요?","options":[{"t":"0.52","correct":true},{"t":"5.2","mis":"M6-1-u3-X05"},{"t":"0.052","mis":"M6-1-u3-X02"},{"t":"52","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 572 ÷ 11 = 52예요.","5.72는 572의 ⟨1/100⟩배라서 몫도 52의 ⟨1/100⟩배예요.","몫이 1보다 작으니 일의 자리에 0을 써서 자리를 지켜요 — 5.72 ÷ 11 = 0.52예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_a#5','math',6,1,'u3','','g6_1_math_u3_review_a','unit_review','M6-1-u3-C3',1,'mc','auto','7.29 ÷ 9의 몫은 1보다 클까요, 작을까요?',ARRAY['M6-1-u3-X12']::text[],true,'{"seq":5,"concept":"M6-1-u3-C3","difficulty":1,"kind":"mc","stem":"7.29 ÷ 9의 몫은 1보다 클까요, 작을까요?","options":[{"t":"1보다 작아요","correct":true},{"t":"1보다 커요","mis":"M6-1-u3-X12"},{"t":"1과 같아요","mis":"M6-1-u3-X12"},{"t":"계산해 보기 전에는 알 수 없어요","mis":"M6-1-u3-X12"}],"explanation":["나누어지는 수 7.29가 나누는 수 9보다 작아요.","9 ÷ 9 = 1이니 7.29 ÷ 9는 1보다 작아요.","실제로 몫은 0.81이에요."],"variant_rule":{"alt":[{"stem":"4.15 ÷ 5의 몫은 1보다 클까요, 작을까요?","options":[{"t":"1보다 작아요","correct":true},{"t":"1보다 커요","mis":"M6-1-u3-X12"},{"t":"1과 같아요","mis":"M6-1-u3-X12"},{"t":"계산해 보기 전에는 알 수 없어요","mis":"M6-1-u3-X12"}],"explanation":["나누어지는 수 4.15가 나누는 수 5보다 작아요.","5 ÷ 5 = 1이니 4.15 ÷ 5는 1보다 작아요.","실제로 몫은 0.83이에요."]},{"stem":"2.38 ÷ 7의 몫은 1보다 클까요, 작을까요?","options":[{"t":"1보다 작아요","correct":true},{"t":"1보다 커요","mis":"M6-1-u3-X12"},{"t":"1과 같아요","mis":"M6-1-u3-X12"},{"t":"계산해 보기 전에는 알 수 없어요","mis":"M6-1-u3-X12"}],"explanation":["나누어지는 수 2.38이 나누는 수 7보다 작아요.","7 ÷ 7 = 1이니 2.38 ÷ 7은 1보다 작아요.","실제로 몫은 0.34예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_a#6','math',6,1,'u3','','g6_1_math_u3_review_a','unit_review','M6-1-u3-C4',1,'mc','auto','4.6 ÷ 4를 계산하다가 소수 첫째 자리까지 나누었더니 2가 남았어요. 다음에 할 일로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u3-X06','M6-1-u3-X13']::text[],true,'{"seq":6,"concept":"M6-1-u3-C4","difficulty":1,"kind":"mc","stem":"4.6 ÷ 4를 계산하다가 소수 첫째 자리까지 나누었더니 2가 남았어요. 다음에 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"소수점 아래에 0을 하나 내려 계산을 이어 가요","correct":true},{"t":"남은 2를 몫 뒤에 붙여 써요","mis":"M6-1-u3-X06"},{"t":"나누어떨어지지 않는다고 답해요","mis":"M6-1-u3-X06"},{"t":"나누는 수를 바꾸어 다시 나누어요","mis":"M6-1-u3-X13"}],"explanation":["4.6은 4.60과 같은 수예요.","소수점 아래 끝자리에 0을 붙여도 수의 크기는 그대로예요.","그래서 0을 내려 이어 계산하면 4.6 ÷ 4 = 1.15예요."],"variant_rule":{"alt":[{"stem":"6.7 ÷ 5를 계산하다가 소수 첫째 자리까지 나누었더니 2가 남았어요. 다음에 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"소수점 아래에 0을 하나 내려 계산을 이어 가요","correct":true},{"t":"남은 2를 몫 뒤에 붙여 써요","mis":"M6-1-u3-X06"},{"t":"나누어떨어지지 않는다고 답해요","mis":"M6-1-u3-X06"},{"t":"나누는 수를 바꾸어 다시 나누어요","mis":"M6-1-u3-X13"}],"explanation":["6.7은 6.70과 같은 수예요.","소수점 아래 끝자리에 0을 붙여도 수의 크기는 그대로예요.","그래서 0을 내려 이어 계산하면 6.7 ÷ 5 = 1.34예요."]},{"stem":"18.8 ÷ 8을 계산하다가 소수 첫째 자리까지 나누었더니 4가 남았어요. 다음에 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"소수점 아래에 0을 하나 내려 계산을 이어 가요","correct":true},{"t":"남은 4를 몫 뒤에 붙여 써요","mis":"M6-1-u3-X06"},{"t":"나누어떨어지지 않는다고 답해요","mis":"M6-1-u3-X06"},{"t":"나누는 수를 바꾸어 다시 나누어요","mis":"M6-1-u3-X13"}],"explanation":["18.8은 18.80과 같은 수예요.","소수점 아래 끝자리에 0을 붙여도 수의 크기는 그대로예요.","그래서 0을 내려 이어 계산하면 18.8 ÷ 8 = 2.35예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_a#7','math',6,1,'u3','','g6_1_math_u3_review_a','unit_review','M6-1-u3-C6',1,'mc','auto','60 ÷ 8을 세로셈으로 계산할 때 60을 어떻게 보아야 하나요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":7,"concept":"M6-1-u3-C6","difficulty":1,"kind":"mc","stem":"60 ÷ 8을 세로셈으로 계산할 때 60을 어떻게 보아야 하나요?","options":[{"t":"60.0으로 봐요","correct":true},{"t":"600으로 봐요","mis":"M6-1-u3-X01"},{"t":"6으로 봐요","mis":"M6-1-u3-X02"},{"t":"⟨60/10⟩으로 봐요","mis":"M6-1-u3-X02"}],"explanation":["자연수의 소수점은 자연수 바로 뒤에 있어요.","60 = 60.0 = 60.00이에요.","그래서 60을 60.0으로 보고 0을 내려 계산해요."],"variant_rule":{"alt":[{"stem":"6 ÷ 5를 세로셈으로 계산할 때 6을 어떻게 보아야 하나요?","options":[{"t":"6.0으로 봐요","correct":true},{"t":"60으로 봐요","mis":"M6-1-u3-X01"},{"t":"0.6으로 봐요","mis":"M6-1-u3-X02"},{"t":"⟨6/10⟩으로 봐요","mis":"M6-1-u3-X02"}],"explanation":["자연수의 소수점은 자연수 바로 뒤에 있어요.","6 = 6.0 = 6.00이에요.","그래서 6을 6.0으로 보고 0을 내려 계산해요."]},{"stem":"9 ÷ 6을 세로셈으로 계산할 때 9를 어떻게 보아야 하나요?","options":[{"t":"9.0으로 봐요","correct":true},{"t":"90으로 봐요","mis":"M6-1-u3-X01"},{"t":"0.9로 봐요","mis":"M6-1-u3-X02"},{"t":"⟨9/10⟩로 봐요","mis":"M6-1-u3-X02"}],"explanation":["자연수의 소수점은 자연수 바로 뒤에 있어요.","9 = 9.0 = 9.00이에요.","그래서 9를 9.0으로 보고 0을 내려 계산해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_a#8','math',6,1,'u3','','g6_1_math_u3_review_a','unit_review','M6-1-u3-C7',1,'sa','auto','가 상자에는 무게가 같은 수박 3통이 18.3 kg 들어 있어요. 18.3을 18로 어림하면 수박 한 통은 약 몇 kg인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u3-C7","difficulty":1,"kind":"sa","stem":"가 상자에는 무게가 같은 수박 3통이 18.3 kg 들어 있어요. 18.3을 18로 어림하면 수박 한 통은 약 몇 kg인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["18.3에 가까우면서 3으로 나누기 쉬운 수는 18이에요.","18 ÷ 3 = 6이에요.","수박 한 통은 약 6 kg이에요."],"mis":"M6-1-u3-X12","variant_rule":{"alt":[{"stem":"나 상자에는 무게가 같은 수박 4통이 19.8 kg 들어 있어요. 19.8을 20으로 어림하면 수박 한 통은 약 몇 kg인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["19.8에 가까우면서 4로 나누기 쉬운 수는 20이에요.","20 ÷ 4 = 5예요.","수박 한 통은 약 5 kg이에요."]},{"stem":"다 상자에는 무게가 같은 수박 5통이 20.2 kg 들어 있어요. 20.2를 20으로 어림하면 수박 한 통은 약 몇 kg인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["20.2에 가까우면서 5로 나누기 쉬운 수는 20이에요.","20 ÷ 5 = 4예요.","수박 한 통은 약 4 kg이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_a#9','math',6,1,'u3','','g6_1_math_u3_review_a','unit_review','M6-1-u3-C2',2,'sa','auto','58.5 ÷ 5의 몫에서 소수 첫째 자리 숫자는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u3-C2","difficulty":2,"kind":"sa","stem":"58.5 ÷ 5의 몫에서 소수 첫째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 585 ÷ 5 = 117이에요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 58.5 ÷ 5 = 11.7이에요.","11.7의 소수 첫째 자리 숫자는 7이에요."],"mis":"M6-1-u3-X13","variant_rule":{"alt":[{"stem":"9.27 ÷ 9의 몫에서 소수 둘째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 927 ÷ 9 = 103이에요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 9.27 ÷ 9 = 1.03이에요.","1.03의 소수 둘째 자리 숫자는 3이에요."]},{"stem":"13.79 ÷ 7의 몫에서 소수 둘째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1379 ÷ 7 = 197이에요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 13.79 ÷ 7 = 1.97이에요.","1.97의 소수 둘째 자리 숫자는 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_a#10','math',6,1,'u3','','g6_1_math_u3_review_a','unit_review','M6-1-u3-C4',2,'mc','auto','18.8 ÷ 8의 몫은 얼마인가요?',ARRAY['M6-1-u3-X06','M6-1-u3-X01']::text[],true,'{"seq":10,"concept":"M6-1-u3-C4","difficulty":2,"kind":"mc","stem":"18.8 ÷ 8의 몫은 얼마인가요?","options":[{"t":"2.35","correct":true},{"t":"2.3","mis":"M6-1-u3-X06"},{"t":"2.34","mis":"M6-1-u3-X06"},{"t":"23.5","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1880 ÷ 8 = 235예요.","18.8은 1880의 ⟨1/100⟩배라서 몫도 235의 ⟨1/100⟩배예요.","나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 18.8 ÷ 8 = 2.35예요."],"variant_rule":{"alt":[{"stem":"4.6 ÷ 4의 몫은 얼마인가요?","options":[{"t":"1.15","correct":true},{"t":"1.1","mis":"M6-1-u3-X06"},{"t":"1.12","mis":"M6-1-u3-X06"},{"t":"11.5","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 460 ÷ 4 = 115예요.","4.6은 460의 ⟨1/100⟩배라서 몫도 115의 ⟨1/100⟩배예요.","나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 4.6 ÷ 4 = 1.15예요."]},{"stem":"6.7 ÷ 5의 몫은 얼마인가요?","options":[{"t":"1.34","correct":true},{"t":"1.3","mis":"M6-1-u3-X06"},{"t":"1.32","mis":"M6-1-u3-X06"},{"t":"13.4","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 670 ÷ 5 = 134예요.","6.7은 670의 ⟨1/100⟩배라서 몫도 134의 ⟨1/100⟩배예요.","나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 6.7 ÷ 5 = 1.34예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_a#11','math',6,1,'u3','','g6_1_math_u3_review_a','unit_review','M6-1-u3-C5',2,'mc','auto','18.1 ÷ 2의 몫은 얼마인가요?',ARRAY['M6-1-u3-X07','M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":11,"concept":"M6-1-u3-C5","difficulty":2,"kind":"mc","stem":"18.1 ÷ 2의 몫은 얼마인가요?","options":[{"t":"9.05","correct":true},{"t":"9.5","mis":"M6-1-u3-X07"},{"t":"90.5","mis":"M6-1-u3-X01"},{"t":"0.905","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1810 ÷ 2 = 905예요.","18.1은 1810의 ⟨1/100⟩배라서 몫도 905의 ⟨1/100⟩배예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 18.1 ÷ 2 = 9.05예요."],"variant_rule":{"alt":[{"stem":"9.27 ÷ 9의 몫은 얼마인가요?","options":[{"t":"1.03","correct":true},{"t":"1.3","mis":"M6-1-u3-X07"},{"t":"10.3","mis":"M6-1-u3-X01"},{"t":"0.103","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 927 ÷ 9 = 103이에요.","9.27은 927의 ⟨1/100⟩배라서 몫도 103의 ⟨1/100⟩배예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 9.27 ÷ 9 = 1.03이에요."]},{"stem":"20.2 ÷ 5의 몫은 얼마인가요?","options":[{"t":"4.04","correct":true},{"t":"4.4","mis":"M6-1-u3-X07"},{"t":"40.4","mis":"M6-1-u3-X01"},{"t":"0.404","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 2020 ÷ 5 = 404예요.","20.2는 2020의 ⟨1/100⟩배라서 몫도 404의 ⟨1/100⟩배예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 20.2 ÷ 5 = 4.04예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_a#12','math',6,1,'u3','','g6_1_math_u3_review_a','unit_review','M6-1-u3-C6',2,'mc','auto','60 ÷ 8의 몫은 얼마인가요?',ARRAY['M6-1-u3-X08','M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":12,"concept":"M6-1-u3-C6","difficulty":2,"kind":"mc","stem":"60 ÷ 8의 몫은 얼마인가요?","options":[{"t":"7.5","correct":true},{"t":"7.4","mis":"M6-1-u3-X08"},{"t":"75","mis":"M6-1-u3-X01"},{"t":"0.75","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 600 ÷ 8 = 75예요.","60은 600의 ⟨1/10⟩배라서 몫도 75의 ⟨1/10⟩배예요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 60 ÷ 8 = 7.5예요."],"variant_rule":{"alt":[{"stem":"6 ÷ 5의 몫은 얼마인가요?","options":[{"t":"1.2","correct":true},{"t":"1.1","mis":"M6-1-u3-X08"},{"t":"12","mis":"M6-1-u3-X01"},{"t":"0.12","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 60 ÷ 5 = 12예요.","6은 60의 ⟨1/10⟩배라서 몫도 12의 ⟨1/10⟩배예요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 6 ÷ 5 = 1.2예요."]},{"stem":"3 ÷ 4의 몫은 얼마인가요?","options":[{"t":"0.75","correct":true},{"t":"0.3","mis":"M6-1-u3-X08"},{"t":"7.5","mis":"M6-1-u3-X01"},{"t":"0.075","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 300 ÷ 4 = 75예요.","3은 300의 ⟨1/100⟩배라서 몫도 75의 ⟨1/100⟩배예요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 3 ÷ 4 = 0.75예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_a#13','math',6,1,'u3','','g6_1_math_u3_review_a','unit_review','M6-1-u3-C1',2,'ox','auto','648 ÷ 2 = 324이면 6.48 ÷ 2 = 32.4예요.',ARRAY['M6-1-u3-X02']::text[],true,'{"seq":13,"concept":"M6-1-u3-C1","difficulty":2,"kind":"ox","stem":"648 ÷ 2 = 324이면 6.48 ÷ 2 = 32.4예요.","answer":"X","reason_options":[{"t":"6.48은 648의 ⟨1/100⟩배라서 몫도 ⟨1/100⟩배인 3.24이기 때문에","correct":true},{"t":"나누어지는 수의 소수점을 한 칸만 옮기면 되기 때문에","mis":"M6-1-u3-X02"}],"mis":"M6-1-u3-X02","explanation":["소수는 0.1이나 0.01이 몇 개인 수로 볼 수 있어요.","나누는 수가 같을 때 나누어지는 수가 ⟨1/10⟩배가 되면 몫도 ⟨1/10⟩배가 돼요.","분수의 나눗셈으로 바꾸면 ÷ 자연수는 × 자연수분의 1이에요."],"variant_rule":{"alt":[{"stem":"5.6 ÷ 7의 몫은 8이에요.","answer":"X","reason_options":[{"t":"몫이 1보다 작아 일의 자리에 0을 써서 0.8이기 때문에","correct":true},{"t":"56 ÷ 7 = 8이니 몫도 8이기 때문에","mis":"M6-1-u3-X05"}],"explanation":["나누어지는 수가 나누는 수보다 작으면 몫은 1보다 작아요.","이때 몫의 일의 자리에 0을 써요.","0은 자리를 지키는 숫자예요."]},{"stem":"4.6 ÷ 4를 소수 첫째 자리까지 나누고 2가 남으면 몫은 1.1이에요.","answer":"X","reason_options":[{"t":"0을 내려 계산을 이어 가면 몫은 1.15이기 때문에","correct":true},{"t":"나누어지는 수의 자리가 끝나면 계산도 끝나기 때문에","mis":"M6-1-u3-X06"}],"explanation":["4.6 = 4.60 = 4.600 — 소수점 아래 끝자리에 0을 붙여도 수의 크기는 같아요.","그래서 나머지가 남으면 0을 내려 계산을 이어 가요.","남은 수를 몫 뒤에 붙이면 안 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_a#14','math',6,1,'u3','','g6_1_math_u3_review_a','unit_review','M6-1-u3-C3',2,'mc','auto','다음 가운데 몫이 1보다 작은 나눗셈은 어느 것인가요?',ARRAY['M6-1-u3-X12']::text[],true,'{"seq":14,"concept":"M6-1-u3-C3","difficulty":2,"kind":"mc","stem":"다음 가운데 몫이 1보다 작은 나눗셈은 어느 것인가요?","options":[{"t":"7.29 ÷ 9","correct":true},{"t":"14.9 ÷ 5","mis":"M6-1-u3-X12"},{"t":"8.4 ÷ 8","mis":"M6-1-u3-X12"},{"t":"4.16 ÷ 4","mis":"M6-1-u3-X12"}],"explanation":["몫이 1보다 작으려면 나누어지는 수가 나누는 수보다 작아야 해요.","나누어지는 수와 나누는 수를 하나씩 견주어 봐요.","7.29 ÷ 9만 나누어지는 수가 더 작아요 — 몫은 0.81이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 가운데 몫이 1보다 작은 나눗셈은 어느 것인가요?","options":[{"t":"6.3 ÷ 7","correct":true},{"t":"9.6 ÷ 8","mis":"M6-1-u3-X12"},{"t":"5.5 ÷ 5","mis":"M6-1-u3-X12"},{"t":"12.6 ÷ 6","mis":"M6-1-u3-X12"}],"explanation":["몫이 1보다 작으려면 나누어지는 수가 나누는 수보다 작아야 해요.","나누어지는 수와 나누는 수를 하나씩 견주어 봐요.","6.3 ÷ 7만 나누어지는 수가 더 작아요 — 몫은 0.9예요."]},{"stem":"이번에는 다른 보기예요. 다음 가운데 몫이 1보다 작은 나눗셈은 어느 것인가요?","options":[{"t":"2.7 ÷ 3","correct":true},{"t":"7.2 ÷ 6","mis":"M6-1-u3-X12"},{"t":"4.4 ÷ 4","mis":"M6-1-u3-X12"},{"t":"8.1 ÷ 3","mis":"M6-1-u3-X12"}],"explanation":["몫이 1보다 작으려면 나누어지는 수가 나누는 수보다 작아야 해요.","나누어지는 수와 나누는 수를 하나씩 견주어 봐요.","2.7 ÷ 3만 나누어지는 수가 더 작아요 — 몫은 0.9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_a#15','math',6,1,'u3','','g6_1_math_u3_review_a','unit_review','M6-1-u3-C1',2,'mc','auto','걷기 대회 코스는 모두 6.8 km예요. 반환점은 코스의 정확히 절반 지점에 있어요. 반환점까지는 몇 km인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02','M6-1-u3-X10']::text[],true,'{"seq":15,"concept":"M6-1-u3-C1","difficulty":2,"kind":"mc","stem":"걷기 대회 코스는 모두 6.8 km예요. 반환점은 코스의 정확히 절반 지점에 있어요. 반환점까지는 몇 km인가요?","options":[{"t":"3.4 km","correct":true},{"t":"34 km","mis":"M6-1-u3-X01"},{"t":"0.34 km","mis":"M6-1-u3-X02"},{"t":"13.6 km","mis":"M6-1-u3-X10"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 68 ÷ 2 = 34예요.","6.8은 68의 ⟨1/10⟩배라서 몫도 34의 ⟨1/10⟩배예요.","6.8 ÷ 2 = 3.4예요."],"variant_rule":{"alt":[{"stem":"쌀 84.88 kg을 자루 4개에 똑같이 나누어 담았어요. 자루 한 개에 담긴 쌀은 몇 kg인가요?","options":[{"t":"21.22 kg","correct":true},{"t":"212.2 kg","mis":"M6-1-u3-X01"},{"t":"2.122 kg","mis":"M6-1-u3-X02"},{"t":"339.52 kg","mis":"M6-1-u3-X10"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 8488 ÷ 4 = 2122예요.","84.88은 8488의 ⟨1/100⟩배라서 몫도 2122의 ⟨1/100⟩배예요.","84.88 ÷ 4 = 21.22예요."]},{"stem":"길이가 3.6 m인 끈을 똑같이 잘라 기념품 상자 3개를 묶어요. 상자 한 개에 쓰는 끈은 몇 m인가요?","options":[{"t":"1.2 m","correct":true},{"t":"12 m","mis":"M6-1-u3-X01"},{"t":"0.12 m","mis":"M6-1-u3-X02"},{"t":"10.8 m","mis":"M6-1-u3-X10"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 36 ÷ 3 = 12예요.","3.6은 36의 ⟨1/10⟩배라서 몫도 12의 ⟨1/10⟩배예요.","3.6 ÷ 3 = 1.2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_a#16','math',6,1,'u3','','g6_1_math_u3_review_a','unit_review','M6-1-u3-C2',2,'sa','auto','넓이가 45.6 cm²이고 가로가 8 cm인 직사각형이 있어요. 이 직사각형의 세로는 몇 mm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M6-1-u3-C2","difficulty":2,"kind":"sa","stem":"넓이가 45.6 cm²이고 가로가 8 cm인 직사각형이 있어요. 이 직사각형의 세로는 몇 mm인가요? 숫자로 쓰세요.","answer":["57"],"explanation":["직사각형의 넓이 = 가로 × 세로이니 세로 = 넓이 ÷ 가로요예요.","45.6 ÷ 8 = 5.7 (cm)예요.","1 cm는 10 mm라서 5.7 cm는 57 mm예요."],"mis":"M6-1-u3-X11","variant_rule":{"alt":[{"stem":"넓이가 25.2 cm²이고 밑변이 4 cm인 평행사변형이 있어요. 이 평행사변형의 높이는 몇 mm인가요? 숫자로 쓰세요.","answer":["63"],"explanation":["평행사변형의 넓이 = 밑변 × 높이이니 높이 = 넓이 ÷ 밑변이에.","25.2 ÷ 4 = 6.3 (cm)예요.","1 cm는 10 mm라서 6.3 cm는 63 mm예요."]},{"stem":"넓이가 34.5 cm²이고 밑변이 5 cm인 평행사변형이 있어요. 이 평행사변형의 높이는 몇 mm인가요? 숫자로 쓰세요.","answer":["69"],"explanation":["평행사변형의 넓이 = 밑변 × 높이이니 높이 = 넓이 ÷ 밑변이에.","34.5 ÷ 5 = 6.9 (cm)예요.","1 cm는 10 mm라서 6.9 cm는 69 mm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_a#17','math',6,1,'u3','','g6_1_math_u3_review_a','unit_review','M6-1-u3-C5',3,'mc','auto','친구가 18.1 ÷ 2의 몫을 9.5라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X06','M6-1-u3-X05']::text[],true,'{"seq":17,"concept":"M6-1-u3-C5","difficulty":3,"kind":"mc","stem":"친구가 18.1 ÷ 2의 몫을 9.5라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"내린 수가 나누는 수보다 작을 때 몫에 0을 쓰지 않아서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"0을 내려 계산하지 않아서","mis":"M6-1-u3-X06"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1810 ÷ 2 = 905예요.","내린 수가 2보다 작으면 몫에 0을 쓰고 하나 더 내려야 해요.","바른 몫은 9.05이고 9.5는 다른 수예요."],"variant_rule":{"alt":[{"stem":"친구가 20.2 ÷ 5의 몫을 4.4라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"내린 수가 나누는 수보다 작을 때 몫에 0을 쓰지 않아서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"0을 내려 계산하지 않아서","mis":"M6-1-u3-X06"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 2020 ÷ 5 = 404예요.","내린 수가 5보다 작으면 몫에 0을 쓰고 하나 더 내려야 해요.","바른 몫은 4.04이고 4.4는 다른 수예요."]},{"stem":"친구가 9.27 ÷ 9의 몫을 1.3이라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"내린 수가 나누는 수보다 작을 때 몫에 0을 쓰지 않아서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"0을 내려 계산하지 않아서","mis":"M6-1-u3-X06"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 927 ÷ 9 = 103이에요.","내린 수가 9보다 작으면 몫에 0을 쓰고 하나 더 내려야 해요.","바른 몫은 1.03이고 1.3은 다른 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_a#18','math',6,1,'u3','','g6_1_math_u3_review_a','unit_review','M6-1-u3-C3',3,'mc','auto','친구가 3.2 ÷ 4의 몫을 8이라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u3-X13','M6-1-u3-X06']::text[],true,'{"seq":18,"concept":"M6-1-u3-C3","difficulty":3,"kind":"mc","stem":"친구가 3.2 ÷ 4의 몫을 8이라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"몫이 1보다 작은데 일의 자리 0과 소수점을 쓰지 않아서","correct":true},{"t":"나누는 수를 잘못 써서","mis":"M6-1-u3-X13"},{"t":"곱셈을 잘못해서","mis":"M6-1-u3-X13"},{"t":"0을 내려 계산하지 않아서","mis":"M6-1-u3-X06"}],"explanation":["3.2는 4보다 작아 몫이 1보다 작아요.","자연수의 나눗셈으로 바꾸어 봐요 — 32 ÷ 4 = 8이에요.","일의 자리에 0을 쓰고 소수점을 찍어 0.8이에요."],"variant_rule":{"alt":[{"stem":"친구가 4.15 ÷ 5의 몫을 83이라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"몫이 1보다 작은데 일의 자리 0과 소수점을 쓰지 않아서","correct":true},{"t":"나누는 수를 잘못 써서","mis":"M6-1-u3-X13"},{"t":"곱셈을 잘못해서","mis":"M6-1-u3-X13"},{"t":"0을 내려 계산하지 않아서","mis":"M6-1-u3-X06"}],"explanation":["4.15는 5보다 작아 몫이 1보다 작아요.","자연수의 나눗셈으로 바꾸어 봐요 — 415 ÷ 5 = 83이에요.","일의 자리에 0을 쓰고 소수점을 찍어 0.83이에요."]},{"stem":"친구가 5.72 ÷ 11의 몫을 52라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"몫이 1보다 작은데 일의 자리 0과 소수점을 쓰지 않아서","correct":true},{"t":"나누는 수를 잘못 써서","mis":"M6-1-u3-X13"},{"t":"곱셈을 잘못해서","mis":"M6-1-u3-X13"},{"t":"0을 내려 계산하지 않아서","mis":"M6-1-u3-X06"}],"explanation":["5.72는 11보다 작아 몫이 1보다 작아요.","자연수의 나눗셈으로 바꾸어 봐요 — 572 ÷ 11 = 52예요.","일의 자리에 0을 쓰고 소수점을 찍어 0.52예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_a#19','math',6,1,'u3','','g6_1_math_u3_review_a','unit_review','M6-1-u3-C6',3,'mc','auto','친구가 6 ÷ 5 = 1 … 1을 보고 몫을 1.1로 나타냈어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X09','M6-1-u3-X05']::text[],true,'{"seq":19,"concept":"M6-1-u3-C6","difficulty":3,"kind":"mc","stem":"친구가 6 ÷ 5 = 1 … 1을 보고 몫을 1.1로 나타냈어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나머지 1을 그대로 소수 부분으로 써서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"나누는 수와 나누어지는 수를 바꾸어서","mis":"M6-1-u3-X09"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["나머지 1은 아직 나누지 않은 양이라 몫의 소수 부분이 아니에요.","6을 6.0으로 보고 0을 내려 계산을 이어 가요.","바른 몫은 1.2예요."],"variant_rule":{"alt":[{"stem":"친구가 9 ÷ 6 = 1 … 3을 보고 몫을 1.3으로 나타냈어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나머지 3을 그대로 소수 부분으로 써서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"나누는 수와 나누어지는 수를 바꾸어서","mis":"M6-1-u3-X09"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["나머지 3은 아직 나누지 않은 양이라 몫의 소수 부분이 아니에요.","9를 9.0으로 보고 0을 내려 계산을 이어 가요.","바른 몫은 1.5예요."]},{"stem":"친구가 7 ÷ 4 = 1 … 3을 보고 몫을 1.3으로 나타냈어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나머지 3을 그대로 소수 부분으로 써서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"나누는 수와 나누어지는 수를 바꾸어서","mis":"M6-1-u3-X09"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["나머지 3은 아직 나누지 않은 양이라 몫의 소수 부분이 아니에요.","7을 7.0으로 보고 0을 내려 계산을 이어 가요.","바른 몫은 1.75예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_a#20','math',6,1,'u3','','g6_1_math_u3_review_a','unit_review','M6-1-u3-C7',3,'mc','auto','가 상자 3통 18.3 kg · 나 상자 4통 19.8 kg · 다 상자 5통 20.2 kg — 수박 한 통이 가장 무거운 상자는 어느 것인가요?',ARRAY['M6-1-u3-X12','M6-1-u3-X14']::text[],true,'{"seq":20,"concept":"M6-1-u3-C7","difficulty":3,"kind":"mc","stem":"가 상자 3통 18.3 kg · 나 상자 4통 19.8 kg · 다 상자 5통 20.2 kg — 수박 한 통이 가장 무거운 상자는 어느 것인가요?","options":[{"t":"가 상자","correct":true},{"t":"나 상자","mis":"M6-1-u3-X12"},{"t":"다 상자","mis":"M6-1-u3-X14"},{"t":"모두 같아요","mis":"M6-1-u3-X12"}],"explanation":["먼저 어림해요 — 18 ÷ 3 = 6, 20 ÷ 4 = 5, 20 ÷ 5 = 4예요.","계산으로 확인하면 가 6.1 kg, 나 4.95 kg, 다 4.04 kg이에요.","수박 한 통이 가장 무거운 것은 가 상자예요."],"variant_rule":{"alt":[{"stem":"라 상자 6통 25.2 kg · 마 상자 5통 14.5 kg · 바 상자 4통 22.4 kg — 수박 한 통이 가장 무거운 상자는 어느 것인가요?","options":[{"t":"바 상자","correct":true},{"t":"라 상자","mis":"M6-1-u3-X12"},{"t":"마 상자","mis":"M6-1-u3-X14"},{"t":"모두 같아요","mis":"M6-1-u3-X12"}],"explanation":["먼저 어림해요 — 24 ÷ 6 = 4, 15 ÷ 5 = 3, 24 ÷ 4 = 6이에요.","계산으로 확인하면 라 4.2 kg, 마 2.9 kg, 바 5.6 kg이에요.","수박 한 통이 가장 무거운 것은 바 상자예요."]},{"stem":"사 상자 3통 16.2 kg · 마 상자 5통 14.5 kg · 다 상자 5통 20.2 kg — 수박 한 통이 가장 무거운 상자는 어느 것인가요?","options":[{"t":"사 상자","correct":true},{"t":"마 상자","mis":"M6-1-u3-X14"},{"t":"다 상자","mis":"M6-1-u3-X12"},{"t":"모두 같아요","mis":"M6-1-u3-X12"}],"explanation":["먼저 어림해요 — 15 ÷ 3 = 5, 15 ÷ 5 = 3, 20 ÷ 5 = 4예요.","계산으로 확인하면 사 5.4 kg, 마 2.9 kg, 다 4.04 kg이에요.","수박 한 통이 가장 무거운 것은 사 상자예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_a#21','math',6,1,'u3','','g6_1_math_u3_review_a','unit_review','M6-1-u3-C1',3,'error','auto','585 ÷ 5 = 117을 이용해 58.5 ÷ 5를 계산하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X14']::text[],true,'{"seq":21,"concept":"M6-1-u3-C1","difficulty":3,"kind":"error","stem":"585 ÷ 5 = 117을 이용해 58.5 ÷ 5를 계산하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「나누어지는 수가 작아졌으니 몫은 117의 10배야.」","correct":true,"mis_target":"M6-1-u3-X01"},{"t":"이현 — 「58.5는 585의 ⟨1/10⟩배야.」","mis":"M6-1-u3-X14"},{"t":"서아 — 「몫은 11.7이야.」","mis":"M6-1-u3-X14"}],"explanation":["나누는 수 5는 그대로예요.","나누어지는 수가 ⟨1/10⟩배가 되면 몫도 ⟨1/10⟩배예요.","준희는 몫이 커진다고 거꾸로 말했어요."],"variant_rule":{"alt":[{"stem":"49.2 ÷ 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「몫은 123이야.」","correct":true,"mis_target":"M6-1-u3-X01"},{"t":"수아 — 「492 ÷ 4를 계산한 몫의 ⟨1/10⟩배야.」","mis":"M6-1-u3-X14"},{"t":"도윤 — 「몫의 소수점은 49.2의 소수점 위에 찍어.」","mis":"M6-1-u3-X14"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 492 ÷ 4 = 123이에요.","49.2는 492의 ⟨1/10⟩배라서 몫도 123의 ⟨1/10⟩배예요.","서호는 몫의 소수점을 한 자리 뒤에 찍었어요 — 바른 몫은 12.3이에요."]},{"stem":"4.6 ÷ 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「소수 첫째 자리까지 나누었으니 몫은 1.1이야.」","correct":true,"mis_target":"M6-1-u3-X06"},{"t":"나린 — 「4.6은 4.60과 같은 수야.」","mis":"M6-1-u3-X14"},{"t":"유진 — 「0을 내려 계산하면 몫은 1.15야.」","mis":"M6-1-u3-X14"}],"explanation":["소수 첫째 자리까지 나누면 나머지가 남아요.","0을 내려 계산을 이어 가야 해요.","가온은 계산을 멈추었어요 — 바른 몫은 1.15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_a#22','math',6,1,'u3','','g6_1_math_u3_review_a','unit_review','M6-1-u3-C5',3,'sa','auto','6.0□가 48.4 ÷ 8의 몫보다 커요. □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M6-1-u3-C5","difficulty":3,"kind":"sa","stem":"6.0□가 48.4 ÷ 8의 몫보다 커요. □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 4840 ÷ 8 = 605예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 48.4 ÷ 8 = 6.05예요.","6.0□ > 6.05 — □는 6부터 9까지, 4개예요."],"mis":"M6-1-u3-X07","variant_rule":{"alt":[{"stem":"4.0□가 24.3 ÷ 6의 몫보다 커요. □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 2430 ÷ 6 = 405예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 24.3 ÷ 6 = 4.05예요.","4.0□ > 4.05 — □는 6부터 9까지, 4개예요."]},{"stem":"3.0□가 15.3 ÷ 5의 몫보다 작아요. □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1530 ÷ 5 = 306이에요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 15.3 ÷ 5 = 3.06이에요.","3.0□ < 3.06 — □는 1부터 5까지, 5개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_a#23','math',6,1,'u3','','g6_1_math_u3_review_a','unit_review','M6-1-u3-C7',4,'mc','auto','가 상자는 수박 3통이 18.3 kg, 라 상자는 수박 6통이 25.2 kg이에요. 라 상자의 수박 한 통은 가 상자의 수박 한 통보다 몇 kg 가벼운가요?',ARRAY['M6-1-u3-X14','M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":23,"concept":"M6-1-u3-C7","difficulty":4,"kind":"mc","stem":"가 상자는 수박 3통이 18.3 kg, 라 상자는 수박 6통이 25.2 kg이에요. 라 상자의 수박 한 통은 가 상자의 수박 한 통보다 몇 kg 가벼운가요?","options":[{"t":"1.9 kg","correct":true},{"t":"10.3 kg","mis":"M6-1-u3-X14"},{"t":"19 kg","mis":"M6-1-u3-X01"},{"t":"0.19 kg","mis":"M6-1-u3-X02"}],"explanation":["가 상자 한 통은 18.3 ÷ 3 = 6.1 (kg)이에요.","라 상자 한 통은 25.2 ÷ 6 = 4.2 (kg)이에요.","6.1 − 4.2 = 1.9 (kg) 가벼워요."],"variant_rule":{"alt":[{"stem":"가 상자는 수박 3통이 18.3 kg, 나 상자는 수박 4통이 19.8 kg이에요. 나 상자의 수박 한 통은 가 상자의 수박 한 통보다 몇 kg 가벼운가요?","options":[{"t":"1.15 kg","correct":true},{"t":"11.05 kg","mis":"M6-1-u3-X14"},{"t":"11.5 kg","mis":"M6-1-u3-X01"},{"t":"0.115 kg","mis":"M6-1-u3-X02"}],"explanation":["가 상자 한 통은 18.3 ÷ 3 = 6.1 (kg)이에요.","나 상자 한 통은 19.8 ÷ 4 = 4.95 (kg)이에요.","6.1 − 4.95 = 1.15 (kg) 가벼워요."]},{"stem":"사 상자는 수박 3통이 16.2 kg, 다 상자는 수박 5통이 20.2 kg이에요. 다 상자의 수박 한 통은 사 상자의 수박 한 통보다 몇 kg 가벼운가요?","options":[{"t":"1.36 kg","correct":true},{"t":"9.44 kg","mis":"M6-1-u3-X14"},{"t":"13.6 kg","mis":"M6-1-u3-X01"},{"t":"0.136 kg","mis":"M6-1-u3-X02"}],"explanation":["사 상자 한 통은 16.2 ÷ 3 = 5.4 (kg)이에요.","다 상자 한 통은 20.2 ÷ 5 = 4.04 (kg)이에요.","5.4 − 4.04 = 1.36 (kg) 가벼워요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_a#24','math',6,1,'u3','','g6_1_math_u3_review_a','unit_review','M6-1-u3-C1',4,'essay','teacher','585 ÷ 5 = 117이에요. 이것을 이용하여 58.5 ÷ 5와 5.85 ÷ 5의 몫을 구하고, 그렇게 구할 수 있는 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u3-C1","difficulty":4,"kind":"essay","stem":"585 ÷ 5 = 117이에요. 이것을 이용하여 58.5 ÷ 5와 5.85 ÷ 5의 몫을 구하고, 그렇게 구할 수 있는 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 나누는 수 5는 그대로이고 58.5는 585의 10분의 1배, 5.85는 585의 100분의 1배이다. 나누어지는 수가 10분의 1배, 100분의 1배가 되면 몫도 10분의 1배, 100분의 1배가 되므로 58.5 ÷ 5 = 11.7, 5.85 ÷ 5 = 1.17이다.","scoring_points":["11.7과 1.17을 구했는가","나누어지는 수가 ⟨1/10⟩배·⟨1/100⟩배임을 밝혔는가","몫도 같은 배율로 작아진다는 까닭을 썼는가"]},"explanation":["58.5는 585의 ⟨1/10⟩배예요.","58.5 ÷ 5 = 11.7이에요.","5.85 ÷ 5 = 1.17이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_a#25','math',6,1,'u3','','g6_1_math_u3_review_a','unit_review','M6-1-u3-C6',4,'essay','teacher','「(자연수)÷(자연수)의 몫은 나머지가 있으면 소수로 나타낼 수 없다.」 이 말이 맞는지 쓰고, 9 ÷ 6을 예로 들어 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u3-C6","difficulty":4,"kind":"essay","stem":"「(자연수)÷(자연수)의 몫은 나머지가 있으면 소수로 나타낼 수 없다.」 이 말이 맞는지 쓰고, 9 ÷ 6을 예로 들어 설명해 보세요.","answer_guide":{"answer":"예: 맞지 않다. 자연수의 소수점은 자연수 바로 뒤에 있어 9 = 9.0으로 볼 수 있다. 9 ÷ 6 = 1 … 3에서 남은 3에 0을 내리면 30 ÷ 6 = 5이므로 9 ÷ 6 = 1.5로 나타낼 수 있다.","scoring_points":["맞지 않다고 답했는가","9를 9.0으로 보고 0을 내렸는가","1.5를 구했는가"]},"explanation":["9 = 9.0으로 볼 수 있어요.","0을 내려 30 ÷ 6 = 5예요.","9 ÷ 6 = 1.5예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_b#1','math',6,1,'u3','','g6_1_math_u3_review_b','unit_review','M6-1-u3-C1',1,'mc','auto','648 ÷ 2 = 324예요. 그러면 64.8 ÷ 2의 몫은 얼마인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":1,"concept":"M6-1-u3-C1","difficulty":1,"kind":"mc","stem":"648 ÷ 2 = 324예요. 그러면 64.8 ÷ 2의 몫은 얼마인가요?","options":[{"t":"32.4","correct":true},{"t":"324","mis":"M6-1-u3-X01"},{"t":"3.24","mis":"M6-1-u3-X02"},{"t":"3240","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 2는 그대로예요.","나누어지는 수 64.8은 648의 ⟨1/10⟩배예요.","그래서 몫도 324의 ⟨1/10⟩배 — 32.4예요."],"variant_rule":{"alt":[{"stem":"393 ÷ 3 = 131이에요. 그러면 3.93 ÷ 3의 몫은 얼마인가요?","options":[{"t":"1.31","correct":true},{"t":"13.1","mis":"M6-1-u3-X01"},{"t":"0.131","mis":"M6-1-u3-X02"},{"t":"131","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 3은 그대로예요.","나누어지는 수 3.93은 393의 ⟨1/100⟩배예요.","그래서 몫도 131의 ⟨1/100⟩배 — 1.31이에요."]},{"stem":"846 ÷ 2 = 423이에요. 그러면 84.6 ÷ 2의 몫은 얼마인가요?","options":[{"t":"42.3","correct":true},{"t":"423","mis":"M6-1-u3-X01"},{"t":"4.23","mis":"M6-1-u3-X02"},{"t":"4230","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 2는 그대로예요.","나누어지는 수 84.6은 846의 ⟨1/10⟩배예요.","그래서 몫도 423의 ⟨1/10⟩배 — 42.3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_b#2','math',6,1,'u3','','g6_1_math_u3_review_b','unit_review','M6-1-u3-C1',1,'sa','auto','4.7은 0.1이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u3-C1","difficulty":1,"kind":"sa","stem":"4.7은 0.1이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["47"],"explanation":["0.1이 10개이면 1이에요.","4.7은 4와 소수 부분을 합해 0.1이 47개예요.","그래서 4.7은 0.1이 47개인 수예요."],"mis":"M6-1-u3-X03","variant_rule":{"alt":[{"stem":"7.2는 0.1이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["72"],"explanation":["0.1이 10개이면 1이에요.","7.2는 7과 소수 부분을 합해 0.1이 72개예요.","그래서 7.2는 0.1이 72개인 수예요."]},{"stem":"8.6은 0.1이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["86"],"explanation":["0.1이 10개이면 1이에요.","8.6은 8과 소수 부분을 합해 0.1이 86개예요.","그래서 8.6은 0.1이 86개인 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_b#3','math',6,1,'u3','','g6_1_math_u3_review_b','unit_review','M6-1-u3-C2',1,'mc','auto','11.7 ÷ 3의 몫은 얼마인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":3,"concept":"M6-1-u3-C2","difficulty":1,"kind":"mc","stem":"11.7 ÷ 3의 몫은 얼마인가요?","options":[{"t":"3.9","correct":true},{"t":"39","mis":"M6-1-u3-X01"},{"t":"0.39","mis":"M6-1-u3-X02"},{"t":"390","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 117 ÷ 3 = 39예요.","11.7은 117의 ⟨1/10⟩배라서 몫도 39의 ⟨1/10⟩배예요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 11.7 ÷ 3 = 3.9예요."],"variant_rule":{"alt":[{"stem":"34.5 ÷ 5의 몫은 얼마인가요?","options":[{"t":"6.9","correct":true},{"t":"69","mis":"M6-1-u3-X01"},{"t":"0.69","mis":"M6-1-u3-X02"},{"t":"690","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 345 ÷ 5 = 69예요.","34.5는 345의 ⟨1/10⟩배라서 몫도 69의 ⟨1/10⟩배예요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 34.5 ÷ 5 = 6.9예요."]},{"stem":"49.2 ÷ 4의 몫은 얼마인가요?","options":[{"t":"12.3","correct":true},{"t":"123","mis":"M6-1-u3-X01"},{"t":"1.23","mis":"M6-1-u3-X02"},{"t":"1230","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 492 ÷ 4 = 123이에요.","49.2는 492의 ⟨1/10⟩배라서 몫도 123의 ⟨1/10⟩배예요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 49.2 ÷ 4 = 12.3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_b#4','math',6,1,'u3','','g6_1_math_u3_review_b','unit_review','M6-1-u3-C3',1,'mc','auto','3.2 ÷ 4의 몫은 얼마인가요?',ARRAY['M6-1-u3-X05','M6-1-u3-X02','M6-1-u3-X01']::text[],true,'{"seq":4,"concept":"M6-1-u3-C3","difficulty":1,"kind":"mc","stem":"3.2 ÷ 4의 몫은 얼마인가요?","options":[{"t":"0.8","correct":true},{"t":"8","mis":"M6-1-u3-X05"},{"t":"0.08","mis":"M6-1-u3-X02"},{"t":"80","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 32 ÷ 4 = 8이에요.","3.2는 32의 ⟨1/10⟩배라서 몫도 8의 ⟨1/10⟩배예요.","몫이 1보다 작으니 일의 자리에 0을 써서 자리를 지켜요 — 3.2 ÷ 4 = 0.8이에요."],"variant_rule":{"alt":[{"stem":"5.72 ÷ 11의 몫은 얼마인가요?","options":[{"t":"0.52","correct":true},{"t":"5.2","mis":"M6-1-u3-X05"},{"t":"0.052","mis":"M6-1-u3-X02"},{"t":"52","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 572 ÷ 11 = 52예요.","5.72는 572의 ⟨1/100⟩배라서 몫도 52의 ⟨1/100⟩배예요.","몫이 1보다 작으니 일의 자리에 0을 써서 자리를 지켜요 — 5.72 ÷ 11 = 0.52예요."]},{"stem":"2.38 ÷ 7의 몫은 얼마인가요?","options":[{"t":"0.34","correct":true},{"t":"3.4","mis":"M6-1-u3-X05"},{"t":"0.034","mis":"M6-1-u3-X02"},{"t":"34","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 238 ÷ 7 = 34예요.","2.38은 238의 ⟨1/100⟩배라서 몫도 34의 ⟨1/100⟩배예요.","몫이 1보다 작으니 일의 자리에 0을 써서 자리를 지켜요 — 2.38 ÷ 7 = 0.34예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_b#5','math',6,1,'u3','','g6_1_math_u3_review_b','unit_review','M6-1-u3-C3',1,'mc','auto','4.15 ÷ 5의 몫은 1보다 클까요, 작을까요?',ARRAY['M6-1-u3-X12']::text[],true,'{"seq":5,"concept":"M6-1-u3-C3","difficulty":1,"kind":"mc","stem":"4.15 ÷ 5의 몫은 1보다 클까요, 작을까요?","options":[{"t":"1보다 작아요","correct":true},{"t":"1보다 커요","mis":"M6-1-u3-X12"},{"t":"1과 같아요","mis":"M6-1-u3-X12"},{"t":"계산해 보기 전에는 알 수 없어요","mis":"M6-1-u3-X12"}],"explanation":["나누어지는 수 4.15가 나누는 수 5보다 작아요.","5 ÷ 5 = 1이니 4.15 ÷ 5는 1보다 작아요.","실제로 몫은 0.83이에요."],"variant_rule":{"alt":[{"stem":"2.38 ÷ 7의 몫은 1보다 클까요, 작을까요?","options":[{"t":"1보다 작아요","correct":true},{"t":"1보다 커요","mis":"M6-1-u3-X12"},{"t":"1과 같아요","mis":"M6-1-u3-X12"},{"t":"계산해 보기 전에는 알 수 없어요","mis":"M6-1-u3-X12"}],"explanation":["나누어지는 수 2.38이 나누는 수 7보다 작아요.","7 ÷ 7 = 1이니 2.38 ÷ 7은 1보다 작아요.","실제로 몫은 0.34예요."]},{"stem":"5.6 ÷ 8의 몫은 1보다 클까요, 작을까요?","options":[{"t":"1보다 작아요","correct":true},{"t":"1보다 커요","mis":"M6-1-u3-X12"},{"t":"1과 같아요","mis":"M6-1-u3-X12"},{"t":"계산해 보기 전에는 알 수 없어요","mis":"M6-1-u3-X12"}],"explanation":["나누어지는 수 5.6이 나누는 수 8보다 작아요.","8 ÷ 8 = 1이니 5.6 ÷ 8은 1보다 작아요.","실제로 몫은 0.7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_b#6','math',6,1,'u3','','g6_1_math_u3_review_b','unit_review','M6-1-u3-C4',1,'mc','auto','6.7 ÷ 5를 계산하다가 소수 첫째 자리까지 나누었더니 2가 남았어요. 다음에 할 일로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u3-X06','M6-1-u3-X13']::text[],true,'{"seq":6,"concept":"M6-1-u3-C4","difficulty":1,"kind":"mc","stem":"6.7 ÷ 5를 계산하다가 소수 첫째 자리까지 나누었더니 2가 남았어요. 다음에 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"소수점 아래에 0을 하나 내려 계산을 이어 가요","correct":true},{"t":"남은 2를 몫 뒤에 붙여 써요","mis":"M6-1-u3-X06"},{"t":"나누어떨어지지 않는다고 답해요","mis":"M6-1-u3-X06"},{"t":"나누는 수를 바꾸어 다시 나누어요","mis":"M6-1-u3-X13"}],"explanation":["6.7은 6.70과 같은 수예요.","소수점 아래 끝자리에 0을 붙여도 수의 크기는 그대로예요.","그래서 0을 내려 이어 계산하면 6.7 ÷ 5 = 1.34예요."],"variant_rule":{"alt":[{"stem":"18.8 ÷ 8을 계산하다가 소수 첫째 자리까지 나누었더니 4가 남았어요. 다음에 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"소수점 아래에 0을 하나 내려 계산을 이어 가요","correct":true},{"t":"남은 4를 몫 뒤에 붙여 써요","mis":"M6-1-u3-X06"},{"t":"나누어떨어지지 않는다고 답해요","mis":"M6-1-u3-X06"},{"t":"나누는 수를 바꾸어 다시 나누어요","mis":"M6-1-u3-X13"}],"explanation":["18.8은 18.80과 같은 수예요.","소수점 아래 끝자리에 0을 붙여도 수의 크기는 그대로예요.","그래서 0을 내려 이어 계산하면 18.8 ÷ 8 = 2.35예요."]},{"stem":"8.3 ÷ 2를 계산하다가 소수 첫째 자리까지 나누었더니 1이 남았어요. 다음에 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"소수점 아래에 0을 하나 내려 계산을 이어 가요","correct":true},{"t":"남은 1을 몫 뒤에 붙여 써요","mis":"M6-1-u3-X06"},{"t":"나누어떨어지지 않는다고 답해요","mis":"M6-1-u3-X06"},{"t":"나누는 수를 바꾸어 다시 나누어요","mis":"M6-1-u3-X13"}],"explanation":["8.3은 8.30과 같은 수예요.","소수점 아래 끝자리에 0을 붙여도 수의 크기는 그대로예요.","그래서 0을 내려 이어 계산하면 8.3 ÷ 2 = 4.15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_b#7','math',6,1,'u3','','g6_1_math_u3_review_b','unit_review','M6-1-u3-C6',1,'mc','auto','6 ÷ 5를 세로셈으로 계산할 때 6을 어떻게 보아야 하나요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":7,"concept":"M6-1-u3-C6","difficulty":1,"kind":"mc","stem":"6 ÷ 5를 세로셈으로 계산할 때 6을 어떻게 보아야 하나요?","options":[{"t":"6.0으로 봐요","correct":true},{"t":"60으로 봐요","mis":"M6-1-u3-X01"},{"t":"0.6으로 봐요","mis":"M6-1-u3-X02"},{"t":"⟨6/10⟩으로 봐요","mis":"M6-1-u3-X02"}],"explanation":["자연수의 소수점은 자연수 바로 뒤에 있어요.","6 = 6.0 = 6.00이에요.","그래서 6을 6.0으로 보고 0을 내려 계산해요."],"variant_rule":{"alt":[{"stem":"9 ÷ 6을 세로셈으로 계산할 때 9를 어떻게 보아야 하나요?","options":[{"t":"9.0으로 봐요","correct":true},{"t":"90으로 봐요","mis":"M6-1-u3-X01"},{"t":"0.9로 봐요","mis":"M6-1-u3-X02"},{"t":"⟨9/10⟩로 봐요","mis":"M6-1-u3-X02"}],"explanation":["자연수의 소수점은 자연수 바로 뒤에 있어요.","9 = 9.0 = 9.00이에요.","그래서 9를 9.0으로 보고 0을 내려 계산해요."]},{"stem":"7 ÷ 4를 세로셈으로 계산할 때 7을 어떻게 보아야 하나요?","options":[{"t":"7.0으로 봐요","correct":true},{"t":"70으로 봐요","mis":"M6-1-u3-X01"},{"t":"0.7로 봐요","mis":"M6-1-u3-X02"},{"t":"⟨7/10⟩로 봐요","mis":"M6-1-u3-X02"}],"explanation":["자연수의 소수점은 자연수 바로 뒤에 있어요.","7 = 7.0 = 7.00이에요.","그래서 7을 7.0으로 보고 0을 내려 계산해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_b#8','math',6,1,'u3','','g6_1_math_u3_review_b','unit_review','M6-1-u3-C7',1,'sa','auto','나 상자에는 무게가 같은 수박 4통이 19.8 kg 들어 있어요. 19.8을 20으로 어림하면 수박 한 통은 약 몇 kg인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u3-C7","difficulty":1,"kind":"sa","stem":"나 상자에는 무게가 같은 수박 4통이 19.8 kg 들어 있어요. 19.8을 20으로 어림하면 수박 한 통은 약 몇 kg인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["19.8에 가까우면서 4로 나누기 쉬운 수는 20이에요.","20 ÷ 4 = 5예요.","수박 한 통은 약 5 kg이에요."],"mis":"M6-1-u3-X12","variant_rule":{"alt":[{"stem":"다 상자에는 무게가 같은 수박 5통이 20.2 kg 들어 있어요. 20.2를 20으로 어림하면 수박 한 통은 약 몇 kg인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["20.2에 가까우면서 5로 나누기 쉬운 수는 20이에요.","20 ÷ 5 = 4예요.","수박 한 통은 약 4 kg이에요."]},{"stem":"라 상자에는 무게가 같은 수박 6통이 25.2 kg 들어 있어요. 25.2를 24로 어림하면 수박 한 통은 약 몇 kg인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["25.2에 가까우면서 6으로 나누기 쉬운 수는 24예요.","24 ÷ 6 = 4예요.","수박 한 통은 약 4 kg이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_b#9','math',6,1,'u3','','g6_1_math_u3_review_b','unit_review','M6-1-u3-C2',2,'sa','auto','9.27 ÷ 9의 몫에서 소수 둘째 자리 숫자는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u3-C2","difficulty":2,"kind":"sa","stem":"9.27 ÷ 9의 몫에서 소수 둘째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 927 ÷ 9 = 103이에요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 9.27 ÷ 9 = 1.03이에요.","1.03의 소수 둘째 자리 숫자는 3이에요."],"mis":"M6-1-u3-X13","variant_rule":{"alt":[{"stem":"13.79 ÷ 7의 몫에서 소수 둘째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1379 ÷ 7 = 197이에요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 13.79 ÷ 7 = 1.97이에요.","1.97의 소수 둘째 자리 숫자는 7이에요."]},{"stem":"22.68 ÷ 4의 몫에서 소수 둘째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 2268 ÷ 4 = 567이에요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 22.68 ÷ 4 = 5.67이에요.","5.67의 소수 둘째 자리 숫자는 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_b#10','math',6,1,'u3','','g6_1_math_u3_review_b','unit_review','M6-1-u3-C4',2,'mc','auto','4.6 ÷ 4의 몫은 얼마인가요?',ARRAY['M6-1-u3-X06','M6-1-u3-X01']::text[],true,'{"seq":10,"concept":"M6-1-u3-C4","difficulty":2,"kind":"mc","stem":"4.6 ÷ 4의 몫은 얼마인가요?","options":[{"t":"1.15","correct":true},{"t":"1.1","mis":"M6-1-u3-X06"},{"t":"1.12","mis":"M6-1-u3-X06"},{"t":"11.5","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 460 ÷ 4 = 115예요.","4.6은 460의 ⟨1/100⟩배라서 몫도 115의 ⟨1/100⟩배예요.","나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 4.6 ÷ 4 = 1.15예요."],"variant_rule":{"alt":[{"stem":"6.7 ÷ 5의 몫은 얼마인가요?","options":[{"t":"1.34","correct":true},{"t":"1.3","mis":"M6-1-u3-X06"},{"t":"1.32","mis":"M6-1-u3-X06"},{"t":"13.4","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 670 ÷ 5 = 134예요.","6.7은 670의 ⟨1/100⟩배라서 몫도 134의 ⟨1/100⟩배예요.","나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 6.7 ÷ 5 = 1.34예요."]},{"stem":"5.4 ÷ 8의 몫은 얼마인가요?","options":[{"t":"0.675","correct":true},{"t":"0.6","mis":"M6-1-u3-X06"},{"t":"0.66","mis":"M6-1-u3-X06"},{"t":"6.75","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 5400 ÷ 8 = 675예요.","5.4는 5400의 ⟨1/1000⟩배라서 몫도 675의 ⟨1/1000⟩배예요.","나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 5.4 ÷ 8 = 0.675예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_b#11','math',6,1,'u3','','g6_1_math_u3_review_b','unit_review','M6-1-u3-C5',2,'mc','auto','9.27 ÷ 9의 몫은 얼마인가요?',ARRAY['M6-1-u3-X07','M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":11,"concept":"M6-1-u3-C5","difficulty":2,"kind":"mc","stem":"9.27 ÷ 9의 몫은 얼마인가요?","options":[{"t":"1.03","correct":true},{"t":"1.3","mis":"M6-1-u3-X07"},{"t":"10.3","mis":"M6-1-u3-X01"},{"t":"0.103","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 927 ÷ 9 = 103이에요.","9.27은 927의 ⟨1/100⟩배라서 몫도 103의 ⟨1/100⟩배예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 9.27 ÷ 9 = 1.03이에요."],"variant_rule":{"alt":[{"stem":"20.2 ÷ 5의 몫은 얼마인가요?","options":[{"t":"4.04","correct":true},{"t":"4.4","mis":"M6-1-u3-X07"},{"t":"40.4","mis":"M6-1-u3-X01"},{"t":"0.404","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 2020 ÷ 5 = 404예요.","20.2는 2020의 ⟨1/100⟩배라서 몫도 404의 ⟨1/100⟩배예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 20.2 ÷ 5 = 4.04예요."]},{"stem":"16.4 ÷ 8의 몫은 얼마인가요?","options":[{"t":"2.05","correct":true},{"t":"2.5","mis":"M6-1-u3-X07"},{"t":"20.5","mis":"M6-1-u3-X01"},{"t":"0.205","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1640 ÷ 8 = 205예요.","16.4는 1640의 ⟨1/100⟩배라서 몫도 205의 ⟨1/100⟩배예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 16.4 ÷ 8 = 2.05예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_b#12','math',6,1,'u3','','g6_1_math_u3_review_b','unit_review','M6-1-u3-C6',2,'mc','auto','6 ÷ 5의 몫은 얼마인가요?',ARRAY['M6-1-u3-X08','M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":12,"concept":"M6-1-u3-C6","difficulty":2,"kind":"mc","stem":"6 ÷ 5의 몫은 얼마인가요?","options":[{"t":"1.2","correct":true},{"t":"1.1","mis":"M6-1-u3-X08"},{"t":"12","mis":"M6-1-u3-X01"},{"t":"0.12","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 60 ÷ 5 = 12예요.","6은 60의 ⟨1/10⟩배라서 몫도 12의 ⟨1/10⟩배예요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 6 ÷ 5 = 1.2예요."],"variant_rule":{"alt":[{"stem":"3 ÷ 4의 몫은 얼마인가요?","options":[{"t":"0.75","correct":true},{"t":"0.3","mis":"M6-1-u3-X08"},{"t":"7.5","mis":"M6-1-u3-X01"},{"t":"0.075","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 300 ÷ 4 = 75예요.","3은 300의 ⟨1/100⟩배라서 몫도 75의 ⟨1/100⟩배예요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 3 ÷ 4 = 0.75예요."]},{"stem":"9 ÷ 6의 몫은 얼마인가요?","options":[{"t":"1.5","correct":true},{"t":"1.3","mis":"M6-1-u3-X08"},{"t":"15","mis":"M6-1-u3-X01"},{"t":"0.15","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 90 ÷ 6 = 15예요.","9는 90의 ⟨1/10⟩배라서 몫도 15의 ⟨1/10⟩배예요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 9 ÷ 6 = 1.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_b#13','math',6,1,'u3','','g6_1_math_u3_review_b','unit_review','M6-1-u3-C3',2,'ox','auto','5.6 ÷ 7의 몫은 8이에요.',ARRAY['M6-1-u3-X05']::text[],true,'{"seq":13,"concept":"M6-1-u3-C3","difficulty":2,"kind":"ox","stem":"5.6 ÷ 7의 몫은 8이에요.","answer":"X","reason_options":[{"t":"몫이 1보다 작아 일의 자리에 0을 써서 0.8이기 때문에","correct":true},{"t":"56 ÷ 7 = 8이니 몫도 8이기 때문에","mis":"M6-1-u3-X05"}],"mis":"M6-1-u3-X05","explanation":["나누어지는 수가 나누는 수보다 작으면 몫은 1보다 작아요.","이때 몫의 일의 자리에 0을 써요.","0은 자리를 지키는 숫자예요."],"variant_rule":{"alt":[{"stem":"4.6 ÷ 4를 소수 첫째 자리까지 나누고 2가 남으면 몫은 1.1이에요.","answer":"X","reason_options":[{"t":"0을 내려 계산을 이어 가면 몫은 1.15이기 때문에","correct":true},{"t":"나누어지는 수의 자리가 끝나면 계산도 끝나기 때문에","mis":"M6-1-u3-X06"}],"explanation":["4.6 = 4.60 = 4.600 — 소수점 아래 끝자리에 0을 붙여도 수의 크기는 같아요.","그래서 나머지가 남으면 0을 내려 계산을 이어 가요.","남은 수를 몫 뒤에 붙이면 안 돼요."]},{"stem":"6 ÷ 5의 몫은 1.1이에요.","answer":"X","reason_options":[{"t":"나머지 1에 0을 내려 10 ÷ 5 = 2를 이어 계산하면 1.2이기 때문에","correct":true},{"t":"6 ÷ 5 = 1 … 1이라 나머지를 소수로 쓰기 때문에","mis":"M6-1-u3-X08"}],"explanation":["자연수의 소수점은 자연수 바로 뒤에 있어요 — 6 = 6.0이에요.","나머지가 남으면 0을 내려 계산을 이어 가요.","몫을 분수로 쓴 뒤 분모를 10·100으로 고쳐 소수로 나타낼 수도 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_b#14','math',6,1,'u3','','g6_1_math_u3_review_b','unit_review','M6-1-u3-C3',2,'mc','auto','다음 가운데 몫이 1보다 작은 나눗셈은 어느 것인가요?',ARRAY['M6-1-u3-X12']::text[],true,'{"seq":14,"concept":"M6-1-u3-C3","difficulty":2,"kind":"mc","stem":"다음 가운데 몫이 1보다 작은 나눗셈은 어느 것인가요?","options":[{"t":"6.3 ÷ 7","correct":true},{"t":"9.6 ÷ 8","mis":"M6-1-u3-X12"},{"t":"5.5 ÷ 5","mis":"M6-1-u3-X12"},{"t":"12.6 ÷ 6","mis":"M6-1-u3-X12"}],"explanation":["몫이 1보다 작으려면 나누어지는 수가 나누는 수보다 작아야 해요.","나누어지는 수와 나누는 수를 하나씩 견주어 봐요.","6.3 ÷ 7만 나누어지는 수가 더 작아요 — 몫은 0.9예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 가운데 몫이 1보다 작은 나눗셈은 어느 것인가요?","options":[{"t":"2.7 ÷ 3","correct":true},{"t":"7.2 ÷ 6","mis":"M6-1-u3-X12"},{"t":"4.4 ÷ 4","mis":"M6-1-u3-X12"},{"t":"8.1 ÷ 3","mis":"M6-1-u3-X12"}],"explanation":["몫이 1보다 작으려면 나누어지는 수가 나누는 수보다 작아야 해요.","나누어지는 수와 나누는 수를 하나씩 견주어 봐요.","2.7 ÷ 3만 나누어지는 수가 더 작아요 — 몫은 0.9예요."]},{"stem":"이번에는 다른 보기예요. 다음 가운데 몫이 1보다 작은 나눗셈은 어느 것인가요?","options":[{"t":"4.15 ÷ 5","correct":true},{"t":"9.9 ÷ 9","mis":"M6-1-u3-X12"},{"t":"6.6 ÷ 6","mis":"M6-1-u3-X12"},{"t":"8.8 ÷ 4","mis":"M6-1-u3-X12"}],"explanation":["몫이 1보다 작으려면 나누어지는 수가 나누는 수보다 작아야 해요.","나누어지는 수와 나누는 수를 하나씩 견주어 봐요.","4.15 ÷ 5만 나누어지는 수가 더 작아요 — 몫은 0.83이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_b#15','math',6,1,'u3','','g6_1_math_u3_review_b','unit_review','M6-1-u3-C1',2,'mc','auto','쌀 84.88 kg을 자루 4개에 똑같이 나누어 담았어요. 자루 한 개에 담긴 쌀은 몇 kg인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02','M6-1-u3-X10']::text[],true,'{"seq":15,"concept":"M6-1-u3-C1","difficulty":2,"kind":"mc","stem":"쌀 84.88 kg을 자루 4개에 똑같이 나누어 담았어요. 자루 한 개에 담긴 쌀은 몇 kg인가요?","options":[{"t":"21.22 kg","correct":true},{"t":"212.2 kg","mis":"M6-1-u3-X01"},{"t":"2.122 kg","mis":"M6-1-u3-X02"},{"t":"339.52 kg","mis":"M6-1-u3-X10"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 8488 ÷ 4 = 2122예요.","84.88은 8488의 ⟨1/100⟩배라서 몫도 2122의 ⟨1/100⟩배예요.","84.88 ÷ 4 = 21.22예요."],"variant_rule":{"alt":[{"stem":"길이가 3.6 m인 끈을 똑같이 잘라 기념품 상자 3개를 묶어요. 상자 한 개에 쓰는 끈은 몇 m인가요?","options":[{"t":"1.2 m","correct":true},{"t":"12 m","mis":"M6-1-u3-X01"},{"t":"0.12 m","mis":"M6-1-u3-X02"},{"t":"10.8 m","mis":"M6-1-u3-X10"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 36 ÷ 3 = 12예요.","3.6은 36의 ⟨1/10⟩배라서 몫도 12의 ⟨1/10⟩배예요.","3.6 ÷ 3 = 1.2예요."]},{"stem":"리본 9.6 m를 세 명이 똑같이 나누어 가져요. 한 명이 가지는 리본은 몇 m인가요?","options":[{"t":"3.2 m","correct":true},{"t":"32 m","mis":"M6-1-u3-X01"},{"t":"0.32 m","mis":"M6-1-u3-X02"},{"t":"28.8 m","mis":"M6-1-u3-X10"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 96 ÷ 3 = 32예요.","9.6은 96의 ⟨1/10⟩배라서 몫도 32의 ⟨1/10⟩배예요.","9.6 ÷ 3 = 3.2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_b#16','math',6,1,'u3','','g6_1_math_u3_review_b','unit_review','M6-1-u3-C2',2,'sa','auto','넓이가 25.2 cm²이고 밑변이 4 cm인 평행사변형이 있어요. 이 평행사변형의 높이는 몇 mm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M6-1-u3-C2","difficulty":2,"kind":"sa","stem":"넓이가 25.2 cm²이고 밑변이 4 cm인 평행사변형이 있어요. 이 평행사변형의 높이는 몇 mm인가요? 숫자로 쓰세요.","answer":["63"],"explanation":["평행사변형의 넓이 = 밑변 × 높이이니 높이 = 넓이 ÷ 밑변이에.","25.2 ÷ 4 = 6.3 (cm)예요.","1 cm는 10 mm라서 6.3 cm는 63 mm예요."],"mis":"M6-1-u3-X11","variant_rule":{"alt":[{"stem":"넓이가 34.5 cm²이고 밑변이 5 cm인 평행사변형이 있어요. 이 평행사변형의 높이는 몇 mm인가요? 숫자로 쓰세요.","answer":["69"],"explanation":["평행사변형의 넓이 = 밑변 × 높이이니 높이 = 넓이 ÷ 밑변이에.","34.5 ÷ 5 = 6.9 (cm)예요.","1 cm는 10 mm라서 6.9 cm는 69 mm예요."]},{"stem":"넓이가 38.4 cm²이고 가로가 6 cm인 직사각형이 있어요. 이 직사각형의 세로는 몇 mm인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["직사각형의 넓이 = 가로 × 세로이니 세로 = 넓이 ÷ 가로요예요.","38.4 ÷ 6 = 6.4 (cm)예요.","1 cm는 10 mm라서 6.4 cm는 64 mm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_b#17','math',6,1,'u3','','g6_1_math_u3_review_b','unit_review','M6-1-u3-C5',3,'mc','auto','친구가 20.2 ÷ 5의 몫을 4.4라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X06','M6-1-u3-X05']::text[],true,'{"seq":17,"concept":"M6-1-u3-C5","difficulty":3,"kind":"mc","stem":"친구가 20.2 ÷ 5의 몫을 4.4라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"내린 수가 나누는 수보다 작을 때 몫에 0을 쓰지 않아서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"0을 내려 계산하지 않아서","mis":"M6-1-u3-X06"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 2020 ÷ 5 = 404예요.","내린 수가 5보다 작으면 몫에 0을 쓰고 하나 더 내려야 해요.","바른 몫은 4.04이고 4.4는 다른 수예요."],"variant_rule":{"alt":[{"stem":"친구가 9.27 ÷ 9의 몫을 1.3이라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"내린 수가 나누는 수보다 작을 때 몫에 0을 쓰지 않아서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"0을 내려 계산하지 않아서","mis":"M6-1-u3-X06"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 927 ÷ 9 = 103이에요.","내린 수가 9보다 작으면 몫에 0을 쓰고 하나 더 내려야 해요.","바른 몫은 1.03이고 1.3은 다른 수예요."]},{"stem":"친구가 12.3 ÷ 6의 몫을 2.5라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"내린 수가 나누는 수보다 작을 때 몫에 0을 쓰지 않아서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"0을 내려 계산하지 않아서","mis":"M6-1-u3-X06"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1230 ÷ 6 = 205예요.","내린 수가 6보다 작으면 몫에 0을 쓰고 하나 더 내려야 해요.","바른 몫은 2.05이고 2.5는 다른 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_b#18','math',6,1,'u3','','g6_1_math_u3_review_b','unit_review','M6-1-u3-C3',3,'mc','auto','친구가 4.15 ÷ 5의 몫을 83이라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u3-X13','M6-1-u3-X06']::text[],true,'{"seq":18,"concept":"M6-1-u3-C3","difficulty":3,"kind":"mc","stem":"친구가 4.15 ÷ 5의 몫을 83이라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"몫이 1보다 작은데 일의 자리 0과 소수점을 쓰지 않아서","correct":true},{"t":"나누는 수를 잘못 써서","mis":"M6-1-u3-X13"},{"t":"곱셈을 잘못해서","mis":"M6-1-u3-X13"},{"t":"0을 내려 계산하지 않아서","mis":"M6-1-u3-X06"}],"explanation":["4.15는 5보다 작아 몫이 1보다 작아요.","자연수의 나눗셈으로 바꾸어 봐요 — 415 ÷ 5 = 83이에요.","일의 자리에 0을 쓰고 소수점을 찍어 0.83이에요."],"variant_rule":{"alt":[{"stem":"친구가 5.72 ÷ 11의 몫을 52라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"몫이 1보다 작은데 일의 자리 0과 소수점을 쓰지 않아서","correct":true},{"t":"나누는 수를 잘못 써서","mis":"M6-1-u3-X13"},{"t":"곱셈을 잘못해서","mis":"M6-1-u3-X13"},{"t":"0을 내려 계산하지 않아서","mis":"M6-1-u3-X06"}],"explanation":["5.72는 11보다 작아 몫이 1보다 작아요.","자연수의 나눗셈으로 바꾸어 봐요 — 572 ÷ 11 = 52예요.","일의 자리에 0을 쓰고 소수점을 찍어 0.52예요."]},{"stem":"친구가 2.38 ÷ 7의 몫을 34라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"몫이 1보다 작은데 일의 자리 0과 소수점을 쓰지 않아서","correct":true},{"t":"나누는 수를 잘못 써서","mis":"M6-1-u3-X13"},{"t":"곱셈을 잘못해서","mis":"M6-1-u3-X13"},{"t":"0을 내려 계산하지 않아서","mis":"M6-1-u3-X06"}],"explanation":["2.38은 7보다 작아 몫이 1보다 작아요.","자연수의 나눗셈으로 바꾸어 봐요 — 238 ÷ 7 = 34예요.","일의 자리에 0을 쓰고 소수점을 찍어 0.34예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_b#19','math',6,1,'u3','','g6_1_math_u3_review_b','unit_review','M6-1-u3-C6',3,'mc','auto','친구가 9 ÷ 6 = 1 … 3을 보고 몫을 1.3으로 나타냈어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X09','M6-1-u3-X05']::text[],true,'{"seq":19,"concept":"M6-1-u3-C6","difficulty":3,"kind":"mc","stem":"친구가 9 ÷ 6 = 1 … 3을 보고 몫을 1.3으로 나타냈어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나머지 3을 그대로 소수 부분으로 써서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"나누는 수와 나누어지는 수를 바꾸어서","mis":"M6-1-u3-X09"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["나머지 3은 아직 나누지 않은 양이라 몫의 소수 부분이 아니에요.","9를 9.0으로 보고 0을 내려 계산을 이어 가요.","바른 몫은 1.5예요."],"variant_rule":{"alt":[{"stem":"친구가 7 ÷ 4 = 1 … 3을 보고 몫을 1.3으로 나타냈어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나머지 3을 그대로 소수 부분으로 써서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"나누는 수와 나누어지는 수를 바꾸어서","mis":"M6-1-u3-X09"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["나머지 3은 아직 나누지 않은 양이라 몫의 소수 부분이 아니에요.","7을 7.0으로 보고 0을 내려 계산을 이어 가요.","바른 몫은 1.75예요."]},{"stem":"친구가 17 ÷ 4 = 4 … 1을 보고 몫을 4.1로 나타냈어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나머지 1을 그대로 소수 부분으로 써서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"나누는 수와 나누어지는 수를 바꾸어서","mis":"M6-1-u3-X09"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["나머지 1은 아직 나누지 않은 양이라 몫의 소수 부분이 아니에요.","17을 17.0으로 보고 0을 내려 계산을 이어 가요.","바른 몫은 4.25예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_b#20','math',6,1,'u3','','g6_1_math_u3_review_b','unit_review','M6-1-u3-C7',3,'mc','auto','라 상자 6통 25.2 kg · 마 상자 5통 14.5 kg · 바 상자 4통 22.4 kg — 수박 한 통이 가장 무거운 상자는 어느 것인가요?',ARRAY['M6-1-u3-X12','M6-1-u3-X14']::text[],true,'{"seq":20,"concept":"M6-1-u3-C7","difficulty":3,"kind":"mc","stem":"라 상자 6통 25.2 kg · 마 상자 5통 14.5 kg · 바 상자 4통 22.4 kg — 수박 한 통이 가장 무거운 상자는 어느 것인가요?","options":[{"t":"바 상자","correct":true},{"t":"라 상자","mis":"M6-1-u3-X12"},{"t":"마 상자","mis":"M6-1-u3-X14"},{"t":"모두 같아요","mis":"M6-1-u3-X12"}],"explanation":["먼저 어림해요 — 24 ÷ 6 = 4, 15 ÷ 5 = 3, 24 ÷ 4 = 6이에요.","계산으로 확인하면 라 4.2 kg, 마 2.9 kg, 바 5.6 kg이에요.","수박 한 통이 가장 무거운 것은 바 상자예요."],"variant_rule":{"alt":[{"stem":"사 상자 3통 16.2 kg · 마 상자 5통 14.5 kg · 다 상자 5통 20.2 kg — 수박 한 통이 가장 무거운 상자는 어느 것인가요?","options":[{"t":"사 상자","correct":true},{"t":"마 상자","mis":"M6-1-u3-X14"},{"t":"다 상자","mis":"M6-1-u3-X12"},{"t":"모두 같아요","mis":"M6-1-u3-X12"}],"explanation":["먼저 어림해요 — 15 ÷ 3 = 5, 15 ÷ 5 = 3, 20 ÷ 5 = 4예요.","계산으로 확인하면 사 5.4 kg, 마 2.9 kg, 다 4.04 kg이에요.","수박 한 통이 가장 무거운 것은 사 상자예요."]},{"stem":"가 상자 3통 18.3 kg · 라 상자 6통 25.2 kg · 마 상자 5통 14.5 kg — 수박 한 통이 가장 무거운 상자는 어느 것인가요?","options":[{"t":"가 상자","correct":true},{"t":"라 상자","mis":"M6-1-u3-X12"},{"t":"마 상자","mis":"M6-1-u3-X14"},{"t":"모두 같아요","mis":"M6-1-u3-X12"}],"explanation":["먼저 어림해요 — 18 ÷ 3 = 6, 24 ÷ 6 = 4, 15 ÷ 5 = 3이에요.","계산으로 확인하면 가 6.1 kg, 라 4.2 kg, 마 2.9 kg이에요.","수박 한 통이 가장 무거운 것은 가 상자예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_b#21','math',6,1,'u3','','g6_1_math_u3_review_b','unit_review','M6-1-u3-C2',3,'error','auto','49.2 ÷ 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X14']::text[],true,'{"seq":21,"concept":"M6-1-u3-C2","difficulty":3,"kind":"error","stem":"49.2 ÷ 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「몫은 123이야.」","correct":true,"mis_target":"M6-1-u3-X01"},{"t":"수아 — 「492 ÷ 4를 계산한 몫의 ⟨1/10⟩배야.」","mis":"M6-1-u3-X14"},{"t":"도윤 — 「몫의 소수점은 49.2의 소수점 위에 찍어.」","mis":"M6-1-u3-X14"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 492 ÷ 4 = 123이에요.","49.2는 492의 ⟨1/10⟩배라서 몫도 123의 ⟨1/10⟩배예요.","서호는 몫의 소수점을 한 자리 뒤에 찍었어요 — 바른 몫은 12.3이에요."],"variant_rule":{"alt":[{"stem":"4.6 ÷ 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「소수 첫째 자리까지 나누었으니 몫은 1.1이야.」","correct":true,"mis_target":"M6-1-u3-X06"},{"t":"나린 — 「4.6은 4.60과 같은 수야.」","mis":"M6-1-u3-X14"},{"t":"유진 — 「0을 내려 계산하면 몫은 1.15야.」","mis":"M6-1-u3-X14"}],"explanation":["소수 첫째 자리까지 나누면 나머지가 남아요.","0을 내려 계산을 이어 가야 해요.","가온은 계산을 멈추었어요 — 바른 몫은 1.15예요."]},{"stem":"18.1 ÷ 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「몫은 9.5야.」","correct":true,"mis_target":"M6-1-u3-X07"},{"t":"라온 — 「몫은 9보다 조금 커.」","mis":"M6-1-u3-X14"},{"t":"예준 — 「몫의 소수 첫째 자리에 0이 들어가.」","mis":"M6-1-u3-X14"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1810 ÷ 2 = 905예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 18.1 ÷ 2 = 9.05예요.","여울은 몫 가운데 0을 빠뜨렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_b#22','math',6,1,'u3','','g6_1_math_u3_review_b','unit_review','M6-1-u3-C5',3,'sa','auto','4.0□가 24.3 ÷ 6의 몫보다 커요. □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M6-1-u3-C5","difficulty":3,"kind":"sa","stem":"4.0□가 24.3 ÷ 6의 몫보다 커요. □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 2430 ÷ 6 = 405예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 24.3 ÷ 6 = 4.05예요.","4.0□ > 4.05 — □는 6부터 9까지, 4개예요."],"mis":"M6-1-u3-X07","variant_rule":{"alt":[{"stem":"3.0□가 15.3 ÷ 5의 몫보다 작아요. □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1530 ÷ 5 = 306이에요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 15.3 ÷ 5 = 3.06이에요.","3.0□ < 3.06 — □는 1부터 5까지, 5개예요."]},{"stem":"2.0□가 16.4 ÷ 8의 몫보다 작아요. □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1640 ÷ 8 = 205예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 16.4 ÷ 8 = 2.05예요.","2.0□ < 2.05 — □는 1부터 4까지, 4개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_b#23','math',6,1,'u3','','g6_1_math_u3_review_b','unit_review','M6-1-u3-C7',4,'mc','auto','가 상자는 수박 3통이 18.3 kg, 나 상자는 수박 4통이 19.8 kg이에요. 나 상자의 수박 한 통은 가 상자의 수박 한 통보다 몇 kg 가벼운가요?',ARRAY['M6-1-u3-X14','M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":23,"concept":"M6-1-u3-C7","difficulty":4,"kind":"mc","stem":"가 상자는 수박 3통이 18.3 kg, 나 상자는 수박 4통이 19.8 kg이에요. 나 상자의 수박 한 통은 가 상자의 수박 한 통보다 몇 kg 가벼운가요?","options":[{"t":"1.15 kg","correct":true},{"t":"11.05 kg","mis":"M6-1-u3-X14"},{"t":"11.5 kg","mis":"M6-1-u3-X01"},{"t":"0.115 kg","mis":"M6-1-u3-X02"}],"explanation":["가 상자 한 통은 18.3 ÷ 3 = 6.1 (kg)이에요.","나 상자 한 통은 19.8 ÷ 4 = 4.95 (kg)이에요.","6.1 − 4.95 = 1.15 (kg) 가벼워요."],"variant_rule":{"alt":[{"stem":"사 상자는 수박 3통이 16.2 kg, 다 상자는 수박 5통이 20.2 kg이에요. 다 상자의 수박 한 통은 사 상자의 수박 한 통보다 몇 kg 가벼운가요?","options":[{"t":"1.36 kg","correct":true},{"t":"9.44 kg","mis":"M6-1-u3-X14"},{"t":"13.6 kg","mis":"M6-1-u3-X01"},{"t":"0.136 kg","mis":"M6-1-u3-X02"}],"explanation":["사 상자 한 통은 16.2 ÷ 3 = 5.4 (kg)이에요.","다 상자 한 통은 20.2 ÷ 5 = 4.04 (kg)이에요.","5.4 − 4.04 = 1.36 (kg) 가벼워요."]},{"stem":"아 상자는 수박 6통이 30.6 kg, 마 상자는 수박 5통이 14.5 kg이에요. 마 상자의 수박 한 통은 아 상자의 수박 한 통보다 몇 kg 가벼운가요?","options":[{"t":"2.2 kg","correct":true},{"t":"8 kg","mis":"M6-1-u3-X14"},{"t":"22 kg","mis":"M6-1-u3-X01"},{"t":"0.22 kg","mis":"M6-1-u3-X02"}],"explanation":["아 상자 한 통은 30.6 ÷ 6 = 5.1 (kg)이에요.","마 상자 한 통은 14.5 ÷ 5 = 2.9 (kg)이에요.","5.1 − 2.9 = 2.2 (kg) 가벼워요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_b#24','math',6,1,'u3','','g6_1_math_u3_review_b','unit_review','M6-1-u3-C3',4,'essay','teacher','동물병원에서 강아지는 3.2 kg, 고양이는 4 kg이었어요. 강아지 몸무게가 고양이 몸무게의 몇 배인지 구하고, 몫의 일의 자리에 0을 써야 하는 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u3-C3","difficulty":4,"kind":"essay","stem":"동물병원에서 강아지는 3.2 kg, 고양이는 4 kg이었어요. 강아지 몸무게가 고양이 몸무게의 몇 배인지 구하고, 몫의 일의 자리에 0을 써야 하는 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 3.2 ÷ 4를 계산한다. 32 ÷ 4 = 8이고 3.2는 32의 10분의 1배이므로 몫은 0.8이다. 강아지는 고양이의 0.8배이다. 나누어지는 수가 나누는 수보다 작아 몫이 1보다 작으므로 일의 자리에 0을 써서 자리를 지켜야 한다. 0을 빼면 8이 되어 10배 큰 다른 수가 된다.","scoring_points":["3.2 ÷ 4로 식을 세웠는가","0.8배를 구했는가","0을 빼면 다른 수가 된다는 까닭을 썼는가"]},"explanation":["3.2 ÷ 4를 계산해요.","몫은 0.8 — 0.8배예요.","0은 자리를 지키는 숫자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_b#25','math',6,1,'u3','','g6_1_math_u3_review_b','unit_review','M6-1-u3-C7',4,'essay','teacher','친구가 20.2 ÷ 5의 몫을 4.4라고 했어요. 어림으로 몫의 크기를 확인하고, 세로셈의 어느 곳이 잘못되었는지 찾아 바른 몫을 구해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u3-C7","difficulty":4,"kind":"essay","stem":"친구가 20.2 ÷ 5의 몫을 4.4라고 했어요. 어림으로 몫의 크기를 확인하고, 세로셈의 어느 곳이 잘못되었는지 찾아 바른 몫을 구해 보세요.","answer_guide":{"answer":"예: 20.2를 20으로 어림하면 20 ÷ 5 = 4이므로 몫은 4보다 조금 크다. 20을 5로 나누고 2를 내리면 2는 5보다 작으므로 몫에 0을 쓰고 하나 더 내려 20 ÷ 5 = 4로 계산해야 한다. 친구는 몫 가운데 0을 빠뜨렸고 바른 몫은 4.04이다.","scoring_points":["20 ÷ 5 = 4로 어림했는가","몫 가운데 0을 빠뜨렸다고 찾았는가","4.04를 구했는가"]},"explanation":["어림하면 약 4예요.","2를 내려도 5보다 작아 몫에 0이에요.","바른 몫은 4.04예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_c#1','math',6,1,'u3','','g6_1_math_u3_review_c','unit_review','M6-1-u3-C1',1,'mc','auto','393 ÷ 3 = 131이에요. 그러면 3.93 ÷ 3의 몫은 얼마인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":1,"concept":"M6-1-u3-C1","difficulty":1,"kind":"mc","stem":"393 ÷ 3 = 131이에요. 그러면 3.93 ÷ 3의 몫은 얼마인가요?","options":[{"t":"1.31","correct":true},{"t":"13.1","mis":"M6-1-u3-X01"},{"t":"0.131","mis":"M6-1-u3-X02"},{"t":"131","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 3은 그대로예요.","나누어지는 수 3.93은 393의 ⟨1/100⟩배예요.","그래서 몫도 131의 ⟨1/100⟩배 — 1.31이에요."],"variant_rule":{"alt":[{"stem":"846 ÷ 2 = 423이에요. 그러면 84.6 ÷ 2의 몫은 얼마인가요?","options":[{"t":"42.3","correct":true},{"t":"423","mis":"M6-1-u3-X01"},{"t":"4.23","mis":"M6-1-u3-X02"},{"t":"4230","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 2는 그대로예요.","나누어지는 수 84.6은 846의 ⟨1/10⟩배예요.","그래서 몫도 423의 ⟨1/10⟩배 — 42.3이에요."]},{"stem":"585 ÷ 5 = 117이에요. 그러면 5.85 ÷ 5의 몫은 얼마인가요?","options":[{"t":"1.17","correct":true},{"t":"11.7","mis":"M6-1-u3-X01"},{"t":"0.117","mis":"M6-1-u3-X02"},{"t":"117","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 5는 그대로예요.","나누어지는 수 5.85는 585의 ⟨1/100⟩배예요.","그래서 몫도 117의 ⟨1/100⟩배 — 1.17이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_c#2','math',6,1,'u3','','g6_1_math_u3_review_c','unit_review','M6-1-u3-C1',1,'sa','auto','7.2는 0.1이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u3-C1","difficulty":1,"kind":"sa","stem":"7.2는 0.1이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["72"],"explanation":["0.1이 10개이면 1이에요.","7.2는 7과 소수 부분을 합해 0.1이 72개예요.","그래서 7.2는 0.1이 72개인 수예요."],"mis":"M6-1-u3-X03","variant_rule":{"alt":[{"stem":"8.6은 0.1이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["86"],"explanation":["0.1이 10개이면 1이에요.","8.6은 8과 소수 부분을 합해 0.1이 86개예요.","그래서 8.6은 0.1이 86개인 수예요."]},{"stem":"5.8은 0.1이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["58"],"explanation":["0.1이 10개이면 1이에요.","5.8은 5와 소수 부분을 합해 0.1이 58개예요.","그래서 5.8은 0.1이 58개인 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_c#3','math',6,1,'u3','','g6_1_math_u3_review_c','unit_review','M6-1-u3-C2',1,'mc','auto','34.5 ÷ 5의 몫은 얼마인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":3,"concept":"M6-1-u3-C2","difficulty":1,"kind":"mc","stem":"34.5 ÷ 5의 몫은 얼마인가요?","options":[{"t":"6.9","correct":true},{"t":"69","mis":"M6-1-u3-X01"},{"t":"0.69","mis":"M6-1-u3-X02"},{"t":"690","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 345 ÷ 5 = 69예요.","34.5는 345의 ⟨1/10⟩배라서 몫도 69의 ⟨1/10⟩배예요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 34.5 ÷ 5 = 6.9예요."],"variant_rule":{"alt":[{"stem":"49.2 ÷ 4의 몫은 얼마인가요?","options":[{"t":"12.3","correct":true},{"t":"123","mis":"M6-1-u3-X01"},{"t":"1.23","mis":"M6-1-u3-X02"},{"t":"1230","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 492 ÷ 4 = 123이에요.","49.2는 492의 ⟨1/10⟩배라서 몫도 123의 ⟨1/10⟩배예요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 49.2 ÷ 4 = 12.3이에요."]},{"stem":"58.5 ÷ 5의 몫은 얼마인가요?","options":[{"t":"11.7","correct":true},{"t":"117","mis":"M6-1-u3-X01"},{"t":"1.17","mis":"M6-1-u3-X02"},{"t":"1170","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 585 ÷ 5 = 117이에요.","58.5는 585의 ⟨1/10⟩배라서 몫도 117의 ⟨1/10⟩배예요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 58.5 ÷ 5 = 11.7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_c#4','math',6,1,'u3','','g6_1_math_u3_review_c','unit_review','M6-1-u3-C3',1,'mc','auto','5.72 ÷ 11의 몫은 얼마인가요?',ARRAY['M6-1-u3-X05','M6-1-u3-X02','M6-1-u3-X01']::text[],true,'{"seq":4,"concept":"M6-1-u3-C3","difficulty":1,"kind":"mc","stem":"5.72 ÷ 11의 몫은 얼마인가요?","options":[{"t":"0.52","correct":true},{"t":"5.2","mis":"M6-1-u3-X05"},{"t":"0.052","mis":"M6-1-u3-X02"},{"t":"52","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 572 ÷ 11 = 52예요.","5.72는 572의 ⟨1/100⟩배라서 몫도 52의 ⟨1/100⟩배예요.","몫이 1보다 작으니 일의 자리에 0을 써서 자리를 지켜요 — 5.72 ÷ 11 = 0.52예요."],"variant_rule":{"alt":[{"stem":"2.38 ÷ 7의 몫은 얼마인가요?","options":[{"t":"0.34","correct":true},{"t":"3.4","mis":"M6-1-u3-X05"},{"t":"0.034","mis":"M6-1-u3-X02"},{"t":"34","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 238 ÷ 7 = 34예요.","2.38은 238의 ⟨1/100⟩배라서 몫도 34의 ⟨1/100⟩배예요.","몫이 1보다 작으니 일의 자리에 0을 써서 자리를 지켜요 — 2.38 ÷ 7 = 0.34예요."]},{"stem":"4.15 ÷ 5의 몫은 얼마인가요?","options":[{"t":"0.83","correct":true},{"t":"8.3","mis":"M6-1-u3-X05"},{"t":"0.083","mis":"M6-1-u3-X02"},{"t":"83","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 415 ÷ 5 = 83이에요.","4.15는 415의 ⟨1/100⟩배라서 몫도 83의 ⟨1/100⟩배예요.","몫이 1보다 작으니 일의 자리에 0을 써서 자리를 지켜요 — 4.15 ÷ 5 = 0.83이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_c#5','math',6,1,'u3','','g6_1_math_u3_review_c','unit_review','M6-1-u3-C3',1,'mc','auto','2.38 ÷ 7의 몫은 1보다 클까요, 작을까요?',ARRAY['M6-1-u3-X12']::text[],true,'{"seq":5,"concept":"M6-1-u3-C3","difficulty":1,"kind":"mc","stem":"2.38 ÷ 7의 몫은 1보다 클까요, 작을까요?","options":[{"t":"1보다 작아요","correct":true},{"t":"1보다 커요","mis":"M6-1-u3-X12"},{"t":"1과 같아요","mis":"M6-1-u3-X12"},{"t":"계산해 보기 전에는 알 수 없어요","mis":"M6-1-u3-X12"}],"explanation":["나누어지는 수 2.38이 나누는 수 7보다 작아요.","7 ÷ 7 = 1이니 2.38 ÷ 7은 1보다 작아요.","실제로 몫은 0.34예요."],"variant_rule":{"alt":[{"stem":"5.6 ÷ 8의 몫은 1보다 클까요, 작을까요?","options":[{"t":"1보다 작아요","correct":true},{"t":"1보다 커요","mis":"M6-1-u3-X12"},{"t":"1과 같아요","mis":"M6-1-u3-X12"},{"t":"계산해 보기 전에는 알 수 없어요","mis":"M6-1-u3-X12"}],"explanation":["나누어지는 수 5.6이 나누는 수 8보다 작아요.","8 ÷ 8 = 1이니 5.6 ÷ 8은 1보다 작아요.","실제로 몫은 0.7이에요."]},{"stem":"7.29 ÷ 9의 몫은 1보다 클까요, 작을까요?","options":[{"t":"1보다 작아요","correct":true},{"t":"1보다 커요","mis":"M6-1-u3-X12"},{"t":"1과 같아요","mis":"M6-1-u3-X12"},{"t":"계산해 보기 전에는 알 수 없어요","mis":"M6-1-u3-X12"}],"explanation":["나누어지는 수 7.29가 나누는 수 9보다 작아요.","9 ÷ 9 = 1이니 7.29 ÷ 9는 1보다 작아요.","실제로 몫은 0.81이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_c#6','math',6,1,'u3','','g6_1_math_u3_review_c','unit_review','M6-1-u3-C4',1,'mc','auto','18.8 ÷ 8을 계산하다가 소수 첫째 자리까지 나누었더니 4가 남았어요. 다음에 할 일로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u3-X06','M6-1-u3-X13']::text[],true,'{"seq":6,"concept":"M6-1-u3-C4","difficulty":1,"kind":"mc","stem":"18.8 ÷ 8을 계산하다가 소수 첫째 자리까지 나누었더니 4가 남았어요. 다음에 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"소수점 아래에 0을 하나 내려 계산을 이어 가요","correct":true},{"t":"남은 4를 몫 뒤에 붙여 써요","mis":"M6-1-u3-X06"},{"t":"나누어떨어지지 않는다고 답해요","mis":"M6-1-u3-X06"},{"t":"나누는 수를 바꾸어 다시 나누어요","mis":"M6-1-u3-X13"}],"explanation":["18.8은 18.80과 같은 수예요.","소수점 아래 끝자리에 0을 붙여도 수의 크기는 그대로예요.","그래서 0을 내려 이어 계산하면 18.8 ÷ 8 = 2.35예요."],"variant_rule":{"alt":[{"stem":"8.3 ÷ 2를 계산하다가 소수 첫째 자리까지 나누었더니 1이 남았어요. 다음에 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"소수점 아래에 0을 하나 내려 계산을 이어 가요","correct":true},{"t":"남은 1을 몫 뒤에 붙여 써요","mis":"M6-1-u3-X06"},{"t":"나누어떨어지지 않는다고 답해요","mis":"M6-1-u3-X06"},{"t":"나누는 수를 바꾸어 다시 나누어요","mis":"M6-1-u3-X13"}],"explanation":["8.3은 8.30과 같은 수예요.","소수점 아래 끝자리에 0을 붙여도 수의 크기는 그대로예요.","그래서 0을 내려 이어 계산하면 8.3 ÷ 2 = 4.15예요."]},{"stem":"4.6 ÷ 4를 계산하다가 소수 첫째 자리까지 나누었더니 2가 남았어요. 다음에 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"소수점 아래에 0을 하나 내려 계산을 이어 가요","correct":true},{"t":"남은 2를 몫 뒤에 붙여 써요","mis":"M6-1-u3-X06"},{"t":"나누어떨어지지 않는다고 답해요","mis":"M6-1-u3-X06"},{"t":"나누는 수를 바꾸어 다시 나누어요","mis":"M6-1-u3-X13"}],"explanation":["4.6은 4.60과 같은 수예요.","소수점 아래 끝자리에 0을 붙여도 수의 크기는 그대로예요.","그래서 0을 내려 이어 계산하면 4.6 ÷ 4 = 1.15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_c#7','math',6,1,'u3','','g6_1_math_u3_review_c','unit_review','M6-1-u3-C6',1,'mc','auto','9 ÷ 6을 세로셈으로 계산할 때 9를 어떻게 보아야 하나요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":7,"concept":"M6-1-u3-C6","difficulty":1,"kind":"mc","stem":"9 ÷ 6을 세로셈으로 계산할 때 9를 어떻게 보아야 하나요?","options":[{"t":"9.0으로 봐요","correct":true},{"t":"90으로 봐요","mis":"M6-1-u3-X01"},{"t":"0.9로 봐요","mis":"M6-1-u3-X02"},{"t":"⟨9/10⟩로 봐요","mis":"M6-1-u3-X02"}],"explanation":["자연수의 소수점은 자연수 바로 뒤에 있어요.","9 = 9.0 = 9.00이에요.","그래서 9를 9.0으로 보고 0을 내려 계산해요."],"variant_rule":{"alt":[{"stem":"7 ÷ 4를 세로셈으로 계산할 때 7을 어떻게 보아야 하나요?","options":[{"t":"7.0으로 봐요","correct":true},{"t":"70으로 봐요","mis":"M6-1-u3-X01"},{"t":"0.7로 봐요","mis":"M6-1-u3-X02"},{"t":"⟨7/10⟩로 봐요","mis":"M6-1-u3-X02"}],"explanation":["자연수의 소수점은 자연수 바로 뒤에 있어요.","7 = 7.0 = 7.00이에요.","그래서 7을 7.0으로 보고 0을 내려 계산해요."]},{"stem":"60 ÷ 8을 세로셈으로 계산할 때 60을 어떻게 보아야 하나요?","options":[{"t":"60.0으로 봐요","correct":true},{"t":"600으로 봐요","mis":"M6-1-u3-X01"},{"t":"6으로 봐요","mis":"M6-1-u3-X02"},{"t":"⟨60/10⟩으로 봐요","mis":"M6-1-u3-X02"}],"explanation":["자연수의 소수점은 자연수 바로 뒤에 있어요.","60 = 60.0 = 60.00이에요.","그래서 60을 60.0으로 보고 0을 내려 계산해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_c#8','math',6,1,'u3','','g6_1_math_u3_review_c','unit_review','M6-1-u3-C7',1,'sa','auto','다 상자에는 무게가 같은 수박 5통이 20.2 kg 들어 있어요. 20.2를 20으로 어림하면 수박 한 통은 약 몇 kg인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u3-C7","difficulty":1,"kind":"sa","stem":"다 상자에는 무게가 같은 수박 5통이 20.2 kg 들어 있어요. 20.2를 20으로 어림하면 수박 한 통은 약 몇 kg인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["20.2에 가까우면서 5로 나누기 쉬운 수는 20이에요.","20 ÷ 5 = 4예요.","수박 한 통은 약 4 kg이에요."],"mis":"M6-1-u3-X12","variant_rule":{"alt":[{"stem":"라 상자에는 무게가 같은 수박 6통이 25.2 kg 들어 있어요. 25.2를 24로 어림하면 수박 한 통은 약 몇 kg인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["25.2에 가까우면서 6으로 나누기 쉬운 수는 24예요.","24 ÷ 6 = 4예요.","수박 한 통은 약 4 kg이에요."]},{"stem":"가 상자에는 무게가 같은 수박 3통이 18.3 kg 들어 있어요. 18.3을 18로 어림하면 수박 한 통은 약 몇 kg인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["18.3에 가까우면서 3으로 나누기 쉬운 수는 18이에요.","18 ÷ 3 = 6이에요.","수박 한 통은 약 6 kg이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_c#9','math',6,1,'u3','','g6_1_math_u3_review_c','unit_review','M6-1-u3-C2',2,'sa','auto','13.79 ÷ 7의 몫에서 소수 둘째 자리 숫자는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u3-C2","difficulty":2,"kind":"sa","stem":"13.79 ÷ 7의 몫에서 소수 둘째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1379 ÷ 7 = 197이에요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 13.79 ÷ 7 = 1.97이에요.","1.97의 소수 둘째 자리 숫자는 7이에요."],"mis":"M6-1-u3-X13","variant_rule":{"alt":[{"stem":"22.68 ÷ 4의 몫에서 소수 둘째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 2268 ÷ 4 = 567이에요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 22.68 ÷ 4 = 5.67이에요.","5.67의 소수 둘째 자리 숫자는 7이에요."]},{"stem":"58.5 ÷ 5의 몫에서 소수 첫째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 585 ÷ 5 = 117이에요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 58.5 ÷ 5 = 11.7이에요.","11.7의 소수 첫째 자리 숫자는 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_c#10','math',6,1,'u3','','g6_1_math_u3_review_c','unit_review','M6-1-u3-C4',2,'mc','auto','6.7 ÷ 5의 몫은 얼마인가요?',ARRAY['M6-1-u3-X06','M6-1-u3-X01']::text[],true,'{"seq":10,"concept":"M6-1-u3-C4","difficulty":2,"kind":"mc","stem":"6.7 ÷ 5의 몫은 얼마인가요?","options":[{"t":"1.34","correct":true},{"t":"1.3","mis":"M6-1-u3-X06"},{"t":"1.32","mis":"M6-1-u3-X06"},{"t":"13.4","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 670 ÷ 5 = 134예요.","6.7은 670의 ⟨1/100⟩배라서 몫도 134의 ⟨1/100⟩배예요.","나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 6.7 ÷ 5 = 1.34예요."],"variant_rule":{"alt":[{"stem":"5.4 ÷ 8의 몫은 얼마인가요?","options":[{"t":"0.675","correct":true},{"t":"0.6","mis":"M6-1-u3-X06"},{"t":"0.66","mis":"M6-1-u3-X06"},{"t":"6.75","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 5400 ÷ 8 = 675예요.","5.4는 5400의 ⟨1/1000⟩배라서 몫도 675의 ⟨1/1000⟩배예요.","나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 5.4 ÷ 8 = 0.675예요."]},{"stem":"18.8 ÷ 8의 몫은 얼마인가요?","options":[{"t":"2.35","correct":true},{"t":"2.3","mis":"M6-1-u3-X06"},{"t":"2.34","mis":"M6-1-u3-X06"},{"t":"23.5","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1880 ÷ 8 = 235예요.","18.8은 1880의 ⟨1/100⟩배라서 몫도 235의 ⟨1/100⟩배예요.","나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 18.8 ÷ 8 = 2.35예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_c#11','math',6,1,'u3','','g6_1_math_u3_review_c','unit_review','M6-1-u3-C5',2,'mc','auto','20.2 ÷ 5의 몫은 얼마인가요?',ARRAY['M6-1-u3-X07','M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":11,"concept":"M6-1-u3-C5","difficulty":2,"kind":"mc","stem":"20.2 ÷ 5의 몫은 얼마인가요?","options":[{"t":"4.04","correct":true},{"t":"4.4","mis":"M6-1-u3-X07"},{"t":"40.4","mis":"M6-1-u3-X01"},{"t":"0.404","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 2020 ÷ 5 = 404예요.","20.2는 2020의 ⟨1/100⟩배라서 몫도 404의 ⟨1/100⟩배예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 20.2 ÷ 5 = 4.04예요."],"variant_rule":{"alt":[{"stem":"16.4 ÷ 8의 몫은 얼마인가요?","options":[{"t":"2.05","correct":true},{"t":"2.5","mis":"M6-1-u3-X07"},{"t":"20.5","mis":"M6-1-u3-X01"},{"t":"0.205","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1640 ÷ 8 = 205예요.","16.4는 1640의 ⟨1/100⟩배라서 몫도 205의 ⟨1/100⟩배예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 16.4 ÷ 8 = 2.05예요."]},{"stem":"18.1 ÷ 2의 몫은 얼마인가요?","options":[{"t":"9.05","correct":true},{"t":"9.5","mis":"M6-1-u3-X07"},{"t":"90.5","mis":"M6-1-u3-X01"},{"t":"0.905","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1810 ÷ 2 = 905예요.","18.1은 1810의 ⟨1/100⟩배라서 몫도 905의 ⟨1/100⟩배예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 18.1 ÷ 2 = 9.05예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_c#12','math',6,1,'u3','','g6_1_math_u3_review_c','unit_review','M6-1-u3-C6',2,'mc','auto','3 ÷ 4의 몫은 얼마인가요?',ARRAY['M6-1-u3-X08','M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":12,"concept":"M6-1-u3-C6","difficulty":2,"kind":"mc","stem":"3 ÷ 4의 몫은 얼마인가요?","options":[{"t":"0.75","correct":true},{"t":"0.3","mis":"M6-1-u3-X08"},{"t":"7.5","mis":"M6-1-u3-X01"},{"t":"0.075","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 300 ÷ 4 = 75예요.","3은 300의 ⟨1/100⟩배라서 몫도 75의 ⟨1/100⟩배예요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 3 ÷ 4 = 0.75예요."],"variant_rule":{"alt":[{"stem":"9 ÷ 6의 몫은 얼마인가요?","options":[{"t":"1.5","correct":true},{"t":"1.3","mis":"M6-1-u3-X08"},{"t":"15","mis":"M6-1-u3-X01"},{"t":"0.15","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 90 ÷ 6 = 15예요.","9는 90의 ⟨1/10⟩배라서 몫도 15의 ⟨1/10⟩배예요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 9 ÷ 6 = 1.5예요."]},{"stem":"60 ÷ 8의 몫은 얼마인가요?","options":[{"t":"7.5","correct":true},{"t":"7.4","mis":"M6-1-u3-X08"},{"t":"75","mis":"M6-1-u3-X01"},{"t":"0.75","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 600 ÷ 8 = 75예요.","60은 600의 ⟨1/10⟩배라서 몫도 75의 ⟨1/10⟩배예요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 60 ÷ 8 = 7.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_c#13','math',6,1,'u3','','g6_1_math_u3_review_c','unit_review','M6-1-u3-C4',2,'ox','auto','4.6 ÷ 4를 소수 첫째 자리까지 나누고 2가 남으면 몫은 1.1이에요.',ARRAY['M6-1-u3-X06']::text[],true,'{"seq":13,"concept":"M6-1-u3-C4","difficulty":2,"kind":"ox","stem":"4.6 ÷ 4를 소수 첫째 자리까지 나누고 2가 남으면 몫은 1.1이에요.","answer":"X","reason_options":[{"t":"0을 내려 계산을 이어 가면 몫은 1.15이기 때문에","correct":true},{"t":"나누어지는 수의 자리가 끝나면 계산도 끝나기 때문에","mis":"M6-1-u3-X06"}],"mis":"M6-1-u3-X06","explanation":["4.6 = 4.60 = 4.600 — 소수점 아래 끝자리에 0을 붙여도 수의 크기는 같아요.","그래서 나머지가 남으면 0을 내려 계산을 이어 가요.","남은 수를 몫 뒤에 붙이면 안 돼요."],"variant_rule":{"alt":[{"stem":"6 ÷ 5의 몫은 1.1이에요.","answer":"X","reason_options":[{"t":"나머지 1에 0을 내려 10 ÷ 5 = 2를 이어 계산하면 1.2이기 때문에","correct":true},{"t":"6 ÷ 5 = 1 … 1이라 나머지를 소수로 쓰기 때문에","mis":"M6-1-u3-X08"}],"explanation":["자연수의 소수점은 자연수 바로 뒤에 있어요 — 6 = 6.0이에요.","나머지가 남으면 0을 내려 계산을 이어 가요.","몫을 분수로 쓴 뒤 분모를 10·100으로 고쳐 소수로 나타낼 수도 있어요."]},{"stem":"648 ÷ 2 = 324이면 6.48 ÷ 2 = 32.4예요.","answer":"X","reason_options":[{"t":"6.48은 648의 ⟨1/100⟩배라서 몫도 ⟨1/100⟩배인 3.24이기 때문에","correct":true},{"t":"나누어지는 수의 소수점을 한 칸만 옮기면 되기 때문에","mis":"M6-1-u3-X02"}],"explanation":["소수는 0.1이나 0.01이 몇 개인 수로 볼 수 있어요.","나누는 수가 같을 때 나누어지는 수가 ⟨1/10⟩배가 되면 몫도 ⟨1/10⟩배가 돼요.","분수의 나눗셈으로 바꾸면 ÷ 자연수는 × 자연수분의 1이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_c#14','math',6,1,'u3','','g6_1_math_u3_review_c','unit_review','M6-1-u3-C3',2,'mc','auto','다음 가운데 몫이 1보다 작은 나눗셈은 어느 것인가요?',ARRAY['M6-1-u3-X12']::text[],true,'{"seq":14,"concept":"M6-1-u3-C3","difficulty":2,"kind":"mc","stem":"다음 가운데 몫이 1보다 작은 나눗셈은 어느 것인가요?","options":[{"t":"2.7 ÷ 3","correct":true},{"t":"7.2 ÷ 6","mis":"M6-1-u3-X12"},{"t":"4.4 ÷ 4","mis":"M6-1-u3-X12"},{"t":"8.1 ÷ 3","mis":"M6-1-u3-X12"}],"explanation":["몫이 1보다 작으려면 나누어지는 수가 나누는 수보다 작아야 해요.","나누어지는 수와 나누는 수를 하나씩 견주어 봐요.","2.7 ÷ 3만 나누어지는 수가 더 작아요 — 몫은 0.9예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 가운데 몫이 1보다 작은 나눗셈은 어느 것인가요?","options":[{"t":"4.15 ÷ 5","correct":true},{"t":"9.9 ÷ 9","mis":"M6-1-u3-X12"},{"t":"6.6 ÷ 6","mis":"M6-1-u3-X12"},{"t":"8.8 ÷ 4","mis":"M6-1-u3-X12"}],"explanation":["몫이 1보다 작으려면 나누어지는 수가 나누는 수보다 작아야 해요.","나누어지는 수와 나누는 수를 하나씩 견주어 봐요.","4.15 ÷ 5만 나누어지는 수가 더 작아요 — 몫은 0.83이에요."]},{"stem":"이번에는 다른 보기예요. 다음 가운데 몫이 1보다 작은 나눗셈은 어느 것인가요?","options":[{"t":"7.29 ÷ 9","correct":true},{"t":"14.9 ÷ 5","mis":"M6-1-u3-X12"},{"t":"8.4 ÷ 8","mis":"M6-1-u3-X12"},{"t":"4.16 ÷ 4","mis":"M6-1-u3-X12"}],"explanation":["몫이 1보다 작으려면 나누어지는 수가 나누는 수보다 작아야 해요.","나누어지는 수와 나누는 수를 하나씩 견주어 봐요.","7.29 ÷ 9만 나누어지는 수가 더 작아요 — 몫은 0.81이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_c#15','math',6,1,'u3','','g6_1_math_u3_review_c','unit_review','M6-1-u3-C1',2,'mc','auto','길이가 3.6 m인 끈을 똑같이 잘라 기념품 상자 3개를 묶어요. 상자 한 개에 쓰는 끈은 몇 m인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02','M6-1-u3-X10']::text[],true,'{"seq":15,"concept":"M6-1-u3-C1","difficulty":2,"kind":"mc","stem":"길이가 3.6 m인 끈을 똑같이 잘라 기념품 상자 3개를 묶어요. 상자 한 개에 쓰는 끈은 몇 m인가요?","options":[{"t":"1.2 m","correct":true},{"t":"12 m","mis":"M6-1-u3-X01"},{"t":"0.12 m","mis":"M6-1-u3-X02"},{"t":"10.8 m","mis":"M6-1-u3-X10"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 36 ÷ 3 = 12예요.","3.6은 36의 ⟨1/10⟩배라서 몫도 12의 ⟨1/10⟩배예요.","3.6 ÷ 3 = 1.2예요."],"variant_rule":{"alt":[{"stem":"리본 9.6 m를 세 명이 똑같이 나누어 가져요. 한 명이 가지는 리본은 몇 m인가요?","options":[{"t":"3.2 m","correct":true},{"t":"32 m","mis":"M6-1-u3-X01"},{"t":"0.32 m","mis":"M6-1-u3-X02"},{"t":"28.8 m","mis":"M6-1-u3-X10"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 96 ÷ 3 = 32예요.","9.6은 96의 ⟨1/10⟩배라서 몫도 32의 ⟨1/10⟩배예요.","9.6 ÷ 3 = 3.2예요."]},{"stem":"걷기 대회 코스는 모두 6.8 km예요. 반환점은 코스의 정확히 절반 지점에 있어요. 반환점까지는 몇 km인가요?","options":[{"t":"3.4 km","correct":true},{"t":"34 km","mis":"M6-1-u3-X01"},{"t":"0.34 km","mis":"M6-1-u3-X02"},{"t":"13.6 km","mis":"M6-1-u3-X10"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 68 ÷ 2 = 34예요.","6.8은 68의 ⟨1/10⟩배라서 몫도 34의 ⟨1/10⟩배예요.","6.8 ÷ 2 = 3.4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_c#16','math',6,1,'u3','','g6_1_math_u3_review_c','unit_review','M6-1-u3-C2',2,'sa','auto','넓이가 34.5 cm²이고 밑변이 5 cm인 평행사변형이 있어요. 이 평행사변형의 높이는 몇 mm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M6-1-u3-C2","difficulty":2,"kind":"sa","stem":"넓이가 34.5 cm²이고 밑변이 5 cm인 평행사변형이 있어요. 이 평행사변형의 높이는 몇 mm인가요? 숫자로 쓰세요.","answer":["69"],"explanation":["평행사변형의 넓이 = 밑변 × 높이이니 높이 = 넓이 ÷ 밑변이에.","34.5 ÷ 5 = 6.9 (cm)예요.","1 cm는 10 mm라서 6.9 cm는 69 mm예요."],"mis":"M6-1-u3-X11","variant_rule":{"alt":[{"stem":"넓이가 38.4 cm²이고 가로가 6 cm인 직사각형이 있어요. 이 직사각형의 세로는 몇 mm인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["직사각형의 넓이 = 가로 × 세로이니 세로 = 넓이 ÷ 가로요예요.","38.4 ÷ 6 = 6.4 (cm)예요.","1 cm는 10 mm라서 6.4 cm는 64 mm예요."]},{"stem":"넓이가 45.6 cm²이고 가로가 8 cm인 직사각형이 있어요. 이 직사각형의 세로는 몇 mm인가요? 숫자로 쓰세요.","answer":["57"],"explanation":["직사각형의 넓이 = 가로 × 세로이니 세로 = 넓이 ÷ 가로요예요.","45.6 ÷ 8 = 5.7 (cm)예요.","1 cm는 10 mm라서 5.7 cm는 57 mm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_c#17','math',6,1,'u3','','g6_1_math_u3_review_c','unit_review','M6-1-u3-C5',3,'mc','auto','친구가 9.27 ÷ 9의 몫을 1.3이라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X06','M6-1-u3-X05']::text[],true,'{"seq":17,"concept":"M6-1-u3-C5","difficulty":3,"kind":"mc","stem":"친구가 9.27 ÷ 9의 몫을 1.3이라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"내린 수가 나누는 수보다 작을 때 몫에 0을 쓰지 않아서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"0을 내려 계산하지 않아서","mis":"M6-1-u3-X06"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 927 ÷ 9 = 103이에요.","내린 수가 9보다 작으면 몫에 0을 쓰고 하나 더 내려야 해요.","바른 몫은 1.03이고 1.3은 다른 수예요."],"variant_rule":{"alt":[{"stem":"친구가 12.3 ÷ 6의 몫을 2.5라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"내린 수가 나누는 수보다 작을 때 몫에 0을 쓰지 않아서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"0을 내려 계산하지 않아서","mis":"M6-1-u3-X06"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1230 ÷ 6 = 205예요.","내린 수가 6보다 작으면 몫에 0을 쓰고 하나 더 내려야 해요.","바른 몫은 2.05이고 2.5는 다른 수예요."]},{"stem":"친구가 18.1 ÷ 2의 몫을 9.5라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"내린 수가 나누는 수보다 작을 때 몫에 0을 쓰지 않아서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"0을 내려 계산하지 않아서","mis":"M6-1-u3-X06"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1810 ÷ 2 = 905예요.","내린 수가 2보다 작으면 몫에 0을 쓰고 하나 더 내려야 해요.","바른 몫은 9.05이고 9.5는 다른 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_c#18','math',6,1,'u3','','g6_1_math_u3_review_c','unit_review','M6-1-u3-C3',3,'mc','auto','친구가 5.72 ÷ 11의 몫을 52라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u3-X13','M6-1-u3-X06']::text[],true,'{"seq":18,"concept":"M6-1-u3-C3","difficulty":3,"kind":"mc","stem":"친구가 5.72 ÷ 11의 몫을 52라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"몫이 1보다 작은데 일의 자리 0과 소수점을 쓰지 않아서","correct":true},{"t":"나누는 수를 잘못 써서","mis":"M6-1-u3-X13"},{"t":"곱셈을 잘못해서","mis":"M6-1-u3-X13"},{"t":"0을 내려 계산하지 않아서","mis":"M6-1-u3-X06"}],"explanation":["5.72는 11보다 작아 몫이 1보다 작아요.","자연수의 나눗셈으로 바꾸어 봐요 — 572 ÷ 11 = 52예요.","일의 자리에 0을 쓰고 소수점을 찍어 0.52예요."],"variant_rule":{"alt":[{"stem":"친구가 2.38 ÷ 7의 몫을 34라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"몫이 1보다 작은데 일의 자리 0과 소수점을 쓰지 않아서","correct":true},{"t":"나누는 수를 잘못 써서","mis":"M6-1-u3-X13"},{"t":"곱셈을 잘못해서","mis":"M6-1-u3-X13"},{"t":"0을 내려 계산하지 않아서","mis":"M6-1-u3-X06"}],"explanation":["2.38은 7보다 작아 몫이 1보다 작아요.","자연수의 나눗셈으로 바꾸어 봐요 — 238 ÷ 7 = 34예요.","일의 자리에 0을 쓰고 소수점을 찍어 0.34예요."]},{"stem":"친구가 3.2 ÷ 4의 몫을 8이라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"몫이 1보다 작은데 일의 자리 0과 소수점을 쓰지 않아서","correct":true},{"t":"나누는 수를 잘못 써서","mis":"M6-1-u3-X13"},{"t":"곱셈을 잘못해서","mis":"M6-1-u3-X13"},{"t":"0을 내려 계산하지 않아서","mis":"M6-1-u3-X06"}],"explanation":["3.2는 4보다 작아 몫이 1보다 작아요.","자연수의 나눗셈으로 바꾸어 봐요 — 32 ÷ 4 = 8이에요.","일의 자리에 0을 쓰고 소수점을 찍어 0.8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_c#19','math',6,1,'u3','','g6_1_math_u3_review_c','unit_review','M6-1-u3-C6',3,'mc','auto','친구가 7 ÷ 4 = 1 … 3을 보고 몫을 1.3으로 나타냈어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X09','M6-1-u3-X05']::text[],true,'{"seq":19,"concept":"M6-1-u3-C6","difficulty":3,"kind":"mc","stem":"친구가 7 ÷ 4 = 1 … 3을 보고 몫을 1.3으로 나타냈어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나머지 3을 그대로 소수 부분으로 써서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"나누는 수와 나누어지는 수를 바꾸어서","mis":"M6-1-u3-X09"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["나머지 3은 아직 나누지 않은 양이라 몫의 소수 부분이 아니에요.","7을 7.0으로 보고 0을 내려 계산을 이어 가요.","바른 몫은 1.75예요."],"variant_rule":{"alt":[{"stem":"친구가 17 ÷ 4 = 4 … 1을 보고 몫을 4.1로 나타냈어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나머지 1을 그대로 소수 부분으로 써서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"나누는 수와 나누어지는 수를 바꾸어서","mis":"M6-1-u3-X09"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["나머지 1은 아직 나누지 않은 양이라 몫의 소수 부분이 아니에요.","17을 17.0으로 보고 0을 내려 계산을 이어 가요.","바른 몫은 4.25예요."]},{"stem":"친구가 6 ÷ 5 = 1 … 1을 보고 몫을 1.1로 나타냈어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나머지 1을 그대로 소수 부분으로 써서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"나누는 수와 나누어지는 수를 바꾸어서","mis":"M6-1-u3-X09"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["나머지 1은 아직 나누지 않은 양이라 몫의 소수 부분이 아니에요.","6을 6.0으로 보고 0을 내려 계산을 이어 가요.","바른 몫은 1.2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_c#20','math',6,1,'u3','','g6_1_math_u3_review_c','unit_review','M6-1-u3-C7',3,'mc','auto','사 상자 3통 16.2 kg · 마 상자 5통 14.5 kg · 다 상자 5통 20.2 kg — 수박 한 통이 가장 무거운 상자는 어느 것인가요?',ARRAY['M6-1-u3-X14','M6-1-u3-X12']::text[],true,'{"seq":20,"concept":"M6-1-u3-C7","difficulty":3,"kind":"mc","stem":"사 상자 3통 16.2 kg · 마 상자 5통 14.5 kg · 다 상자 5통 20.2 kg — 수박 한 통이 가장 무거운 상자는 어느 것인가요?","options":[{"t":"사 상자","correct":true},{"t":"마 상자","mis":"M6-1-u3-X14"},{"t":"다 상자","mis":"M6-1-u3-X12"},{"t":"모두 같아요","mis":"M6-1-u3-X12"}],"explanation":["먼저 어림해요 — 15 ÷ 3 = 5, 15 ÷ 5 = 3, 20 ÷ 5 = 4예요.","계산으로 확인하면 사 5.4 kg, 마 2.9 kg, 다 4.04 kg이에요.","수박 한 통이 가장 무거운 것은 사 상자예요."],"variant_rule":{"alt":[{"stem":"가 상자 3통 18.3 kg · 라 상자 6통 25.2 kg · 마 상자 5통 14.5 kg — 수박 한 통이 가장 무거운 상자는 어느 것인가요?","options":[{"t":"가 상자","correct":true},{"t":"라 상자","mis":"M6-1-u3-X12"},{"t":"마 상자","mis":"M6-1-u3-X14"},{"t":"모두 같아요","mis":"M6-1-u3-X12"}],"explanation":["먼저 어림해요 — 18 ÷ 3 = 6, 24 ÷ 6 = 4, 15 ÷ 5 = 3이에요.","계산으로 확인하면 가 6.1 kg, 라 4.2 kg, 마 2.9 kg이에요.","수박 한 통이 가장 무거운 것은 가 상자예요."]},{"stem":"가 상자 3통 18.3 kg · 나 상자 4통 19.8 kg · 다 상자 5통 20.2 kg — 수박 한 통이 가장 무거운 상자는 어느 것인가요?","options":[{"t":"가 상자","correct":true},{"t":"나 상자","mis":"M6-1-u3-X12"},{"t":"다 상자","mis":"M6-1-u3-X14"},{"t":"모두 같아요","mis":"M6-1-u3-X12"}],"explanation":["먼저 어림해요 — 18 ÷ 3 = 6, 20 ÷ 4 = 5, 20 ÷ 5 = 4예요.","계산으로 확인하면 가 6.1 kg, 나 4.95 kg, 다 4.04 kg이에요.","수박 한 통이 가장 무거운 것은 가 상자예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_c#21','math',6,1,'u3','','g6_1_math_u3_review_c','unit_review','M6-1-u3-C4',3,'error','auto','4.6 ÷ 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u3-X06','M6-1-u3-X14']::text[],true,'{"seq":21,"concept":"M6-1-u3-C4","difficulty":3,"kind":"error","stem":"4.6 ÷ 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「소수 첫째 자리까지 나누었으니 몫은 1.1이야.」","correct":true,"mis_target":"M6-1-u3-X06"},{"t":"나린 — 「4.6은 4.60과 같은 수야.」","mis":"M6-1-u3-X14"},{"t":"유진 — 「0을 내려 계산하면 몫은 1.15야.」","mis":"M6-1-u3-X14"}],"explanation":["소수 첫째 자리까지 나누면 나머지가 남아요.","0을 내려 계산을 이어 가야 해요.","가온은 계산을 멈추었어요 — 바른 몫은 1.15예요."],"variant_rule":{"alt":[{"stem":"18.1 ÷ 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「몫은 9.5야.」","correct":true,"mis_target":"M6-1-u3-X07"},{"t":"라온 — 「몫은 9보다 조금 커.」","mis":"M6-1-u3-X14"},{"t":"예준 — 「몫의 소수 첫째 자리에 0이 들어가.」","mis":"M6-1-u3-X14"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1810 ÷ 2 = 905예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 18.1 ÷ 2 = 9.05예요.","여울은 몫 가운데 0을 빠뜨렸어요."]},{"stem":"585 ÷ 5 = 117을 이용해 58.5 ÷ 5를 계산하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「나누어지는 수가 작아졌으니 몫은 117의 10배야.」","correct":true,"mis_target":"M6-1-u3-X01"},{"t":"이현 — 「58.5는 585의 ⟨1/10⟩배야.」","mis":"M6-1-u3-X14"},{"t":"서아 — 「몫은 11.7이야.」","mis":"M6-1-u3-X14"}],"explanation":["나누는 수 5는 그대로예요.","나누어지는 수가 ⟨1/10⟩배가 되면 몫도 ⟨1/10⟩배예요.","준희는 몫이 커진다고 거꾸로 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_c#22','math',6,1,'u3','','g6_1_math_u3_review_c','unit_review','M6-1-u3-C5',3,'sa','auto','3.0□가 15.3 ÷ 5의 몫보다 작아요. □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M6-1-u3-C5","difficulty":3,"kind":"sa","stem":"3.0□가 15.3 ÷ 5의 몫보다 작아요. □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1530 ÷ 5 = 306이에요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 15.3 ÷ 5 = 3.06이에요.","3.0□ < 3.06 — □는 1부터 5까지, 5개예요."],"mis":"M6-1-u3-X07","variant_rule":{"alt":[{"stem":"2.0□가 16.4 ÷ 8의 몫보다 작아요. □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1640 ÷ 8 = 205예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 16.4 ÷ 8 = 2.05예요.","2.0□ < 2.05 — □는 1부터 4까지, 4개예요."]},{"stem":"6.0□가 48.4 ÷ 8의 몫보다 커요. □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 4840 ÷ 8 = 605예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 48.4 ÷ 8 = 6.05예요.","6.0□ > 6.05 — □는 6부터 9까지, 4개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_c#23','math',6,1,'u3','','g6_1_math_u3_review_c','unit_review','M6-1-u3-C7',4,'mc','auto','사 상자는 수박 3통이 16.2 kg, 다 상자는 수박 5통이 20.2 kg이에요. 다 상자의 수박 한 통은 사 상자의 수박 한 통보다 몇 kg 가벼운가요?',ARRAY['M6-1-u3-X14','M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":23,"concept":"M6-1-u3-C7","difficulty":4,"kind":"mc","stem":"사 상자는 수박 3통이 16.2 kg, 다 상자는 수박 5통이 20.2 kg이에요. 다 상자의 수박 한 통은 사 상자의 수박 한 통보다 몇 kg 가벼운가요?","options":[{"t":"1.36 kg","correct":true},{"t":"9.44 kg","mis":"M6-1-u3-X14"},{"t":"13.6 kg","mis":"M6-1-u3-X01"},{"t":"0.136 kg","mis":"M6-1-u3-X02"}],"explanation":["사 상자 한 통은 16.2 ÷ 3 = 5.4 (kg)이에요.","다 상자 한 통은 20.2 ÷ 5 = 4.04 (kg)이에요.","5.4 − 4.04 = 1.36 (kg) 가벼워요."],"variant_rule":{"alt":[{"stem":"아 상자는 수박 6통이 30.6 kg, 마 상자는 수박 5통이 14.5 kg이에요. 마 상자의 수박 한 통은 아 상자의 수박 한 통보다 몇 kg 가벼운가요?","options":[{"t":"2.2 kg","correct":true},{"t":"8 kg","mis":"M6-1-u3-X14"},{"t":"22 kg","mis":"M6-1-u3-X01"},{"t":"0.22 kg","mis":"M6-1-u3-X02"}],"explanation":["아 상자 한 통은 30.6 ÷ 6 = 5.1 (kg)이에요.","마 상자 한 통은 14.5 ÷ 5 = 2.9 (kg)이에요.","5.1 − 2.9 = 2.2 (kg) 가벼워요."]},{"stem":"가 상자는 수박 3통이 18.3 kg, 라 상자는 수박 6통이 25.2 kg이에요. 라 상자의 수박 한 통은 가 상자의 수박 한 통보다 몇 kg 가벼운가요?","options":[{"t":"1.9 kg","correct":true},{"t":"10.3 kg","mis":"M6-1-u3-X14"},{"t":"19 kg","mis":"M6-1-u3-X01"},{"t":"0.19 kg","mis":"M6-1-u3-X02"}],"explanation":["가 상자 한 통은 18.3 ÷ 3 = 6.1 (kg)이에요.","라 상자 한 통은 25.2 ÷ 6 = 4.2 (kg)이에요.","6.1 − 4.2 = 1.9 (kg) 가벼워요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_c#24','math',6,1,'u3','','g6_1_math_u3_review_c','unit_review','M6-1-u3-C4',4,'essay','teacher','물 5.4 L를 병 8개에 똑같이 나누어 담았어요. 한 병에 담긴 물이 몇 L인지 0을 내려 계산하는 과정을 쓰고, 몇 mL인지도 구해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u3-C4","difficulty":4,"kind":"essay","stem":"물 5.4 L를 병 8개에 똑같이 나누어 담았어요. 한 병에 담긴 물이 몇 L인지 0을 내려 계산하는 과정을 쓰고, 몇 mL인지도 구해 보세요.","answer_guide":{"answer":"예: 5.4 ÷ 8에서 5.4가 8보다 작으므로 몫의 일의 자리에 0을 쓴다. 54 ÷ 8 = 6 … 6이므로 0을 내려 60 ÷ 8 = 7 … 4, 다시 0을 내려 40 ÷ 8 = 5로 나누어떨어진다. 몫은 0.675 L이고 1 L = 1000 mL이므로 675 mL이다.","scoring_points":["일의 자리에 0을 썼는가","0을 두 번 내려 0.675를 구했는가","675 mL로 바꾸었는가"]},"explanation":["5.4 < 8이라 일의 자리에 0이에요.","0을 두 번 내려 0.675 L예요.","0.675 L = 675 mL예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_c#25','math',6,1,'u3','','g6_1_math_u3_review_c','unit_review','M6-1-u3-C6',4,'essay','teacher','분수 광장의 분수대는 가로가 6 m, 세로가 5 m예요. 가로가 세로의 몇 배인지 두 가지 방법(분수로 나타낸 뒤 소수로 바꾸기, 세로셈)으로 구해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u3-C6","difficulty":4,"kind":"essay","stem":"분수 광장의 분수대는 가로가 6 m, 세로가 5 m예요. 가로가 세로의 몇 배인지 두 가지 방법(분수로 나타낸 뒤 소수로 바꾸기, 세로셈)으로 구해 보세요.","answer_guide":{"answer":"예: 6 ÷ 5의 몫은 5분의 6이다. 분모를 10으로 고치면 10분의 12이고 이것을 소수로 쓰면 1.2이다. 세로셈에서는 6을 6.0으로 보고 6 ÷ 5 = 1 … 1에서 남은 1에 0을 내려 10 ÷ 5 = 2를 계산해 1.2이다. 가로는 세로의 1.2배이다.","scoring_points":["⟨6/5⟩ = ⟨12/10⟩ = 1.2로 구했는가","6을 6.0으로 보고 0을 내려 세로셈으로 구했는가","1.2배라고 답했는가"]},"explanation":["⟨6/5⟩ = ⟨12/10⟩ = 1.2예요.","6을 6.0으로 보고 0을 내려요.","가로는 세로의 1.2배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_d#1','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C1',1,'mc','auto','846 ÷ 2 = 423이에요. 그러면 84.6 ÷ 2의 몫은 얼마인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":1,"concept":"M6-1-u3-C1","difficulty":1,"kind":"mc","stem":"846 ÷ 2 = 423이에요. 그러면 84.6 ÷ 2의 몫은 얼마인가요?","options":[{"t":"42.3","correct":true},{"t":"423","mis":"M6-1-u3-X01"},{"t":"4.23","mis":"M6-1-u3-X02"},{"t":"4230","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 2는 그대로예요.","나누어지는 수 84.6은 846의 ⟨1/10⟩배예요.","그래서 몫도 423의 ⟨1/10⟩배 — 42.3이에요."],"variant_rule":{"alt":[{"stem":"585 ÷ 5 = 117이에요. 그러면 5.85 ÷ 5의 몫은 얼마인가요?","options":[{"t":"1.17","correct":true},{"t":"11.7","mis":"M6-1-u3-X01"},{"t":"0.117","mis":"M6-1-u3-X02"},{"t":"117","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 5는 그대로예요.","나누어지는 수 5.85는 585의 ⟨1/100⟩배예요.","그래서 몫도 117의 ⟨1/100⟩배 — 1.17이에요."]},{"stem":"648 ÷ 2 = 324예요. 그러면 64.8 ÷ 2의 몫은 얼마인가요?","options":[{"t":"32.4","correct":true},{"t":"324","mis":"M6-1-u3-X01"},{"t":"3.24","mis":"M6-1-u3-X02"},{"t":"3240","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 2는 그대로예요.","나누어지는 수 64.8은 648의 ⟨1/10⟩배예요.","그래서 몫도 324의 ⟨1/10⟩배 — 32.4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_d#2','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C1',1,'sa','auto','8.6은 0.1이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u3-C1","difficulty":1,"kind":"sa","stem":"8.6은 0.1이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["86"],"explanation":["0.1이 10개이면 1이에요.","8.6은 8과 소수 부분을 합해 0.1이 86개예요.","그래서 8.6은 0.1이 86개인 수예요."],"mis":"M6-1-u3-X03","variant_rule":{"alt":[{"stem":"5.8은 0.1이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["58"],"explanation":["0.1이 10개이면 1이에요.","5.8은 5와 소수 부분을 합해 0.1이 58개예요.","그래서 5.8은 0.1이 58개인 수예요."]},{"stem":"4.7은 0.1이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["47"],"explanation":["0.1이 10개이면 1이에요.","4.7은 4와 소수 부분을 합해 0.1이 47개예요.","그래서 4.7은 0.1이 47개인 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_d#3','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C2',1,'mc','auto','49.2 ÷ 4의 몫은 얼마인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":3,"concept":"M6-1-u3-C2","difficulty":1,"kind":"mc","stem":"49.2 ÷ 4의 몫은 얼마인가요?","options":[{"t":"12.3","correct":true},{"t":"123","mis":"M6-1-u3-X01"},{"t":"1.23","mis":"M6-1-u3-X02"},{"t":"1230","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 492 ÷ 4 = 123이에요.","49.2는 492의 ⟨1/10⟩배라서 몫도 123의 ⟨1/10⟩배예요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 49.2 ÷ 4 = 12.3이에요."],"variant_rule":{"alt":[{"stem":"58.5 ÷ 5의 몫은 얼마인가요?","options":[{"t":"11.7","correct":true},{"t":"117","mis":"M6-1-u3-X01"},{"t":"1.17","mis":"M6-1-u3-X02"},{"t":"1170","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 585 ÷ 5 = 117이에요.","58.5는 585의 ⟨1/10⟩배라서 몫도 117의 ⟨1/10⟩배예요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 58.5 ÷ 5 = 11.7이에요."]},{"stem":"11.7 ÷ 3의 몫은 얼마인가요?","options":[{"t":"3.9","correct":true},{"t":"39","mis":"M6-1-u3-X01"},{"t":"0.39","mis":"M6-1-u3-X02"},{"t":"390","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 117 ÷ 3 = 39예요.","11.7은 117의 ⟨1/10⟩배라서 몫도 39의 ⟨1/10⟩배예요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 11.7 ÷ 3 = 3.9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_d#4','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C3',1,'mc','auto','2.38 ÷ 7의 몫은 얼마인가요?',ARRAY['M6-1-u3-X05','M6-1-u3-X02','M6-1-u3-X01']::text[],true,'{"seq":4,"concept":"M6-1-u3-C3","difficulty":1,"kind":"mc","stem":"2.38 ÷ 7의 몫은 얼마인가요?","options":[{"t":"0.34","correct":true},{"t":"3.4","mis":"M6-1-u3-X05"},{"t":"0.034","mis":"M6-1-u3-X02"},{"t":"34","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 238 ÷ 7 = 34예요.","2.38은 238의 ⟨1/100⟩배라서 몫도 34의 ⟨1/100⟩배예요.","몫이 1보다 작으니 일의 자리에 0을 써서 자리를 지켜요 — 2.38 ÷ 7 = 0.34예요."],"variant_rule":{"alt":[{"stem":"4.15 ÷ 5의 몫은 얼마인가요?","options":[{"t":"0.83","correct":true},{"t":"8.3","mis":"M6-1-u3-X05"},{"t":"0.083","mis":"M6-1-u3-X02"},{"t":"83","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 415 ÷ 5 = 83이에요.","4.15는 415의 ⟨1/100⟩배라서 몫도 83의 ⟨1/100⟩배예요.","몫이 1보다 작으니 일의 자리에 0을 써서 자리를 지켜요 — 4.15 ÷ 5 = 0.83이에요."]},{"stem":"3.2 ÷ 4의 몫은 얼마인가요?","options":[{"t":"0.8","correct":true},{"t":"8","mis":"M6-1-u3-X05"},{"t":"0.08","mis":"M6-1-u3-X02"},{"t":"80","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 32 ÷ 4 = 8이에요.","3.2는 32의 ⟨1/10⟩배라서 몫도 8의 ⟨1/10⟩배예요.","몫이 1보다 작으니 일의 자리에 0을 써서 자리를 지켜요 — 3.2 ÷ 4 = 0.8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_d#5','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C3',1,'mc','auto','5.6 ÷ 8의 몫은 1보다 클까요, 작을까요?',ARRAY['M6-1-u3-X12']::text[],true,'{"seq":5,"concept":"M6-1-u3-C3","difficulty":1,"kind":"mc","stem":"5.6 ÷ 8의 몫은 1보다 클까요, 작을까요?","options":[{"t":"1보다 작아요","correct":true},{"t":"1보다 커요","mis":"M6-1-u3-X12"},{"t":"1과 같아요","mis":"M6-1-u3-X12"},{"t":"계산해 보기 전에는 알 수 없어요","mis":"M6-1-u3-X12"}],"explanation":["나누어지는 수 5.6이 나누는 수 8보다 작아요.","8 ÷ 8 = 1이니 5.6 ÷ 8은 1보다 작아요.","실제로 몫은 0.7이에요."],"variant_rule":{"alt":[{"stem":"7.29 ÷ 9의 몫은 1보다 클까요, 작을까요?","options":[{"t":"1보다 작아요","correct":true},{"t":"1보다 커요","mis":"M6-1-u3-X12"},{"t":"1과 같아요","mis":"M6-1-u3-X12"},{"t":"계산해 보기 전에는 알 수 없어요","mis":"M6-1-u3-X12"}],"explanation":["나누어지는 수 7.29가 나누는 수 9보다 작아요.","9 ÷ 9 = 1이니 7.29 ÷ 9는 1보다 작아요.","실제로 몫은 0.81이에요."]},{"stem":"4.15 ÷ 5의 몫은 1보다 클까요, 작을까요?","options":[{"t":"1보다 작아요","correct":true},{"t":"1보다 커요","mis":"M6-1-u3-X12"},{"t":"1과 같아요","mis":"M6-1-u3-X12"},{"t":"계산해 보기 전에는 알 수 없어요","mis":"M6-1-u3-X12"}],"explanation":["나누어지는 수 4.15가 나누는 수 5보다 작아요.","5 ÷ 5 = 1이니 4.15 ÷ 5는 1보다 작아요.","실제로 몫은 0.83이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_d#6','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C4',1,'mc','auto','8.3 ÷ 2를 계산하다가 소수 첫째 자리까지 나누었더니 1이 남았어요. 다음에 할 일로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u3-X06','M6-1-u3-X13']::text[],true,'{"seq":6,"concept":"M6-1-u3-C4","difficulty":1,"kind":"mc","stem":"8.3 ÷ 2를 계산하다가 소수 첫째 자리까지 나누었더니 1이 남았어요. 다음에 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"소수점 아래에 0을 하나 내려 계산을 이어 가요","correct":true},{"t":"남은 1을 몫 뒤에 붙여 써요","mis":"M6-1-u3-X06"},{"t":"나누어떨어지지 않는다고 답해요","mis":"M6-1-u3-X06"},{"t":"나누는 수를 바꾸어 다시 나누어요","mis":"M6-1-u3-X13"}],"explanation":["8.3은 8.30과 같은 수예요.","소수점 아래 끝자리에 0을 붙여도 수의 크기는 그대로예요.","그래서 0을 내려 이어 계산하면 8.3 ÷ 2 = 4.15예요."],"variant_rule":{"alt":[{"stem":"4.6 ÷ 4를 계산하다가 소수 첫째 자리까지 나누었더니 2가 남았어요. 다음에 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"소수점 아래에 0을 하나 내려 계산을 이어 가요","correct":true},{"t":"남은 2를 몫 뒤에 붙여 써요","mis":"M6-1-u3-X06"},{"t":"나누어떨어지지 않는다고 답해요","mis":"M6-1-u3-X06"},{"t":"나누는 수를 바꾸어 다시 나누어요","mis":"M6-1-u3-X13"}],"explanation":["4.6은 4.60과 같은 수예요.","소수점 아래 끝자리에 0을 붙여도 수의 크기는 그대로예요.","그래서 0을 내려 이어 계산하면 4.6 ÷ 4 = 1.15예요."]},{"stem":"6.7 ÷ 5를 계산하다가 소수 첫째 자리까지 나누었더니 2가 남았어요. 다음에 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"소수점 아래에 0을 하나 내려 계산을 이어 가요","correct":true},{"t":"남은 2를 몫 뒤에 붙여 써요","mis":"M6-1-u3-X06"},{"t":"나누어떨어지지 않는다고 답해요","mis":"M6-1-u3-X06"},{"t":"나누는 수를 바꾸어 다시 나누어요","mis":"M6-1-u3-X13"}],"explanation":["6.7은 6.70과 같은 수예요.","소수점 아래 끝자리에 0을 붙여도 수의 크기는 그대로예요.","그래서 0을 내려 이어 계산하면 6.7 ÷ 5 = 1.34예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_d#7','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C6',1,'mc','auto','7 ÷ 4를 세로셈으로 계산할 때 7을 어떻게 보아야 하나요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":7,"concept":"M6-1-u3-C6","difficulty":1,"kind":"mc","stem":"7 ÷ 4를 세로셈으로 계산할 때 7을 어떻게 보아야 하나요?","options":[{"t":"7.0으로 봐요","correct":true},{"t":"70으로 봐요","mis":"M6-1-u3-X01"},{"t":"0.7로 봐요","mis":"M6-1-u3-X02"},{"t":"⟨7/10⟩로 봐요","mis":"M6-1-u3-X02"}],"explanation":["자연수의 소수점은 자연수 바로 뒤에 있어요.","7 = 7.0 = 7.00이에요.","그래서 7을 7.0으로 보고 0을 내려 계산해요."],"variant_rule":{"alt":[{"stem":"60 ÷ 8을 세로셈으로 계산할 때 60을 어떻게 보아야 하나요?","options":[{"t":"60.0으로 봐요","correct":true},{"t":"600으로 봐요","mis":"M6-1-u3-X01"},{"t":"6으로 봐요","mis":"M6-1-u3-X02"},{"t":"⟨60/10⟩으로 봐요","mis":"M6-1-u3-X02"}],"explanation":["자연수의 소수점은 자연수 바로 뒤에 있어요.","60 = 60.0 = 60.00이에요.","그래서 60을 60.0으로 보고 0을 내려 계산해요."]},{"stem":"6 ÷ 5를 세로셈으로 계산할 때 6을 어떻게 보아야 하나요?","options":[{"t":"6.0으로 봐요","correct":true},{"t":"60으로 봐요","mis":"M6-1-u3-X01"},{"t":"0.6으로 봐요","mis":"M6-1-u3-X02"},{"t":"⟨6/10⟩으로 봐요","mis":"M6-1-u3-X02"}],"explanation":["자연수의 소수점은 자연수 바로 뒤에 있어요.","6 = 6.0 = 6.00이에요.","그래서 6을 6.0으로 보고 0을 내려 계산해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_d#8','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C7',1,'sa','auto','라 상자에는 무게가 같은 수박 6통이 25.2 kg 들어 있어요. 25.2를 24로 어림하면 수박 한 통은 약 몇 kg인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u3-C7","difficulty":1,"kind":"sa","stem":"라 상자에는 무게가 같은 수박 6통이 25.2 kg 들어 있어요. 25.2를 24로 어림하면 수박 한 통은 약 몇 kg인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["25.2에 가까우면서 6으로 나누기 쉬운 수는 24예요.","24 ÷ 6 = 4예요.","수박 한 통은 약 4 kg이에요."],"mis":"M6-1-u3-X12","variant_rule":{"alt":[{"stem":"가 상자에는 무게가 같은 수박 3통이 18.3 kg 들어 있어요. 18.3을 18로 어림하면 수박 한 통은 약 몇 kg인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["18.3에 가까우면서 3으로 나누기 쉬운 수는 18이에요.","18 ÷ 3 = 6이에요.","수박 한 통은 약 6 kg이에요."]},{"stem":"나 상자에는 무게가 같은 수박 4통이 19.8 kg 들어 있어요. 19.8을 20으로 어림하면 수박 한 통은 약 몇 kg인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["19.8에 가까우면서 4로 나누기 쉬운 수는 20이에요.","20 ÷ 4 = 5예요.","수박 한 통은 약 5 kg이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_d#9','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C2',2,'sa','auto','22.68 ÷ 4의 몫에서 소수 둘째 자리 숫자는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u3-C2","difficulty":2,"kind":"sa","stem":"22.68 ÷ 4의 몫에서 소수 둘째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 2268 ÷ 4 = 567이에요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 22.68 ÷ 4 = 5.67이에요.","5.67의 소수 둘째 자리 숫자는 7이에요."],"mis":"M6-1-u3-X13","variant_rule":{"alt":[{"stem":"58.5 ÷ 5의 몫에서 소수 첫째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 585 ÷ 5 = 117이에요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 58.5 ÷ 5 = 11.7이에요.","11.7의 소수 첫째 자리 숫자는 7이에요."]},{"stem":"9.27 ÷ 9의 몫에서 소수 둘째 자리 숫자는 무엇인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 927 ÷ 9 = 103이에요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 9.27 ÷ 9 = 1.03이에요.","1.03의 소수 둘째 자리 숫자는 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_d#10','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C4',2,'mc','auto','5.4 ÷ 8의 몫은 얼마인가요?',ARRAY['M6-1-u3-X06','M6-1-u3-X01']::text[],true,'{"seq":10,"concept":"M6-1-u3-C4","difficulty":2,"kind":"mc","stem":"5.4 ÷ 8의 몫은 얼마인가요?","options":[{"t":"0.675","correct":true},{"t":"0.6","mis":"M6-1-u3-X06"},{"t":"0.66","mis":"M6-1-u3-X06"},{"t":"6.75","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 5400 ÷ 8 = 675예요.","5.4는 5400의 ⟨1/1000⟩배라서 몫도 675의 ⟨1/1000⟩배예요.","나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 5.4 ÷ 8 = 0.675예요."],"variant_rule":{"alt":[{"stem":"18.8 ÷ 8의 몫은 얼마인가요?","options":[{"t":"2.35","correct":true},{"t":"2.3","mis":"M6-1-u3-X06"},{"t":"2.34","mis":"M6-1-u3-X06"},{"t":"23.5","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1880 ÷ 8 = 235예요.","18.8은 1880의 ⟨1/100⟩배라서 몫도 235의 ⟨1/100⟩배예요.","나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 18.8 ÷ 8 = 2.35예요."]},{"stem":"4.6 ÷ 4의 몫은 얼마인가요?","options":[{"t":"1.15","correct":true},{"t":"1.1","mis":"M6-1-u3-X06"},{"t":"1.12","mis":"M6-1-u3-X06"},{"t":"11.5","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 460 ÷ 4 = 115예요.","4.6은 460의 ⟨1/100⟩배라서 몫도 115의 ⟨1/100⟩배예요.","나머지가 남으면 소수점 아래에 0을 내려 계산을 이어 가요 — 4.6 ÷ 4 = 1.15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_d#11','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C5',2,'mc','auto','16.4 ÷ 8의 몫은 얼마인가요?',ARRAY['M6-1-u3-X07','M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":11,"concept":"M6-1-u3-C5","difficulty":2,"kind":"mc","stem":"16.4 ÷ 8의 몫은 얼마인가요?","options":[{"t":"2.05","correct":true},{"t":"2.5","mis":"M6-1-u3-X07"},{"t":"20.5","mis":"M6-1-u3-X01"},{"t":"0.205","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1640 ÷ 8 = 205예요.","16.4는 1640의 ⟨1/100⟩배라서 몫도 205의 ⟨1/100⟩배예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 16.4 ÷ 8 = 2.05예요."],"variant_rule":{"alt":[{"stem":"18.1 ÷ 2의 몫은 얼마인가요?","options":[{"t":"9.05","correct":true},{"t":"9.5","mis":"M6-1-u3-X07"},{"t":"90.5","mis":"M6-1-u3-X01"},{"t":"0.905","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1810 ÷ 2 = 905예요.","18.1은 1810의 ⟨1/100⟩배라서 몫도 905의 ⟨1/100⟩배예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 18.1 ÷ 2 = 9.05예요."]},{"stem":"9.27 ÷ 9의 몫은 얼마인가요?","options":[{"t":"1.03","correct":true},{"t":"1.3","mis":"M6-1-u3-X07"},{"t":"10.3","mis":"M6-1-u3-X01"},{"t":"0.103","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 927 ÷ 9 = 103이에요.","9.27은 927의 ⟨1/100⟩배라서 몫도 103의 ⟨1/100⟩배예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 9.27 ÷ 9 = 1.03이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_d#12','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C6',2,'mc','auto','9 ÷ 6의 몫은 얼마인가요?',ARRAY['M6-1-u3-X08','M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":12,"concept":"M6-1-u3-C6","difficulty":2,"kind":"mc","stem":"9 ÷ 6의 몫은 얼마인가요?","options":[{"t":"1.5","correct":true},{"t":"1.3","mis":"M6-1-u3-X08"},{"t":"15","mis":"M6-1-u3-X01"},{"t":"0.15","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 90 ÷ 6 = 15예요.","9는 90의 ⟨1/10⟩배라서 몫도 15의 ⟨1/10⟩배예요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 9 ÷ 6 = 1.5예요."],"variant_rule":{"alt":[{"stem":"60 ÷ 8의 몫은 얼마인가요?","options":[{"t":"7.5","correct":true},{"t":"7.4","mis":"M6-1-u3-X08"},{"t":"75","mis":"M6-1-u3-X01"},{"t":"0.75","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 600 ÷ 8 = 75예요.","60은 600의 ⟨1/10⟩배라서 몫도 75의 ⟨1/10⟩배예요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 60 ÷ 8 = 7.5예요."]},{"stem":"6 ÷ 5의 몫은 얼마인가요?","options":[{"t":"1.2","correct":true},{"t":"1.1","mis":"M6-1-u3-X08"},{"t":"12","mis":"M6-1-u3-X01"},{"t":"0.12","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 60 ÷ 5 = 12예요.","6은 60의 ⟨1/10⟩배라서 몫도 12의 ⟨1/10⟩배예요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 6 ÷ 5 = 1.2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_d#13','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C6',2,'ox','auto','6 ÷ 5의 몫은 1.1이에요.',ARRAY['M6-1-u3-X08']::text[],true,'{"seq":13,"concept":"M6-1-u3-C6","difficulty":2,"kind":"ox","stem":"6 ÷ 5의 몫은 1.1이에요.","answer":"X","reason_options":[{"t":"나머지 1에 0을 내려 10 ÷ 5 = 2를 이어 계산하면 1.2이기 때문에","correct":true},{"t":"6 ÷ 5 = 1 … 1이라 나머지를 소수로 쓰기 때문에","mis":"M6-1-u3-X08"}],"mis":"M6-1-u3-X08","explanation":["자연수의 소수점은 자연수 바로 뒤에 있어요 — 6 = 6.0이에요.","나머지가 남으면 0을 내려 계산을 이어 가요.","몫을 분수로 쓴 뒤 분모를 10·100으로 고쳐 소수로 나타낼 수도 있어요."],"variant_rule":{"alt":[{"stem":"648 ÷ 2 = 324이면 6.48 ÷ 2 = 32.4예요.","answer":"X","reason_options":[{"t":"6.48은 648의 ⟨1/100⟩배라서 몫도 ⟨1/100⟩배인 3.24이기 때문에","correct":true},{"t":"나누어지는 수의 소수점을 한 칸만 옮기면 되기 때문에","mis":"M6-1-u3-X02"}],"explanation":["소수는 0.1이나 0.01이 몇 개인 수로 볼 수 있어요.","나누는 수가 같을 때 나누어지는 수가 ⟨1/10⟩배가 되면 몫도 ⟨1/10⟩배가 돼요.","분수의 나눗셈으로 바꾸면 ÷ 자연수는 × 자연수분의 1이에요."]},{"stem":"5.6 ÷ 7의 몫은 8이에요.","answer":"X","reason_options":[{"t":"몫이 1보다 작아 일의 자리에 0을 써서 0.8이기 때문에","correct":true},{"t":"56 ÷ 7 = 8이니 몫도 8이기 때문에","mis":"M6-1-u3-X05"}],"explanation":["나누어지는 수가 나누는 수보다 작으면 몫은 1보다 작아요.","이때 몫의 일의 자리에 0을 써요.","0은 자리를 지키는 숫자예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_d#14','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C3',2,'mc','auto','다음 가운데 몫이 1보다 작은 나눗셈은 어느 것인가요?',ARRAY['M6-1-u3-X12']::text[],true,'{"seq":14,"concept":"M6-1-u3-C3","difficulty":2,"kind":"mc","stem":"다음 가운데 몫이 1보다 작은 나눗셈은 어느 것인가요?","options":[{"t":"4.15 ÷ 5","correct":true},{"t":"9.9 ÷ 9","mis":"M6-1-u3-X12"},{"t":"6.6 ÷ 6","mis":"M6-1-u3-X12"},{"t":"8.8 ÷ 4","mis":"M6-1-u3-X12"}],"explanation":["몫이 1보다 작으려면 나누어지는 수가 나누는 수보다 작아야 해요.","나누어지는 수와 나누는 수를 하나씩 견주어 봐요.","4.15 ÷ 5만 나누어지는 수가 더 작아요 — 몫은 0.83이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 가운데 몫이 1보다 작은 나눗셈은 어느 것인가요?","options":[{"t":"7.29 ÷ 9","correct":true},{"t":"14.9 ÷ 5","mis":"M6-1-u3-X12"},{"t":"8.4 ÷ 8","mis":"M6-1-u3-X12"},{"t":"4.16 ÷ 4","mis":"M6-1-u3-X12"}],"explanation":["몫이 1보다 작으려면 나누어지는 수가 나누는 수보다 작아야 해요.","나누어지는 수와 나누는 수를 하나씩 견주어 봐요.","7.29 ÷ 9만 나누어지는 수가 더 작아요 — 몫은 0.81이에요."]},{"stem":"이번에는 다른 보기예요. 다음 가운데 몫이 1보다 작은 나눗셈은 어느 것인가요?","options":[{"t":"6.3 ÷ 7","correct":true},{"t":"9.6 ÷ 8","mis":"M6-1-u3-X12"},{"t":"5.5 ÷ 5","mis":"M6-1-u3-X12"},{"t":"12.6 ÷ 6","mis":"M6-1-u3-X12"}],"explanation":["몫이 1보다 작으려면 나누어지는 수가 나누는 수보다 작아야 해요.","나누어지는 수와 나누는 수를 하나씩 견주어 봐요.","6.3 ÷ 7만 나누어지는 수가 더 작아요 — 몫은 0.9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_d#15','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C1',2,'mc','auto','리본 9.6 m를 세 명이 똑같이 나누어 가져요. 한 명이 가지는 리본은 몇 m인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02','M6-1-u3-X10']::text[],true,'{"seq":15,"concept":"M6-1-u3-C1","difficulty":2,"kind":"mc","stem":"리본 9.6 m를 세 명이 똑같이 나누어 가져요. 한 명이 가지는 리본은 몇 m인가요?","options":[{"t":"3.2 m","correct":true},{"t":"32 m","mis":"M6-1-u3-X01"},{"t":"0.32 m","mis":"M6-1-u3-X02"},{"t":"28.8 m","mis":"M6-1-u3-X10"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 96 ÷ 3 = 32예요.","9.6은 96의 ⟨1/10⟩배라서 몫도 32의 ⟨1/10⟩배예요.","9.6 ÷ 3 = 3.2예요."],"variant_rule":{"alt":[{"stem":"걷기 대회 코스는 모두 6.8 km예요. 반환점은 코스의 정확히 절반 지점에 있어요. 반환점까지는 몇 km인가요?","options":[{"t":"3.4 km","correct":true},{"t":"34 km","mis":"M6-1-u3-X01"},{"t":"0.34 km","mis":"M6-1-u3-X02"},{"t":"13.6 km","mis":"M6-1-u3-X10"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 68 ÷ 2 = 34예요.","6.8은 68의 ⟨1/10⟩배라서 몫도 34의 ⟨1/10⟩배예요.","6.8 ÷ 2 = 3.4예요."]},{"stem":"쌀 84.88 kg을 자루 4개에 똑같이 나누어 담았어요. 자루 한 개에 담긴 쌀은 몇 kg인가요?","options":[{"t":"21.22 kg","correct":true},{"t":"212.2 kg","mis":"M6-1-u3-X01"},{"t":"2.122 kg","mis":"M6-1-u3-X02"},{"t":"339.52 kg","mis":"M6-1-u3-X10"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 8488 ÷ 4 = 2122예요.","84.88은 8488의 ⟨1/100⟩배라서 몫도 2122의 ⟨1/100⟩배예요.","84.88 ÷ 4 = 21.22예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_d#16','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C2',2,'sa','auto','넓이가 38.4 cm²이고 가로가 6 cm인 직사각형이 있어요. 이 직사각형의 세로는 몇 mm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M6-1-u3-C2","difficulty":2,"kind":"sa","stem":"넓이가 38.4 cm²이고 가로가 6 cm인 직사각형이 있어요. 이 직사각형의 세로는 몇 mm인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["직사각형의 넓이 = 가로 × 세로이니 세로 = 넓이 ÷ 가로요예요.","38.4 ÷ 6 = 6.4 (cm)예요.","1 cm는 10 mm라서 6.4 cm는 64 mm예요."],"mis":"M6-1-u3-X11","variant_rule":{"alt":[{"stem":"넓이가 45.6 cm²이고 가로가 8 cm인 직사각형이 있어요. 이 직사각형의 세로는 몇 mm인가요? 숫자로 쓰세요.","answer":["57"],"explanation":["직사각형의 넓이 = 가로 × 세로이니 세로 = 넓이 ÷ 가로요예요.","45.6 ÷ 8 = 5.7 (cm)예요.","1 cm는 10 mm라서 5.7 cm는 57 mm예요."]},{"stem":"넓이가 25.2 cm²이고 밑변이 4 cm인 평행사변형이 있어요. 이 평행사변형의 높이는 몇 mm인가요? 숫자로 쓰세요.","answer":["63"],"explanation":["평행사변형의 넓이 = 밑변 × 높이이니 높이 = 넓이 ÷ 밑변이에.","25.2 ÷ 4 = 6.3 (cm)예요.","1 cm는 10 mm라서 6.3 cm는 63 mm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_d#17','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C5',3,'mc','auto','친구가 12.3 ÷ 6의 몫을 2.5라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X06','M6-1-u3-X05']::text[],true,'{"seq":17,"concept":"M6-1-u3-C5","difficulty":3,"kind":"mc","stem":"친구가 12.3 ÷ 6의 몫을 2.5라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"내린 수가 나누는 수보다 작을 때 몫에 0을 쓰지 않아서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"0을 내려 계산하지 않아서","mis":"M6-1-u3-X06"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1230 ÷ 6 = 205예요.","내린 수가 6보다 작으면 몫에 0을 쓰고 하나 더 내려야 해요.","바른 몫은 2.05이고 2.5는 다른 수예요."],"variant_rule":{"alt":[{"stem":"친구가 18.1 ÷ 2의 몫을 9.5라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"내린 수가 나누는 수보다 작을 때 몫에 0을 쓰지 않아서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"0을 내려 계산하지 않아서","mis":"M6-1-u3-X06"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1810 ÷ 2 = 905예요.","내린 수가 2보다 작으면 몫에 0을 쓰고 하나 더 내려야 해요.","바른 몫은 9.05이고 9.5는 다른 수예요."]},{"stem":"친구가 20.2 ÷ 5의 몫을 4.4라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"내린 수가 나누는 수보다 작을 때 몫에 0을 쓰지 않아서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"0을 내려 계산하지 않아서","mis":"M6-1-u3-X06"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 2020 ÷ 5 = 404예요.","내린 수가 5보다 작으면 몫에 0을 쓰고 하나 더 내려야 해요.","바른 몫은 4.04이고 4.4는 다른 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_d#18','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C3',3,'mc','auto','친구가 2.38 ÷ 7의 몫을 34라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u3-X13','M6-1-u3-X06']::text[],true,'{"seq":18,"concept":"M6-1-u3-C3","difficulty":3,"kind":"mc","stem":"친구가 2.38 ÷ 7의 몫을 34라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"몫이 1보다 작은데 일의 자리 0과 소수점을 쓰지 않아서","correct":true},{"t":"나누는 수를 잘못 써서","mis":"M6-1-u3-X13"},{"t":"곱셈을 잘못해서","mis":"M6-1-u3-X13"},{"t":"0을 내려 계산하지 않아서","mis":"M6-1-u3-X06"}],"explanation":["2.38은 7보다 작아 몫이 1보다 작아요.","자연수의 나눗셈으로 바꾸어 봐요 — 238 ÷ 7 = 34예요.","일의 자리에 0을 쓰고 소수점을 찍어 0.34예요."],"variant_rule":{"alt":[{"stem":"친구가 3.2 ÷ 4의 몫을 8이라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"몫이 1보다 작은데 일의 자리 0과 소수점을 쓰지 않아서","correct":true},{"t":"나누는 수를 잘못 써서","mis":"M6-1-u3-X13"},{"t":"곱셈을 잘못해서","mis":"M6-1-u3-X13"},{"t":"0을 내려 계산하지 않아서","mis":"M6-1-u3-X06"}],"explanation":["3.2는 4보다 작아 몫이 1보다 작아요.","자연수의 나눗셈으로 바꾸어 봐요 — 32 ÷ 4 = 8이에요.","일의 자리에 0을 쓰고 소수점을 찍어 0.8이에요."]},{"stem":"친구가 4.15 ÷ 5의 몫을 83이라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"몫이 1보다 작은데 일의 자리 0과 소수점을 쓰지 않아서","correct":true},{"t":"나누는 수를 잘못 써서","mis":"M6-1-u3-X13"},{"t":"곱셈을 잘못해서","mis":"M6-1-u3-X13"},{"t":"0을 내려 계산하지 않아서","mis":"M6-1-u3-X06"}],"explanation":["4.15는 5보다 작아 몫이 1보다 작아요.","자연수의 나눗셈으로 바꾸어 봐요 — 415 ÷ 5 = 83이에요.","일의 자리에 0을 쓰고 소수점을 찍어 0.83이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_d#19','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C6',3,'mc','auto','친구가 17 ÷ 4 = 4 … 1을 보고 몫을 4.1로 나타냈어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X09','M6-1-u3-X05']::text[],true,'{"seq":19,"concept":"M6-1-u3-C6","difficulty":3,"kind":"mc","stem":"친구가 17 ÷ 4 = 4 … 1을 보고 몫을 4.1로 나타냈어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나머지 1을 그대로 소수 부분으로 써서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"나누는 수와 나누어지는 수를 바꾸어서","mis":"M6-1-u3-X09"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["나머지 1은 아직 나누지 않은 양이라 몫의 소수 부분이 아니에요.","17을 17.0으로 보고 0을 내려 계산을 이어 가요.","바른 몫은 4.25예요."],"variant_rule":{"alt":[{"stem":"친구가 6 ÷ 5 = 1 … 1을 보고 몫을 1.1로 나타냈어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나머지 1을 그대로 소수 부분으로 써서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"나누는 수와 나누어지는 수를 바꾸어서","mis":"M6-1-u3-X09"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["나머지 1은 아직 나누지 않은 양이라 몫의 소수 부분이 아니에요.","6을 6.0으로 보고 0을 내려 계산을 이어 가요.","바른 몫은 1.2예요."]},{"stem":"친구가 9 ÷ 6 = 1 … 3을 보고 몫을 1.3으로 나타냈어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나머지 3을 그대로 소수 부분으로 써서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"나누는 수와 나누어지는 수를 바꾸어서","mis":"M6-1-u3-X09"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["나머지 3은 아직 나누지 않은 양이라 몫의 소수 부분이 아니에요.","9를 9.0으로 보고 0을 내려 계산을 이어 가요.","바른 몫은 1.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_d#20','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C7',3,'mc','auto','가 상자 3통 18.3 kg · 라 상자 6통 25.2 kg · 마 상자 5통 14.5 kg — 수박 한 통이 가장 무거운 상자는 어느 것인가요?',ARRAY['M6-1-u3-X12','M6-1-u3-X14']::text[],true,'{"seq":20,"concept":"M6-1-u3-C7","difficulty":3,"kind":"mc","stem":"가 상자 3통 18.3 kg · 라 상자 6통 25.2 kg · 마 상자 5통 14.5 kg — 수박 한 통이 가장 무거운 상자는 어느 것인가요?","options":[{"t":"가 상자","correct":true},{"t":"라 상자","mis":"M6-1-u3-X12"},{"t":"마 상자","mis":"M6-1-u3-X14"},{"t":"모두 같아요","mis":"M6-1-u3-X12"}],"explanation":["먼저 어림해요 — 18 ÷ 3 = 6, 24 ÷ 6 = 4, 15 ÷ 5 = 3이에요.","계산으로 확인하면 가 6.1 kg, 라 4.2 kg, 마 2.9 kg이에요.","수박 한 통이 가장 무거운 것은 가 상자예요."],"variant_rule":{"alt":[{"stem":"가 상자 3통 18.3 kg · 나 상자 4통 19.8 kg · 다 상자 5통 20.2 kg — 수박 한 통이 가장 무거운 상자는 어느 것인가요?","options":[{"t":"가 상자","correct":true},{"t":"나 상자","mis":"M6-1-u3-X12"},{"t":"다 상자","mis":"M6-1-u3-X14"},{"t":"모두 같아요","mis":"M6-1-u3-X12"}],"explanation":["먼저 어림해요 — 18 ÷ 3 = 6, 20 ÷ 4 = 5, 20 ÷ 5 = 4예요.","계산으로 확인하면 가 6.1 kg, 나 4.95 kg, 다 4.04 kg이에요.","수박 한 통이 가장 무거운 것은 가 상자예요."]},{"stem":"라 상자 6통 25.2 kg · 마 상자 5통 14.5 kg · 바 상자 4통 22.4 kg — 수박 한 통이 가장 무거운 상자는 어느 것인가요?","options":[{"t":"바 상자","correct":true},{"t":"라 상자","mis":"M6-1-u3-X12"},{"t":"마 상자","mis":"M6-1-u3-X14"},{"t":"모두 같아요","mis":"M6-1-u3-X12"}],"explanation":["먼저 어림해요 — 24 ÷ 6 = 4, 15 ÷ 5 = 3, 24 ÷ 4 = 6이에요.","계산으로 확인하면 라 4.2 kg, 마 2.9 kg, 바 5.6 kg이에요.","수박 한 통이 가장 무거운 것은 바 상자예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_d#21','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C5',3,'error','auto','18.1 ÷ 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u3-X07','M6-1-u3-X14']::text[],true,'{"seq":21,"concept":"M6-1-u3-C5","difficulty":3,"kind":"error","stem":"18.1 ÷ 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「몫은 9.5야.」","correct":true,"mis_target":"M6-1-u3-X07"},{"t":"라온 — 「몫은 9보다 조금 커.」","mis":"M6-1-u3-X14"},{"t":"예준 — 「몫의 소수 첫째 자리에 0이 들어가.」","mis":"M6-1-u3-X14"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1810 ÷ 2 = 905예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 18.1 ÷ 2 = 9.05예요.","여울은 몫 가운데 0을 빠뜨렸어요."],"variant_rule":{"alt":[{"stem":"585 ÷ 5 = 117을 이용해 58.5 ÷ 5를 계산하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「나누어지는 수가 작아졌으니 몫은 117의 10배야.」","correct":true,"mis_target":"M6-1-u3-X01"},{"t":"이현 — 「58.5는 585의 ⟨1/10⟩배야.」","mis":"M6-1-u3-X14"},{"t":"서아 — 「몫은 11.7이야.」","mis":"M6-1-u3-X14"}],"explanation":["나누는 수 5는 그대로예요.","나누어지는 수가 ⟨1/10⟩배가 되면 몫도 ⟨1/10⟩배예요.","준희는 몫이 커진다고 거꾸로 말했어요."]},{"stem":"49.2 ÷ 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「몫은 123이야.」","correct":true,"mis_target":"M6-1-u3-X01"},{"t":"수아 — 「492 ÷ 4를 계산한 몫의 ⟨1/10⟩배야.」","mis":"M6-1-u3-X14"},{"t":"도윤 — 「몫의 소수점은 49.2의 소수점 위에 찍어.」","mis":"M6-1-u3-X14"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 492 ÷ 4 = 123이에요.","49.2는 492의 ⟨1/10⟩배라서 몫도 123의 ⟨1/10⟩배예요.","서호는 몫의 소수점을 한 자리 뒤에 찍었어요 — 바른 몫은 12.3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_d#22','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C5',3,'sa','auto','2.0□가 16.4 ÷ 8의 몫보다 작아요. □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M6-1-u3-C5","difficulty":3,"kind":"sa","stem":"2.0□가 16.4 ÷ 8의 몫보다 작아요. □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1640 ÷ 8 = 205예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 16.4 ÷ 8 = 2.05예요.","2.0□ < 2.05 — □는 1부터 4까지, 4개예요."],"mis":"M6-1-u3-X07","variant_rule":{"alt":[{"stem":"6.0□가 48.4 ÷ 8의 몫보다 커요. □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 4840 ÷ 8 = 605예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 48.4 ÷ 8 = 6.05예요.","6.0□ > 6.05 — □는 6부터 9까지, 4개예요."]},{"stem":"4.0□가 24.3 ÷ 6의 몫보다 커요. □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 2430 ÷ 6 = 405예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 24.3 ÷ 6 = 4.05예요.","4.0□ > 4.05 — □는 6부터 9까지, 4개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_d#23','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C7',4,'mc','auto','아 상자는 수박 6통이 30.6 kg, 마 상자는 수박 5통이 14.5 kg이에요. 마 상자의 수박 한 통은 아 상자의 수박 한 통보다 몇 kg 가벼운가요?',ARRAY['M6-1-u3-X14','M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":23,"concept":"M6-1-u3-C7","difficulty":4,"kind":"mc","stem":"아 상자는 수박 6통이 30.6 kg, 마 상자는 수박 5통이 14.5 kg이에요. 마 상자의 수박 한 통은 아 상자의 수박 한 통보다 몇 kg 가벼운가요?","options":[{"t":"2.2 kg","correct":true},{"t":"8 kg","mis":"M6-1-u3-X14"},{"t":"22 kg","mis":"M6-1-u3-X01"},{"t":"0.22 kg","mis":"M6-1-u3-X02"}],"explanation":["아 상자 한 통은 30.6 ÷ 6 = 5.1 (kg)이에요.","마 상자 한 통은 14.5 ÷ 5 = 2.9 (kg)이에요.","5.1 − 2.9 = 2.2 (kg) 가벼워요."],"variant_rule":{"alt":[{"stem":"가 상자는 수박 3통이 18.3 kg, 라 상자는 수박 6통이 25.2 kg이에요. 라 상자의 수박 한 통은 가 상자의 수박 한 통보다 몇 kg 가벼운가요?","options":[{"t":"1.9 kg","correct":true},{"t":"10.3 kg","mis":"M6-1-u3-X14"},{"t":"19 kg","mis":"M6-1-u3-X01"},{"t":"0.19 kg","mis":"M6-1-u3-X02"}],"explanation":["가 상자 한 통은 18.3 ÷ 3 = 6.1 (kg)이에요.","라 상자 한 통은 25.2 ÷ 6 = 4.2 (kg)이에요.","6.1 − 4.2 = 1.9 (kg) 가벼워요."]},{"stem":"가 상자는 수박 3통이 18.3 kg, 나 상자는 수박 4통이 19.8 kg이에요. 나 상자의 수박 한 통은 가 상자의 수박 한 통보다 몇 kg 가벼운가요?","options":[{"t":"1.15 kg","correct":true},{"t":"11.05 kg","mis":"M6-1-u3-X14"},{"t":"11.5 kg","mis":"M6-1-u3-X01"},{"t":"0.115 kg","mis":"M6-1-u3-X02"}],"explanation":["가 상자 한 통은 18.3 ÷ 3 = 6.1 (kg)이에요.","나 상자 한 통은 19.8 ÷ 4 = 4.95 (kg)이에요.","6.1 − 4.95 = 1.15 (kg) 가벼워요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_d#24','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C5',4,'essay','teacher','강변을 자전거로 같은 빠르기로 18.1 km를 달리는 데 2시간이 걸렸어요. 한 시간 동안 달린 거리를 구하고, 친구가 쓴 9.5 km가 왜 틀렸는지 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u3-C5","difficulty":4,"kind":"essay","stem":"강변을 자전거로 같은 빠르기로 18.1 km를 달리는 데 2시간이 걸렸어요. 한 시간 동안 달린 거리를 구하고, 친구가 쓴 9.5 km가 왜 틀렸는지 설명해 보세요.","answer_guide":{"answer":"예: 18.1 ÷ 2를 계산한다. 18을 2로 나누면 9이고 1을 내렸지만 1은 2보다 작으므로 몫에 0을 쓰고 수를 하나 더 내려 10 ÷ 2 = 5로 계산한다. 그래서 몫은 9.05이고 한 시간에 9.05 km를 달렸다. 9.5는 몫 가운데 0을 빠뜨려 전혀 다른 수가 되었다.","scoring_points":["몫에 0을 쓰고 하나 더 내렸는가","9.05 km를 구했는가","9.5는 0을 빠뜨린 것이라고 설명했는가"]},"explanation":["1을 내려도 2보다 작아 몫에 0을 써요.","18.1 ÷ 2 = 9.05 — 9.05 km예요.","9.5는 0을 빠뜨렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u3_review_d#25','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C4',4,'essay','teacher','넓이가 4.6 m²인 벽을 칠하는 데 페인트 4통을 똑같이 썼어요. 4.6 ÷ 4를 계산하다가 2가 남았을 때 어떻게 해야 하는지 쓰고, 페인트 한 통으로 칠한 넓이를 구해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u3-C4","difficulty":4,"kind":"essay","stem":"넓이가 4.6 m²인 벽을 칠하는 데 페인트 4통을 똑같이 썼어요. 4.6 ÷ 4를 계산하다가 2가 남았을 때 어떻게 해야 하는지 쓰고, 페인트 한 통으로 칠한 넓이를 구해 보세요.","answer_guide":{"answer":"예: 4.6은 4.60과 같은 수이므로 소수점 아래에 0을 하나 내려 계산을 이어 간다. 남은 2에 0을 내리면 20 ÷ 4 = 5로 나누어떨어진다. 그래서 4.6 ÷ 4 = 1.15이고 페인트 한 통으로 1.15 m²를 칠했다.","scoring_points":["4.6 = 4.60이라는 까닭을 썼는가","0을 내려 계산을 이어 갔는가","1.15 m²를 구했는가"]},"explanation":["4.6 = 4.60이에요.","0을 내려 20 ÷ 4 = 5를 이어 계산해요.","한 통으로 1.15 m²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
